-- [COMP:api/native-turn-frame] Separate the publication writer queue from workspace authority readers.
BEGIN;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $publication_lock_prerequisites$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D') THEN RAISE EXCEPTION 'publication_lock_unreviewed_ddl_trigger'; END IF;
END $publication_lock_prerequisites$;
SET LOCAL search_path=pg_catalog;
DO $workspace_files_prompt_catalog_receipt$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8333_workspace_files_prompt_catalog.sql')
 THEN RAISE EXCEPTION 'workspace_files_prompt_catalog_release_missing'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_index installed
  JOIN pg_class relation ON relation.oid=installed.indrelid
  JOIN pg_class index_relation ON index_relation.oid=installed.indexrelid AND index_relation.relowner=relation.relowner
  WHERE installed.indexrelid=to_regclass('public.idx_wf_prompt_catalog_updated')
    AND relation.oid='public.workspace_files'::regclass AND installed.indisvalid AND installed.indisready AND installed.indislive
    AND pg_get_indexdef(installed.indexrelid)=$definition$CREATE INDEX idx_wf_prompt_catalog_updated ON public.workspace_files USING btree (workspace_id, updated_at DESC) WHERE ((purpose = 'operational'::text) AND (valid_to IS NULL) AND ((path !~~ '/doc/%'::text) OR ((upload_identity IS NOT NULL) AND (source_episode_id IS NOT NULL))) AND (path !~~ '/apps/%'::text) AND (path !~~ '/office/sessions/%'::text) AND ((metadata ->> 'noIndex'::text) IS DISTINCT FROM 'true'::text))$definition$)
 THEN RAISE EXCEPTION 'workspace_files_prompt_catalog_changed'; END IF;
END $workspace_files_prompt_catalog_receipt$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $conversation_context_cost_receipt$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8332_conversation_context_cost.sql')
 THEN RAISE EXCEPTION 'conversation_context_cost_release_missing';END IF;
END $conversation_context_cost_receipt$;
DO $conversation_context_cost_display$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.private_session_display_contract d
  JOIN pg_catalog.pg_proc p ON p.oid=to_regprocedure(d.signature)
  WHERE d.signature='public.application_scope_lineage(uuid,text[],uuid[],text[])'
   AND d.fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex'))
 THEN RAISE EXCEPTION 'conversation_context_cost_display_pin_changed';END IF;
END $conversation_context_cost_display$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $memory_prompt_candidates_receipt$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8330_memory_prompt_candidates.sql')
 THEN RAISE EXCEPTION 'memory_prompt_candidates_release_missing'; END IF;
 IF 2<>(SELECT count(*)
  FROM (VALUES
   ('public.idx_memories_prompt_voice_identity',
    $definition$CREATE INDEX idx_memories_prompt_voice_identity ON public.memories USING btree (workspace_id) WHERE ((((scope = 'workspace'::text) AND (tags @> ARRAY['self-profile'::text])) OR (tags @> ARRAY['voice'::text])) AND (valid_to IS NULL))$definition$),
   ('public.idx_memories_learning_exception',
    $definition$CREATE INDEX idx_memories_learning_exception ON public.memories USING btree (workspace_id) WHERE (((learning #>> '{applicability,exceptionTo}'::text[]) IS NOT NULL) AND ((learning ->> 'origin'::text) = 'explicit'::text) AND ((learning ->> 'confirmed'::text) = 'true'::text) AND (valid_to IS NULL) AND (retracted_at IS NULL) AND (NOT scope_held))$definition$)
  ) expected(index_name,definition)
  JOIN pg_index installed ON installed.indexrelid=to_regclass(expected.index_name)
  JOIN pg_class relation ON relation.oid=installed.indrelid
  JOIN pg_class index_relation ON index_relation.oid=installed.indexrelid AND index_relation.relowner=relation.relowner
  WHERE relation.oid='public.memories'::regclass AND installed.indisvalid AND installed.indisready AND installed.indislive
    AND pg_get_indexdef(installed.indexrelid)=expected.definition)
 THEN RAISE EXCEPTION 'memory_prompt_candidates_catalog_changed'; END IF;
END $memory_prompt_candidates_receipt$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $conversation_memory_candidates_receipt$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8329_conversation_memory_query_candidates.sql')
 THEN RAISE EXCEPTION 'conversation_memory_candidates_release_missing';END IF;
END $conversation_memory_candidates_receipt$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $conversation_frontier_receipt$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8328_conversation_graph_frontier.sql')
 THEN RAISE EXCEPTION 'conversation_frontier_release_missing';END IF;
END $conversation_frontier_receipt$;
DO $conversation_frontier_revision$ BEGIN
 IF (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc
  WHERE oid='public.conversation_revision_snapshot(uuid,uuid,jsonb)'::regprocedure) IS DISTINCT FROM 'a2be517491cd8353e7c72137f3068d50a2421b35c3c0c2a260cb0a43d33901b2'
 THEN RAISE EXCEPTION 'conversation_frontier_revision_source_changed';END IF;
END $conversation_frontier_revision$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $conversation_graph_receipt$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8327_conversation_graph_set_verification.sql')
 THEN RAISE EXCEPTION 'conversation_graph_release_missing';END IF;
END $conversation_graph_receipt$;
SET LOCAL search_path=pg_catalog,public,pg_temp;
DO $memory_write_receipt$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public._migrations WHERE name='8326_native_memory_query_write_contract.sql')
 THEN RAISE EXCEPTION 'memory_query_write_release_missing';END IF;
END $memory_write_receipt$;
DO $memory_write_routines$
DECLARE member record; actual pg_proc;
 owner_oid oid:=(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass);
 runtime_oid oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
 owner_grant aclitem; runtime_grant aclitem;
BEGIN
 IF current_user::regrole::oid IS DISTINCT FROM owner_oid OR runtime_oid IS NULL
  OR EXISTS(SELECT 1 FROM pg_roles WHERE oid=owner_oid AND (rolsuper OR rolbypassrls))
 THEN RAISE EXCEPTION 'memory_query_write_owner_changed';END IF;
 owner_grant:=makeaclitem(owner_oid,owner_oid,'EXECUTE',false);
 runtime_grant:=makeaclitem(runtime_oid,owner_oid,'EXECUTE',false);
 FOR member IN SELECT * FROM (VALUES ('application_memory_historical_query_scan(uuid,text[],jsonb,boolean,jsonb)','fc0eb35e01aa364049649bd9d1bbf13ae6515ef6795d59db809d7e5aaf01c4f2'),('application_memory_statement_scan(uuid,text[],jsonb,boolean,jsonb,jsonb)','f45fb6e82229635698c0d48ef98244b7c974eb12b1e1cd507f87fbd28ce0ee11'),('record_admitted_application_field_derivation(uuid,text,uuid,text,text,jsonb)','e09717426c463f354ee9491681bb80f7f51bc5a1d935e635368b56b4f273d6b4')) known(signature,body_digest) LOOP
  SELECT * INTO STRICT actual FROM pg_proc WHERE oid=to_regprocedure('public.'||member.signature);
  IF encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM member.body_digest
   OR actual.proowner IS DISTINCT FROM owner_oid OR actual.pronamespace<>'public'::regnamespace
   OR actual.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
   OR (actual.proacl IS DISTINCT FROM (CASE WHEN member.signature='record_admitted_application_field_derivation(uuid,text,uuid,text,text,jsonb)' THEN ARRAY[owner_grant,runtime_grant] ELSE ARRAY[owner_grant] END)
    AND (member.signature<>'record_admitted_application_field_derivation(uuid,text,uuid,text,text,jsonb)' OR actual.proacl IS DISTINCT FROM ARRAY[runtime_grant,owner_grant]))
   OR actual.proconfig IS DISTINCT FROM ARRAY['search_path=pg_catalog, public, pg_temp']
   OR actual.proargnames IS DISTINCT FROM (CASE member.signature
    WHEN 'record_admitted_application_field_derivation(uuid,text,uuid,text,text,jsonb)' THEN ARRAY['w','k','i','v','producer','sources']
    WHEN 'application_memory_statement_scan(uuid,text[],jsonb,boolean,jsonb,jsonb)' THEN ARRAY['w','fields','bounds','include_retained','frozen','admitted']
    ELSE ARRAY['w','fields','bounds','include_retained','frozen'] END)
   OR actual.prorettype IS DISTINCT FROM (CASE WHEN member.signature='record_admitted_application_field_derivation(uuid,text,uuid,text,text,jsonb)' THEN 'uuid'::regtype::oid ELSE 'jsonb'::regtype::oid END)
   OR NOT actual.prosecdef OR actual.proleakproof OR actual.proisstrict OR actual.proretset
   OR actual.prokind<>'f' OR actual.provolatile<>'v' OR actual.proparallel<>'u'
   OR actual.procost<>100 OR actual.prorows<>0 OR actual.pronargdefaults<>0
   OR actual.proargdefaults IS NOT NULL OR actual.proallargtypes IS NOT NULL OR actual.proargmodes IS NOT NULL
   OR actual.protrftypes IS NOT NULL OR actual.provariadic<>0 OR actual.prosupport<>0
   OR actual.probin IS NOT NULL OR actual.prosqlbody IS NOT NULL
  THEN RAISE EXCEPTION 'memory_query_write_routine_contract_changed: %',member.signature;END IF;
 END LOOP;
END $memory_write_routines$;
DO $memory_write_intents$
DECLARE installed pg_class;
 owner_oid oid:=(SELECT relowner FROM pg_class WHERE oid='public.memories'::regclass);
BEGIN
 SELECT * INTO STRICT installed FROM pg_class WHERE oid='public.native_memory_query_write_intents'::regclass;
 IF installed.relowner IS DISTINCT FROM owner_oid OR installed.relkind<>'r'
  OR installed.relpersistence<>'p' OR NOT installed.relrowsecurity OR installed.relforcerowsecurity
  OR installed.relispartition
  OR coalesce(installed.relacl,acldefault('r',owner_oid)) IS DISTINCT FROM acldefault('r',owner_oid)
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=installed.oid)
  OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=installed.oid)
  OR EXISTS(SELECT 1 FROM pg_inherits WHERE inhrelid=installed.oid OR inhparent=installed.oid)
  OR (SELECT array_agg(attname||':'||format_type(atttypid,atttypmod) ORDER BY attnum)
      FROM pg_attribute WHERE attrelid=installed.oid AND attnum>0)
   IS DISTINCT FROM ARRAY['derivation_id:uuid','workspace_id:uuid','field_id:uuid','field_version:text','transaction_id:xid8']
  OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=installed.oid AND attnum>0
   AND (NOT attnotnull OR attisdropped OR atthasdef OR attgenerated<>'' OR attidentity<>'' OR attacl IS NOT NULL))
  OR (SELECT array_agg(pg_get_constraintdef(oid) ORDER BY pg_get_constraintdef(oid) COLLATE "C")
   FROM pg_constraint WHERE conrelid=installed.oid AND contype IN('p','f')
    AND convalidated AND NOT condeferrable AND NOT condeferred)
   IS DISTINCT FROM ARRAY[
    'FOREIGN KEY (derivation_id) REFERENCES scope_derivations(id) ON DELETE CASCADE',
    'FOREIGN KEY (field_id, field_version) REFERENCES application_field_observations(resource_id, version)',
    'FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE',
    'PRIMARY KEY (derivation_id, field_id, field_version)']
  OR (SELECT count(*) FROM pg_constraint WHERE conrelid=installed.oid AND contype<>'n')<>4
  OR (SELECT count(*) FROM pg_index WHERE indrelid=installed.oid)<>1
  OR NOT EXISTS(SELECT 1 FROM pg_index WHERE indrelid=installed.oid AND indisprimary AND indisvalid AND indisready AND indislive)
  OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=installed.oid
   AND (NOT tgisinternal OR tgenabled<>'O'))
  OR EXISTS(SELECT 1 FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
   WHERE k.conrelid=installed.oid AND (NOT t.tgisinternal OR t.tgenabled<>'O'))
  OR (SELECT count(*) FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint WHERE k.conrelid=installed.oid)<>12
 THEN RAISE EXCEPTION 'memory_query_write_intents_contract_changed';END IF;
 IF EXISTS(SELECT 1 FROM public.native_memory_query_write_intents)
 THEN RAISE EXCEPTION 'memory_query_write_intents_not_empty';END IF;
 IF EXISTS(SELECT 1 FROM public.crm_erasure_journal_targets
  WHERE table_name='native_memory_query_write_intents')
 THEN RAISE EXCEPTION 'memory_query_write_recovery_target_unexpected';END IF;

END $memory_write_intents$;
DO $input_shape$ BEGIN IF (
 SELECT t.typtype='c' AND t.typnamespace='public'::regnamespace
 AND t.typowner=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
 AND t.typinput='pg_catalog.record_in'::regproc AND t.typoutput='pg_catalog.record_out'::regproc
 AND t.typreceive='pg_catalog.record_recv'::regproc AND t.typsend='pg_catalog.record_send'::regproc
 AND t.typmodin=0 AND t.typmodout=0 AND t.typsubscript=0 AND t.typanalyze=0
 AND t.typelem=0 AND t.typbasetype=0 AND t.typnotnull=false AND t.typisdefined
 AND t.typcategory='C' AND t.typlen=-1 AND NOT t.typbyval AND t.typalign='d' AND t.typstorage='x'
 AND t.typcollation=0 AND t.typdefault IS NULL AND t.typdefaultbin IS NULL
 AND t.typacl IS NOT DISTINCT FROM ARRAY[makeaclitem(t.typowner,t.typowner,'USAGE',false)]
 AND EXISTS(SELECT 1 FROM pg_attribute registry_column WHERE registry_column.attrelid='public.native_turn_contract_helpers'::regclass
  AND registry_column.attname='contract' AND registry_column.atttypid=t.oid AND registry_column.attnotnull
  AND NOT registry_column.attisdropped AND NOT registry_column.atthasdef AND registry_column.attacl IS NULL)
 AND(SELECT count(*) FROM pg_attribute a WHERE a.attrelid=t.typrelid AND a.attnum>0)=30
 AND NOT EXISTS(SELECT 1 FROM pg_attribute a FULL JOIN(VALUES
 (1,'oid','pg_catalog.oid'::regtype::oid,0::oid),
 (2,'proname','pg_catalog.name'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (3,'pronamespace','pg_catalog.oid'::regtype::oid,0::oid),
 (4,'proowner','pg_catalog.oid'::regtype::oid,0::oid),
 (5,'prolang','pg_catalog.oid'::regtype::oid,0::oid),
 (6,'procost','pg_catalog.float4'::regtype::oid,0::oid),
 (7,'prorows','pg_catalog.float4'::regtype::oid,0::oid),
 (8,'provariadic','pg_catalog.oid'::regtype::oid,0::oid),
 (9,'prosupport','pg_catalog.regproc'::regtype::oid,0::oid),
 (10,'prokind','pg_catalog."char"'::regtype::oid,0::oid),
 (11,'prosecdef','pg_catalog.bool'::regtype::oid,0::oid),
 (12,'proleakproof','pg_catalog.bool'::regtype::oid,0::oid),
 (13,'proisstrict','pg_catalog.bool'::regtype::oid,0::oid),
 (14,'proretset','pg_catalog.bool'::regtype::oid,0::oid),
 (15,'provolatile','pg_catalog."char"'::regtype::oid,0::oid),
 (16,'proparallel','pg_catalog."char"'::regtype::oid,0::oid),
 (17,'pronargs','pg_catalog.int2'::regtype::oid,0::oid),
 (18,'pronargdefaults','pg_catalog.int2'::regtype::oid,0::oid),
 (19,'prorettype','pg_catalog.oid'::regtype::oid,0::oid),
 (20,'proargtypes','pg_catalog.oidvector'::regtype::oid,0::oid),
 (21,'proallargtypes','pg_catalog.oid[]'::regtype::oid,0::oid),
 (22,'proargmodes','pg_catalog."char"[]'::regtype::oid,0::oid),
 (23,'proargnames','pg_catalog.text[]'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (24,'proargdefaults','pg_catalog.text'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (25,'protrftypes','pg_catalog.oid[]'::regtype::oid,0::oid),
 (26,'prosrc','pg_catalog.text'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (27,'probin','pg_catalog.text'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (28,'prosqlbody','pg_catalog.text'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (29,'proconfig','pg_catalog.text[]'::regtype::oid,'pg_catalog."C"'::regcollation::oid),
 (30,'proacl','pg_catalog.aclitem[]'::regtype::oid,0::oid)
 ) expected(position,name,type_oid,collation_oid) ON a.attnum=expected.position
 WHERE a.attrelid=t.typrelid AND a.attnum>0 AND(a.attname::text IS DISTINCT FROM expected.name OR a.atttypid IS DISTINCT FROM expected.type_oid
 OR a.attcollation IS DISTINCT FROM expected.collation_oid OR a.atttypmod<>-1 OR a.attnotnull OR a.attisdropped
 OR a.atthasdef OR a.atthasmissing OR a.attgenerated<>'' OR a.attidentity<>'' OR a.attacl IS NOT NULL))
 FROM pg_type t WHERE t.oid='public.native_executable_contract_v1'::regtype
) IS NOT TRUE THEN RAISE EXCEPTION 'installation_executable_type_shape_changed';END IF;END $input_shape$;
DO $owner_roles$ DECLARE actor pg_roles;runtime pg_roles;owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);BEGIN
 SELECT * INTO STRICT actor FROM pg_roles WHERE rolname=current_user;SELECT * INTO STRICT runtime FROM pg_roles WHERE rolname='app_user';
 IF actor.oid<>owner_id OR actor.rolsuper OR actor.rolbypassrls OR runtime.rolsuper OR runtime.rolbypassrls OR runtime.rolcreaterole OR runtime.rolcreatedb OR runtime.rolreplication OR runtime.rolinherit
 OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=runtime.oid OR roleid=runtime.oid)
 OR EXISTS(SELECT 1 FROM pg_class WHERE relowner=runtime.oid) OR EXISTS(SELECT 1 FROM pg_proc WHERE proowner=runtime.oid) THEN RAISE EXCEPTION 'installation_runtime_role_unsafe';END IF;
END $owner_roles$;
-- Source-bound complete post8272 authentication, before conversion enrollment.

-- Catalog reads precede private installer state; public runtime routines retain
-- their independently declared pg_catalog,public,pg_temp configuration.
SET LOCAL search_path=pg_catalog,pg_temp,public;
-- Refuse executable DDL hooks before even the source-only comparator compiler.
DO $publication_profile$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_event_trigger WHERE evtenabled<>'D') THEN RAISE EXCEPTION 'publication_unreviewed_ddl_trigger';END IF;
END $publication_profile$;
CREATE TEMP TABLE pg_temp.a8314_publication_argument_defaults(profile text PRIMARY KEY,ast text NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.a8314_publication_default_profile_boolean_false(d0 pg_catalog.bool DEFAULT false) RETURNS pg_catalog.int4 LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS 'SELECT 1';
INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'boolean_false',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_boolean_false(boolean)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_boolean_false(boolean);
CREATE FUNCTION pg_temp.a8314_publication_default_profile_boolean_false_jsonb_null(d0 pg_catalog.bool DEFAULT false,d1 pg_catalog.jsonb DEFAULT NULL::pg_catalog.jsonb) RETURNS pg_catalog.int4 LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS 'SELECT 1';
INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'boolean_false_jsonb_null',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_boolean_false_jsonb_null(boolean,jsonb)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_boolean_false_jsonb_null(boolean,jsonb);
CREATE FUNCTION pg_temp.a8314_publication_default_profile_integer_zero(d0 pg_catalog.int4 DEFAULT 0) RETURNS pg_catalog.int4 LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS 'SELECT 1';
INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'integer_zero',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_integer_zero(integer)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_integer_zero(integer);
CREATE FUNCTION pg_temp.a8314_publication_default_profile_integer_zero_jsonb_null(d0 pg_catalog.int4 DEFAULT 0,d1 pg_catalog.jsonb DEFAULT NULL::pg_catalog.jsonb) RETURNS pg_catalog.int4 LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS 'SELECT 1';
INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'integer_zero_jsonb_null',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_integer_zero_jsonb_null(integer,jsonb)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_integer_zero_jsonb_null(integer,jsonb);
CREATE FUNCTION pg_temp.a8314_publication_default_profile_jsonb_null_jsonb_null(d0 pg_catalog.jsonb DEFAULT NULL::pg_catalog.jsonb,d1 pg_catalog.jsonb DEFAULT NULL::pg_catalog.jsonb) RETURNS pg_catalog.int4 LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS 'SELECT 1';
INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'jsonb_null_jsonb_null',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_jsonb_null_jsonb_null(jsonb,jsonb)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_jsonb_null_jsonb_null(jsonb,jsonb);
