INSERT INTO pg_temp.a8314_publication_argument_defaults SELECT 'uuid_null',p.proargdefaults::text FROM pg_proc p WHERE p.oid='pg_temp.a8314_publication_default_profile_uuid_null(uuid)'::regprocedure;
DROP FUNCTION pg_temp.a8314_publication_default_profile_uuid_null(uuid);

CREATE TEMP TABLE pg_temp.a8314_publication_compiled_expressions(profile text PRIMARY KEY,expression text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE pg_temp.a8314_publication_expression_source(
 workspace_id pg_catalog.uuid,id pg_catalog.uuid,session_id pg_catalog.uuid,format pg_catalog.int4,manifest_digest pg_catalog.text,
 flag pg_catalog.bool DEFAULT false,
 CONSTRAINT source_format CHECK(format OPERATOR(pg_catalog.=) ANY(ARRAY[1::pg_catalog.int4,2::pg_catalog.int4])),
 CONSTRAINT source_digest CHECK(manifest_digest OPERATOR(pg_catalog.~) '^[a-f0-9]{64}$'::pg_catalog.text),
 CONSTRAINT source_false CHECK(false));
INSERT INTO pg_temp.a8314_publication_compiled_expressions SELECT 'table_default_false',adbin::text FROM pg_attrdef
 WHERE adrelid='pg_temp.a8314_publication_expression_source'::regclass AND adnum=6;
INSERT INTO pg_temp.a8314_publication_compiled_expressions SELECT CASE conname WHEN 'source_format' THEN 'table_check_format'
 WHEN 'source_digest' THEN 'table_check_digest' WHEN 'source_false' THEN 'table_check_false' END,conbin::text FROM pg_constraint
 WHERE conrelid='pg_temp.a8314_publication_expression_source'::regclass;
DROP TABLE pg_temp.a8314_publication_expression_source;
CREATE TEMP TABLE pg_temp.a8314_publication_historical_projections(identity text PRIMARY KEY,template jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO pg_temp.a8314_publication_historical_projections VALUES ('application_scope_source_edges(uuid,text,uuid,text)','{"name":"application_scope_source_edges","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"DECLARE resource application_field_resources;observation application_field_observations;proof jsonb;\nBEGIN\n RETURN QUERY SELECT e.kind,e.id,e.version FROM knowledge_version_source_edges(w,k,i,v) e;\n IF k IS DISTINCT FROM ''application_field'' THEN RETURN;END IF;\n SELECT f.* INTO resource FROM application_field_resources f WHERE f.workspace_id=w AND f.id=i\n  AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history'';\n IF NOT FOUND THEN RETURN;END IF;\n SELECT o.* INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=i AND o.version=v;\n IF NOT FOUND OR observation.source_kind IS DISTINCT FROM ''memory'' OR observation.source_id IS DISTINCT FROM resource.resource_id\n  OR observation.record_version IS DISTINCT FROM resource.selected_version OR observation.source_version IS DISTINCT FROM resource.selected_version THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n proof:=application_memory_history_status(w,resource.resource_id,resource.selected_version);\n IF proof IS NULL THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n RETURN QUERY SELECT value->>''kind'',(value->>''id'')::uuid,value->>''version'' FROM jsonb_array_elements(proof->''roots'');\nEND\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('application_scope_source_edges_before_knowledge_versions(uuid,text,uuid,text)','{"name":"application_scope_source_edges_before_knowledge_versions","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"SELECT * FROM public.application_native_source_edges_dispatch(w,k,i,v)","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}}}'::jsonb),('knowledge_version_source_edges(uuid,text,uuid,text)','{"name":"knowledge_version_source_edges","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"\nDECLARE publication knowledge_entry_revision_publications;\nBEGIN\n IF k IS DISTINCT FROM ''knowledge_entry'' AND k IS DISTINCT FROM ''knowledge_entry_revision'' THEN\n  RETURN QUERY SELECT e.kind,e.id,e.version FROM application_scope_source_edges_before_knowledge_versions(w,k,i,v) e;RETURN;\n END IF;\n IF k=''knowledge_entry'' THEN\n  SELECT * INTO publication FROM knowledge_entry_revision_publications p WHERE p.workspace_id=w AND p.entry_id=i AND p.entry_version=v;\n  IF FOUND THEN RETURN QUERY SELECT ''knowledge_entry_revision''::text,publication.revision_id,''1''::text;RETURN;END IF;\n  IF EXISTS(SELECT 1 FROM knowledge_entry_revision_publications p JOIN knowledge_entry_scope_revisions r ON r.workspace_id=p.workspace_id AND r.id=p.revision_id\n   WHERE p.workspace_id=w AND p.entry_id=i AND r.revision_kind=''body'') THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END IF;\n RETURN QUERY SELECT e.kind,e.id,e.version FROM application_scope_source_edges_before_knowledge_versions(w,k,i,v) e\n  UNION SELECT c.source_kind,c.source_id,c.source_version FROM knowledge_entry_revision_capture_inputs c\n   WHERE k=''knowledge_entry_revision'' AND c.workspace_id=w AND c.revision_id=i AND v=''1''\n  UNION SELECT ''knowledge_entry''::text,p.entry_id,p.entry_version FROM knowledge_entry_revision_publications p\n   WHERE k=''knowledge_entry_revision'' AND p.workspace_id=w AND p.revision_id=i AND v=''1'';\nEND ","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('scope_source_ancestors(uuid,text,uuid)','{"name":"scope_source_ancestors","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"\nBEGIN\n IF k=''workflow_run'' THEN\n  RETURN QUERY WITH RECURSIVE consumers(id) AS (\n   SELECT i UNION SELECT s.run_id FROM workflow_run_copy_sources s JOIN consumers c ON c.id=s.source_run_id WHERE s.workspace_id=w\n  ) SELECT id FROM consumers;\n ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_workflow_run(w,k,i); END IF;\nEND ","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('scope_source_ancestors_before_workflow_run(uuid,text,uuid)','{"name":"scope_source_ancestors_before_workflow_run","config":["search_path=public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"\nBEGIN\n IF k=''browser_session'' THEN RETURN QUERY SELECT id FROM sessions WHERE workspace_id=w AND id=i;\n ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_browser_session(w,k,i);\n END IF;\nEND ","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('scope_source_ancestors_before_browser_session(uuid,text,uuid)','{"name":"scope_source_ancestors_before_browser_session","config":["search_path=public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"\nBEGIN\n IF k=''browser_profile'' THEN\n  RETURN QUERY SELECT id FROM browser_profiles WHERE workspace_id=w AND id=i;\n ELSE RETURN QUERY SELECT * FROM scope_source_ancestors_before_browser_profile(w,k,i);\n END IF;\nEND ","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('scope_source_ancestors_before_browser_profile(uuid,text,uuid)','{"name":"scope_source_ancestors_before_browser_profile","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"\nDECLARE tab text; versioned boolean;\nBEGIN\n  -- These are the same workspace-scoped column walks, with static plans.\n  IF p_kind=''memory'' THEN\n    RETURN QUERY WITH RECURSIVE ancestry(id) AS (\n      SELECT id FROM memories WHERE workspace_id=p_workspace AND id=p_id\n      UNION SELECT r.id FROM memories r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace\n    ) SELECT id FROM ancestry;\n    RETURN;\n  ELSIF p_kind=''session_message'' THEN\n    RETURN QUERY SELECT id FROM session_messages WHERE workspace_id=p_workspace AND id=p_id;\n    RETURN;\n  ELSIF p_kind=''session_context_revision'' THEN\n    RETURN QUERY SELECT id FROM session_context_scope_revisions WHERE workspace_id=p_workspace AND id=p_id;\n    RETURN;\n  END IF;\n  IF p_kind IN(''crm_event'',''memory_verification'',''brain_verification'',''correction_audit'') THEN RETURN QUERY SELECT p_id; RETURN; END IF;\n  tab=scope_source_table(p_kind);\n  IF tab IS NULL THEN RAISE EXCEPTION ''scope_evidence_missing''; END IF;\n  SELECT EXISTS(\n    SELECT 1 FROM pg_attribute\n     WHERE attrelid=format(''%I'',tab)::regclass AND attname=''superseded_by'' AND NOT attisdropped\n  ) INTO versioned;\n\n  -- Retain the live canonical mapping and column-shape decision above.\n  -- Schema changes or a replacement mapping use the original dynamic branch.\n  IF p_kind=''workspace_file'' AND tab=''workspace_files'' AND versioned THEN\n    RETURN QUERY WITH RECURSIVE ancestry(id) AS (\n      SELECT id FROM workspace_files WHERE workspace_id=p_workspace AND id=p_id\n      UNION SELECT r.id FROM workspace_files r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=p_workspace\n    ) SELECT id FROM ancestry;\n    RETURN;\n  END IF;\n  IF NOT versioned THEN\n    RETURN QUERY EXECUTE format(''SELECT id FROM %I WHERE workspace_id=$2 AND id=$1'',tab) USING p_id,p_workspace;\n    RETURN;\n  END IF;\n  RETURN QUERY EXECUTE format(''WITH RECURSIVE ancestry(id) AS (\n    SELECT id FROM %I WHERE workspace_id=$2 AND id=$1\n    UNION SELECT r.id FROM %I r JOIN ancestry a ON r.superseded_by=a.id WHERE r.workspace_id=$2)\n    SELECT id FROM ancestry'',tab,tab) USING p_id,p_workspace;\nEND;\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb),('scope_source_table(text)','{"name":"scope_source_table","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":false,"volatility":"i","strict":false,"parallel":"u","body":"\n SELECT CASE WHEN k=''knowledge_entry_revision'' THEN ''knowledge_entry_scope_revisions'' ELSE scope_source_table_before_knowledge_versions(k) END\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}}}'::jsonb),('scope_source_table_before_knowledge_versions(text)','{"name":"scope_source_table_before_knowledge_versions","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":false,"volatility":"i","strict":false,"parallel":"u","body":"\n SELECT CASE WHEN k=''session_context_revision'' THEN ''session_context_scope_revisions'' ELSE scope_source_table_before_persistent_context(k) END\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}}}'::jsonb),('scope_source_table_before_persistent_context(text)','{"name":"scope_source_table_before_persistent_context","config":null,"securityDefiner":false,"volatility":"i","strict":false,"parallel":"u","body":"\n SELECT CASE k WHEN ''blueprint_record'' THEN ''blueprint_records''\n WHEN ''recording'' THEN ''recordings'' WHEN ''file_segment'' THEN ''file_segments''\n WHEN ''transcript_segment'' THEN ''transcript_segments'' ELSE scope_source_table_before_media(k) END\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}}}'::jsonb),('scope_source_table_before_media(text)','{"name":"scope_source_table_before_media","config":null,"securityDefiner":false,"volatility":"i","strict":false,"parallel":"u","body":"\n  SELECT CASE p_kind WHEN ''memory'' THEN ''memories'' WHEN ''entity'' THEN ''entities''\n    WHEN ''entity_link'' THEN ''entity_links'' WHEN ''task'' THEN ''tasks''\n    WHEN ''workspace_file'' THEN ''workspace_files'' WHEN ''episode'' THEN ''episodes''\n    WHEN ''knowledge_entry'' THEN ''knowledge_entries'' WHEN ''kb_chunk'' THEN ''kb_chunks''\n    WHEN ''session_message'' THEN ''session_messages''\n    WHEN ''feedback_event'' THEN ''analytics_events''\n    WHEN ''workspace_skill_revision'' THEN ''workspace_skill_scope_revisions'' END\n","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}}}'::jsonb),('application_native_source_edges_dispatch(uuid,text,uuid,text)','{"name":"application_native_source_edges_dispatch","config":["search_path=pg_catalog, public, pg_temp"],"securityDefiner":true,"volatility":"v","strict":false,"parallel":"u","body":"BEGIN\n IF k=''application_field'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT o.source_kind,o.source_id,o.source_version FROM application_field_observations o\n  WHERE k=''application_field'' AND o.workspace_id=w AND o.resource_id=i AND o.version=v\n UNION\n SELECT s.source_kind,s.source_id,s.source_version FROM application_field_observation_sources s\n  WHERE k=''application_field'' AND s.workspace_id=w AND s.resource_id=i AND s.version=v;\n ELSIF k=''file_segment'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT ''workspace_file'',wf.id,wf.scope_version::text FROM file_segments fs\n  JOIN workspace_files wf ON wf.id=fs.file_id AND wf.workspace_id=fs.workspace_id\n  WHERE k=''file_segment'' AND fs.workspace_id=w AND fs.id=i;\n ELSIF k=''workflow_run'' THEN\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i\n UNION\n SELECT observed.value->>''resourceKind'',(observed.value->>''resourceId'')::uuid,observed.value->>''version''\n  FROM jsonb_array_elements(CASE WHEN k=''workflow_run'' THEN read_workflow_derivation_inputs(w,i) ELSE ''[]''::jsonb END) input\n  CROSS JOIN LATERAL jsonb_array_elements(coalesce(input#>''{evidence,sources}'',''[]''::jsonb)\n   ||CASE WHEN jsonb_typeof(input->''blueprintSource'')=''object'' THEN jsonb_build_array(input->''blueprintSource'') ELSE ''[]''::jsonb END) observed(value);\n ELSE\n RETURN QUERY SELECT s.source_kind,s.source_id,s.source_version FROM scope_derivations d\n  JOIN scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id\n  WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i\n UNION\n SELECT k,prior_id,v FROM unnest(CASE WHEN scope_source_table(k) IS NOT NULL\n  THEN ARRAY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i;\n END IF;\nEND","namespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"language":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}}}'::jsonb);

CREATE TEMP TABLE pg_temp.a8314_publication_reviewed_contracts(signature text PRIMARY KEY,metadata jsonb NOT NULL,fingerprint text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE pg_temp.a8314_publication_expected_current(signature text PRIMARY KEY,metadata jsonb NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE pg_temp.a8314_publication_successor_templates(signature text PRIMARY KEY,parts jsonb NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE pg_temp.a8314_publication_legacy_acl_repairs(signature text PRIMARY KEY,canonical_acl aclitem[] NOT NULL) ON COMMIT DROP;
DO $legacy_default$
DECLARE owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 runtime_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');actual aclitem[];present boolean;
BEGIN
 IF runtime_id IS NULL OR EXISTS(SELECT 1 FROM pg_default_acl WHERE defaclrole=owner_id AND defaclobjtype='f' AND defaclnamespace=0)
 THEN RAISE EXCEPTION 'publication_legacy_function_default_changed';END IF;
 SELECT defaclacl INTO actual FROM pg_default_acl WHERE defaclrole=owner_id AND defaclobjtype='f' AND defaclnamespace='public'::regnamespace;
 present:=FOUND;
 IF present AND actual IS DISTINCT FROM ARRAY[makeaclitem(runtime_id,owner_id,'EXECUTE',false)]
 THEN RAISE EXCEPTION 'publication_legacy_function_default_changed';END IF;
END $legacy_default$;
CREATE FUNCTION pg_temp.a8314_publication_authenticate_acl(signature text,actual pg_catalog.pg_proc,expected_acl jsonb,actual_acl jsonb) RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $authenticate_acl$
DECLARE profile constant jsonb:='{"format":1,"schema":"public","runtime":"app_user","defaultHistory":{"file":"81110_legacy_function_execute_privileges.sql","sha256":"3caf80819fccc0b7bd6e731be85b8c75f56061e07063b802b7f58ea92ad36227"},"functions":[{"signature":"crm_install_erasure_capture()","publicExecute":false,"source":[{"file":"522_crm_erasure_journal.sql","sha256":"e2eaa62ac310476040249728e3fa889d04154147842f35cb9130ecad736c22f9"},{"file":"8271_refresh_recovery_capture.sql","sha256":"e5a45a266160672f84a7a28a35338ea6b138f378b4ff72327e909d03e04e80b8"}]},{"signature":"file_session_binding_allows(uuid)","publicExecute":true,"source":[{"file":"637_file_publication_bindings.sql","sha256":"bf2b613f965c51551b5734f0db53e15f0bd443e223fcb18b1a47dc6552d82e73"}]},{"signature":"media_parent_visible(text,uuid)","publicExecute":true,"source":[{"file":"643_recording_segment_publication.sql","sha256":"bb59dcbc9e0da3ba9e15048911d7095077a8f0d9fcff2f7a276bfa5f112a735e"}]},{"signature":"office_output_file_allows(uuid,boolean)","publicExecute":true,"source":[{"file":"639_office_generation_publication.sql","sha256":"235c61d306da2030c6e3c0b1dee564c5a74a1130c0a905f0e22325052300b011"}]},{"signature":"pdf_intake_file_visible(uuid)","publicExecute":true,"source":[{"file":"638_pdf_intake_publication.sql","sha256":"30ac58e4a5ad48542ab646ec711d11f2de958c2464dd54d38dea86196d7785ac"}]},{"signature":"project_labels_allowed(jsonb,uuid,text[],boolean)","publicExecute":true,"source":[{"file":"749_project_shared_spaces.sql","sha256":"65d9bb836c45ee68f89fdbafc36eaa68ff686cd4cf07b83f720745785bb297e5"}]},{"signature":"read_session_authority_facts(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean)","publicExecute":false,"source":[{"file":"8269_canonical_conversation_publication.sql","sha256":"d17106c521097797416a2a51ba53d07fce978ea1da587dae82d066da4575ec39"}]},{"signature":"recording_transcript_file_allows(uuid)","publicExecute":true,"source":[{"file":"643_recording_segment_publication.sql","sha256":"bb59dcbc9e0da3ba9e15048911d7095077a8f0d9fcff2f7a276bfa5f112a735e"}]}]}'::jsonb;binding jsonb;legacy_acl jsonb;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 runtime_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');legacy_raw aclitem[];canonical_raw aclitem[];
BEGIN
 IF actual_acl IS NOT DISTINCT FROM expected_acl THEN RETURN;END IF;
 SELECT value INTO binding FROM jsonb_array_elements(profile->'functions') WHERE value->>'signature'=signature;
 IF binding IS NULL
 THEN RAISE EXCEPTION 'publication_predecessor_changed: %',signature;END IF;
 SELECT jsonb_agg(value ORDER BY value->>'grantee' COLLATE "C") INTO legacy_acl
 FROM jsonb_array_elements(expected_acl||jsonb_build_array(jsonb_build_object('grantee','app_user','grantor','OWNER','privilege','EXECUTE','grantable',false)));
 -- The historical per-schema default compiles entries in grantee-OID order.
 -- Neither expected grants nor their raw order are copied from installed ACLs.
 SELECT array_agg(makeaclitem(grantee,owner_id,'EXECUTE',false) ORDER BY grantee) INTO legacy_raw
 FROM(SELECT CASE value->>'grantee' WHEN 'OWNER' THEN owner_id WHEN 'PUBLIC' THEN 0::oid END grantee
  FROM jsonb_array_elements(expected_acl) UNION ALL SELECT runtime_id) grants;
 IF actual_acl IS DISTINCT FROM legacy_acl OR (actual).proacl IS DISTINCT FROM legacy_raw
 THEN RAISE EXCEPTION 'publication_predecessor_changed: %',signature;END IF;
 SELECT array_agg(makeaclitem(grantee,owner_id,'EXECUTE',false) ORDER BY grantee) INTO canonical_raw
 FROM(SELECT CASE value->>'grantee' WHEN 'OWNER' THEN owner_id WHEN 'PUBLIC' THEN 0::oid END grantee
  FROM jsonb_array_elements(expected_acl)) grants;
 INSERT INTO pg_temp.a8314_publication_legacy_acl_repairs VALUES(signature,canonical_raw);
END $authenticate_acl$;

-- Render ONLY reviewed positions. All other body bytes and metadata fields are literal.
CREATE FUNCTION pg_temp.a8314_publication_slot(slot jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $slot$
DECLARE value text;pieces text[];projection jsonb;owner_id oid;runtime_id oid;owner_name text;
BEGIN
 IF slot-ARRAY['kind','identity','encoding','relation','triggerType','internal']<>'{}' OR NOT slot ?& ARRAY['kind','identity']
 THEN RAISE EXCEPTION 'publication_unknown_slot';END IF;
 CASE slot->>'kind'
  WHEN 'owner' THEN SELECT relowner::text INTO STRICT value FROM pg_class WHERE oid='public.sessions'::regclass;
  WHEN 'namespace' THEN value:=to_regnamespace(slot->>'identity')::oid::text;
  WHEN 'language' THEN SELECT oid::text INTO STRICT value FROM pg_language WHERE lanname=slot->>'identity';
  WHEN 'function' THEN value:=to_regprocedure(slot->>'identity')::oid::text;
  WHEN 'fingerprint' THEN SELECT encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') INTO STRICT value FROM pg_proc p WHERE p.oid=to_regprocedure(slot->>'identity');
  WHEN 'argumentDefaults' THEN SELECT ast INTO STRICT value FROM pg_temp.a8314_publication_argument_defaults WHERE profile=slot->>'identity';
  WHEN 'catalogExpression' THEN SELECT expression INTO STRICT value FROM pg_temp.a8314_publication_compiled_expressions WHERE profile=slot->>'identity';
  WHEN 'columnDefaultOid' THEN
   pieces:=string_to_array(slot->>'identity','.');
   SELECT d.oid::text INTO STRICT value FROM pg_attrdef d JOIN pg_attribute a ON a.attrelid=d.adrelid AND a.attnum=d.adnum
    WHERE d.adrelid=to_regclass(pieces[1]||'.'||pieces[2]) AND a.attname=pieces[3] AND NOT a.attisdropped;
  WHEN 'historicalProjection' THEN
   SELECT template INTO STRICT projection FROM pg_temp.a8314_publication_historical_projections WHERE identity=slot->>'identity';
   value:=encode(sha256(convert_to(pg_temp.a8314_publication_json(projection)::text,'UTF8')),'hex');
  WHEN 'relation' THEN value:=to_regclass(slot->>'identity')::oid::text;
  WHEN 'type' THEN value:=to_regtype(slot->>'identity')::oid::text;
  WHEN 'constraintNamespace' THEN
   pieces:=string_to_array(slot->>'identity','.');
   IF cardinality(pieces)<>3 OR pieces[1]<>'public' THEN RAISE EXCEPTION 'publication_constraint_namespace_binding_changed';END IF;
   PERFORM 1 FROM pg_constraint WHERE conrelid=to_regclass(pieces[1]||'.'||pieces[2]) AND conname=pieces[3] AND connamespace='public'::regnamespace;
   IF NOT FOUND THEN RAISE EXCEPTION 'publication_constraint_namespace_changed: %',slot->>'identity';END IF;
   value:='public'::regnamespace::oid::text;
  WHEN 'constraint' THEN pieces:=string_to_array(slot->>'identity','.');SELECT oid::text INTO STRICT value FROM pg_constraint WHERE conrelid=to_regclass(pieces[1]||'.'||pieces[2]) AND conname=pieces[3];
  WHEN 'trigger' THEN pieces:=string_to_array(slot->>'identity','.');SELECT oid::text INTO STRICT value FROM pg_trigger WHERE tgrelid=to_regclass(pieces[1]||'.'||pieces[2]) AND tgname=pieces[3];
  WHEN 'constraintTriggerOid','constraintTriggerName' THEN
   pieces:=string_to_array(slot->>'identity','.');
   SELECT CASE WHEN slot->>'kind'='constraintTriggerOid' THEN t.oid::text ELSE t.tgname::text END INTO STRICT value
    FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint
    WHERE c.conrelid=to_regclass(pieces[1]||'.'||pieces[2]) AND c.conname=pieces[3]
     AND t.tgrelid=to_regclass(slot->>'relation') AND t.tgtype=(slot->>'triggerType')::integer AND t.tgisinternal=(slot->>'internal')::boolean;
  WHEN 'ownerAcl' THEN
   IF slot->>'identity'!~'^[A-Za-z*]*$' THEN RAISE EXCEPTION 'publication_acl_slot_invalid';END IF;
   SELECT quote_ident(pg_get_userbyid(relowner))||'='||(slot->>'identity')||'/'||quote_ident(pg_get_userbyid(relowner)) INTO STRICT value FROM pg_class WHERE oid='public.sessions'::regclass;
  WHEN 'relationDefaultAcl' THEN
   IF slot->>'identity' NOT IN('public.scope_derivations','public.scope_derivation_sources') THEN RAISE EXCEPTION 'publication_relation_acl_profile_changed';END IF;
   SELECT relowner,pg_get_userbyid(relowner) INTO STRICT owner_id,owner_name FROM pg_class WHERE oid='public.sessions'::regclass;
   SELECT oid INTO STRICT runtime_id FROM pg_roles WHERE rolname='app_user';
   -- Both maintained bootstraps apply this closed table default ACL. Its entry
   -- order follows the declared grantee OIDs, never target relacl contents.
   SELECT jsonb_agg(entry.acl ORDER BY entry.grantee)::text INTO value FROM(VALUES
    (owner_id,quote_ident(owner_name)||'=arwdDxtm/'||quote_ident(owner_name)),
    (runtime_id,quote_ident('app_user')||'=arwd/'||quote_ident(owner_name))) entry(grantee,acl);
