CREATE FUNCTION pg_temp.a8314_publication_json(template jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $render$
DECLARE result jsonb;entry record;rendered_value text;
