-- [COMP:api/native-turn-frame] Authenticate the retained guard before invocation.
DO $authenticate_retained_guard$
DECLARE actual pg_proc;reference pg_proc;expected jsonb;relation pg_class;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 body constant text:='
 SELECT native_turn_helpers_current() AND EXISTS(SELECT 1 FROM pg_class r WHERE r.oid=''native_retained_contract_helpers''::regclass
  AND r.relkind=''r'' AND r.relpersistence=''p'' AND r.relrowsecurity AND NOT r.relforcerowsecurity
  AND r.relowner=(SELECT oid FROM pg_roles WHERE rolname=current_user)
  AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(r.relacl,acldefault(''r'',r.relowner))) a WHERE a.grantee<>r.relowner OR a.grantor<>r.relowner)
  AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=r.oid)
  AND (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped)=ARRAY[''signature'',''fingerprint'']
  AND NOT EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=r.oid AND attnum>0 AND NOT attisdropped AND (atttypid<>''text''::regtype OR NOT attnotnull)))
 AND array_agg(h.signature ORDER BY h.signature)=ARRAY[''native_retained_helpers_current()'',''native_turn_privacy_edges(uuid,jsonb)'']::text[]
 AND bool_and(p.oid IS NOT NULL AND h.fingerprint=encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex''))
 FROM native_retained_contract_helpers h LEFT JOIN pg_proc p ON p.oid=to_regprocedure(''public.''||h.signature)
';
BEGIN
 -- Reading the private registry must not execute an unreviewed RLS policy/rule.
 SELECT * INTO relation FROM pg_class WHERE oid=to_regclass('public.native_retained_contract_helpers');
 IF relation.oid IS NULL OR relation.relkind<>'r' OR relation.relpersistence<>'p'
  OR relation.relowner<>owner_id OR NOT relation.relrowsecurity OR relation.relforcerowsecurity
  OR coalesce(relation.relacl,acldefault('r',owner_id)) IS DISTINCT FROM acldefault('r',owner_id)
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=relation.oid)
  OR EXISTS(SELECT 1 FROM pg_rewrite WHERE ev_class=relation.oid)
  OR (SELECT jsonb_agg(jsonb_build_array(attnum,attname,atttypid,atttypmod,attnotnull,attgenerated,attidentity,attisdropped,attacl) ORDER BY attnum)
   FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0) IS DISTINCT FROM
   '[[1,"signature","25",-1,true,"","",false,null],[2,"fingerprint","25",-1,true,"","",false,null]]'::jsonb
  OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid=relation.oid AND attnum>0
   AND (atthasdef OR attcollation<>'pg_catalog."default"'::regcollation))
 THEN RAISE EXCEPTION 'publication_retained_registry_changed';END IF;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.native_retained_helpers_current()');
 IF actual.oid IS NULL THEN RAISE EXCEPTION 'publication_retained_guard_missing';END IF;
 -- This declaration is reconstructed from the immutable source and named
 -- retirement, never from actual.prosrc or an installed registry record.
 EXECUTE format('CREATE FUNCTION pg_temp.a8314_publication_retained_guard_reference() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS %L',body);
 SELECT * INTO STRICT reference FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname='a8314_publication_retained_guard_reference';
 expected:=(to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])||jsonb_build_object(
  'oid',actual.oid,'proname','native_retained_helpers_current','pronamespace','public'::regnamespace::oid,
  'proowner',owner_id,'proacl',ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)]);
 IF (actual.prosrc COLLATE "C") IS DISTINCT FROM (body COLLATE "C") OR to_jsonb(actual) IS DISTINCT FROM expected
 THEN RAISE EXCEPTION 'publication_retained_guard_changed';END IF;
 INSERT INTO pg_temp.a8314_publication_reviewed_contracts VALUES('native_retained_helpers_current()',expected,encode(sha256(convert_to(expected::text,'UTF8')),'hex'));
 INSERT INTO pg_temp.a8314_publication_expected_current VALUES('native_retained_helpers_current()',expected);
 INSERT INTO pg_temp.a8314_publication_successor_templates VALUES('native_retained_helpers_current()',jsonb_build_array(body));
 DROP FUNCTION pg_temp.a8314_publication_retained_guard_reference();
END $authenticate_retained_guard$;



CREATE FUNCTION pg_temp.a8314_publication_reference_schema() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $reference$
BEGIN
 IF to_regnamespace('a8314_publication_source_reference') IS NOT NULL THEN
  RAISE EXCEPTION 'publication_source_reference_schema_exists';END IF;
 EXECUTE 'CREATE SCHEMA a8314_publication_source_reference';
 IF NOT EXISTS(SELECT FROM pg_namespace WHERE nspname='a8314_publication_source_reference'
  AND nspowner=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  AND coalesce(nspacl,acldefault('n',nspowner)) IS NOT DISTINCT FROM acldefault('n',nspowner))
 THEN RAISE EXCEPTION 'publication_reference_schema_private_profile_changed';END IF;
 EXECUTE $ddl$CREATE TABLE a8314_publication_source_reference.native_conversation_publications(
 id uuid PRIMARY KEY,
 workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
 session_id uuid NOT NULL REFERENCES public.sessions(id) ON DELETE CASCADE,
 input_message_id uuid NOT NULL REFERENCES public.session_messages(id) ON DELETE CASCADE,
 actor_user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
 assistant_id uuid NOT NULL REFERENCES public.assistants(id) ON DELETE CASCADE,
 turn_token uuid NOT NULL,slot text NOT NULL CHECK(slot='buffered_transcript'),
 command_format integer NOT NULL CHECK(command_format IN(1,2)),command_digest text NOT NULL CHECK(command_digest~'^[a-f0-9]{64}$'),
 stopped boolean NOT NULL,frame_ids uuid[] NOT NULL CHECK(cardinality(frame_ids) BETWEEN 1 AND 2),
 leader_frame_id uuid NOT NULL,expected_output_count integer NOT NULL CHECK(expected_output_count BETWEEN 1 AND 513),
 annotation_user_id uuid,annotation_assistant_id uuid,outputs jsonb,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),completed_at timestamptz,
 requested_stopped boolean,terminal_descriptor jsonb,terminal_outputs jsonb,
 CONSTRAINT native_conversation_terminal_format CHECK(
  command_format=1 AND requested_stopped IS NULL AND terminal_descriptor IS NULL AND terminal_outputs IS NULL
  OR command_format=2 AND requested_stopped IS NOT NULL AND (NOT requested_stopped OR stopped)
   AND (terminal_descriptor IS NULL)=(terminal_outputs IS NULL) AND (NOT stopped OR terminal_descriptor IS NULL)),
 CONSTRAINT native_conversation_publication_slot UNIQUE(workspace_id,session_id,turn_token,slot),
 CONSTRAINT native_conversation_publication_result CHECK((outputs IS NULL)=(completed_at IS NULL)))$ddl$;
 EXECUTE 'CREATE INDEX native_conversation_publication_discovery ON a8314_publication_source_reference.native_conversation_publications(workspace_id,session_id,actor_user_id,assistant_id,created_at,id)';
 EXECUTE 'REVOKE ALL ON a8314_publication_source_reference.native_conversation_publications FROM PUBLIC,app_user';
 EXECUTE 'ALTER TABLE a8314_publication_source_reference.native_conversation_publications ENABLE ROW LEVEL SECURITY';
 EXECUTE $ddl$CREATE TABLE a8314_publication_source_reference.native_turn_publication_work(publication_id uuid,
  CONSTRAINT native_turn_publication_operation FOREIGN KEY(publication_id)
  REFERENCES a8314_publication_source_reference.native_conversation_publications(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED)$ddl$;
 EXECUTE 'REVOKE ALL ON a8314_publication_source_reference.native_turn_publication_work FROM PUBLIC,app_user';
 IF EXISTS(SELECT FROM pg_class WHERE relnamespace='a8314_publication_source_reference'::regnamespace
  AND relkind='r' AND (relowner<>(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
   OR relacl IS DISTINCT FROM acldefault('r',relowner)))
 THEN RAISE EXCEPTION 'publication_reference_table_private_profile_changed';END IF;
 EXECUTE 'CREATE CONSTRAINT TRIGGER native_conversation_publication_complete AFTER INSERT ON a8314_publication_source_reference.native_conversation_publications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.native_conversation_publication_complete()';
 EXECUTE 'CREATE TRIGGER native_conversation_publication_immutable BEFORE UPDATE ON a8314_publication_source_reference.native_conversation_publications FOR EACH ROW EXECUTE FUNCTION public.native_conversation_publication_immutable()';
 EXECUTE 'CREATE TRIGGER crm_recovery_capture AFTER INSERT OR UPDATE OR DELETE ON a8314_publication_source_reference.native_conversation_publications FOR EACH ROW EXECUTE FUNCTION public.crm_capture_erasure_effect()';
END $reference$;

CREATE FUNCTION pg_temp.a8314_publication_map_reference_relation(relation_id oid) RETURNS oid
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE relation_name name;namespace_name name;mapped oid;
BEGIN
 IF relation_id=0 THEN RETURN 0;END IF;
 SELECT c.relname,n.nspname INTO STRICT relation_name,namespace_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid=relation_id;
 IF namespace_name<>'a8314_publication_source_reference' THEN RETURN relation_id;END IF;
 mapped:=to_regclass(format('public.%I',relation_name));
 IF mapped IS NULL THEN RAISE EXCEPTION 'publication_reference_relation_missing: %',relation_name;END IF;
 RETURN mapped;
END $map$;
CREATE FUNCTION pg_temp.a8314_publication_map_reference_constraint(constraint_id oid) RETURNS oid
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE original pg_constraint;mapped oid;
BEGIN
 IF constraint_id=0 THEN RETURN 0;END IF;
 SELECT * INTO STRICT original FROM pg_constraint WHERE oid=constraint_id;
 SELECT oid INTO STRICT mapped FROM pg_constraint WHERE conrelid=pg_temp.a8314_publication_map_reference_relation((original).conrelid) AND conname=(original).conname;
 RETURN mapped;
END $map$;
CREATE FUNCTION pg_temp.a8314_publication_map_reference_attributes(relation_id oid,attributes smallint[]) RETURNS smallint[]
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE mapped smallint;
BEGIN
 IF relation_id<>'a8314_publication_source_reference.native_turn_publication_work'::regclass OR attributes IS NULL THEN RETURN attributes;END IF;
 IF attributes<>ARRAY[1]::smallint[] THEN RAISE EXCEPTION 'publication_reference_attribute_shape';END IF;
 SELECT attnum INTO STRICT mapped FROM pg_attribute WHERE attrelid='public.native_turn_publication_work'::regclass AND attname='publication_id' AND NOT attisdropped;
 RETURN ARRAY[mapped];
END $map$;
CREATE FUNCTION pg_temp.a8314_publication_reference_constraint_record(original pg_constraint) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
 SELECT (to_jsonb(original)-ARRAY['oid','connamespace','conrelid','conindid','confrelid','conkey','confkey'])||jsonb_build_object(
  'oid',pg_temp.a8314_publication_map_reference_constraint((original).oid),'connamespace','public'::regnamespace::oid,
  'conrelid',pg_temp.a8314_publication_map_reference_relation((original).conrelid),
  'conindid',pg_temp.a8314_publication_map_reference_relation((original).conindid),
  'confrelid',pg_temp.a8314_publication_map_reference_relation((original).confrelid),
  'conkey',pg_temp.a8314_publication_map_reference_attributes((original).conrelid,(original).conkey),
  'confkey',pg_temp.a8314_publication_map_reference_attributes((original).confrelid,(original).confkey))
$map$;
CREATE FUNCTION pg_temp.a8314_publication_reference_trigger_record(original pg_trigger) RETURNS jsonb
LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $map$
DECLARE mapped oid;trigger_name text;prefix text;
BEGIN
 IF (original).tgisinternal THEN
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.a8314_publication_map_reference_relation((original).tgrelid)
   AND tgconstraint=pg_temp.a8314_publication_map_reference_constraint((original).tgconstraint) AND tgtype=(original).tgtype AND tgisinternal;
  IF right((original).tgname::text,length((original).oid::text))<>(original).oid::text THEN RAISE EXCEPTION 'publication_reference_internal_name';END IF;
  prefix:=left((original).tgname::text,length((original).tgname::text)-length((original).oid::text));
  IF prefix NOT IN('RI_ConstraintTrigger_a_','RI_ConstraintTrigger_c_') THEN RAISE EXCEPTION 'publication_reference_internal_kind';END IF;
  trigger_name:=prefix||mapped::text;
 ELSE
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.a8314_publication_map_reference_relation((original).tgrelid) AND tgname=(original).tgname;
  trigger_name:=(original).tgname;
 END IF;
 RETURN (to_jsonb(original)-ARRAY['oid','tgname','tgrelid','tgconstraint','tgconstrrelid','tgconstrindid'])||jsonb_build_object(
  'oid',mapped,'tgname',trigger_name,'tgrelid',pg_temp.a8314_publication_map_reference_relation((original).tgrelid),
  'tgconstraint',pg_temp.a8314_publication_map_reference_constraint((original).tgconstraint),
  'tgconstrrelid',pg_temp.a8314_publication_map_reference_relation((original).tgconstrrelid),
  'tgconstrindid',pg_temp.a8314_publication_map_reference_relation((original).tgconstrindid));
END $map$;

CREATE FUNCTION pg_temp.a8314_publication_relation_semantics(relation_record pg_class) RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $shape$
 SELECT jsonb_build_object('name',(relation_record).relname,'owner',(relation_record).relowner,'kind',(relation_record).relkind,
  'persistence',(relation_record).relpersistence,'am',(relation_record).relam,'tablespace',(relation_record).reltablespace,
  'options',(relation_record).reloptions,'replicaIdentity',(relation_record).relreplident,'ofType',(relation_record).reloftype,
  'attributes',(relation_record).relnatts,'checks',(relation_record).relchecks,'hasIndex',(relation_record).relhasindex,
  'hasRules',(relation_record).relhasrules,'hasTriggers',(relation_record).relhastriggers,'hasSubclass',(relation_record).relhassubclass,
  'rls',(relation_record).relrowsecurity,'forceRls',(relation_record).relforcerowsecurity,'partition',(relation_record).relispartition,
  'partitionBound',(relation_record).relpartbound,'acl',(relation_record).relacl)
$shape$;

CREATE FUNCTION pg_temp.a8314_publication_schema_details() RETURNS jsonb
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $details$
 SELECT jsonb_build_object(
  'header',pg_temp.a8314_publication_relation_semantics(c),
  'columns',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid=c.oid AND a.attnum>0),
  'constraints',(SELECT jsonb_agg(to_jsonb(k) ORDER BY k.conname COLLATE "C") FROM pg_constraint k WHERE k.conrelid=c.oid),
  'indexes',(SELECT jsonb_agg(jsonb_build_object('index',to_jsonb(i),'relation',pg_temp.a8314_publication_relation_semantics(r)) ORDER BY r.relname COLLATE "C")
   FROM pg_index i JOIN pg_class r ON r.oid=i.indexrelid WHERE i.indrelid=c.oid),
  'defaults',(SELECT jsonb_agg(to_jsonb(d) ORDER BY d.adnum) FROM pg_attrdef d WHERE d.adrelid=c.oid),
  'triggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t WHERE t.tgrelid=c.oid),
  'rules',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.oid) FROM pg_rewrite r WHERE r.ev_class=c.oid),
  'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.oid) FROM pg_policy p WHERE p.polrelid=c.oid),
  'inheritance',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.inhrelid,i.inhseqno) FROM pg_inherits i WHERE i.inhrelid=c.oid OR i.inhparent=c.oid),
  'workColumn',(SELECT to_jsonb(a) FROM pg_attribute a WHERE a.attrelid='public.native_turn_publication_work'::regclass AND a.attname='publication_id' AND NOT a.attisdropped),
  'workConstraint',(SELECT to_jsonb(k) FROM pg_constraint k WHERE k.conrelid='public.native_turn_publication_work'::regclass AND k.conname='native_turn_publication_operation'),
  'workTriggers',(SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
   WHERE k.conrelid='public.native_turn_publication_work'::regclass AND k.conname='native_turn_publication_operation' AND t.tgrelid=k.conrelid))
 FROM pg_class c WHERE c.oid='public.native_conversation_publications'::regclass
$details$;
CREATE TEMP TABLE pg_temp.a8314_publication_before_installer_details(snapshot jsonb NOT NULL) ON COMMIT DROP;

-- PG18 back branches reserve pg_attver for the engine's durable attribute
-- version (XLogRecPtr/uint64). Only this typed installation identity differs
-- between independently compiled objects. Every other option stays literal;
-- the authenticated before/after snapshot below retains the FULL actual value.
CREATE FUNCTION pg_temp.a8314_publication_attribute_semantics(attribute_record pg_attribute) RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $attribute$
DECLARE option_value text;options text[];versions integer:=0;decimal_value text;
BEGIN
 IF (attribute_record).attoptions IS NULL THEN RETURN to_jsonb(attribute_record);END IF;
 options:=ARRAY[]::text[];
 FOREACH option_value IN ARRAY (attribute_record).attoptions LOOP
  IF split_part(option_value,'=',1)='pg_attver' THEN
   versions:=versions+1;decimal_value:=substring(option_value FROM length('pg_attver=')+1);
   IF versions>1 OR option_value!~'^pg_attver=(0|[1-9][0-9]{0,19})$' THEN
    RAISE EXCEPTION 'publication_attribute_version_option_changed' USING ERRCODE='55000';END IF;
   IF decimal_value::numeric>18446744073709551615::numeric THEN
    RAISE EXCEPTION 'publication_attribute_version_option_changed' USING ERRCODE='55000';END IF;
   options:=array_append(options,'pg_attver=__ENGINE_ATTRIBUTE_VERSION__');
  ELSE options:=array_append(options,option_value);END IF;
 END LOOP;
 RETURN jsonb_set(to_jsonb(attribute_record),'{attoptions}',to_jsonb(options));
END $attribute$;

CREATE FUNCTION pg_temp.a8314_publication_assert_source_schema() RETURNS void
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $schema$
DECLARE actual jsonb;expected jsonb;item record;original pg_attribute;attribute_json jsonb;
 actual_header oid:='public.native_conversation_publications'::regclass;
 actual_work oid:='public.native_turn_publication_work'::regclass;
 reference_header oid;reference_work oid;new_attribute integer;old_snapshot jsonb;
BEGIN
 -- Reference equality must not bless ambient third-party default grants.
 IF NOT EXISTS(SELECT FROM pg_class WHERE oid=actual_header
  AND relowner=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  AND relacl IS NOT DISTINCT FROM acldefault('r',relowner)
  AND relkind='r' AND relpersistence='p' AND relrowsecurity AND NOT relforcerowsecurity)
 THEN RAISE EXCEPTION 'publication_header_private_profile_changed' USING ERRCODE='55000';END IF;
 PERFORM pg_temp.a8314_publication_reference_schema();
 reference_header:='a8314_publication_source_reference.native_conversation_publications'::regclass;
 reference_work:='a8314_publication_source_reference.native_turn_publication_work'::regclass;
 SELECT snapshot INTO STRICT old_snapshot FROM pg_temp.a8314_publication_predecessor_table_snapshot;
 SELECT coalesce(max((value->>1)::integer),0)+1 INTO new_attribute FROM jsonb_array_elements(old_snapshot->'columns')
  WHERE value->>0=actual_work::text;
 IF (SELECT count(*) FROM pg_attribute WHERE attrelid=actual_work AND attname='publication_id' AND attnum=new_attribute AND NOT attisdropped)<>1
 THEN RAISE EXCEPTION 'publication_work_column_position_changed';END IF;

 SELECT pg_temp.a8314_publication_relation_semantics(c) INTO actual FROM pg_class c WHERE oid=actual_header;
 SELECT pg_temp.a8314_publication_relation_semantics(c) INTO expected FROM pg_class c WHERE oid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_relation_changed' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM pg_rewrite WHERE ev_class=actual_header) OR EXISTS(SELECT FROM pg_policy WHERE polrelid=actual_header)
  OR EXISTS(SELECT FROM pg_inherits WHERE inhrelid=actual_header OR inhparent=actual_header)
 THEN RAISE EXCEPTION 'publication_header_extra_schema';END IF;
 SELECT jsonb_agg(pg_temp.a8314_publication_attribute_semantics(a) ORDER BY a.attnum) INTO actual FROM pg_attribute a WHERE a.attrelid=actual_header AND a.attnum>0;
 SELECT jsonb_agg((pg_temp.a8314_publication_attribute_semantics(a)-'attrelid')||jsonb_build_object('attrelid',actual_header) ORDER BY a.attnum) INTO expected
  FROM pg_attribute a WHERE a.attrelid=reference_header AND a.attnum>0;
 IF actual IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'publication_header_columns_changed' USING DETAIL=(SELECT jsonb_agg(jsonb_build_object('attribute',coalesce(a.value->>'attname',e.value->>'attname'),'actual',a.value,'expected',e.value))::text
   FROM jsonb_array_elements(actual) WITH ORDINALITY a(value,n) FULL JOIN jsonb_array_elements(expected) WITH ORDINALITY e(value,n) ON a.n=e.n WHERE a.value IS DISTINCT FROM e.value);
 END IF;
 SELECT * INTO STRICT original FROM pg_attribute WHERE attrelid=reference_work AND attname='publication_id' AND NOT attisdropped;
 attribute_json:=(pg_temp.a8314_publication_attribute_semantics(original)-ARRAY['attrelid','attnum'])||jsonb_build_object('attrelid',actual_work,'attnum',new_attribute);
 IF attribute_json IS DISTINCT FROM (SELECT pg_temp.a8314_publication_attribute_semantics(a) FROM pg_attribute a WHERE a.attrelid=actual_work AND a.attnum=new_attribute)
 THEN RAISE EXCEPTION 'publication_work_column_changed';END IF;

 SELECT jsonb_agg(jsonb_build_object('index',to_jsonb(i),'relation',pg_temp.a8314_publication_relation_semantics(c)) ORDER BY c.relname COLLATE "C") INTO actual
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=actual_header;
 SELECT jsonb_agg(jsonb_build_object('index',(to_jsonb(i)-ARRAY['indexrelid','indrelid'])||jsonb_build_object(
  'indexrelid',pg_temp.a8314_publication_map_reference_relation(i.indexrelid),'indrelid',actual_header),
  'relation',pg_temp.a8314_publication_relation_semantics(c)) ORDER BY c.relname COLLATE "C") INTO expected
  FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid WHERE i.indrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_indexes_changed';END IF;
 SELECT jsonb_agg(to_jsonb(k) ORDER BY k.conname COLLATE "C") INTO actual FROM pg_constraint k WHERE k.conrelid=actual_header;
 SELECT jsonb_agg(pg_temp.a8314_publication_reference_constraint_record(k) ORDER BY k.conname COLLATE "C") INTO expected FROM pg_constraint k WHERE k.conrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_constraints_changed';END IF;
 SELECT to_jsonb(k) INTO actual FROM pg_constraint k WHERE k.conrelid=actual_work AND k.conname='native_turn_publication_operation';
 SELECT pg_temp.a8314_publication_reference_constraint_record(k) INTO expected FROM pg_constraint k WHERE k.conrelid=reference_work AND k.conname='native_turn_publication_operation';
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_work_foreign_key_changed';END IF;

 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO actual FROM pg_trigger t WHERE t.tgrelid=actual_header;
 SELECT jsonb_agg(mapped ORDER BY (mapped->>'oid')::oid) INTO expected FROM(
  SELECT pg_temp.a8314_publication_reference_trigger_record(t) mapped FROM pg_trigger t WHERE t.tgrelid=reference_header) mapped;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_triggers_changed';END IF;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) INTO actual FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
  WHERE k.conrelid=actual_work AND k.conname='native_turn_publication_operation' AND t.tgrelid=actual_work;
 SELECT jsonb_agg(mapped ORDER BY (mapped->>'oid')::oid) INTO expected FROM(
  SELECT pg_temp.a8314_publication_reference_trigger_record(t) mapped FROM pg_trigger t JOIN pg_constraint k ON k.oid=t.tgconstraint
  WHERE k.conrelid=reference_work AND k.conname='native_turn_publication_operation' AND t.tgrelid=reference_work) mapped;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_work_constraint_triggers_changed';END IF;

 SELECT jsonb_agg(to_jsonb(d) ORDER BY d.adnum) INTO actual FROM pg_attrdef d WHERE d.adrelid=actual_header;
 SELECT jsonb_agg((to_jsonb(d)-ARRAY['oid','adrelid'])||jsonb_build_object('adrelid',actual_header,
  'oid',(SELECT a.oid FROM pg_attrdef a WHERE a.adrelid=actual_header AND a.adnum=d.adnum)) ORDER BY d.adnum)
  INTO expected FROM pg_attrdef d WHERE d.adrelid=reference_header;
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'publication_header_defaults_changed';END IF;
 IF EXISTS(SELECT FROM pg_attrdef WHERE adrelid=actual_work AND adnum=new_attribute)
 THEN RAISE EXCEPTION 'publication_work_column_default_changed';END IF;
 EXECUTE 'DROP SCHEMA a8314_publication_source_reference CASCADE';
END $schema$;



CREATE TEMP TABLE a8314_record_conversion_predecessor(body text NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.a8314_record_plain_body(signature text,template jsonb,successor boolean) RETURNS text LANGUAGE sql AS 'SELECT template->>0';
CREATE FUNCTION pg_temp.a8314_record_direct_source_body(signature text,template jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $record_publication_renderer$
 DECLARE body text:=pg_temp.a8314_record_plain_body(signature,template,successor);marker text;
 BEGIN
 CASE signature
  WHEN 'conversation_prepare_publications(uuid,uuid,jsonb)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='FROM jsonb_array_elements(compiled) c CROSS JOIN LATERAL jsonb_array_elements(c->''expanded'') n';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'FROM jsonb_array_elements(compiled) c CROSS JOIN LATERAL jsonb_array_elements(c->''expanded'') n
  WHERE n->>''resourceKind''<>''conversation_record''');
   marker:='  ELSIF node->>''resourceKind''=''external_source'' THEN';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  ELSIF node->>''resourceKind''=''conversation_record'' THEN
   current_source:=public.conversation_record_publication_source(w,(node->>''resourceId'')::uuid,s,actor,coalesce(command->>''purpose''=''session_title'',false));
  ELSIF node->>''resourceKind''=''external_source'' THEN');
   marker:='''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>2 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record''');
   marker:=' source_scope:=jsonb_build_object(''workspaceId'',w,''userId'',target->''userId''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,' IF EXISTS(SELECT 1 FROM jsonb_array_elements(sources) origin WHERE origin->>''resourceKind''=''conversation_record'')
  AND NOT EXISTS(SELECT 1 FROM public.conversation_envelopes e WHERE e.session_id=s AND e.workspace_id=w
   AND sensitivity_rank(floor_tier)<=sensitivity_rank(e.cap) AND teams<@e.compartments
   AND projects<@public.conversation_hard_project_ids(e.compartments))
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 source_scope:=jsonb_build_object(''workspaceId'',w,''userId'',target->''userId''');
  WHEN 'validate_scope_resource_reference()' THEN
   marker:='  source_row=CASE WHEN TG_TABLE_NAME=''scope_resource_states''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  IF TG_TABLE_NAME=''scope_derivation_sources'' AND expected_kind=''conversation_record'' THEN
    PERFORM public.require_conversation_record_edge(NEW.workspace_id,NEW.derivation_id,expected_id,expected_version);
    RETURN NEW;
  END IF;
  source_row=CASE WHEN TG_TABLE_NAME=''scope_resource_states''');
  WHEN 'native_turn_frame_payload_shape(jsonb)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='   IF n-ARRAY[''workspaceId''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'   IF n->>''resourceKind''=''conversation_record'' AND (n->>''version'' IS DISTINCT FROM ''1''
    OR n->>''userId'' IS NOT NULL OR n->>''assistantId'' IS NOT NULL) THEN RETURN false;END IF;
   IF n-ARRAY[''workspaceId''');
  WHEN 'native_conversation_compiled_frame_pair(uuid,uuid)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='  IF n.workspace_id IS DISTINCT FROM w';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  IF n.kind=''conversation_record'' AND (n.version IS DISTINCT FROM ''1''
   OR n.user_id IS NOT NULL OR n.assistant_id IS NOT NULL) THEN RETURN false;END IF;
  IF n.workspace_id IS DISTINCT FROM w');
  ELSE NULL;
 END CASE;
 RETURN body;
 END $record_publication_renderer$;
CREATE TEMP TABLE a8314_page_delivery_original_sources(signature text PRIMARY KEY,body text NOT NULL) ON COMMIT DROP;
CREATE FUNCTION pg_temp.a8314_page_delivery_early_body(signature text,parts jsonb,successor boolean) RETURNS text
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $private_page_body$
DECLARE body text:=pg_temp.a8314_record_plain_body(signature,parts,successor);marker text;
BEGIN CASE signature
WHEN 'native_turn_frame_pair(uuid,uuid)' THEN marker:='n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text
   AND NOT (f.format=2 AND r.user_id IS NULL AND n->>''assistantId'' IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'',(n->>''userId'')::uuid))');
WHEN 'native_conversation_frame_requirement_input(uuid,uuid)' THEN marker:='n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text
   AND NOT (f.format=2 AND r.user_id IS NULL AND n->>''assistantId'' IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'',(n->>''userId'')::uuid))');
WHEN 'native_conversation_compiled_frame_pair(uuid,uuid)' THEN marker:='n.user_id IS NOT NULL AND n.user_id IS DISTINCT FROM r.user_id';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n.user_id IS NOT NULL AND n.user_id IS DISTINCT FROM r.user_id
   AND NOT (f.format=2 AND r.user_id IS NULL AND n.assistant_id IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n.kind,n.id,n.version,n.user_id))');
ELSE NULL; END CASE; RETURN body; END $private_page_body$;
DO $conversion_source_functions$
DECLARE spec jsonb;actual pg_proc;reference pg_proc;owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
BEGIN
 FOR spec IN SELECT value FROM jsonb_array_elements('[{"name":"native_conversation_frame_requirement_input","referenceName":"a8314_conversion_source_function_0","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_0(w uuid,i uuid) RETURNS public.native_conversation_frame_requirements LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE f native_turn_frames;r session_context_scope_revisions;declaration scope_derivations;p jsonb;o public.native_conversation_requirement_source[];d public.native_conversation_requirement_source[];actual_edges jsonb;expected_edges jsonb;\nBEGIN\n -- Hold the original identity and bytes until descriptor insertion commits.\n PERFORM 1 FROM public.native_turn_frames WHERE workspace_id=w AND id=i FOR KEY SHARE;\n PERFORM 1 FROM public.session_context_revision_contents WHERE workspace_id=w AND revision_id=i FOR KEY SHARE;\n SELECT * INTO f FROM native_turn_frames WHERE workspace_id=w AND id=i;\n IF f.id IS NULL THEN RAISE EXCEPTION ''conversion_missing_frame'';END IF;\n IF NOT EXISTS(SELECT 1 FROM session_context_scope_revisions WHERE workspace_id=w AND id=i) THEN RAISE EXCEPTION ''conversion_missing_revision'';END IF;\n SELECT content INTO p FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=i;\n IF p IS NULL THEN RAISE EXCEPTION ''conversion_missing_payload'';END IF;\n IF native_turn_frame_payload_shape(p) IS NOT TRUE THEN RAISE EXCEPTION ''conversion_unsupported_payload'';END IF;\n IF NOT EXISTS(SELECT 1 FROM scope_derivations WHERE workspace_id=w AND resource_kind=''session_context_revision'' AND resource_id=i AND resource_version=''1'') THEN RAISE EXCEPTION ''conversion_missing_declaration'';END IF;\n -- Compile immutable shape/binding only. Current holds, grants and parent audience are not compilation inputs.\n SELECT * INTO r FROM session_context_scope_revisions WHERE workspace_id=w AND id=i;\n SELECT * INTO declaration FROM scope_derivations WHERE workspace_id=w AND resource_kind=''session_context_revision'' AND resource_id=i AND resource_version=''1'';\n SELECT coalesce(jsonb_agg(jsonb_build_array(s.source_kind,s.source_id,s.source_version) ORDER BY s.source_kind,s.source_id,s.source_version),''[]'') INTO actual_edges FROM scope_derivation_sources s WHERE s.workspace_id=w AND s.derivation_id=declaration.id;\n SELECT coalesce(jsonb_agg(jsonb_build_array(n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'') ORDER BY n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version''),''[]'') INTO expected_edges FROM jsonb_array_elements(p->''declaredSources'') n;\n IF native_turn_frame_payload_shape(p) IS NOT TRUE OR f.format NOT IN(1,2) OR (f.format=1) IS DISTINCT FROM (p->>''kind''=''native_turn_frame_v1'')\n  OR r.parent_kind IS DISTINCT FROM ''turn_frame'' OR r.parent_id IS DISTINCT FROM i OR r.session_id IS DISTINCT FROM f.session_id OR r.scope_version<>1\n  OR r.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(p::text,''UTF8'')),''hex'') OR f.manifest_digest IS DISTINCT FROM r.payload_sha256\n  OR (declaration.user_id,declaration.assistant_id,declaration.sensitivity,declaration.compartments,declaration.project_ids) IS DISTINCT FROM (r.user_id,r.assistant_id,r.sensitivity,r.compartments,r.project_ids)\n  OR actual_edges IS DISTINCT FROM expected_edges OR EXISTS(SELECT 1 FROM jsonb_array_elements((p->''originalSources'')||(p->''declaredSources'')) n WHERE n->>''workspaceId'' IS DISTINCT FROM w::text OR n->>''resourceKind''=''session_context_revision'' AND n->>''resourceId''=i::text\n   OR n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text OR sensitivity_rank(n->>''sensitivity'')>sensitivity_rank(r.sensitivity)\n   OR NOT to_jsonb(r.compartments) @> (n->''compartments'') OR NOT to_jsonb(r.project_ids) @> (n->''projectIds''))\n THEN RAISE EXCEPTION ''conversion_invalid_original_pair'';END IF;\n IF pg_column_size(p)>16777216 THEN RAISE EXCEPTION ''conversion_unit_too_large'';END IF;\n SELECT array_agg(ROW((n->>''workspaceId'')::uuid,(n->>''userId'')::uuid,(n->>''assistantId'')::uuid,n->>''sensitivity'',ARRAY(SELECT jsonb_array_elements_text(n->''compartments'')),ARRAY(SELECT jsonb_array_elements_text(n->''projectIds'')::uuid),n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'')::public.native_conversation_requirement_source ORDER BY ord) INTO o FROM jsonb_array_elements(p->''originalSources'') WITH ORDINALITY a(n,ord);\n SELECT array_agg(ROW((n->>''workspaceId'')::uuid,(n->>''userId'')::uuid,(n->>''assistantId'')::uuid,n->>''sensitivity'',ARRAY(SELECT jsonb_array_elements_text(n->''compartments'')),ARRAY(SELECT jsonb_array_elements_text(n->''projectIds'')::uuid),n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'')::public.native_conversation_requirement_source ORDER BY ord) INTO d FROM jsonb_array_elements(p->''declaredSources'') WITH ORDINALITY a(n,ord);\n IF pg_column_size(o)+coalesce(pg_column_size(d),0)>16777216 THEN RAISE EXCEPTION ''conversion_unit_too_large'';END IF;\n RETURN ROW(w,i,f.format,f.manifest_digest,o,coalesce(d,''{}''))::public.native_conversation_frame_requirements;\nEND $$;"},{"name":"native_conversation_compile_frame_requirements","referenceName":"a8314_conversion_source_function_1","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_1(w uuid,i uuid) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE expected public.native_conversation_frame_requirements;actual public.native_conversation_frame_requirements;\nBEGIN\n expected:=public.native_conversation_frame_requirement_input(w,i);\n SELECT * INTO actual FROM public.native_conversation_frame_requirements WHERE workspace_id=w AND id=i;\n IF actual.id IS NOT NULL AND actual IS DISTINCT FROM expected THEN RAISE EXCEPTION ''conversion_original_or_descriptor_mismatch'';END IF;\n INSERT INTO public.native_conversation_frame_requirements SELECT (expected).* ON CONFLICT(workspace_id,id) DO NOTHING;\n RETURN jsonb_build_object(''format'',expected.format,''originals'',cardinality(expected.originals),''declared'',cardinality(expected.declared),\n  ''bytes'',pg_column_size(expected),''payloadDigest'',expected.payload_digest);\nEND $$;"},{"name":"native_conversation_frame_requirement_guard","referenceName":"a8314_conversion_source_function_2","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_2() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE expected public.native_conversation_frame_requirements;\nBEGIN\n IF TG_OP=''DELETE'' AND (NOT EXISTS(SELECT 1 FROM public.native_turn_frames WHERE id=OLD.id)\n   OR NOT EXISTS(SELECT 1 FROM public.session_context_revision_contents WHERE revision_id=OLD.id)) THEN RETURN OLD;END IF;\n IF TG_OP<>''INSERT'' THEN RAISE EXCEPTION ''conversion_requirement_immutable'';END IF;\n expected:=public.native_conversation_frame_requirement_input(NEW.workspace_id,NEW.id);\n IF NEW IS DISTINCT FROM expected THEN RAISE EXCEPTION ''conversion_original_or_descriptor_mismatch'';END IF;\n RETURN NEW;\nEND $$;"},{"name":"native_conversation_compiled_frame_pair","referenceName":"a8314_conversion_source_function_3","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_3(w uuid,i uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE cert public.native_conversation_frame_requirements;f native_turn_frames;r session_context_scope_revisions;d scope_derivations;parent sessions;p jsonb;edges jsonb;declared jsonb;n public.native_conversation_requirement_source;\nBEGIN\n SELECT * INTO cert FROM public.native_conversation_frame_requirements WHERE workspace_id=w AND id=i;\n IF cert.id IS NULL THEN RAISE EXCEPTION ''conversion_missing_certificate'';END IF;\n SELECT * INTO f FROM native_turn_frames WHERE workspace_id=w AND id=i;\n SELECT * INTO r FROM session_context_scope_revisions WHERE workspace_id=w AND id=i;\n SELECT id,visibility,user_id INTO parent.id,parent.visibility,parent.user_id FROM sessions WHERE workspace_id=w AND id=r.session_id;\n SELECT content INTO p FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=i;\n IF f.id IS NULL OR r.id IS NULL OR parent.id IS NULL OR r.scope_held OR scope_review_state_held(''session_context_revision'',i)\n  OR parent.visibility=''personal'' AND r.user_id IS DISTINCT FROM parent.user_id\n  OR f.format=1 AND parent.visibility<>''personal'' AND r.user_id IS NOT NULL\n  OR r.assistant_id IS NOT NULL OR f.format NOT IN(1,2) OR f.format IS DISTINCT FROM cert.format OR r.parent_kind IS DISTINCT FROM ''turn_frame''\n  OR r.parent_id IS DISTINCT FROM i OR r.session_id IS DISTINCT FROM f.session_id OR r.scope_version<>1\n  OR p IS NULL OR encode(sha256(convert_to(p::text,''UTF8'')),''hex'') IS DISTINCT FROM cert.payload_digest\n  OR r.payload_sha256 IS DISTINCT FROM cert.payload_digest OR f.manifest_digest IS DISTINCT FROM cert.payload_digest\n THEN RETURN false;END IF;\n -- Dynamic source vocabulary remains fresh, as in payload_shape. Scalar shape and V1 subset were compiled from the hash-bound immutable payload.\n FOREACH n IN ARRAY cert.originals||cert.declared LOOP\n  IF n.workspace_id IS DISTINCT FROM w OR n.kind=''session_context_revision'' AND n.id=i\n   OR (CASE WHEN cert.format=1 THEN n.kind NOT IN(''session_message'',''session_context_revision'',''application_field'',''workspace_file'')\n    ELSE n.kind NOT IN(''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'') AND scope_source_table(n.kind) IS NULL END)\n  THEN RETURN false;END IF;\n END LOOP;\n SELECT * INTO d FROM scope_derivations WHERE workspace_id=w AND resource_kind=''session_context_revision'' AND resource_id=i AND resource_version=''1'';\n IF d.id IS NULL OR (d.user_id,d.assistant_id,d.sensitivity,d.compartments,d.project_ids) IS DISTINCT FROM (r.user_id,r.assistant_id,r.sensitivity,r.compartments,r.project_ids) THEN RETURN false;END IF;\n SELECT coalesce(jsonb_agg(jsonb_build_array(source_kind,source_id,source_version) ORDER BY source_kind,source_id,source_version),''[]'') INTO edges FROM scope_derivation_sources WHERE workspace_id=w AND derivation_id=d.id;\n SELECT coalesce(jsonb_agg(jsonb_build_array(decl.kind,decl.id,decl.version) ORDER BY decl.kind,decl.id,decl.version),''[]'') INTO declared FROM unnest(cert.declared) decl;\n IF edges IS DISTINCT FROM declared THEN RETURN false;END IF;\n FOREACH n IN ARRAY cert.originals||cert.declared LOOP\n  IF n.user_id IS NOT NULL AND n.user_id IS DISTINCT FROM r.user_id OR sensitivity_rank(n.sensitivity)>sensitivity_rank(r.sensitivity)\n    OR NOT r.compartments @> n.compartments OR NOT r.project_ids @> n.project_ids THEN RETURN false;END IF;\n END LOOP;\n RETURN true;\nEND $$;"},{"name":"native_conversation_conversion_keys","referenceName":"a8314_conversion_source_function_4","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_4(w uuid)\nRETURNS TABLE(kind public.native_conversation_conversion_unit_kind,id uuid,version text)\nLANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$\n SELECT ''frame''::public.native_conversation_conversion_unit_kind,id,format::text FROM native_turn_frames WHERE workspace_id=w\n UNION ALL SELECT ''field_observation'',resource_id,version FROM application_field_observations WHERE workspace_id=w\n UNION ALL SELECT ''query_domain'',id,identity FROM application_query_domains WHERE workspace_id=w\n UNION ALL SELECT ''derivation'',id,resource_version FROM scope_derivations WHERE workspace_id=w\n$$;"},{"name":"native_conversation_conversion_witness","referenceName":"a8314_conversion_source_function_5","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_5(w uuid,k public.native_conversation_conversion_unit_kind,i uuid,v text)\nRETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE fact jsonb;\nBEGIN\n CASE k\n WHEN ''frame'' THEN\n  SELECT jsonb_build_object(''frame'',to_jsonb(f),''revision'',to_jsonb(r)-''scope_held''-''created_at'',''payload'',c.content)\n  INTO fact FROM native_turn_frames f JOIN session_context_scope_revisions r ON r.workspace_id=f.workspace_id AND r.id=f.id\n  JOIN session_context_revision_contents c ON c.workspace_id=f.workspace_id AND c.revision_id=f.id\n  WHERE f.workspace_id=w AND f.id=i AND f.format::text=v;\n WHEN ''field_observation'' THEN\n  SELECT jsonb_build_object(''resource'',to_jsonb(r)-''created_at'',''observation'',to_jsonb(o)-''created_at'') INTO fact\n  FROM application_field_resources r JOIN application_field_observations o ON o.workspace_id=r.workspace_id AND o.resource_id=r.id\n  WHERE r.workspace_id=w AND r.id=i AND o.version=v;\n WHEN ''query_domain'' THEN\n  SELECT to_jsonb(q)-''created_at'' INTO fact FROM application_query_domains q WHERE q.workspace_id=w AND q.id=i AND q.identity=v;\n WHEN ''derivation'' THEN\n  SELECT to_jsonb(d)-''created_at'' INTO fact FROM scope_derivations d WHERE d.workspace_id=w AND d.id=i AND d.resource_version=v;\n END CASE;\n RETURN fact;\nEND $$;"},{"name":"native_conversation_conversion_validate_witness","referenceName":"a8314_conversion_source_function_6","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_6(k public.native_conversation_conversion_unit_kind,fact jsonb)\nRETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE d jsonb;\nBEGIN\n IF fact IS NULL THEN RAISE EXCEPTION ''conversion_missing_original'';END IF;\n\n IF k=''frame'' THEN\n  IF fact#>>''{frame,format}'' NOT IN(''1'',''2'') THEN RAISE EXCEPTION ''conversion_unsupported_frame'';END IF;\n ELSIF k=''field_observation'' THEN\n  IF fact#>>''{resource,selection}'' NOT IN(''read'',''query'',''history'',''identity'',''query_domain'')\n   OR fact#>''{resource,fields}'' IS NULL OR fact#>''{observation,record_version}'' IS NULL\n   OR fact#>''{observation,policy_version}'' IS NULL OR fact#>''{observation,source_scope}'' IS NULL\n  THEN RAISE EXCEPTION ''conversion_missing_field_witness'';END IF;\n ELSIF k=''query_domain'' THEN\n  d:=fact->''domain'';\n  IF fact->''origin''=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb THEN\n   CASE d->>''kind''\n   WHEN ''session_query_domain_v1'' THEN\n    IF fact->>''type_key'' NOT IN(''session_message'',''session_message_annotation'') OR NOT d ?& ARRAY[''kind'',''sessionId'',''throughSequence'',''fields'',''bounds'',''visibility'',''parentFingerprint'',''candidates'',''points'']\n     OR d-ARRAY[''kind'',''sessionId'',''throughSequence'',''fields'',''bounds'',''visibility'',''parentFingerprint'',''candidates'',''points'']<>''{}''\n    THEN RAISE EXCEPTION ''conversion_missing_session_domain_witness'';END IF;\n   WHEN ''memory_query_domain_v1'' THEN\n    IF fact->>''type_key''<>''memory'' OR NOT d ?& ARRAY[''kind'',''fields'',''bounds'',''visibility'',''includeRetained'',''candidates'',''policies'']\n     OR d-ARRAY[''kind'',''fields'',''bounds'',''visibility'',''includeRetained'',''candidates'',''policies'']<>''{}''\n    THEN RAISE EXCEPTION ''conversion_missing_memory_domain_witness'';END IF;\n   WHEN ''memory_outcome_domain_v1'' THEN\n    IF fact->>''type_key''<>''feedback_event'' OR NOT d ?& ARRAY[''kind'',''fields'',''bounds'',''visibility'',''memoryIds'',''windowStart'',''windowEnd'',''memoryCandidates'',''associations'',''feedback'',''policies'']\n     OR d-ARRAY[''kind'',''fields'',''bounds'',''visibility'',''memoryIds'',''windowStart'',''windowEnd'',''memoryCandidates'',''associations'',''feedback'',''policies'']<>''{}''\n    THEN RAISE EXCEPTION ''conversion_missing_outcome_domain_witness'';END IF;\n   ELSE RAISE EXCEPTION ''conversion_unsupported_native_domain'';\n   END CASE;\n  ELSIF fact#>>''{origin,kind}''=''generic'' AND d->>''kind''=''native_legacy'' THEN\n   -- Typed original owner stays with its explicit application adapter.\n   NULL;\n  ELSE RAISE EXCEPTION ''conversion_unsupported_domain_adapter'';END IF;\n END IF;\nEND $$;"},{"name":"native_conversation_conversion_enroll","referenceName":"a8314_conversion_source_function_7","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_7() RETURNS trigger\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE w uuid; k public.native_conversation_conversion_unit_kind;i uuid;v text;\nBEGIN\n w:=NEW.workspace_id;\n CASE TG_TABLE_NAME\n WHEN ''native_turn_frames'' THEN k:=''frame'';i:=NEW.id;v:=NEW.format::text;\n WHEN ''session_context_revision_contents'' THEN\n  SELECT ''frame''::public.native_conversation_conversion_unit_kind,f.id,f.format::text INTO k,i,v FROM public.native_turn_frames f WHERE f.workspace_id=w AND f.id=NEW.revision_id;\n WHEN ''application_field_resources'' THEN RETURN NEW; -- observations are complete units\n WHEN ''application_field_observations'' THEN k:=''field_observation'';i:=NEW.resource_id;v:=NEW.version;\n WHEN ''application_field_observation_sources'' THEN k:=''field_observation'';i:=NEW.resource_id;v:=NEW.version;\n WHEN ''application_query_domains'' THEN k:=''query_domain'';i:=NEW.id;v:=NEW.identity;\n WHEN ''scope_derivations'' THEN k:=''derivation'';i:=NEW.id;v:=NEW.resource_version;\n WHEN ''scope_derivation_sources'' THEN\n  SELECT ''derivation''::public.native_conversation_conversion_unit_kind,d.id,d.resource_version INTO k,i,v FROM public.scope_derivations d WHERE d.workspace_id=w AND d.id=NEW.derivation_id;\n END CASE;\n IF i IS NOT NULL THEN\n  INSERT INTO public.native_conversation_conversion_pending VALUES(w,k,i,v,1)\n  ON CONFLICT(workspace_id,kind,id,version) DO UPDATE SET generation=public.native_conversation_conversion_pending.generation+1;\n END IF;\n RETURN NEW;\nEND $$;"},{"name":"native_conversation_conversion_start","referenceName":"a8314_conversion_source_function_8","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_8(w uuid,compiler text) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE result uuid;\nBEGIN\n IF compiler IS DISTINCT FROM ''df21a20f92682c1d66a1ee2706f2f96e0647731a30dd73272adbad0285a8a702'' OR compiler IS NULL OR compiler !~ ''^[a-f0-9]{64}$'' THEN RAISE EXCEPTION ''conversion_invalid_compiler_digest'';END IF;\n PERFORM 1 FROM public.workspaces WHERE id=w FOR KEY SHARE;\n IF NOT FOUND THEN RAISE EXCEPTION ''conversion_workspace_absent'';END IF;\n INSERT INTO public.native_conversation_conversion_runs(id,workspace_id,compiler_digest)\n VALUES(gen_random_uuid(),w,compiler) ON CONFLICT(workspace_id,compiler_digest) DO NOTHING;\n SELECT id INTO result FROM public.native_conversation_conversion_runs WHERE workspace_id=w AND compiler_digest=compiler;\n IF result IS NULL THEN RAISE EXCEPTION ''conversion_run_absent'';END IF;\n RETURN result;\nEND $$;"},{"name":"native_conversation_conversion_page","referenceName":"a8314_conversion_source_function_9","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_9(run uuid,unit_limit integer,byte_limit integer) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE w uuid;r public.native_conversation_conversion_runs;unit record;acquired jsonb;original_digest text;\n descriptor public.native_conversation_frame_requirements;descriptor_digest text;prior public.native_conversation_conversion_inputs;mode text;\n source_bytes bigint:=0;written_bytes integer:=0;unit_bytes integer;receipt_bytes integer;counted integer:=0;\n units jsonb:=''[]'';before_cursor jsonb;after_cursor jsonb;next_page bigint;chain text;\n last_kind public.native_conversation_conversion_unit_kind;last_id uuid;last_version text;\nBEGIN\n IF unit_limit IS NULL OR unit_limit NOT BETWEEN 1 AND 32 OR byte_limit IS NULL OR byte_limit NOT BETWEEN 1 AND 16777216\n THEN RAISE EXCEPTION ''conversion_invalid_page_budget'';END IF;\n SELECT workspace_id INTO w FROM public.native_conversation_conversion_runs WHERE id=run;\n IF w IS NULL THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n -- Workspace precedes the run row, matching parent cascade lock order.\n PERFORM 1 FROM public.workspaces WHERE id=w FOR KEY SHARE;\n IF NOT FOUND THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n SELECT * INTO r FROM public.native_conversation_conversion_runs WHERE id=run FOR UPDATE;\n IF r.id IS NULL THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n IF r.protocol_version<>1 OR r.compiler_digest IS DISTINCT FROM ''df21a20f92682c1d66a1ee2706f2f96e0647731a30dd73272adbad0285a8a702'' THEN RAISE EXCEPTION ''conversion_unsupported_protocol'';END IF;\n IF r.phase=''reconciled'' THEN\n  IF NOT EXISTS(SELECT 1 FROM public.native_conversation_conversion_pending WHERE workspace_id=w)\n  THEN RETURN jsonb_build_object(''state'',''reconciled'',''page'',r.page);END IF;\n  UPDATE public.native_conversation_conversion_runs SET phase=''delta'' WHERE id=run;\n  r.phase:=''delta'';\n END IF;\n before_cursor:=CASE WHEN r.cursor_kind IS NULL THEN ''null''::jsonb ELSE jsonb_build_array(r.cursor_kind,r.cursor_id,r.cursor_version) END;\n last_kind:=r.cursor_kind;last_id:=r.cursor_id;last_version:=r.cursor_version;\n FOR unit IN\n  SELECT candidates.* FROM (\n   SELECT p.kind,p.id,p.version,p.generation FROM public.native_conversation_conversion_pending p\n    WHERE r.phase=''delta'' AND p.workspace_id=w\n   UNION ALL\n   SELECT k.kind,k.id,k.version,NULL::bigint FROM public.native_conversation_conversion_keys(w) k\n    WHERE r.phase<>''delta'' AND (r.cursor_kind IS NULL OR (k.kind,k.id,k.version)>(r.cursor_kind,r.cursor_id,r.cursor_version))\n  ) candidates ORDER BY kind,id,version LIMIT unit_limit\n LOOP\n  -- Acquire once: validation and the digest consume this same SQL value. No\n  -- JavaScript parse/reserialization changes numeric values or ordered arrays.\n  acquired:=public.native_conversation_conversion_witness(w,unit.kind,unit.id,unit.version);\n  PERFORM public.native_conversation_conversion_validate_witness(unit.kind,acquired);\n  unit_bytes:=pg_column_size(acquired);\n  source_bytes:=source_bytes+unit_bytes;\n  original_digest:=encode(sha256(convert_to(acquired::text,''UTF8'')),''hex'');\n  descriptor:=NULL;descriptor_digest:=NULL;mode:=''original_adapter'';\n  -- These are native conversion eligibility bounds only. Other valid original\n  -- units retain their complete adapter; no new content limit or truncation.\n  IF unit.kind=''frame'' AND unit_bytes<=16777216\n   AND (CASE WHEN jsonb_typeof(acquired#>''{payload,originalSources}'')=''array''\n     THEN jsonb_array_length(acquired#>''{payload,originalSources}'')<=4096 ELSE true END)\n   AND (CASE WHEN jsonb_typeof(acquired#>''{payload,declaredSources}'')=''array''\n     THEN jsonb_array_length(acquired#>''{payload,declaredSources}'')<=4096 ELSE true END) THEN\n   -- Validation acquires immutable originals but writes no descriptor. Budget\n   -- eligibility is decided before the counted unit may materialize anything.\n   BEGIN\n    descriptor:=public.native_conversation_frame_requirement_input(w,unit.id);\n    descriptor_digest:=encode(sha256(convert_to(to_jsonb(descriptor)::text,''UTF8'')),''hex'');\n    mode:=''compiled_frame'';\n   EXCEPTION WHEN raise_exception THEN\n    IF SQLERRM<>''conversion_unit_too_large'' THEN RAISE;END IF;\n    descriptor:=NULL;descriptor_digest:=NULL;mode:=''original_adapter'';\n   END;\n  END IF;\n  receipt_bytes:=pg_column_size(jsonb_build_array(unit.kind,unit.id,unit.version,original_digest,descriptor_digest,mode))\n   +coalesce(pg_column_size(descriptor),0);\n  IF written_bytes+receipt_bytes>byte_limit THEN\n   IF counted=0 THEN RAISE EXCEPTION ''conversion_page_budget_too_small'';END IF;\n   EXIT;\n  END IF;\n  IF mode=''compiled_frame'' THEN\n   PERFORM public.native_conversation_compile_frame_requirements(w,unit.id);\n  END IF;\n  SELECT * INTO prior FROM public.native_conversation_conversion_inputs\n   WHERE run_id=run AND kind=unit.kind AND id=unit.id AND version=unit.version;\n  IF prior.run_id IS NOT NULL AND (prior.original_digest,prior.compiler_digest,prior.descriptor_digest,prior.processing_mode)\n   IS DISTINCT FROM (original_digest,r.compiler_digest,descriptor_digest,mode)\n  THEN RAISE EXCEPTION ''conversion_original_or_descriptor_mismatch'';END IF;\n  IF prior.run_id IS NULL THEN\n   INSERT INTO public.native_conversation_conversion_inputs(run_id,kind,id,version,original_digest,compiler_digest,bytes,descriptor_digest,processing_mode)\n    VALUES(run,unit.kind,unit.id,unit.version,original_digest,r.compiler_digest,unit_bytes,descriptor_digest,mode);\n  END IF;\n  -- Never lock pending ahead of its source owner. A concurrent generation3\n  -- survives the generation2 delete even when the delete waited for its writer.\n  IF r.phase=''delta'' THEN\n   DELETE FROM public.native_conversation_conversion_pending p WHERE p.workspace_id=w AND p.kind=unit.kind\n    AND p.id=unit.id AND p.version=unit.version AND p.generation=unit.generation;\n  END IF;\n  written_bytes:=written_bytes+receipt_bytes;counted:=counted+1;\n  last_kind:=unit.kind;last_id:=unit.id;last_version:=unit.version;\n  units:=units||jsonb_build_array(jsonb_build_array(unit.kind,unit.id,unit.version,original_digest,descriptor_digest,mode));\n END LOOP;\n IF counted=0 THEN\n  IF r.phase IN(''scan'',''audit'') THEN\n   UPDATE public.native_conversation_conversion_runs SET phase=''delta'',cursor_kind=NULL,cursor_id=NULL,cursor_version=NULL,\n    audit_done=audit_done OR r.phase=''audit'' WHERE id=run;\n  ELSIF NOT r.audit_done THEN\n   UPDATE public.native_conversation_conversion_runs SET phase=''audit'',cursor_kind=NULL,cursor_id=NULL,cursor_version=NULL WHERE id=run;\n  END IF;\n  RETURN jsonb_build_object(''state'',CASE WHEN r.phase=''delta'' AND r.audit_done THEN ''await_barrier'' ELSE ''phase_advanced'' END,''phase'',r.phase);\n END IF;\n next_page:=r.page+1;\n chain:=encode(sha256(convert_to(jsonb_build_array(r.chain_digest,next_page,r.phase,units)::text,''UTF8'')),''hex'');\n after_cursor:=jsonb_build_array(last_kind,last_id,last_version);\n INSERT INTO public.native_conversation_conversion_pages(run_id,page,phase,units,bytes,before_cursor,after_cursor,chain_digest,source_bytes)\n VALUES(run,next_page,r.phase,counted,written_bytes,before_cursor,after_cursor,chain,source_bytes);\n UPDATE public.native_conversation_conversion_runs SET page=next_page,chain_digest=chain,\n  cursor_kind=CASE WHEN r.phase=''delta'' THEN r.cursor_kind ELSE last_kind END,\n  cursor_id=CASE WHEN r.phase=''delta'' THEN r.cursor_id ELSE last_id END,\n  cursor_version=CASE WHEN r.phase=''delta'' THEN r.cursor_version ELSE last_version END WHERE id=run;\n RETURN jsonb_build_object(''state'',''committed'',''page'',next_page,''phase'',r.phase,''units'',counted,''bytes'',written_bytes,''sourceBytes'',source_bytes,''chain'',chain);\nEND $$;"},{"name":"native_conversation_conversion_reconcile","referenceName":"a8314_conversion_source_function_10","reference":"CREATE FUNCTION pg_temp.a8314_conversion_source_function_10(run uuid) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$\nDECLARE w uuid;r public.native_conversation_conversion_runs;\nBEGIN\n SELECT workspace_id INTO w FROM public.native_conversation_conversion_runs WHERE id=run;\n IF w IS NULL THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n PERFORM 1 FROM public.workspaces WHERE id=w FOR KEY SHARE;\n IF NOT FOUND THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n -- The barrier checks only indexed pending existence, never a full inventory\n -- scan or digest while holding this brief source-enrollment lock.\n LOCK TABLE public.native_turn_frames,public.session_context_revision_contents,public.application_field_observations,\n  public.application_field_observation_sources,public.application_query_domains,public.scope_derivations,public.scope_derivation_sources IN SHARE MODE NOWAIT;\n SELECT * INTO r FROM public.native_conversation_conversion_runs WHERE id=run FOR UPDATE;\n IF r.id IS NULL THEN RETURN jsonb_build_object(''state'',''absent'');END IF;\n IF r.protocol_version<>1 OR r.compiler_digest IS DISTINCT FROM ''df21a20f92682c1d66a1ee2706f2f96e0647731a30dd73272adbad0285a8a702'' OR NOT r.audit_done OR r.phase<>''delta'' THEN RETURN jsonb_build_object(''state'',''not_reconciled'');END IF;\n IF EXISTS(SELECT 1 FROM public.native_conversation_conversion_pending WHERE workspace_id=w) THEN RETURN jsonb_build_object(''state'',''pending'');END IF;\n UPDATE public.native_conversation_conversion_runs SET phase=''reconciled'' WHERE id=run;\n RETURN jsonb_build_object(''state'',''reconciled'',''page'',r.page,''chain'',r.chain_digest);\nEND $$;"}]'::jsonb) LOOP
