END $conversion_source_functions$;
CREATE FUNCTION pg_temp.a8314_conversion_map_relation(i oid) RETURNS oid LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE n name;s name;
BEGIN
 IF i=0 THEN RETURN 0;END IF;
 SELECT c.relname,ns.nspname INTO STRICT n,s FROM pg_class c JOIN pg_namespace ns ON ns.oid=c.relnamespace WHERE c.oid=i;
 IF s<>'a8314_conversion_source_reference' THEN RETURN i;END IF;
 RETURN to_regclass(format('public.%I',n));
END $$;
CREATE FUNCTION pg_temp.a8314_conversion_map_type(i oid) RETURNS oid LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE n name;s name;
BEGIN
 IF i=0 THEN RETURN 0;END IF;
 SELECT t.typname,ns.nspname INTO STRICT n,s FROM pg_type t JOIN pg_namespace ns ON ns.oid=t.typnamespace WHERE t.oid=i;
 IF s<>'a8314_conversion_source_reference' THEN RETURN i;END IF;
 RETURN to_regtype(format('public.%I',n));
END $$;
CREATE FUNCTION pg_temp.a8314_conversion_map_constraint(i oid) RETURNS oid LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE original pg_constraint;mapped oid;
BEGIN
 IF i=0 THEN RETURN 0;END IF;
 SELECT * INTO STRICT original FROM pg_constraint WHERE oid=i;
 SELECT oid INTO STRICT mapped FROM pg_constraint WHERE conrelid=pg_temp.a8314_conversion_map_relation((original).conrelid) AND conname=(original).conname;
 RETURN mapped;
END $$;
CREATE FUNCTION pg_temp.a8314_conversion_constraint(c pg_constraint,mapping boolean) RETURNS jsonb LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT CASE WHEN mapping THEN (to_jsonb(c)-ARRAY['oid','connamespace','conrelid','conindid','confrelid'])||jsonb_build_object(
  'oid',pg_temp.a8314_conversion_map_constraint((c).oid),'connamespace','public'::regnamespace::oid,
  'conrelid',pg_temp.a8314_conversion_map_relation((c).conrelid),'conindid',pg_temp.a8314_conversion_map_relation((c).conindid),'confrelid',pg_temp.a8314_conversion_map_relation((c).confrelid),
  'conbin',replace((c).conbin::text,
   ':vartype '||to_regtype('a8314_conversion_source_reference.native_conversation_conversion_unit_kind')::oid||' ',
   ':vartype '||'public.native_conversation_conversion_unit_kind'::regtype::oid||' ')) ELSE to_jsonb(c) END
$$;
CREATE FUNCTION pg_temp.a8314_conversion_trigger(t pg_trigger,mapping boolean) RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE mapped oid;n text;
BEGIN
 IF NOT mapping THEN RETURN to_jsonb(t);END IF;
 IF (t).tgisinternal THEN
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.a8314_conversion_map_relation((t).tgrelid)
    AND tgconstraint=pg_temp.a8314_conversion_map_constraint((t).tgconstraint) AND tgtype=(t).tgtype AND tgisinternal;
  IF right((t).tgname::text,length((t).oid::text))<>(t).oid::text OR (t).tgname!~'^RI_ConstraintTrigger_[ac]_' THEN RAISE EXCEPTION 'conversion_reference_internal_trigger_name';END IF;
  n:=left((t).tgname::text,length((t).tgname::text)-length((t).oid::text))||mapped::text;
 ELSE
  SELECT oid INTO STRICT mapped FROM pg_trigger WHERE tgrelid=pg_temp.a8314_conversion_map_relation((t).tgrelid) AND tgname=(t).tgname;
  n:=(t).tgname;
 END IF;
 RETURN (to_jsonb(t)-ARRAY['oid','tgname','tgrelid','tgconstraint','tgconstrrelid','tgconstrindid'])||jsonb_build_object(
  'oid',mapped,'tgname',n,'tgrelid',pg_temp.a8314_conversion_map_relation((t).tgrelid),'tgconstraint',pg_temp.a8314_conversion_map_constraint((t).tgconstraint),
  'tgconstrrelid',pg_temp.a8314_conversion_map_relation((t).tgconstrrelid),'tgconstrindid',pg_temp.a8314_conversion_map_relation((t).tgconstrindid));
END $$;
