CREATE SCHEMA a8314_conversion_source_reference;
CREATE TYPE a8314_conversion_source_reference.native_conversation_requirement_source AS (workspace_id uuid,user_id uuid,assistant_id uuid,sensitivity text,compartments text[],project_ids uuid[],kind text,id uuid,version text);
CREATE TABLE a8314_conversion_source_reference.native_conversation_frame_requirements(
 workspace_id uuid NOT NULL,id uuid NOT NULL,format smallint NOT NULL CHECK(format IN(1,2)),
 payload_digest text NOT NULL CHECK(payload_digest ~ '^[a-f0-9]{64}$'),
 originals a8314_conversion_source_reference.native_conversation_requirement_source[] NOT NULL,
 declared a8314_conversion_source_reference.native_conversation_requirement_source[] NOT NULL,PRIMARY KEY(workspace_id,id)
);
ALTER TABLE a8314_conversion_source_reference.native_conversation_frame_requirements ADD CONSTRAINT native_conversation_frame_requirement_frame_fk
 FOREIGN KEY(id) REFERENCES public.native_turn_frames(id) ON DELETE CASCADE;
ALTER TABLE a8314_conversion_source_reference.native_conversation_frame_requirements ADD CONSTRAINT native_conversation_frame_requirement_payload_fk
 FOREIGN KEY(id) REFERENCES public.session_context_revision_contents(revision_id) ON DELETE CASCADE;
CREATE TYPE a8314_conversion_source_reference.native_conversation_conversion_unit_kind AS ENUM('frame','field_observation','query_domain','derivation');
CREATE TABLE a8314_conversion_source_reference.native_conversation_conversion_runs(
 id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
 compiler_digest text NOT NULL CHECK(compiler_digest ~ '^[a-f0-9]{64}$'),
 phase text NOT NULL DEFAULT 'scan' CHECK(phase IN('scan','delta','audit','reconciled')),
 cursor_kind a8314_conversion_source_reference.native_conversation_conversion_unit_kind, cursor_id uuid,cursor_version text,
 page bigint NOT NULL DEFAULT 0,chain_digest text NOT NULL DEFAULT repeat('0',64),
 UNIQUE(workspace_id,compiler_digest)
);
CREATE TABLE a8314_conversion_source_reference.native_conversation_conversion_inputs(
 run_id uuid NOT NULL REFERENCES a8314_conversion_source_reference.native_conversation_conversion_runs(id) ON DELETE CASCADE,
 kind a8314_conversion_source_reference.native_conversation_conversion_unit_kind NOT NULL,id uuid NOT NULL,version text NOT NULL,
 original_digest text NOT NULL,compiler_digest text NOT NULL,bytes integer NOT NULL,
 PRIMARY KEY(run_id,kind,id,version)
);
CREATE TABLE a8314_conversion_source_reference.native_conversation_conversion_pending(
 workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
 kind a8314_conversion_source_reference.native_conversation_conversion_unit_kind NOT NULL,id uuid NOT NULL,version text NOT NULL,
 generation bigint NOT NULL DEFAULT 1,
 PRIMARY KEY(workspace_id,kind,id,version)
);
CREATE TABLE a8314_conversion_source_reference.native_conversation_conversion_pages(
 run_id uuid NOT NULL REFERENCES a8314_conversion_source_reference.native_conversation_conversion_runs(id) ON DELETE CASCADE,
 page bigint NOT NULL,phase text NOT NULL,units integer NOT NULL,bytes integer NOT NULL,
 before_cursor jsonb,after_cursor jsonb,chain_digest text NOT NULL,
 PRIMARY KEY(run_id,page)
);
ALTER TABLE a8314_conversion_source_reference.native_conversation_conversion_runs ADD COLUMN audit_done boolean NOT NULL DEFAULT false;
ALTER TABLE a8314_conversion_source_reference.native_conversation_conversion_inputs ADD COLUMN descriptor_digest text;
ALTER TABLE a8314_conversion_source_reference.native_conversation_conversion_runs ADD COLUMN protocol_version smallint NOT NULL DEFAULT 1 CHECK(protocol_version=1);
ALTER TABLE a8314_conversion_source_reference.native_conversation_conversion_inputs ADD COLUMN processing_mode text NOT NULL DEFAULT 'original_adapter'
 CHECK(processing_mode IN('compiled_frame','original_adapter'));
ALTER TABLE a8314_conversion_source_reference.native_conversation_conversion_pages ADD COLUMN source_bytes bigint NOT NULL DEFAULT 0;
REVOKE ALL ON TYPE a8314_conversion_source_reference.native_conversation_requirement_source,a8314_conversion_source_reference.native_conversation_conversion_unit_kind FROM PUBLIC,app_user;
REVOKE ALL ON a8314_conversion_source_reference.native_conversation_frame_requirements,a8314_conversion_source_reference.native_conversation_conversion_runs,
 a8314_conversion_source_reference.native_conversation_conversion_inputs,a8314_conversion_source_reference.native_conversation_conversion_pending,a8314_conversion_source_reference.native_conversation_conversion_pages FROM PUBLIC,app_user;
