CREATE TRIGGER crm_recovery_capture AFTER INSERT OR UPDATE OR DELETE ON a8314_conversion_source_reference.native_conversation_conversion_runs FOR EACH ROW EXECUTE FUNCTION public.crm_capture_erasure_effect();
CREATE TRIGGER crm_recovery_capture AFTER INSERT OR UPDATE OR DELETE ON a8314_conversion_source_reference.native_conversation_conversion_inputs FOR EACH ROW EXECUTE FUNCTION public.crm_capture_erasure_effect();
