 THEN RAISE EXCEPTION 'conversion_relation_private_acl_changed';END IF;
 actual:=pg_temp.a8314_conversion_schema_snapshot_metadata('public',false);expected:=pg_temp.a8314_conversion_schema_snapshot_metadata('a8314_conversion_source_reference',true);
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'installation_input_schema_mismatch' USING DETAIL=(SELECT jsonb_agg(key)::text FROM jsonb_each(expected) e WHERE e.value IS DISTINCT FROM actual->e.key);END IF;
 actual:=pg_temp.a8314_conversion_schema_snapshot('public',false);expected:=pg_temp.a8314_conversion_schema_snapshot('a8314_conversion_source_reference',true);
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'conversion_source_schema_mismatch' USING DETAIL=(SELECT jsonb_agg(key)::text FROM jsonb_each(expected) e WHERE e.value IS DISTINCT FROM actual->e.key);END IF;
