 WHERE c.conname<>'native_conversation_conversion_inputs_record_session_id_fkey' AND c.conrelid IN(
  SELECT oid FROM pg_class WHERE relnamespace='a8314_conversion_source_reference'::regnamespace AND relkind='r' AND relname<>'conversation_envelopes');
 IF (SELECT jsonb_agg(pg_temp.a8314_conversion_trigger(t,true) ORDER BY (pg_temp.a8314_conversion_trigger(t,true)->>'oid')::oid)
  FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint
  WHERE c.connamespace='a8314_conversion_source_reference'::regnamespace AND c.conname='native_conversation_conversion_inputs_record_session_id_fkey')
 IS DISTINCT FROM (SELECT jsonb_agg(to_jsonb(t) ORDER BY t.oid) FROM pg_trigger t JOIN pg_constraint c ON c.oid=t.tgconstraint
  WHERE c.connamespace='public'::regnamespace AND c.conname='native_conversation_conversion_inputs_record_session_id_fkey')
 THEN RAISE EXCEPTION 'record_conversion_auth_envelope_foreign_key_changed';END IF;
