T value->''write'' FROM fields),\n decisions AS MATERIALIZED(SELECT rule,application_native_field_rule_allows(rule,roles) allowed FROM rules)\n SELECT jsonb_build_object(\n  ''read'',ARRAY(SELECT f.value->>''key'' FROM fields f JOIN decisions d ON d.rule IS NOT DISTINCT FROM f.value->''read'' WHERE d.allowed ORDER BY 1),\n  ''write'',ARRAY(SELECT f.value->>''key'' FROM fields f JOIN decisions d ON d.rule IS NOT DISTINCT FROM f.value->''write'' WHERE d.allowed ORDER BY 1)) INTO result;\n RETURN result;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_query_bounds(uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"application_native_query_bounds","prorows":0,"pronargs":1,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL THEN RETURN NULL; END IF;\n RETURN public.application_principal_query_bounds(w,nullif(current_setting(''app.current_user_id'',true),'''')::uuid,false);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_record_port_valid(regprocedure)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},