AY(SELECT resource_id FROM scope_source_ancestors(w,k,i)) ELSE ''{}''::uuid[] END) prior_id WHERE prior_id<>i;\n END IF;\nEND"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"application_native_title_acquisition_helpers_current()","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"application_native_title_acquisition_helpers_current","prorows":0,"pronargs":0,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["BEGIN IF (SELECT count(*)=8 AND coalesce(bool_and(encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'')=pin.fingerprint),false)\n   FROM (VALUES (",{"slot":{"kind":"function","identity":"application_scope_lineage(uuid,text[],uuid[],text[])"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"application_scope_lineage(uuid,text[],uuid[],text[])"}},"''::text),(",{"slot":{"kind":"function","identity":"read_entity_derivation_source(uuid,text,uuid)"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"read_entity_derivation_source(uuid,text,uuid)"}},"''::text),(",{"slot":{"kind":"function","identity":"session_recording_read_allowed(uuid)"}},"::oid,''",{"slot":{"kind":"fingerprint","identity":"session_recording_read_allowed(uuid)"}},"''::text),(",{"slot":{"kind":"function","identity":"recording_source_read_allowed(uuid,text,uuid)"}},"::oid,''",{"s