M pg_catalog.pg_proc p WHERE p.oid=''public.application_native_worklist_helpers_current()''::regprocedure)=''",{"slot":{"kind":"fingerprint","identity":"application_native_worklist_helpers_current()"}},"'' THEN\n IF application_native_worklist_helpers_current() IS TRUE THEN\n  DECLARE worklist_result jsonb;\n  BEGIN\n  worklist_result:=read_native_file_worklist_evidence(w,kinds,ids,versions,include_memory,false);\n  IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'') FROM pg_catalog.pg_proc p WHERE p.oid=''public.application_native_worklist_helpers_current()''::regprocedure)=''",{"slot":{"kind":"fingerprint","identity":"application_native_worklist_helpers_current()"}},"'' THEN\n  IF worklist_result->>''admitted''=''true'' THEN RETURN worklist_result;END IF;\n END IF;\n END;\n END IF;\n END IF;\n\n IF native_turn_helpers_current() IS NOT TRUE\n  OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n   WHERE oid=''public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)''::regprocedure)\n   IS DISTINCT FROM ''2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376'' THEN RETURN NULL;END IF;\n \n IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100\n  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)\n  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n -- A changed original evaluator retains its full original fallback contract.\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n  WHERE oid=''public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)''::regprocedure)\n  IS DISTINCT FROM ''b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca'' THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018'' THEN RETURN NULL;END IF;\n -- Every other profile/resource family delegates to the original validator.\n IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN(''application_field'',''session_context_revision'',''session_message'',''memory'',''workspace_file'')) OR NOT include_memory AND ''memory''=ANY(kinds) THEN RETURN NULL;END IF;\n IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''session_messages''::regclass WHERE r.rolname=session_user\n  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE''))) THEN RETURN NULL;END IF;\n -- Ineligible root metadata adds no native lock or full-closure walk.\n IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)\n  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id\n  WHERE root.kind=''application_field'' AND(field.id IS NULL OR field.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n   OR NOT(field.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND field.type_key=''memory''))) THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind'' NOT IN(''application_field'',''application_query_domain'',''session_context_revision'',''session_message'',''memory'',''workspace_file''))\n  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''memory'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid\n   WHERE n->>''kind''=''application_field'' AND(f.id IS NULL OR f.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb OR NOT(f.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND f.type_key=''memory''))) THEN RETURN NULL;END IF;\n\n -- Discover eligibility only. A file with its own derivation, any historical\n -- selector, or independent Page ancestry keeps the complete original path.\n IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''workspace_file'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN scope_derivations d\n   ON d.workspace_id=w AND d.resource_kind=''workspace_file'' AND d.resource_id=(n->>''id'')::uuid\n   WHERE n->>''kind''=''workspace_file'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f\n   ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field''\n   AND (f.selected_version IS NOT NULL OR f.selection=''history'')) THEN RETURN NULL;END IF;\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind''=''workspace_file'' LOOP\n  IF read_admitted_page_dependencies(w,''workspace_file'',(node->>''id'')::uuid,node->>''version'')\n   IS DISTINCT FROM ''[]''::jsonb THEN RETURN NULL;END IF;\n END LOOP;\n -- Source-denied physical candidates still require fresh remote cohort\n -- context. No fast-path admission is inferred from the original closure.\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n\n -- This private argument is created only by this closed SQL operation. It holds\n -- scope metadata, never a Memory business row or a shared selected-field grant.\n IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN\n  BEGIN\n   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;\n   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_context:=application_memory_query_context(w);\n   IF memory_context#>>''{policy,nativeDefault}'' IS DISTINCT FROM ''true'' THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_rows:=''{}'';memory_cohort:=''[]'';\n   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object(''kind'',''memory'',''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n    memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object(''source'',memory_source,''lineage'',memory_lineage));\n    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object(''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text));\n   END LOOP;\n   memo:=memo||jsonb_build_object(''memoryStatement'',jsonb_build_object(''workspaceId'',w,''context'',memory_context,''rows'',memory_rows,''cohort'',memory_cohort));\n  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;\n  END;\n END IF;\n -- Read every original field under the current actor and original selector.\n -- Parent/payload/domain checks are inside the unchanged closed evaluator.\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind''=''application_field'' ORDER BY value->>''id'',value->>''version'' LOOP\n  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>''id'')::uuid AND version=node->>''version'';\n  result:=application_session_eval_field(w,(node->>''id'')::uuid,node->>''version'',memo);memo:=coalesce(result->''memo'',memo);current_source:=result->''value'';\n  IF current_source IS NULL OR current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object(''resourceKind'',''application_field'',''resourceId'',observation.resource_id,''version'',observation.version));\n  currents:=currents||jsonb_build_array(current_source-ARRAY[''held'',''validTo'',''retractedAt'']);\n END LOOP;\n -- Direct native/context roots and every persistent ancestor retain the same\n -- current native admission, D1 lifecycle and immutable high-water behavior.\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind'' IN(''session_message'',''session_context_revision'',''memory'',''workspace_file'') ORDER BY value->>''kind'',value->>''id'',value->>''version'' LOOP\n  IF node->>''kind''=''session_context_revision'' AND read_entity_derivation_source(w,node->>''kind'',(node->>''id'')::uuid) IS NULL THEN\n   RETURN jsonb_build_object(''admitted'',false);END IF;\n  current_source:=read_admitted_native_scope_snapshot(w,node->>''kind'',(node->>''id'')::uuid);\n  IF current_source IS NULL THEN\n   IF node->>''kind''=''session_context_revision'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n   CONTINUE;\n  END IF;\n  IF current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n  current_source:=jsonb_build_object(''workspaceId'',w,''userId'',current_source->''userId'',''assistantId'',current_source->''assistantId'',\n   ''sensitivity'',current_source->''sensitivity'',''compartments'',current_source->''compartments'',''projectIds'',current_source->''projectIds'',\n   ''resourceKind'',node->''kind'',''resourceId'',node->''id'',''version'',current_source->''version'');\n  currents:=currents||jsonb_build_array(current_source);\n  IF node->>''kind''=''session_context_revision'' THEN\n   IF current_source->>''version'' IS DISTINCT FROM node->>''version'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n   immutable:=immutable||jsonb_build_array(current_source);\n  END IF;\n END LOOP;\n -- Every original derivation envelope still applies, including those on\n -- native ancestors. The full closure contains no raw Entity source; any such\n -- source already delegated above to the unchanged original evaluator.\n FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)\n  ON d.resource_kind=ancestor.value->>''kind'' AND d.resource_id=(ancestor.value->>''id'')::uuid WHERE d.workspace_id=w LOOP\n  IF workflow_evidence_envelope_visible(w,jsonb_build_object(''workspaceId'',w,\n   ''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids)) IS NOT TRUE THEN\n   RETURN jsonb_build_object(''admitted'',false);END IF;\n END LOOP;\n -- The evaluator contract is also current at return.\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n  WHERE oid=''public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)''::regprocedure)\n  IS DISTINCT FROM ''b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca'' THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018'' THEN RETURN NULL;END IF;\n\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n\n IF memo ? ''memoryStatement'' THEN\n  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;\n  SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''version'',scope_version::text) ORDER BY id),''[]'') INTO memory_cohort FROM memories WHERE workspace_id=w;\n  IF memory_cohort IS DISTINCT FROM memo#>''{memoryStatement,cohort}'' THEN RETURN NULL;END IF;\n  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n   memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''source''] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''lineage''] THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n \n IF native_turn_helpers_current() IS NOT TRUE\n  OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n   WHERE oid=''public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)''::regprocedure)\n   IS DISTINCT FROM ''2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376'' THEN RETURN NULL;END IF;\n RETURN jsonb_build_object(''admitted'',true,''immutable'',immutable,''current'',currents);\nEND "],"hashLiteralReview":{"fingerprints":{"application_native_worklist_helpers_current()":[{"partIndex":1,"beforeSha256":"02e70f65f7989546a3962c0f34f9854fe70f944661196b381bb50e4503cba8f7","afterSha256":"8c337f0898baa5adbbfa52c162fe0703e956c5c62b98d39c17ec513cb5b20236"},{"partIndex":3,"beforeSha256":"8c337f0898baa5adbbfa52c162fe0703e956c5c62b98d39c17ec513cb5b20236","afterSha256":"83103431c6d02a13441b1bcbb81f733136bd7b723df37599d9dfb15db758f4c8"}]},"frozen":{"2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376":2,"8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd":2,"b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca":2,"decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018":2},"historical":{}}},{"signature":"read_native_file_session_field_snapshots(uuid,uuid[],text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_file_session_field_snapshots","prorows":1000,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t","t"],"proargnames":["w","ids","versions","ord","snapshot"],"proargtypes":["2950","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","2951","1009","23","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE buffered jsonb:=''[]'';position integer;memo jsonb:=''{}'';result jsonb;resource application_field_resources;\n frame_nodes jsonb;frame_result jsonb;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\nBEGIN\n IF application_native_file_capture_helpers_current() IS NOT TRUE THEN RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;END IF;\n IF ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 4096 OR cardinality(ids)<>cardinality(versions)\n  OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n -- This is a NEW complete proof after capture materialization. Initial\n -- capture state is never an input. Invalid roots retain per-row held results.\n IF cardinality(ids)<=100 AND array_ndims(ids)=1 AND array_lower(ids,1)=1\n  AND array_ndims(versions)=1 AND array_lower(versions,1)=1\n  AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)\n  AND NOT EXISTS(SELECT 1 FROM unnest(ids,versions) root(id,version)\n   LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id\n   LEFT JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=field.id\n    AND observation.version=root.version WHERE field.id IS NULL OR observation.resource_id IS NULL) THEN\n  WITH RECURSIVE candidates(kind,id,version) AS (\n   SELECT ''application_field''::text,root.id,root.version FROM unnest(ids,versions) root(id,version)\n   UNION SELECT edge.kind,edge.id,edge.version FROM candidates node\n    CROSS JOIN LATERAL application_scope_source_edges(w,node.kind,node.id,node.version) edge\n  ), bounded AS MATERIALIZED(SELECT * FROM candidates LIMIT 4097)\n  SELECT coalesce(jsonb_agg(to_jsonb(node)),''[]'') INTO frame_nodes FROM bounded node;\n  IF jsonb_array_length(frame_nodes)<=4096\n   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node\n    WHERE node->>''kind'' IS NULL OR node->>''id'' IS NULL OR node->>''version'' IS NULL)\n   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node\n    LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>''id'')::uuid\n    LEFT JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=field.id\n     AND observation.version=node->>''version''\n    WHERE node->>''kind''=''application_field'' AND(field.id IS NULL OR observation.resource_id IS NULL))\n   AND EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node\n    JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>''id'')::uuid\n    WHERE node->>''kind''=''application_field'' AND field.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n     AND field.type_key=''memory'' AND field.selection=''query_domain'')\n   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(frame_nodes) node\n    JOIN application_field_resources field ON field.workspace_id=w AND field.id=(node->>''id'')::uuid\n    WHERE node->>''kind''=''application_field'' AND field.type_key=''memory''\n     AND(field.selection<>''query_domain'' OR field.selected_version IS NOT NULL)) THEN\n   IF application_native_file_capture_helpers_current() IS NOT TRUE THEN RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;END IF;\n   frame_result:=read_native_file_session_cohort_frame(w,ARRAY(SELECT ''application_field''::text FROM unnest(ids)),ids,versions,true);\n   IF frame_result->>''admitted''=''true'' AND jsonb_typeof(frame_result->''memo'')=''object''\n    AND frame_result#>>''{memo,memoryStatement,workspaceId}''=w::text THEN memo:=frame_result->''memo'';END IF;\n  END IF;\n END IF;\n IF frame_result->>''admitted'' IS DISTINCT FROM ''true'' OR memo#>>''{memoryStatement,workspaceId}'' IS DISTINCT FROM w::text THEN\n  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;\n END IF;\n FOR position IN 1..cardinality(ids) LOOP\n  SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=ids[position];\n  IF FOUND AND resource.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n   AND(resource.type_key IN(''session_message'',''session_message_annotation'')\n    OR resource.type_key=''memory'' AND resource.selected_version IS NULL\n     AND resource.selection IN(''read'',''query'',''identity'',''query_domain'')\n     AND coalesce(memo#>>''{memoryStatement,workspaceId}''=w::text,false)) THEN\n   result:=application_session_eval_field(w,ids[position],versions[position],memo);memo:=coalesce(result->''memo'',memo);snapshot:=coalesce(result->''value'',''{\"held\":true}''::jsonb);\n  ELSE snapshot:=read_admitted_application_field_snapshot(w,ids[position],versions[position]);END IF;\n  ord:=position;buffered:=buffered||jsonb_build_array(jsonb_build_object(''ord'',ord,''snapshot'',snapshot));\n END LOOP;\n\n -- No seed proof from capture enters this function. Qualify these buffered\n -- snapshots with another complete proof belonging to this new invocation.\n IF application_native_file_capture_helpers_current() IS NOT TRUE THEN\n  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;\n END IF;\n IF application_native_file_frame_current(w,ARRAY(SELECT ''application_field''::text FROM unnest(ids)),ids,versions,frame_result) IS NOT TRUE THEN\n  RETURN QUERY SELECT * FROM read_native_session_field_snapshots(w,ids,versions);RETURN;\n END IF;\n RETURN QUERY SELECT (item->>''ord'')::integer,item->''snapshot'' FROM jsonb_array_elements(buffered) item ORDER BY (item->>''ord'')::integer;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_native_file_worklist_evidence(uuid,text[],uuid[],text[],boolean,boolean)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_file_worklist_evidence","prorows":0,"pronargs":6,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","kinds","ids","versions","include_memory","return_frame"],"proargtypes":["2950","1009","2951","1009","16","16"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":{"$slot":{"kind":"argumentDefaults","identity":"boolean_false","encoding":"string"}},"pronargdefaults":1},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;nodes jsonb;node jsonb;\n observation application_field_observations;memo jsonb:=''{}'';result jsonb;current_source jsonb;worklist_frame jsonb;\n schedule jsonb;ready record;memo_size integer;native_currents jsonb;native_immutable jsonb;\n immutable jsonb:=''[]'';currents jsonb:=''[]'';dependency record;fresh_nodes jsonb;memory_candidate record;memory_rows jsonb;memory_cohort jsonb;memory_context jsonb;memory_lineage jsonb;memory_source jsonb;\nBEGIN\n IF application_native_worklist_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n\n IF native_turn_helpers_current() IS NOT TRUE\n  OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n   WHERE oid=''public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)''::regprocedure)\n   IS DISTINCT FROM ''2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376'' THEN RETURN NULL;END IF;\n \n IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100\n  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)\n  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n -- A changed original evaluator retains its full original fallback contract.\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n  WHERE oid=''public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)''::regprocedure)\n  IS DISTINCT FROM ''b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca'' THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018'' THEN RETURN NULL;END IF;\n -- Every other profile/resource family delegates to the original validator.\n IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN(''application_field'',''session_context_revision'',''session_message'',''memory'',''workspace_file'')) OR NOT include_memory AND ''memory''=ANY(kinds) THEN RETURN NULL;END IF;\n IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''session_messages''::regclass WHERE r.rolname=session_user\n  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE''))) THEN RETURN NULL;END IF;\n -- Ineligible root metadata adds no native lock or full-closure walk.\n IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)\n  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id\n  WHERE root.kind=''application_field'' AND(field.id IS NULL OR field.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n   OR NOT(field.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND field.type_key=''memory''))) THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind'' NOT IN(''application_field'',''application_query_domain'',''session_context_revision'',''session_message'',''memory'',''workspace_file''))\n  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''memory'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid\n   WHERE n->>''kind''=''application_field'' AND(f.id IS NULL OR f.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb OR NOT(f.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND f.type_key=''memory''))) THEN RETURN NULL;END IF;\n\n -- Discover eligibility only. A file with its own derivation, any historical\n -- selector, or independent Page ancestry keeps the complete original path.\n IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''workspace_file'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN scope_derivations d\n   ON d.workspace_id=w AND d.resource_kind=''workspace_file'' AND d.resource_id=(n->>''id'')::uuid\n   WHERE n->>''kind''=''workspace_file'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f\n   ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field''\n   AND (f.selected_version IS NOT NULL OR f.selection=''history'')) THEN RETURN NULL;END IF;\n -- Decline an overfull graph before the original per-file Page walks.\n IF native_worklist_edges(w,nodes) IS NULL THEN RETURN NULL;END IF;\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind''=''workspace_file'' LOOP\n  IF read_admitted_page_dependencies(w,''workspace_file'',(node->>''id'')::uuid,node->>''version'')\n   IS DISTINCT FROM ''[]''::jsonb THEN RETURN NULL;END IF;\n END LOOP;\n -- Source-denied physical candidates still require fresh remote cohort\n -- context. No fast-path admission is inferred from the original closure.\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n\n -- This private argument is created only by this closed SQL operation. It holds\n -- scope metadata, never a Memory business row or a shared selected-field grant.\n IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN\n  BEGIN\n   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;\n   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_context:=application_memory_query_context(w);\n   IF memory_context#>>''{policy,nativeDefault}'' IS DISTINCT FROM ''true'' THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_rows:=''{}'';memory_cohort:=''[]'';\n   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object(''kind'',''memory'',''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n    memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object(''source'',memory_source,''lineage'',memory_lineage));\n    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object(''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text));\n   END LOOP;\n   memo:=memo||jsonb_build_object(''memoryStatement'',jsonb_build_object(''workspaceId'',w,''context'',memory_context,''rows'',memory_rows,''cohort'',memory_cohort));\n  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;\n  END;\n END IF;\n -- Read every original field under the current actor and original selector.\n -- Parent/payload/domain checks are inside the unchanged closed evaluator.\n IF return_frame AND memo#>>''{memoryStatement,workspaceId}'' IS DISTINCT FROM w::text THEN RETURN NULL;END IF;\n worklist_frame:=native_worklist_seed(w,nodes);\n IF worklist_frame IS NULL THEN RETURN NULL;END IF;\n memo:=memo||jsonb_build_object(''nativeWorklist'',true);\n\n -- Metadata-only schedule. Its bound is independent of the canonical graph\n -- limit; an overfull schedule keeps the original recursive evaluator.\n WITH RECURSIVE reach(root,node) AS (\n  SELECT (n->>''kind'')||'':''||(n->>''id'')||'':''||(n->>''version''),(n->>''kind'')||'':''||(n->>''id'')||'':''||(n->>''version'') FROM jsonb_array_elements(nodes) n\n  UNION\n  SELECT r.root,(e->>''kind'')||'':''||(e->>''id'')||'':''||(e->>''version'') FROM reach r\n   CROSS JOIN LATERAL jsonb_array_elements(worklist_frame#>ARRAY[''edges'',r.node]) e\n ), bounded AS MATERIALIZED(SELECT * FROM reach LIMIT 262145), grouped AS(\n  SELECT bounded.root,coalesce(jsonb_agg(''field:''||substring(bounded.node FROM 19) ORDER BY bounded.node)\n   FILTER(WHERE bounded.node LIKE ''application_field:%''),''[]'') fields FROM bounded GROUP BY bounded.root\n ) SELECT CASE WHEN (SELECT count(*) FROM bounded)>262144 THEN NULL ELSE\n  (SELECT jsonb_object_agg(root,fields) FROM grouped) END INTO schedule;\n -- Extended empty-domain fields cannot prime ordinary native entries.\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f\n  ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field''\n  AND(f.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb OR NOT(f.type_key IN(''session_message'',''session_message_annotation'')\n   OR f.type_key=''memory'' AND memo#>>''{memoryStatement,workspaceId}''=w::text))) THEN schedule:=NULL;END IF;\n -- Direct native/context roots and every persistent ancestor retain the same\n -- current native admission, D1 lifecycle and immutable high-water behavior.\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind'' IN(''session_message'',''session_context_revision'',''memory'',''workspace_file'') ORDER BY value->>''kind'',value->>''id'',value->>''version'' LOOP\n  IF node->>''kind''=''session_context_revision'' AND native_worklist_source(w,node->>''kind'',(node->>''id'')::uuid,worklist_frame) IS NULL THEN\n   RETURN NULL;END IF;\n  current_source:=native_detached_snapshot(w,node->>''kind'',(node->>''id'')::uuid,node->>''version'',(CASE WHEN memo->''nativeWorklist''=''true''::jsonb THEN worklist_frame END));\n  IF current_source IS NULL THEN\n   IF node->>''kind''=''session_context_revision'' THEN RETURN NULL;END IF;\n   CONTINUE;\n  END IF;\n  IF current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN NULL;END IF;\n  current_source:=jsonb_build_object(''workspaceId'',w,''userId'',current_source->''userId'',''assistantId'',current_source->''assistantId'',\n   ''sensitivity'',current_source->''sensitivity'',''compartments'',current_source->''compartments'',''projectIds'',current_source->''projectIds'',\n   ''resourceKind'',node->''kind'',''resourceId'',node->''id'',''version'',current_source->''version'');\n  currents:=currents||jsonb_build_array(current_source);\n  IF node->>''kind''=''session_context_revision'' THEN\n   IF current_source->>''version'' IS DISTINCT FROM node->>''version'' THEN RETURN NULL;END IF;\n   immutable:=immutable||jsonb_build_array(current_source);\n  END IF;\n END LOOP;\n -- Every original derivation envelope still applies, including those on\n -- native ancestors. The full closure contains no raw Entity source; any such\n -- source already delegated above to the unchanged original evaluator.\n FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)\n  ON d.resource_kind=ancestor.value->>''kind'' AND d.resource_id=(ancestor.value->>''id'')::uuid WHERE d.workspace_id=w LOOP\n  IF workflow_evidence_envelope_visible(w,jsonb_build_object(''workspaceId'',w,\n   ''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids)) IS NOT TRUE THEN\n   RETURN NULL;END IF;\n END LOOP;\n native_currents:=currents;native_immutable:=immutable;currents:=''[]'';immutable:=''[]'';\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind''=''application_field'' ORDER BY coalesce(jsonb_array_length(schedule->((value->>''kind'')||'':''||(value->>''id'')||'':''||(value->>''version''))),0),value->>''id'',value->>''version'' LOOP\n -- A completed scope is a conjunction of already completed obligations.\n -- Never create a pending allow, overwrite a busy entry, or re-enable a reset\n -- worklist. The original evaluator remains the consumer and fallback.\n IF schedule IS NOT NULL AND memo->''nativeWorklist''=''true''::jsonb AND NOT memo ? ''emptyQueries'' THEN\n  SELECT count(*) INTO memo_size FROM jsonb_object_keys(memo-''nativeWorklist''-''memoryStatement'');\n  FOR ready IN SELECT * FROM jsonb_each(schedule) WHERE key LIKE ''session_message:%''\n   OR key LIKE ''session_context_revision:%'' OR key LIKE ''memory:%'' OR key LIKE ''workspace_file:%'' LOOP\n   EXIT WHEN memo_size>=4096;\n   IF NOT memo ? (''native:''||ready.key) AND NOT EXISTS(\n    SELECT 1 FROM jsonb_array_elements_text(ready.value) dependency_key\n    WHERE memo#>>ARRAY[dependency_key,''busy'']=''true''\n     OR scope_review_state_held(''application_field'',substring(dependency_key FROM 7 FOR 36)::uuid)\n     OR memo#>>ARRAY[dependency_key,''value'',''held''] IS DISTINCT FROM ''false''\n     OR memo#>ARRAY[dependency_key,''external''] IS DISTINCT FROM ''[]''::jsonb) THEN\n    memo:=memo||jsonb_build_object(''native:''||ready.key,jsonb_build_object(''value'',true,''external'',''[]''::jsonb));\n    memo_size:=memo_size+1;\n   END IF;\n  END LOOP;\n END IF;\n\n  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>''id'')::uuid AND version=node->>''version'';\n  result:=native_detached_eval_field(w,(node->>''id'')::uuid,node->>''version'',memo,worklist_frame);memo:=coalesce(result->''memo'',memo);current_source:=result->''value'';\n  IF current_source IS NULL OR current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN NULL;END IF;\n  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object(''resourceKind'',''application_field'',''resourceId'',observation.resource_id,''version'',observation.version));\n  currents:=currents||jsonb_build_array(current_source-ARRAY[''held'',''validTo'',''retractedAt'']);\n END LOOP;\n\n -- A completed scope is a conjunction of already completed obligations.\n -- Never create a pending allow, overwrite a busy entry, or re-enable a reset\n -- worklist. The original evaluator remains the consumer and fallback.\n IF schedule IS NOT NULL AND memo->''nativeWorklist''=''true''::jsonb AND NOT memo ? ''emptyQueries'' THEN\n  SELECT count(*) INTO memo_size FROM jsonb_object_keys(memo-''nativeWorklist''-''memoryStatement'');\n  FOR ready IN SELECT * FROM jsonb_each(schedule) WHERE key LIKE ''session_message:%''\n   OR key LIKE ''session_context_revision:%'' OR key LIKE ''memory:%'' OR key LIKE ''workspace_file:%'' LOOP\n   EXIT WHEN memo_size>=4096;\n   IF NOT memo ? (''native:''||ready.key) AND NOT EXISTS(\n    SELECT 1 FROM jsonb_array_elements_text(ready.value) dependency_key\n    WHERE memo#>>ARRAY[dependency_key,''busy'']=''true''\n     OR scope_review_state_held(''application_field'',substring(dependency_key FROM 7 FOR 36)::uuid)\n     OR memo#>>ARRAY[dependency_key,''value'',''held''] IS DISTINCT FROM ''false''\n     OR memo#>ARRAY[dependency_key,''external''] IS DISTINCT FROM ''[]''::jsonb) THEN\n    memo:=memo||jsonb_build_object(''native:''||ready.key,jsonb_build_object(''value'',true,''external'',''[]''::jsonb));\n    memo_size:=memo_size+1;\n   END IF;\n  END LOOP;\n END IF;\n\n SELECT coalesce(jsonb_agg(value ORDER BY value->>''resourceId'',value->>''version''),''[]'') INTO immutable FROM jsonb_array_elements(immutable);\n SELECT coalesce(jsonb_agg(value ORDER BY value->>''resourceId'',value->>''version''),''[]'') INTO currents FROM jsonb_array_elements(currents);\n immutable:=immutable||native_immutable;currents:=currents||native_currents;\n FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)\n  ON d.resource_kind=ancestor.value->>''kind'' AND d.resource_id=(ancestor.value->>''id'')::uuid WHERE d.workspace_id=w LOOP\n  IF workflow_evidence_envelope_visible(w,jsonb_build_object(''workspaceId'',w,\n   ''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids)) IS NOT TRUE THEN\n   RETURN NULL;END IF;\n END LOOP;\n -- The evaluator contract is also current at return.\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n  WHERE oid=''public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)''::regprocedure)\n  IS DISTINCT FROM ''b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca'' THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018'' THEN RETURN NULL;END IF;\n\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n\n IF memo ? ''memoryStatement'' THEN\n  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;\n  SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''version'',scope_version::text) ORDER BY id),''[]'') INTO memory_cohort FROM memories WHERE workspace_id=w;\n  IF memory_cohort IS DISTINCT FROM memo#>''{memoryStatement,cohort}'' THEN RETURN NULL;END IF;\n  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n   memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''source''] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''lineage''] THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n \n IF native_turn_helpers_current() IS NOT TRUE\n  OR (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n   WHERE oid=''public.read_native_session_cohort_evidence(uuid,text[],uuid[],text[],boolean)''::regprocedure)\n   IS DISTINCT FROM ''2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376'' THEN RETURN NULL;END IF;\n IF native_worklist_frame_current(w,worklist_frame) IS NOT TRUE THEN RETURN NULL;END IF;\n IF application_native_worklist_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n -- Native worklists are invocation-local. Only the original canonical memo\n -- entries may cross into the existing independently revalidated capture path.\n memo:=memo-''nativeWorklist'';\n IF return_frame THEN RETURN jsonb_build_object(''admitted'',true,''immutable'',immutable,''current'',currents,''memo'',memo,''lineage'',fresh_nodes);END IF;\n RETURN jsonb_build_object(''admitted'',true,''immutable'',immutable,''current'',currents);\nEXCEPTION WHEN data_exception OR insufficient_privilege OR no_data_found THEN RETURN NULL;\n WHEN raise_exception THEN\n  IF SQLERRM IN(''page_ancestry_unavailable'',''scope_source_changed'',''scope_evidence_missing'',''scope_operation_denied'',''access_unavailable'',''scope_ancestry_unavailable'') THEN RETURN NULL;END IF;\n  RAISE;\nEND\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{"2afff03ed88d3de82386880a3b582bbfa2c4379b06ecbc06fd98ff467f60c376":2,"8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd":2,"b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca":2,"decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018":2},"historical":{}}},{"signature":"read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_memory_query_cohort_sources","prorows":1000,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t"],"proargnames":["w","kinds","ids","versions","source"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","1009","2951","1009","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE nodes jsonb;selector record;candidate record;root jsonb;attempts integer:=0;\nBEGIN\n SELECT coalesce(jsonb_agg(to_jsonb(n)),''[]'') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n FOR selector IN SELECT DISTINCT q.domain FROM jsonb_to_recordset(nodes) n(kind text,id uuid,version text)\n  JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id AND n.kind=''application_field''\n  JOIN application_field_observations o ON o.workspace_id=w AND o.resource_id=f.id AND o.version=n.version\n  JOIN application_query_domains q ON q.workspace_id=w AND q.id=f.resource_id AND q.type_key=f.type_key AND q.origin=f.origin\n  WHERE f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''query_domain'' LOOP\n  IF selector.domain->>''kind'' IS DISTINCT FROM ''memory_query_domain_v1'' OR application_query_scope_valid(selector.domain->''bounds'') IS NOT TRUE THEN\n   RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n  IF selector.domain->>''includeRetained'' IS DISTINCT FROM ''true'' THEN CONTINUE;END IF;\n  FOR candidate IN SELECT id FROM memories WHERE workspace_id=w ORDER BY id LOOP\n   attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n   root:=read_scope_source(w,''memory'',candidate.id);\n   IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' OR application_query_scope_admits_point(selector.domain->''bounds'',root) IS NOT TRUE THEN CONTINUE;END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',root->''userId'',''assistantId'',root->''assistantId'',''sensitivity'',root->''sensitivity'',\n    ''compartments'',root->''compartments'',''projectIds'',root->''projectIds'',''resourceKind'',''memory'',''resourceId'',candidate.id,''version'',root->''version'');RETURN NEXT;\n  END LOOP;\n END LOOP;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_native_personal_title_group(uuid,uuid[],uuid[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_personal_title_group","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","session_ids","revision_ids"],"proargtypes":["2950","2951","2951"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n assistant uuid:=nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid;\n position integer;head uuid;nodes jsonb;proof jsonb;root jsonb;sources jsonb:=''[]'';payload jsonb;rows_json jsonb:=''[]'';\nBEGIN\n IF application_native_title_group_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n IF actor IS NULL OR assistant IS NULL OR session_ids IS NULL OR revision_ids IS NULL\n  OR array_ndims(session_ids)<>1 OR array_lower(session_ids,1)<>1 OR array_ndims(revision_ids)<>1 OR array_lower(revision_ids,1)<>1\n  OR cardinality(session_ids) NOT BETWEEN 2 AND 50 OR cardinality(session_ids)<>cardinality(revision_ids)\n  OR array_position(session_ids,NULL) IS NOT NULL OR array_position(revision_ids,NULL) IS NOT NULL\n  OR (SELECT count(DISTINCT id) FROM unnest(session_ids) id)<>cardinality(session_ids)\n  OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n  OR current_setting(''app.agent_shared_audience'',true)=''true''\n  OR EXISTS(SELECT 1 FROM pg_roles role JOIN pg_class owned ON owned.oid=''public.session_context_revision_contents''::regclass\n   WHERE role.rolname=session_user AND(role.rolsuper OR role.rolbypassrls OR pg_has_role(role.oid,owned.relowner,''USAGE''))) THEN RETURN NULL;END IF;\n -- Every original head and parent stays bound to its own session. The SHARE\n -- lock is the canonical title reader''s lock, held until this read commits.\n FOR position IN 1..cardinality(session_ids) LOOP\n  IF NOT EXISTS(SELECT 1 FROM sessions s WHERE s.workspace_id=w AND s.id=session_ids[position]\n   AND s.user_id=actor AND s.assistant_id=assistant AND s.visibility=''personal'' AND s.channel_type=''web'' AND s.anchor_kind=''none'')\n   OR session_recording_read_allowed(session_ids[position]) IS NOT TRUE\n   OR recording_source_read_allowed(w,''session_context_revision'',revision_ids[position]) IS NOT TRUE THEN RETURN NULL;END IF;\n  SELECT h.scope_revision_id INTO head FROM session_title_heads h WHERE h.workspace_id=w AND h.session_id=session_ids[position] FOR SHARE;\n  IF head IS DISTINCT FROM revision_ids[position] OR NOT EXISTS(SELECT 1 FROM session_context_scope_revisions r\n   WHERE r.workspace_id=w AND r.id=revision_ids[position] AND r.session_id=session_ids[position]\n    AND r.parent_kind=''session_title'' AND r.parent_id=session_ids[position]) THEN RETURN NULL;END IF;\n  root:=read_entity_derivation_source(w,''session_context_revision'',revision_ids[position]);\n  IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' OR root->>''version'' IS DISTINCT FROM ''1'' THEN RETURN NULL;END IF;\n  SELECT coalesce(jsonb_agg(to_jsonb(node)),''[]'') INTO nodes\n   FROM application_scope_lineage(w,ARRAY[''session_context_revision''],ARRAY[revision_ids[position]],ARRAY[''1'']) node;\n  -- Keep the exact ordinary Memory/file title branch. Other purposes use\n  -- the unchanged individual reader, including selected Memory history.\n  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''workspace_file'')\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f\n    ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field''\n     AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND f.type_key=''memory'' AND f.selection=''query_domain'')\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f\n    ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field''\n     AND f.type_key=''memory'' AND (f.selected_version IS NOT NULL OR f.selection<>''query_domain'')) THEN RETURN NULL;END IF;\n  sources:=sources||jsonb_build_array(jsonb_build_object(''workspaceId'',root->''workspaceId'',''userId'',root->''userId'',''assistantId'',root->''assistantId'',\n   ''sensitivity'',root->''sensitivity'',''compartments'',root->''compartments'',''projectIds'',root->''projectIds'',\n   ''resourceKind'',''session_context_revision'',''resourceId'',revision_ids[position],''version'',''1''));\n END LOOP;\n proof:=capture_conversation_evidence(w,(SELECT jsonb_agg(jsonb_build_object(\n   ''kind'',''session_context_revision'',''id'',id,''version'',''1'') ORDER BY ordinal)\n   FROM unnest(revision_ids) WITH ORDINALITY input(id,ordinal)));\n IF proof->>''admitted'' IS DISTINCT FROM ''true'' OR NOT coalesce(proof->''immutable'' @> sources,false) THEN RETURN NULL;END IF;\n FOR position IN 1..cardinality(session_ids) LOOP\n  SELECT c.content INTO payload FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=revision_ids[position];\n  IF payload IS NULL THEN RETURN NULL;END IF;\n  rows_json:=rows_json||jsonb_build_array(jsonb_build_object(''sessionId'',session_ids[position],''revisionId'',revision_ids[position],\n   ''content'',payload,''source'',sources->(position-1)));\n END LOOP;\n IF application_native_title_group_helpers_current() IS NOT TRUE THEN RETURN NULL;END IF;\n RETURN rows_json;\nEXCEPTION WHEN invalid_parameter_value THEN\n IF SQLERRM=''scope_ancestry_unavailable'' THEN RETURN NULL;END IF;\n RAISE;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_native_personal_title_group_evidence(uuid,uuid[],uuid[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_personal_title_group_evidence","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","session_ids","revision_ids"],"proargtypes":["2950","2951","2951"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["DECLARE captured jsonb;\nBEGIN\n -- Pin the guard itself before invoking any new helper, including unknown guard code.\n IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'') FROM pg_catalog.pg_proc p\n  WHERE p.oid=''public.application_native_title_acquisition_helpers_current()''::regproced