HEN RETURN NULL;END IF;\n -- Every other profile/resource family delegates to the original validator.\n IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n  OR EXISTS(SELECT 1 FROM unnest(kinds) kind WHERE kind NOT IN(''application_field'',''session_context_revision'',''session_message'',''memory'')) OR NOT include_memory AND ''memory''=ANY(kinds) THEN RETURN NULL;END IF;\n IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''session_messages''::regclass WHERE r.rolname=session_user\n  AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE''))) THEN RETURN NULL;END IF;\n -- Ineligible root metadata adds no native lock or full-closure walk.\n IF EXISTS(SELECT 1 FROM unnest(kinds,ids) root(kind,id)\n  LEFT JOIN application_field_resources field ON field.workspace_id=w AND field.id=root.id\n  WHERE root.kind=''application_field'' AND(field.id IS NULL OR field.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n   OR NOT(field.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND field.type_key=''memory''))) THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind'' NOT IN(''application_field'',''application_query_domain'',''session_context_revision'',''session_message'',''memory''))\n  OR NOT include_memory AND EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n WHERE n->>''kind''=''memory'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid\n   WHERE n->>''kind''=''application_field'' AND(f.id IS NULL OR f.origin<>''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb OR NOT(f.type_key IN(''session_message'',''session_message_annotation'') OR include_memory AND f.type_key=''memory''))) THEN RETURN NULL;END IF;\n -- Source-denied physical candidates still require fresh remote cohort\n -- context. No fast-path admission is inferred from the original closure.\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,nodes)) THEN RETURN NULL;END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor) THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n\n -- This private argument is created only by this closed SQL operation. It holds\n -- scope metadata, never a Memory business row or a shared selected-field grant.\n IF include_memory AND native_turn_helpers_current() AND (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN\n  BEGIN\n   PERFORM singleton FROM application_policy_contract_epoch WHERE singleton FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM workspace_id FROM application_policy_workspace_epochs WHERE workspace_id=w FOR SHARE NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   PERFORM id FROM memories WHERE workspace_id=w ORDER BY id FOR SHARE NOWAIT;\n   IF NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_context:=application_memory_query_context(w);\n   IF memory_context#>>''{policy,nativeDefault}'' IS DISTINCT FROM ''true'' THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n   memory_rows:=''{}'';memory_cohort:=''[]'';\n   FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n    SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n    IF memory_lineage IS DISTINCT FROM jsonb_build_array(jsonb_build_object(''kind'',''memory'',''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text)) THEN RAISE EXCEPTION ''memory_statement_unavailable'' USING ERRCODE=''55P03'';END IF;\n    memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n    memory_rows:=memory_rows||jsonb_build_object(memory_candidate.id::text,jsonb_build_object(''source'',memory_source,''lineage'',memory_lineage));\n    memory_cohort:=memory_cohort||jsonb_build_array(jsonb_build_object(''id'',memory_candidate.id,''version'',memory_candidate.scope_version::text));\n   END LOOP;\n   memo:=memo||jsonb_build_object(''memoryStatement'',jsonb_build_object(''workspaceId'',w,''context'',memory_context,''rows'',memory_rows,''cohort'',memory_cohort));\n  EXCEPTION WHEN lock_not_available THEN memory_rows:=NULL;memory_context:=NULL;memory_cohort:=NULL;\n  END;\n END IF;\n -- This private port only exports a qualified locked Memory frame. Without\n -- it the caller must use its original reader, not repeat a discarded full proof.\n IF memo#>>''{memoryStatement,workspaceId}'' IS DISTINCT FROM w::text THEN RETURN NULL;END IF;\n -- Read every original field under the current actor and original selector.\n -- Parent/payload/domain checks are inside the unchanged closed evaluator.\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind''=''application_field'' ORDER BY value->>''id'',value->>''version'' LOOP\n  SELECT * INTO STRICT observation FROM application_field_observations WHERE workspace_id=w AND resource_id=(node->>''id'')::uuid AND version=node->>''version'';\n  result:=application_session_eval_field(w,(node->>''id'')::uuid,node->>''version'',memo);memo:=coalesce(result->''memo'',memo);current_source:=result->''value'';\n  IF current_source IS NULL OR current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n  immutable:=immutable||jsonb_build_array(observation.source_scope||jsonb_build_object(''resourceKind'',''application_field'',''resourceId'',observation.resource_id,''version'',observation.version));\n  currents:=currents||jsonb_build_array(current_source-ARRAY[''held'',''validTo'',''retractedAt'']);\n END LOOP;\n -- Direct native/context roots and every persistent ancestor retain the same\n -- current native admission, D1 lifecycle and immutable high-water behavior.\n FOR node IN SELECT value FROM jsonb_array_elements(nodes) WHERE value->>''kind'' IN(''session_message'',''session_context_revision'',''memory'') ORDER BY value->>''kind'',value->>''id'',value->>''version'' LOOP\n  IF node->>''kind''=''session_context_revision'' AND read_entity_derivation_source(w,node->>''kind'',(node->>''id'')::uuid) IS NULL THEN\n   RETURN jsonb_build_object(''admitted'',false);END IF;\n  current_source:=read_admitted_native_scope_snapshot(w,node->>''kind'',(node->>''id'')::uuid);\n  IF current_source IS NULL THEN\n   IF node->>''kind''=''session_context_revision'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n   CONTINUE;\n  END IF;\n  IF current_source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n  current_source:=jsonb_build_object(''workspaceId'',w,''userId'',current_source->''userId'',''assistantId'',current_source->''assistantId'',\n   ''sensitivity'',current_source->''sensitivity'',''compartments'',current_source->''compartments'',''projectIds'',current_source->''projectIds'',\n   ''resourceKind'',node->''kind'',''resourceId'',node->''id'',''version'',current_source->''version'');\n  currents:=currents||jsonb_build_array(current_source);\n  IF node->>''kind''=''session_context_revision'' THEN\n   IF current_source->>''version'' IS DISTINCT FROM node->>''version'' THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n   immutable:=immutable||jsonb_build_array(current_source);\n  END IF;\n END LOOP;\n -- Every original derivation envelope still applies, including those on\n -- native ancestors. The full closure contains no raw Entity source; any such\n -- source already delegated above to the unchanged original evaluator.\n FOR dependency IN SELECT DISTINCT d.* FROM scope_derivations d JOIN jsonb_array_elements(nodes) ancestor(value)\n  ON d.resource_kind=ancestor.value->>''kind'' AND d.resource_id=(ancestor.value->>''id'')::uuid WHERE d.workspace_id=w LOOP\n  IF workflow_evidence_envelope_visible(w,jsonb_build_object(''workspaceId'',w,\n   ''userId'',dependency.user_id,''assistantId'',dependency.assistant_id,''sensitivity'',dependency.sensitivity,\n   ''compartments'',dependency.compartments,''projectIds'',dependency.project_ids)) IS NOT TRUE THEN\n   RETURN jsonb_build_object(''admitted'',false);END IF;\n END LOOP;\n -- The evaluator contract is also current at return.\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc\n  WHERE oid=''public.application_session_eval_scope_current(uuid,text,uuid,text,jsonb)''::regprocedure)\n  IS DISTINCT FROM ''b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca'' THEN RETURN NULL;END IF;\n SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO fresh_nodes FROM application_scope_lineage(w,kinds,ids,versions) n;\n IF nodes IS DISTINCT FROM fresh_nodes THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018'' THEN RETURN NULL;END IF;\n\n IF EXISTS(SELECT 1 FROM read_native_session_query_cohort_nodes(w,fresh_nodes)) THEN RETURN jsonb_build_object(''admitted'',false);END IF;\n IF (SELECT encode(sha256(convert_to(prosrc,''UTF8'')),''hex'') FROM pg_proc WHERE oid=''public.read_native_memory_query_cohort_sources(uuid,text[],uuid[],text[])''::regprocedure)\n  IS DISTINCT FROM ''8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd'' THEN RETURN NULL;END IF;\n -- Complete current Memory query cohorts cannot hide an independent source.\n -- Metadata is not permission; any independent candidate delegates unchanged.\n IF include_memory THEN\n  FOR dependency IN SELECT array_agg(candidate.source->>''resourceKind'') AS kinds,\n    array_agg((candidate.source->>''resourceId'')::uuid) AS ids,array_agg(candidate.source->>''version'') AS versions\n   FROM read_native_memory_query_cohort_sources(w,kinds,ids,versions) WITH ORDINALITY candidate(source,ord)\n   GROUP BY (candidate.ord-1)/100 LOOP\n   IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,dependency.kinds,dependency.ids,dependency.versions)) THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n\n\n IF memo ? ''memoryStatement'' THEN\n  IF native_turn_helpers_current() IS NOT TRUE OR application_memory_query_context(w) IS DISTINCT FROM memory_context OR NOT (NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND (\n m.valid_to IS NOT NULL OR m.retracted_at IS NOT NULL OR m.superseded_by IS NOT NULL OR m.source_session_id IS NOT NULL OR m.source_episode_id IS NOT NULL\n OR EXISTS(SELECT 1 FROM scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=m.id)\n OR EXISTS(SELECT 1 FROM memories prior WHERE prior.workspace_id=w AND prior.superseded_by=m.id)\n OR EXISTS(SELECT 1 FROM native_memory_successor_transitions t WHERE t.workspace_id=w AND (t.predecessor_id=m.id OR t.successor_id=m.id))))\n AND NOT EXISTS(SELECT 1 FROM application_native_resource_owners o WHERE o.workspace_id=w AND o.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND o.resource_type=''memory'')\n AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(nodes) n JOIN application_field_resources f ON f.workspace_id=w AND f.id=(n->>''id'')::uuid WHERE n->>''kind''=''application_field'' AND f.type_key=''memory'' AND (\n  f.selected_version IS NOT NULL OR f.selection NOT IN(''read'',''query'',''identity'',''query_domain'')\n  OR f.selection<>''query_domain'' AND NOT EXISTS(SELECT 1 FROM memories m WHERE m.workspace_id=w AND m.id=f.resource_id)\n  OR EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=f.id AND s.version=n->>''version'')))\n AND (SELECT count(*) FROM (SELECT id FROM memories WHERE workspace_id=w LIMIT 4097) bounded)<=4096) THEN RETURN NULL;END IF;\n  SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',id,''version'',scope_version::text) ORDER BY id),''[]'') INTO memory_cohort FROM memories WHERE workspace_id=w;\n  IF memory_cohort IS DISTINCT FROM memo#>''{memoryStatement,cohort}'' THEN RETURN NULL;END IF;\n  FOR memory_candidate IN SELECT id,scope_version FROM memories WHERE workspace_id=w ORDER BY id LOOP\n   memory_source:=read_admitted_native_scope_snapshot(w,''memory'',memory_candidate.id);\n   SELECT coalesce(jsonb_agg(to_jsonb(n) ORDER BY n.kind,n.id,n.version),''[]'') INTO memory_lineage FROM application_scope_lineage(w,ARRAY[''memory''],ARRAY[memory_candidate.id],ARRAY[memory_candidate.scope_version::text]) n;\n   IF memory_source IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''source''] OR memory_lineage IS DISTINCT FROM memory_rows#>ARRAY[memory_candidate.id::text,''lineage''] THEN RETURN NULL;END IF;\n  END LOOP;\n END IF;\n -- This frame is private to the definer capture in this same SQL invocation.\n RETURN jsonb_build_object(''admitted'',true,''immutable'',immutable,''current'',currents,''memo'',memo);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{"8a01f2a9a01cbe613ce23a519610a77e3ae8354bef88df8e99cab0d32bcc2bcd":2,"b977bab4f04ae2d61d7c7d042225d41a97346466f95352e6f8c8e934bd2a46ca":2,"decf5058016df0127f14f201c843b311dad798075d3a86ed41071523139c7018":2},"historical":{}}},{"signature":"read_native_session_field_dependencies(uuid,text[],uuid[],text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_session_field_dependencies","prorows":1000,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t","t"],"proargnames":["w","kinds","ids","versions","node_version","source"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","1009","2951","1009","25","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE dependency record;item jsonb;rows_json jsonb:=''[]'';memo jsonb:=''{}'';result jsonb;admitted jsonb;native_only boolean:=true;belongs boolean;position integer;\n resource application_field_resources;observation application_field_observations;proof jsonb;history_snapshot jsonb;\n actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;child_kinds text[];child_ids uuid[];child_versions text[];\n eligible boolean;eligible_roots jsonb:=''{}'';root_shape jsonb;\n wrapper_position integer;current_envelope jsonb;child jsonb;wrapper_rows jsonb;wrapper_row jsonb;frozen application_query_domains;\n direct_kinds text[];direct_ids uuid[];direct_versions text[];direct_position integer;history_shape boolean;\n observed_sources jsonb;expected_sources jsonb;delegated jsonb;wrapper_source jsonb;\nBEGIN\n -- Native titles and canonical turn frames delegate their complete stored field roots.\n -- Only a verified frame may carry the original Memory history purpose.\n IF kinds IS NOT NULL AND ids IS NOT NULL AND versions IS NOT NULL AND cardinality(ids) BETWEEN 1 AND 100\n  AND cardinality(kinds)=cardinality(ids) AND cardinality(versions)=cardinality(ids)\n  AND array_position(kinds,NULL) IS NULL AND array_position(ids,NULL) IS NULL AND array_position(versions,NULL) IS NULL\n  AND (actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)\n  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL\n  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL\n  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass WHERE login.rolname=session_user\n    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE'')))) THEN\n  FOR position IN 1..cardinality(ids) LOOP\n   IF kinds[position]<>''session_context_revision'' THEN CONTINUE;END IF;\n\n SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),\n  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind=''application_field'')\n   AND bool_or(s.source_kind=''application_field'' AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id\n    AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history''))\n INTO child_kinds,child_ids,child_versions,eligible\n FROM session_context_scope_revisions r JOIN scope_derivations d ON d.workspace_id=r.workspace_id AND d.resource_kind=''session_context_revision''\n  AND d.resource_id=r.id AND d.resource_version=''1'' AND d.user_id IS NOT DISTINCT FROM r.user_id AND d.assistant_id IS NOT DISTINCT FROM r.assistant_id\n  AND d.sensitivity=r.sensitivity AND d.compartments=r.compartments AND d.project_ids=r.project_ids\n JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id\n WHERE r.workspace_id=w AND r.id=ids[position] AND r.scope_version=1\n  AND (r.parent_kind=''session_title'' AND r.parent_id=r.session_id\n   OR r.parent_kind=''turn_frame'' AND r.parent_id=r.id AND EXISTS(SELECT 1 FROM native_turn_frames frame\n    WHERE frame.workspace_id=w AND frame.id=r.id AND frame.session_id=r.session_id AND frame.format=2));\n IF eligible IS TRUE AND EXISTS(SELECT 1 FROM application_scope_lineage(w,child_kinds,child_ids,child_versions) n WHERE n.kind=''session_context_revision'') THEN eligible:=false;END IF;\n\n   IF eligible IS TRUE THEN\n    eligible_roots:=eligible_roots||jsonb_build_object(position::text,jsonb_build_object(''kinds'',child_kinds,''ids'',child_ids,''versions'',child_versions));\n   END IF;\n  END LOOP;\n  IF eligible_roots<>''{}''::jsonb THEN\n   FOR position IN 1..cardinality(ids) LOOP\n    root_shape:=eligible_roots->position::text;\n    IF root_shape IS NULL THEN\n     RETURN QUERY SELECT * FROM read_native_session_field_dependencies(w,ARRAY[kinds[position]],ARRAY[ids[position]],ARRAY[versions[position]]);\n    ELSE\n     IF versions[position] IS DISTINCT FROM ''1'' THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n     IF EXISTS(SELECT 1 FROM native_turn_frames frame WHERE frame.workspace_id=w AND frame.id=ids[position] AND frame.format=2) THEN\n      IF native_turn_helpers_current() IS NOT TRUE OR native_turn_frame_pair(w,ids[position]) IS NOT TRUE THEN\n       RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n      memo:=conversation_dag(w,jsonb_build_array(jsonb_build_object(''kind'',''session_context_revision'',''id'',ids[position],''version'',''1'')),''[]'');\n      IF memo#>>ARRAY[''native:session_context_revision:''||ids[position]||'':1'',''value''] IS DISTINCT FROM ''true'' THEN\n       RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n     ELSIF session_context_revision_allowed(w,ids[position]) IS NOT TRUE THEN\n      RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n     SELECT array_agg(value) INTO child_kinds FROM jsonb_array_elements_text(root_shape->''kinds'');\n     SELECT array_agg(value::uuid) INTO child_ids FROM jsonb_array_elements_text(root_shape->''ids'');\n     SELECT array_agg(value) INTO child_versions FROM jsonb_array_elements_text(root_shape->''versions'');\n     RETURN QUERY SELECT * FROM read_native_session_field_dependencies(w,child_kinds,child_ids,child_versions);\n    END IF;\n   END LOOP;\n   RETURN;\n  END IF;\n END IF;\n\n -- Each original root keeps its own purpose before union/deduplication.\n IF kinds IS NOT NULL AND ids IS NOT NULL AND versions IS NOT NULL AND cardinality(ids) BETWEEN 1 AND 100\n  AND cardinality(kinds)=cardinality(ids) AND cardinality(versions)=cardinality(ids)\n  AND array_position(kinds,NULL) IS NULL AND array_position(ids,NULL) IS NULL AND array_position(versions,NULL) IS NULL\n  AND EXISTS(SELECT 1 FROM unnest(kinds,ids) r(kind,id) JOIN application_field_resources f ON f.workspace_id=w AND f.id=r.id\n    WHERE r.kind=''application_field'' AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history'') THEN\n  FOR position IN 1..cardinality(ids) LOOP\n   SELECT * INTO resource FROM application_field_resources WHERE workspace_id=w AND id=ids[position]\n    AND kinds[position]=''application_field'' AND origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND type_key=''memory'' AND selection=''history'';\n   IF NOT FOUND THEN\n    RETURN QUERY SELECT * FROM read_native_session_field_dependencies(w,ARRAY[kinds[position]],ARRAY[ids[position]],ARRAY[versions[position]]);\n    CONTINUE;\n   END IF;\n   admitted:=read_admitted_application_field_snapshot(w,ids[position],versions[position]);\n   IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM versions[position] THEN\n    RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   history_snapshot:=admitted;\n   proof:=application_memory_history_status(w,resource.resource_id,resource.selected_version);\n   IF proof IS NULL THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   FOR dependency IN SELECT * FROM read_application_field_dependencies(w,ARRAY[kinds[position]],ARRAY[ids[position]],ARRAY[versions[position]]) LOOP\n    IF EXISTS(SELECT 1 FROM jsonb_array_elements(proof->''ownFields'') f\n      WHERE f->>''id''=dependency.source->>''resourceId'' AND f->>''version''=dependency.node_version)\n     AND NOT EXISTS(SELECT 1 FROM unnest(kinds,ids,versions) r(kind,id,version) WHERE r.kind=''application_field''\n      AND r.id=(dependency.source->>''resourceId'')::uuid AND r.version=dependency.node_version) THEN CONTINUE;END IF;\n    IF dependency.source->>''resourceKind''=''application_field'' AND dependency.source->>''resourceId''=ids[position]::text\n     AND dependency.node_version=versions[position] THEN\n     -- This exact root was canonically admitted after the caller''s metadata discovery.\n     IF dependency.source IS DISTINCT FROM (history_snapshot-ARRAY[''held'',''validTo'',''retractedAt''])\n      OR scope_review_state_held(''application_field'',ids[position]) IS TRUE THEN\n      RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    ELSE\n     result:=application_session_eval_field(w,(dependency.source->>''resourceId'')::uuid,dependency.node_version,memo);\n     memo:=coalesce(result->''memo'',memo);admitted:=result->''value'';\n     IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    END IF;\n    node_version:=dependency.node_version;source:=dependency.source;RETURN NEXT;\n   END LOOP;\n  END LOOP;\n  RETURN;\n END IF;\n -- Typed native session wrappers preserve their own immutable binding and all original roots.\n IF kinds IS NOT NULL AND ids IS NOT NULL AND versions IS NOT NULL AND cardinality(ids) BETWEEN 1 AND 100\n  AND cardinality(kinds)=cardinality(ids) AND cardinality(versions)=cardinality(ids)\n  AND array_position(kinds,NULL) IS NULL AND array_position(ids,NULL) IS NULL AND array_position(versions,NULL) IS NULL\n  AND actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)\n  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL\n  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL\n  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass WHERE login.rolname=session_user\n    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN\n  wrapper_rows:=''{}'';\n  FOR wrapper_position IN 1..cardinality(ids) LOOP\n   SELECT * INTO resource FROM application_field_resources f WHERE f.workspace_id=w AND f.id=ids[wrapper_position]\n    AND kinds[wrapper_position]=''application_field'' AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''\n    AND f.type_key=''session_message'' AND f.selected_version IS NULL AND f.selection IN(''read'',''query'',''identity'',''query_domain'');\n   IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY[kinds[wrapper_position]],ARRAY[ids[wrapper_position]],ARRAY[versions[wrapper_position]]) n\n    JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id WHERE n.kind=''application_field''\n     AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history'') THEN CONTINUE;END IF;\n   history_shape:=false;\n   IF resource.selection<>''query_domain'' THEN\n\n SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),\n  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind=''application_field'')\n   AND bool_or(EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id\n    AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history''))\n INTO direct_kinds,direct_ids,direct_versions,history_shape\n FROM session_messages message JOIN sessions session ON session.id=message.session_id AND session.workspace_id=message.workspace_id\n JOIN scope_derivations d ON d.workspace_id=message.workspace_id AND d.resource_kind=''session_message''\n  AND d.resource_id=message.id AND d.resource_version=''1'' AND d.user_id IS NOT DISTINCT FROM message.user_id\n  AND d.assistant_id IS NOT DISTINCT FROM message.assistant_id AND d.sensitivity=message.sensitivity\n  AND d.compartments=message.compartments AND d.project_ids=message.project_ids\n JOIN scope_derivation_sources link ON link.workspace_id=d.workspace_id AND link.derivation_id=d.id\n CROSS JOIN LATERAL (\n  SELECT link.source_kind,link.source_id,link.source_version WHERE link.source_kind<>''session_context_revision''\n  UNION ALL\n  SELECT edge.source_kind,edge.source_id,edge.source_version FROM native_turn_frames frame\n   JOIN scope_derivations declaration ON declaration.workspace_id=frame.workspace_id\n    AND declaration.resource_kind=''session_context_revision'' AND declaration.resource_id=frame.id AND declaration.resource_version=''1''\n   JOIN scope_derivation_sources edge ON edge.workspace_id=declaration.workspace_id AND edge.derivation_id=declaration.id\n   WHERE link.source_kind=''session_context_revision'' AND link.source_version=''1'' AND frame.workspace_id=w\n    AND frame.id=link.source_id AND frame.session_id=message.session_id AND frame.format=2\n    AND (SELECT count(*) FROM scope_derivation_sources original WHERE original.workspace_id=w AND original.derivation_id=d.id)=1\n    AND native_turn_frame_pair(w,frame.id) IS TRUE\n ) s\n WHERE message.workspace_id=w AND message.id=resource.resource_id AND message.scope_version=1 AND message.scope_held IS FALSE;\n IF history_shape IS TRUE THEN\n  IF EXISTS(SELECT 1 FROM application_scope_lineage(w,direct_kinds,direct_ids,direct_versions) n\n   WHERE n.kind=''session_context_revision'' OR n.kind=''session_message'' AND n.id=resource.resource_id) THEN history_shape:=false;END IF;\n  FOR direct_position IN 1..cardinality(direct_ids) LOOP\n   IF NOT EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=direct_ids[direct_position]\n    AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history'')\n    AND EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY[direct_kinds[direct_position]],ARRAY[direct_ids[direct_position]],ARRAY[direct_versions[direct_position]]) n\n     JOIN application_field_resources f ON f.workspace_id=w AND f.id=n.id WHERE n.kind=''application_field''\n      AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history'') THEN history_shape:=false;END IF;\n  END LOOP;\n END IF;\n\n    IF history_shape IS NOT TRUE THEN CONTINUE;END IF;\n   END IF;\n   SELECT * INTO observation FROM application_field_observations o WHERE o.workspace_id=w AND o.resource_id=resource.id AND o.version=versions[wrapper_position];\n   IF NOT FOUND THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   -- The wrapper was captured by the canonical graph. Rebuilding it through\n   -- the legacy session reader changes query membership for framed history.\n   IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n   memo:=conversation_dag(w,jsonb_build_array(jsonb_build_object(''kind'',''application_field'',''id'',resource.id,''version'',versions[wrapper_position])),''[]'');\n   current_envelope:=memo#>ARRAY[''field:''||resource.id||'':''||versions[wrapper_position],''envelope''];\n   IF current_envelope IS NULL OR current_envelope->>''resourceId'' IS DISTINCT FROM resource.id::text\n    OR current_envelope->>''identity'' IS DISTINCT FROM resource.identity\n    OR current_envelope#>>''{source,version}'' IS DISTINCT FROM versions[wrapper_position]\n    OR current_envelope#>>''{state,recordVersion}'' IS DISTINCT FROM observation.record_version\n    OR current_envelope#>>''{state,policyVersion}'' IS DISTINCT FROM observation.policy_version\n    OR current_envelope#>>''{state,sourceKind}'' IS DISTINCT FROM observation.source_kind\n    OR current_envelope#>>''{state,sourceId}'' IS DISTINCT FROM observation.source_id::text\n    OR current_envelope#>>''{state,sourceVersion}'' IS DISTINCT FROM observation.source_version\n    OR ((current_envelope->''source'')-ARRAY[''resourceKind'',''resourceId'',''version'']) IS DISTINCT FROM observation.source_scope\n    THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   SELECT coalesce(jsonb_agg(jsonb_build_array(s.source_kind,s.source_id::text,s.source_version) ORDER BY s.source_kind,s.source_id::text,s.source_version),''[]'') INTO observed_sources\n    FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=resource.id AND s.version=versions[wrapper_position];\n   SELECT coalesce(jsonb_agg(jsonb_build_array(s->>''resourceKind'',s->>''resourceId'',s->>''version'') ORDER BY s->>''resourceKind'',s->>''resourceId'',s->>''version''),''[]'') INTO expected_sources\n    FROM jsonb_array_elements(current_envelope->''sources'') s;\n   IF observed_sources IS DISTINCT FROM expected_sources THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   admitted:=memo#>ARRAY[''field:''||resource.id||'':''||versions[wrapper_position],''value''];\n   IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM versions[wrapper_position]\n    OR (admitted-ARRAY[''held'',''validTo'',''retractedAt'']) IS DISTINCT FROM current_envelope->''source'' THEN\n    RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n   wrapper_source:=current_envelope->''source'';delegated:=''[]'';\n   IF resource.selection=''query_domain'' THEN\n    SELECT * INTO frozen FROM application_query_domains q WHERE q.workspace_id=w AND q.id=resource.resource_id\n     AND q.origin=resource.origin AND q.type_key=resource.type_key AND q.schema_version=''1'';\n    IF NOT FOUND OR frozen.identity IS DISTINCT FROM observation.source_version OR observation.source_kind<>''application_query_domain''\n     OR observation.source_id IS DISTINCT FROM frozen.id OR jsonb_array_length(current_envelope->''children'')>4096 THEN\n     RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    FOR child IN SELECT value FROM jsonb_array_elements(current_envelope->''children'') LOOP\n     IF child->''origin'' IS DISTINCT FROM resource.origin OR child->>''typeKey''<>''session_message''\n      OR child->>''selection''<>''query'' OR child->>''selectedVersion'' IS NOT NULL\n      OR child#>>''{state,sourceKind}''<>''session_message''\n      OR NOT EXISTS(SELECT 1 FROM session_messages message WHERE message.workspace_id=w AND message.id=(child->>''id'')::uuid\n       AND message.id=(child#>>''{state,sourceId}'')::uuid AND message.session_id=(frozen.domain->>''sessionId'')::uuid\n       AND message.sequence_num<=(frozen.domain->>''throughSequence'')::integer)\n      OR NOT EXISTS(SELECT 1 FROM application_field_observation_sources s WHERE s.workspace_id=w AND s.resource_id=resource.id AND s.version=versions[wrapper_position]\n       AND s.source_kind=''application_field'' AND s.source_id=(child->>''resourceId'')::uuid AND s.source_version=child#>>''{source,version}'') THEN\n      RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n     FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,ARRAY[''application_field''],ARRAY[(child->>''resourceId'')::uuid],ARRAY[child#>>''{source,version}'']) LOOP\n      delegated:=delegated||jsonb_build_array(jsonb_build_object(''version'',dependency.node_version,''source'',dependency.source));\n      IF jsonb_array_length(delegated)>4096 THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n     END LOOP;\n    END LOOP;\n   ELSE\n    IF observation.source_kind<>''session_message'' OR observation.source_id IS DISTINCT FROM resource.resource_id\n     OR observation.source_version<>''1'' OR observation.record_version NOT LIKE ''1:%'' THEN\n     RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,direct_kinds,direct_ids,direct_versions) LOOP\n     delegated:=delegated||jsonb_build_array(jsonb_build_object(''version'',dependency.node_version,''source'',dependency.source));\n     IF jsonb_array_length(delegated)>4096 THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    END LOOP;\n    FOR direct_position IN 1..cardinality(direct_ids) LOOP\n     IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(delegated) s WHERE s#>>''{source,resourceKind}''=''application_field''\n      AND s#>>''{source,resourceId}''=direct_ids[direct_position]::text AND s->>''version''=direct_versions[direct_position]) THEN\n      RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n    END LOOP;\n   END IF;\n   wrapper_rows:=wrapper_rows||jsonb_build_object(wrapper_position::text,jsonb_build_array(jsonb_build_object(''version'',versions[wrapper_position],''source'',wrapper_source))||delegated);\n  END LOOP;\n  IF wrapper_rows<>''{}''::jsonb THEN\n   FOR wrapper_position IN 1..cardinality(ids) LOOP\n    IF wrapper_rows ? wrapper_position::text THEN\n     RETURN QUERY SELECT value->>''version'',value->''source'' FROM jsonb_array_elements(wrapper_rows->wrapper_position::text);\n    ELSE\n     RETURN QUERY SELECT * FROM read_native_session_field_dependencies(w,ARRAY[kinds[wrapper_position]],ARRAY[ids[wrapper_position]],ARRAY[versions[wrapper_position]]);\n    END IF;\n   END LOOP;\n   RETURN;\n  END IF;\n END IF;\n FOR dependency IN SELECT * FROM read_application_field_dependencies(w,kinds,ids,versions) LOOP\n  SELECT origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND type_key IN(''session_message'',''session_message_annotation'') INTO belongs\n   FROM application_field_resources WHERE workspace_id=w AND id=(dependency.source->>''resourceId'')::uuid;\n  IF belongs IS DISTINCT FROM true THEN native_only:=false;END IF;\n  rows_json:=rows_json||jsonb_build_array(jsonb_build_object(''version'',dependency.node_version,''source'',dependency.source));\n END LOOP;\n IF NOT native_only THEN RETURN QUERY SELECT * FROM read_admitted_application_field_dependencies(w,kinds,ids,versions);RETURN;END IF;\n IF (SELECT encode(sha256(convert_to(to_jsonb(guard_proc)::text,''UTF8'')),''hex'') FROM pg_proc guard_proc WHERE guard_proc.oid=''native_turn_helpers_current()''::regprocedure)\n  IS DISTINCT FROM ''",{"slot":{"kind":"fingerprint","identity":"native_turn_helpers_current()"}},"'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n memo:=conversation_dag(w,coalesce((SELECT jsonb_agg(jsonb_build_object(''kind'',''application_field'',''id'',entry.node#>>''{source,resourceId}'',''version'',entry.node->>''version'')) FROM jsonb_array_elements(rows_json) entry(node)),''[]''::jsonb),''[]'');\n FOR item IN SELECT value FROM jsonb_array_elements(rows_json) LOOP\n  admitted:=memo#>ARRAY[''field:''||(item#>>''{source,resourceId}'')||'':''||(item->>''version''),''value''];\n  IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' THEN RAISE EXCEPTION ''scope_operation_denied'' USING ERRCODE=''42501'';END IF;\n END LOOP;\n RETURN QUERY SELECT value->>''version'',value->''source'' FROM jsonb_array_elements(rows_json);\nEND "],"hashLiteralReview":{"fingerprints":{"native_turn_helpers_current()":[{"partIndex":1,"beforeSha256":"b0882a6efdca147d0fb91d6e5aff82969df78f207811dd94559a7ed846b6216b","afterSha256":"a97df58c78445ac9dabd1fda4f844cf8c708f2e5832e12f9304bcbbf6b502604"}]},"frozen":{},"historical":{}}},{"signature":"read_native_session_field_snapshots(uuid,uuid[],text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_session_field_snapshots","prorows":1000,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t","t"],"proargnames":["w","ids","versions","ord","snapshot"],"proargtypes":["2950","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","2951","1009","23","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE roots jsonb;memo jsonb;context jsonb;policy_revision jsonb;entry record;owner_login boolean;\nBEGIN\n IF ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 4096 OR cardinality(ids)<>cardinality(versions)\n  OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL\n  OR array_ndims(ids)<>1 OR array_lower(ids,1)<>1 OR array_ndims(versions)<>1 OR array_lower(versions,1)<>1\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass\n  WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE'')))\n INTO owner_login;\n SELECT coalesce(jsonb_agg(root),''[]'') INTO roots FROM (\n  SELECT DISTINCT jsonb_build_object(''kind'',''application_field'',''id'',input.id,''version'',input.version) root\n  FROM unnest(ids,versions) input(id,version) JOIN application_field_resources f ON f.workspace_id=w AND f.id=input.id\n  WHERE f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key IN(''session_message'',''session_message_annotation'')\n ) native;\n IF roots<>''[]'' AND NOT owner_login THEN\n  IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  context:=native_turn_context();\n  SELECT jsonb_build_array(c.revision,p.revision) INTO policy_revision\n  FROM application_policy_contract_epoch c CROSS JOIN application_policy_workspace_epochs p\n  WHERE c.singleton AND p.workspace_id=w;\n IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  memo:=conversation_dag(w,roots,''[]'');\n END IF;\n FOR entry IN SELECT input.*,f.origin,f.type_key FROM unnest(ids,versions) WITH ORDINALITY input(id,version,position)\n  LEFT JOIN application_field_resources f ON f.workspace_id=w AND f.id=input.id ORDER BY input.position LOOP\n  IF entry.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND entry.type_key IN(''session_message'',''session_message_annotation'') THEN\n   snapshot:=coalesce(nullif(memo#>ARRAY[''field:''||entry.id||'':''||entry.version,''value''],''null''::jsonb),''{\"held\":true}''::jsonb);\n  ELSE\n   snapshot:=read_admitted_application_field_snapshot(w,entry.id,entry.version);\n  END IF;\n  ord:=entry.position;RETURN NEXT;\n END LOOP;\n -- PL/pgSQL buffers SETOF results: no row escapes before this final fence.\n IF memo IS NOT NULL AND (native_turn_helpers_current() IS NOT TRUE OR native_turn_context() IS DISTINCT FROM context\n  OR policy_revision IS DISTINCT FROM (SELECT jsonb_build_array(c.revision,p.revision) FROM application_policy_contract_epoch c\n   CROSS JOIN application_policy_workspace_epochs p WHERE c.singleton AND p.workspace_id=w)\n  OR clock_timestamp()>=(memo->>''validUntil'')::timestamptz)\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_native_session_query_cohort_nodes(uuid,jsonb)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_session_query_cohort_nodes","prorows":1000,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","t"],"proargnames":["w","nodes","source"],"proargtypes":["2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","3802","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE item record;selector record;message record;specs jsonb:=''[]'';root jsonb;kind text;id uuid;attempts integer:=0;\n candidates jsonb;part record;has_external boolean:=false;\nBEGIN\n IF jsonb_typeof(nodes) IS DISTINCT FROM ''array'' OR jsonb_array_length(nodes)>4096 THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n FOR item IN SELECT DISTINCT q.type_key,q.domain FROM jsonb_to_recordset(nodes) node(kind text,id uuid,version text)\n  JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=node.id AND node.kind=''application_field''\n  JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=resource.id AND observation.version=node.version\n  JOIN application_query_domains q ON q.workspace_id=w AND q.id=resource.resource_id AND q.origin=resource.origin AND q.type_key=resource.type_key\n  WHERE resource.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND resource.type_key IN(''session_message'',''session_message_annotation'')\n   AND resource.selection=''query_domain'' LOOP\n  IF item.domain->>''kind'' IS DISTINCT FROM ''session_query_domain_v1'' OR application_query_scope_valid(item.domain->''bounds'') IS NOT TRUE\n   OR jsonb_typeof(item.domain->''visibility'') IS DISTINCT FROM ''object'' OR jsonb_typeof(item.domain->''throughSequence'') IS DISTINCT FROM ''number''\n   OR (item.domain->>''throughSequence'')::integer<0 OR item.domain->>''sessionId'' IS NULL THEN\n   RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n  specs:=specs||jsonb_build_array(jsonb_build_object(''type'',item.type_key,''sessionId'',item.domain->''sessionId'',\n   ''bounds'',item.domain->''bounds'',''visibility'',item.domain->''visibility'',''through'',item.domain->''throughSequence''));\n END LOOP;\n -- A complete fresh physical-cohort superset can prove there are no\n -- independent-source references before expensive native scope snapshots.\n -- This grants no local rights and does not reuse an envelope or permission.\n SELECT coalesce(jsonb_agg(jsonb_build_object(''kind'',n.kind,''id'',n.id,''version'',n.version)),''[]'') INTO candidates FROM (\n  SELECT DISTINCT CASE WHEN spec.value->>''type''=''session_message'' THEN ''session_message'' ELSE ''session_context_revision'' END AS kind,\n   CASE WHEN spec.value->>''type''=''session_message'' THEN m.id ELSE h.scope_revision_id END AS id,\n   CASE WHEN spec.value->>''type''=''session_message'' THEN m.scope_version::text ELSE ''1'' END AS version\n  FROM jsonb_array_elements(specs) spec(value)\n  JOIN session_messages m ON m.workspace_id=w AND m.session_id=(spec.value->>''sessionId'')::uuid AND m.sequence_num<=(spec.value->>''through'')::integer\n  LEFT JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id\n  WHERE spec.value->>''type''=''session_message'' OR h.scope_revision_id IS NOT NULL\n  LIMIT 4097\n ) n;\n IF jsonb_array_length(candidates)>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n FOR part IN SELECT array_agg(node->>''kind'') AS kinds,array_agg((node->>''id'')::uuid) AS ids,array_agg(node->>''version'') AS versions\n  FROM jsonb_array_elements(candidates) WITH ORDINALITY candidate(node,ord) GROUP BY (ord-1)/100 LOOP\n  IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,part.kinds,part.ids,part.versions)) THEN has_external:=true;EXIT;END IF;\n END LOOP;\n IF NOT has_external THEN RETURN;END IF;\n -- Equal scope/visibility prefixes have an exact union at their maximum\n -- sequence. Field values never participate in this metadata normalization.\n FOR selector IN SELECT value->>''type'' AS type_key,(value->>''sessionId'')::uuid AS session_id,\n  value->''bounds'' AS bounds,value->''visibility'' AS visibility,max((value->>''through'')::integer) AS through_sequence\n  FROM jsonb_array_elements(specs) GROUP BY value->>''type'',value->>''sessionId'',value->''bounds'',value->''visibility'' LOOP\n  FOR message IN SELECT m.id,m.scope_version,h.scope_revision_id FROM session_messages m\n   LEFT JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id\n   WHERE m.workspace_id=w AND m.session_id=selector.session_id AND m.sequence_num<=selector.through_sequence ORDER BY m.sequence_num,m.id LOOP\n   IF selector.type_key=''session_message'' THEN kind:=''session_message'';id:=message.id;\n   ELSE kind:=''session_context_revision'';id:=message.scope_revision_id;IF id IS NULL THEN CONTINUE;END IF;END IF;\n   root:=read_scope_source(w,kind,id);\n   IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' THEN CONTINUE;END IF;\n   IF application_query_scope_admits_point(selector.bounds,root) IS NOT TRUE\n    OR root->>''userId'' IS NOT NULL AND root->>''userId'' IS DISTINCT FROM selector.visibility->>''userId''\n    OR root->>''assistantId'' IS NOT NULL AND selector.visibility->''assistants''<>''null''::jsonb\n     AND NOT coalesce(selector.visibility->''assistants'' ? (root->>''assistantId''),false) THEN CONTINUE;END IF;\n   attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',root->''userId'',''assistantId'',root->''assistantId'',\n    ''sensitivity'',root->''sensitivity'',''compartments'',root->''compartments'',''projectIds'',root->''projectIds'',\n    ''resourceKind'',kind,''resourceId'',id,''version'',root->''version'');RETURN NEXT;\n  END LOOP;\n END LOOP;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_native_session_query_cohort_sources(uuid,text[],uuid[],text[])","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_native_session_query_cohort_sources","prorows":1000,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","i","t"],"proargnames":["w","kinds","ids","versions","source"],"proargtypes":["2950","1009","2951","1009"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":["2950","1009","2951","1009","3802"],"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE item record;selector record;message record;specs jsonb:=''[]'';root jsonb;kind text;id uuid;attempts integer:=0;\n candidates jsonb;part record;has_external boolean:=false;\nBEGIN\n IF kinds IS NULL OR ids IS NULL OR versions IS NULL OR cardinality(ids) NOT BETWEEN 1 AND 100\n  OR cardinality(kinds)<>cardinality(ids) OR cardinality(versions)<>cardinality(ids)\n  OR array_position(kinds,NULL) IS NOT NULL OR array_position(ids,NULL) IS NOT NULL OR array_position(versions,NULL) IS NOT NULL THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n FOR item IN SELECT DISTINCT q.type_key,q.domain FROM application_scope_lineage(w,kinds,ids,versions) node\n  JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=node.id AND node.kind=''application_field''\n  JOIN application_field_observations observation ON observation.workspace_id=w AND observation.resource_id=resource.id AND observation.version=node.version\n  JOIN application_query_domains q ON q.workspace_id=w AND q.id=resource.resource_id AND q.origin=resource.origin AND q.type_key=resource.type_key\n  WHERE resource.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb AND resource.type_key IN(''session_message'',''session_message_annotation'')\n   AND resource.selection=''query_domain'' LOOP\n  IF item.domain->>''kind'' IS DISTINCT FROM ''session_query_domain_v1'' OR application_query_scope_valid(item.domain->''bounds'') IS NOT TRUE\n   OR jsonb_typeof(item.domain->''visibility'') IS DISTINCT FROM ''object'' OR jsonb_typeof(item.domain->''throughSequence'') IS DISTINCT FROM ''number''\n   OR (item.domain->>''throughSequence'')::integer<0 OR item.domain->>''sessionId'' IS NULL THEN\n   RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n  specs:=specs||jsonb_build_array(jsonb_build_object(''type'',item.type_key,''sessionId'',item.domain->''sessionId'',\n   ''bounds'',item.domain->''bounds'',''visibility'',item.domain->''visibility'',''through'',item.domain->''throughSequence''));\n END LOOP;\n -- A complete fresh physical-cohort superset can prove there are no\n -- independent-source references before expensive native scope snapshots.\n -- This grants no local rights and does not reuse an envelope or permission.\n SELECT coalesce(jsonb_agg(jsonb_build_object(''kind'',n.kind,''id'',n.id,''version'',n.version)),''[]'') INTO candidates FROM (\n  SELECT DISTINCT CASE WHEN spec.value->>''type''=''session_message'' THEN ''session_message'' ELSE ''session_context_revision'' END AS kind,\n   CASE WHEN spec.value->>''type''=''session_message'' THEN m.id ELSE h.scope_revision_id END AS id,\n   CASE WHEN spec.value->>''type''=''session_message'' THEN m.scope_version::text ELSE ''1'' END AS version\n  FROM jsonb_array_elements(specs) spec(value)\n  JOIN session_messages m ON m.workspace_id=w AND m.session_id=(spec.value->>''sessionId'')::uuid AND m.sequence_num<=(spec.value->>''through'')::integer\n  LEFT JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id\n  WHERE spec.value->>''type''=''session_message'' OR h.scope_revision_id IS NOT NULL\n  LIMIT 4097\n ) n;\n IF jsonb_array_length(candidates)>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n FOR part IN SELECT array_agg(node->>''kind'') AS kinds,array_agg((node->>''id'')::uuid) AS ids,array_agg(node->>''version'') AS versions\n  FROM jsonb_array_elements(candidates) WITH ORDINALITY candidate(node,ord) GROUP BY (ord-1)/100 LOOP\n  IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,part.kinds,part.ids,part.versions)) THEN has_external:=true;EXIT;END IF;\n END LOOP;\n IF NOT has_external THEN RETURN;END IF;\n -- Equal scope/visibility prefixes have an exact union at their maximum\n -- sequence. Field values never participate in this metadata normalization.\n FOR selector IN SELECT value->>''type'' AS type_key,(value->>''sessionId'')::uuid AS session_id,\n  value->''bounds'' AS bounds,value->''visibility'' AS visibility,max((value->>''through'')::integer) AS through_sequence\n  FROM jsonb_array_elements(specs) GROUP BY value->>''type'',value->>''sessionId'',value->''bounds'',value->''visibility'' LOOP\n  FOR message IN SELECT m.id,m.scope_version,h.scope_revision_id FROM session_messages m\n   LEFT JOIN session_message_annotation_heads h ON h.workspace_id=m.workspace_id AND h.session_id=m.session_id AND h.message_id=m.id\n   WHERE m.workspace_id=w AND m.session_id=selector.session_id AND m.sequence_num<=selector.through_sequence ORDER BY m.sequence_num,m.id LOOP\n   IF selector.type_key=''session_message'' THEN kind:=''session_message'';id:=message.id;\n   ELSE kind:=''session_context_revision'';id:=message.scope_revision_id;IF id IS NULL THEN CONTINUE;END IF;END IF;\n   root:=read_scope_source(w,kind,id);\n   IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' THEN CONTINUE;END IF;\n   IF application_query_scope_admits_point(selector.bounds,root) IS NOT TRUE\n    OR root->>''userId'' IS NOT NULL AND root->>''userId'' IS DISTINCT FROM selector.visibility->>''userId''\n    OR root->>''assistantId'' IS NOT NULL AND selector.visibility->''assistants''<>''null''::jsonb\n     AND NOT coalesce(selector.visibility->''assistants'' ? (root->>''assistantId''),false) THEN CONTINUE;END IF;\n   attempts:=attempts+1;IF attempts>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''22023'';END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',root->''userId'',''assistantId'',root->''assistantId'',\n    ''sensitivity'',root->''sensitivity'',''compartments'',root->''compartments'',''projectIds'',root->''projectIds'',\n    ''resourceKind'',kind,''resourceId'',id,''version'',root->''version'');RETURN NEXT;\n  END LOOP;\n END LOOP;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_private_transcript_source(uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_private_transcript_source","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","i"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE o private_transcript_observations;s sessions;item record;\nBEGIN\n SELECT * INTO o FROM private_transcript_observations WHERE workspace_id=w AND id=i;\n IF NOT FOUND THEN RETURN ''{\"held\":true}'';END IF;\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n PERFORM user_id FROM workspace_members WHERE workspace_id=w AND user_id=o.user_id FOR SHARE;\n IF NOT FOUND THEN RETURN ''{\"held\":true}'';END IF;\n SELECT * INTO s FROM sessions WHERE id=o.session_id FOR SHARE;\n IF NOT FOUND OR s.user_id<>o.user_id OR private_legacy_history_binding(s) IS DISTINCT FROM o.binding\n  OR session_recording_read_allowed(s.id) IS NOT TRUE OR scope_review_state_held(''session'',s.id) IS TRUE\n  OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=o.user_id)\n  OR NOT EXISTS(SELECT 1 FROM assistants WHERE id=s.assistant_id AND workspace_id=w)\n THEN RETURN ''{\"held\":true}'';END IF;\n PERFORM id FROM private_transcript_observations WHERE id=i FOR SHARE;\n -- Revalidate the transcript itself, never the sources behind the utterances.\n IF EXISTS(SELECT 1 FROM jsonb_object_keys(o.manifest) AS entry(message_id) WHERE NOT EXISTS(SELECT 1 FROM session_messages m WHERE m.id=entry.message_id::uuid AND m.session_id=o.session_id)) THEN RETURN ''{\"held\":true}'';END IF;\n FOR item IN SELECT m.*,entry.value expected FROM jsonb_each_text(o.manifest) entry\n  JOIN session_messages m ON m.id=entry.key::uuid AND m.session_id=o.session_id ORDER BY entry.key FOR SHARE OF m\n LOOP\n  IF item.id IS NULL OR item.scope_held IS TRUE OR scope_review_state_held(''session_message'',item.id) IS TRUE\n   OR private_transcript_message_fingerprint((SELECT m FROM session_messages m WHERE m.id=item.id)) IS DISTINCT FROM item.expected\n  THEN RETURN ''{\"held\":true}'';END IF;\n END LOOP;\n RETURN jsonb_build_object(''workspaceId'',w,''resourceKind'',''private_transcript'',''resourceId'',i,''version'',''1'',\n  ''userId'',o.user_id,''assistantId'',NULL,''sensitivity'',o.sensitivity,''compartments'',o.compartments,''projectIds'',o.project_ids,\n  ''held'',false,''validTo'',NULL,''retractedAt'',NULL);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_resource_page_dependencies(uuid,text,uuid,text)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_resource_page_dependencies","prorows":0,"pronargs":4,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i","v"],"proargtypes":["2950","25","2950","25"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE node record; snapshot jsonb; result jsonb:=''[]'';\nBEGIN\n FOR node IN SELECT * FROM application_scope_lineage(w,ARRAY[k],ARRAY[i],ARRAY[v])\n  WHERE kind IN(''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'') LOOP\n  snapshot:=page_scope_source_snapshot(w,node.kind,node.id);\n  IF snapshot IS NULL OR snapshot->>''version'' IS DISTINCT FROM node.version THEN RAISE EXCEPTION ''page_ancestry_unavailable''; END IF;\n  result:=result||jsonb_build_array(snapshot);\n END LOOP;\n RETURN (SELECT coalesce(jsonb_agg(DISTINCT value),''[]'') FROM jsonb_array_elements(result));\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n\n IF k=''private_transcript'' THEN RETURN read_private_transcript_source(w,i);END IF;\n\n IF k=''office_observation'' THEN RETURN read_office_observation(w,i);END IF;\n -- Recording privacy admission precedes body selection.\n IF NOT recording_source_read_allowed(w,k,i) THEN RETURN NULL;END IF;\n IF k=''session_context_revision'' THEN RETURN session_context_revision_snapshot(w,i); END IF;\n RETURN read_scope_source_before_persistent_context(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_application_fields(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_application_fields","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF k=''external_source'' THEN RETURN external_source_snapshot(w,i); END IF;\n RETURN read_scope_source_before_external(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_browser_profile(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_browser_profile","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_workspace","p_kind","p_id"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE s workspace_knowledge_sources;\nBEGIN\n IF p_kind=''blueprint_record'' THEN RETURN read_scope_review_source(p_workspace,p_kind,p_id); END IF;\n IF p_kind<>''knowledge_source'' THEN RETURN read_scope_source_before_knowledge_binding(p_workspace,p_kind,p_id); END IF;\n SELECT * INTO s FROM workspace_knowledge_sources WHERE workspace_id=p_workspace AND id=p_id FOR SHARE;\n IF s.configured_by_user_id IS NULL THEN RETURN NULL; END IF;\n RETURN jsonb_build_object(''workspaceId'',p_workspace,''resourceKind'',p_kind,''resourceId'',p_id,''version'',s.binding_version::text,\n  ''userId'',NULL,''assistantId'',NULL,''sensitivity'',s.binding_sensitivity,''compartments'',s.binding_compartments,\n  ''projectIds'',s.binding_project_ids,''held'',s.binding_held,''validTo'',NULL,''retractedAt'',NULL);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_browser_session(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_browser_session","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE p browser_profiles; dept workspace_groups; held boolean:=false;\nBEGIN\n IF k<>''browser_profile'' THEN RETURN read_scope_source_before_browser_profile(w,k,i); END IF;\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n SELECT * INTO p FROM browser_profiles WHERE workspace_id=w AND id=i FOR SHARE;\n IF NOT FOUND THEN RETURN NULL; END IF;\n IF p.department_id IS NOT NULL THEN\n  SELECT * INTO dept FROM workspace_groups WHERE workspace_id=w AND id=p.department_id FOR SHARE;\n  held:=NOT FOUND OR dept.kind<>''team'' OR dept.status<>''active'' OR dept.compartment_key IS DISTINCT FROM ''team:''||p.department_id::text;\n ELSIF p.scope=''workspace'' THEN held:=true;\n END IF;\n RETURN jsonb_build_object(''workspaceId'',w,''resourceKind'',k,''resourceId'',i,''version'',p.scope_version::text,\n  ''userId'',CASE WHEN p.scope=''owner'' THEN p.owner_user_id ELSE NULL END,''assistantId'',NULL,\n  ''sensitivity'',p.clearance,''compartments'',CASE WHEN p.department_id IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array(''team:''||p.department_id::text) END,\n  ''projectIds'',''[]''::jsonb,''held'',held,''validTo'',NULL,''retractedAt'',NULL);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_external(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_external","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE result jsonb;\nBEGIN\n result:=public.read_scope_source_before_routines(w,k,i);\n IF k=''task'' AND result IS NOT NULL AND public.routine_task_sources_visible(i) IS NOT TRUE THEN\n  -- Withheld current ancestry is not D1 deletion. Every native metadata,\n  -- model-input and copied-outcome consumer sees an actual blocking state.\n  result:=jsonb_set(result,''{held}'',''true''::jsonb);\n END IF;\n RETURN result;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_knowledge_binding(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_knowledge_binding","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_workspace","p_kind","p_id"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE tab text; row_json jsonb; ev crm_domain_event_outbox;\nBEGIN\n  IF p_kind IN(''memory_verification'',''brain_verification'',''correction_audit'') THEN\n    RETURN read_verification_scope(p_workspace,p_kind,p_id);\n  END IF;\n  IF p_kind=''crm_event'' THEN\n    SELECT * INTO ev FROM crm_domain_event_outbox WHERE workspace_id=p_workspace AND id=p_id FOR SHARE;\n    IF ev.id IS NULL OR ev.scope_origin<>''captured'' OR ev.scope_held OR ev.status=''retired''\n      OR ev.scope_source IS NULL OR ev.scope_source->>''held'' IS DISTINCT FROM ''false''\n      OR ev.scope_source->>''validTo'' IS NOT NULL OR ev.scope_source->>''retractedAt'' IS NOT NULL\n      OR crm_event_entity_source(ev.workspace_id,ev.subject_kind,ev.subject_id,true)\n        IS DISTINCT FROM (ev.scope_source->>''resourceId'')::uuid THEN RETURN NULL; END IF;\n    RETURN ev.scope_source || jsonb_build_object(''resourceKind'',''crm_event'',''resourceId'',ev.id,\n      ''causalEntityId'',ev.scope_source->>''resourceId'',\n      ''version'',ev.scope_version::text||'':''||(extract(epoch FROM ev.created_at)*1000000)::numeric::text,\n      ''held'',false,''validTo'',NULL,''retractedAt'',NULL);\n  END IF;\n  tab=scope_source_table(p_kind);\n  IF tab IS NULL THEN RAISE EXCEPTION ''scope_evidence_missing''; END IF;\n  EXECUTE format(''SELECT to_jsonb(r) FROM %I r WHERE workspace_id=$1 AND id=$2 FOR SHARE'',tab)\n    INTO row_json USING p_workspace,p_id;\n  IF row_json IS NULL THEN RETURN NULL; END IF;\n  IF p_kind=''feedback_event'' AND row_json->>''event_name''<>''feedback_negative'' THEN RETURN NULL; END IF;\n  IF NOT (row_json ?& ARRAY[''workspace_id'',''sensitivity'',''compartments'',''project_ids'',''scope_version'',''scope_held''])\n    OR (p_kind<>''knowledge_entry'' AND NOT(row_json ?& ARRAY[''user_id'',''assistant_id''])) THEN\n    RAISE EXCEPTION ''scope_evidence_missing'';\n  END IF;\n  -- Held sources remain readable to the canonical validator so holding-state\n  -- rows can reference their exact version. Application validators reject the\n  -- returned `held:true`; only legacy rows with no version are unprovable.\n  IF row_json->>''scope_version'' IS NULL THEN RETURN NULL; END IF;\n  RETURN jsonb_build_object(''workspaceId'',row_json->''workspace_id'',''userId'',row_json->''user_id'',\n    ''assistantId'',row_json->''assistant_id'',''sensitivity'',row_json->''sensitivity'',\n    ''compartments'',row_json->''compartments'',''projectIds'',row_json->''project_ids'',\n    ''resourceKind'',p_kind,''resourceId'',p_id,''version'',row_json->>''scope_version'',\n    ''held'',row_json->''scope_held'',''validTo'',row_json->''valid_to'',''retractedAt'',row_json->''retracted_at'');\nEND;\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_page(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_page","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF k=''workflow_run'' THEN RETURN workflow_derivation_snapshot(w,i); END IF;\n RETURN read_scope_source_before_workflow_run(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_persistent_context(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_persistent_context","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE result jsonb;\nBEGIN\n IF k=''entity_instance'' THEN\n  SELECT jsonb_build_object(''workspaceId'',r.workspace_id,''userId'',NULL,''assistantId'',NULL,\n   ''sensitivity'',r.sensitivity,''compartments'',r.compartments,''projectIds'',r.project_ids,\n   ''version'',r.record_version::text,''held'',scope_review_state_held(k,i),''validTo'',NULL,''retractedAt'',NULL)\n   INTO result FROM entity_instances r WHERE r.workspace_id=w AND r.id=i FOR SHARE;\n  RETURN result;\n ELSIF k=''workspace_member'' THEN\n  SELECT jsonb_build_object(''workspaceId'',m.workspace_id,''userId'',NULL,''assistantId'',NULL,\n   ''sensitivity'',''internal'',''compartments'',''[]''::jsonb,''projectIds'',''[]''::jsonb,\n   ''version'',md5(to_jsonb(m)::text),''held'',scope_review_state_held(k,i),''validTo'',NULL,''retractedAt'',NULL)\n   INTO result FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=i FOR SHARE;\n  RETURN result;\n ELSIF k=''application_field'' THEN\n  RETURN application_current_field_snapshot(w,i);\n END IF;\n RETURN read_scope_source_before_application_fields(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_routines(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_routines","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nBEGIN\n IF k IN(''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'') THEN\n  RETURN page_scope_source_snapshot(w,k,i)||jsonb_build_object(''held'',false,''validTo'',NULL,''retractedAt'',NULL);\n END IF;\n RETURN read_scope_source_before_page(w,k,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_scope_source_before_workflow_run(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_scope_source_before_workflow_run","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE s sessions; held boolean;\nBEGIN\n IF k<>''browser_session'' THEN RETURN read_scope_source_before_browser_session(w,k,i); END IF;\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n SELECT * INTO s FROM sessions WHERE workspace_id=w AND id=i FOR SHARE;\n IF NOT FOUND THEN RETURN NULL; END IF;\n PERFORM id FROM assistants WHERE workspace_id=w AND id=s.assistant_id FOR SHARE;\n IF NOT FOUND THEN RETURN NULL; END IF;\n -- Only a personal, unanchored web conversation is a browser-session source.\n held:=s.channel_type IS DISTINCT FROM ''web'' OR s.visibility IS DISTINCT FROM ''personal'' OR s.anchor_kind<>''none''\n  OR s.context_locked_at IS NULL OR s.context_binding_origin=''held'' OR s.context_compartments IS NULL\n  OR (s.context_group_id IS NOT NULL AND NOT (''team:''||s.context_group_id::text)=ANY(s.context_compartments))\n  OR EXISTS(SELECT 1 FROM unnest(s.context_compartments) label WHERE label IS NULL OR NOT EXISTS(\n   SELECT 1 FROM workspace_groups g WHERE g.workspace_id=w AND g.kind=''team'' AND g.compartment_key=label))\n  OR (s.context_project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM workspace_projects p\n   WHERE p.workspace_id=w AND p.id=s.context_project_id));\n RETURN jsonb_build_object(''workspaceId'',w,''resourceKind'',k,''resourceId'',i,''version'',s.browser_source_version::text,\n  ''userId'',s.user_id,''assistantId'',NULL,''sensitivity'',coalesce(s.effective_clearance,''public''),\n  ''compartments'',to_jsonb(s.context_compartments),''projectIds'',CASE WHEN s.context_project_id IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array(s.context_project_id) END,\n  ''held'',held,''validTo'',NULL,''retractedAt'',NULL);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_session_authority_facts(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"read_session_authority_facts","prorows":0,"pronargs":9,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":["2950","2950","2950","2950","2950","23","2950","16","16"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nSELECT jsonb_build_object(\n    ''scope'', jsonb_build_object(\n      ''assignedTeams'', coalesce((SELECT jsonb_agg(jsonb_build_object(''readAll'',g.read_all,''own'',g.compartment_key,''grant'',cg.compartment_key))\n        FROM workspace_group_assistants ga JOIN workspace_groups g ON g.id=ga.group_id\n        LEFT JOIN workspace_group_compartment_grants cg ON cg.group_id=g.id\n        WHERE ga.assistant_id=$3 AND g.workspace_id=$1 AND g.kind=''team''\n          AND EXISTS(SELECT 1 FROM assistants WHERE id=$3 AND team_scope_mode=''assigned'')), ''[]''::jsonb),\n      ''assignedProjects'', coalesce((SELECT jsonb_agg(p.id ORDER BY p.id) FROM assistant_project_grants apg\n        JOIN workspace_projects p ON p.id=apg.project_id WHERE apg.assistant_id=$3 AND p.workspace_id=$1\n          AND EXISTS(SELECT 1 FROM assistants WHERE id=$3 AND project_scope_mode=''assigned'')), ''[]''::jsonb),\n      ''team'', (SELECT jsonb_build_object(''id'',g.id,''name'',g.name,''key'',g.key,''compartmentKey'',g.compartment_key,\n        ''status'',g.status,''readAll'',g.read_all,''grants'',coalesce((SELECT jsonb_agg(cg.compartment_key ORDER BY cg.compartment_key)\n          FROM workspace_group_compartment_grants cg WHERE cg.group_id=g.id),''[]''::jsonb))\n        FROM workspace_groups g JOIN sessions s ON s.context_group_id=g.id\n        WHERE s.id=$4 AND g.workspace_id=$1 AND g.kind=''team''),\n      ''project'', (SELECT jsonb_build_object(''id'',p.id,''name'',p.name,''status'',p.status,\n        ''shared'',EXISTS(SELECT 1 FROM project_shared_scopes ps WHERE ps.project_id=p.id))\n        FROM workspace_projects p JOIN sessions s ON s.context_project_id=p.id WHERE s.id=$4 AND p.workspace_id=$1)),\n    ''policy'', CASE WHEN $9::boolean THEN public.read_application_policy_epoch($1,$2,$3) ELSE NULL END,\n    ''session'', (SELECT jsonb_build_object(''id'',s.id,''assistantId'',s.assistant_id,''userId'',s.user_id,\n      ''contextGroupId'',s.context_group_id,''contextProjectId'',s.context_project_id,''contextLockedAt'',s.context_locked_at,''appOrigin'',s.app_origin,''anchorKind'',s.anchor_kind,''anchorRef'',s.anchor_ref,''channelType'',s.channel_type,''channelId'',s.channel_id,\n      ''visibility'',s.visibility,''mode'',s.mode,''effectiveClearance'',s.effective_clearance,''contextCompartments'',s.context_compartments)\n      FROM sessions s WHERE s.id=$4 AND session_recording_read_allowed(s.id)),\n    ''assistant'', (SELECT jsonb_build_object(''id'',a.id,''workspaceId'',a.workspace_id,''kind'',a.kind,\n      ''clearance'',a.clearance,''compartments'',a.compartments,''defaultCompartments'',a.default_compartments,\n      ''teamScopeMode'',a.team_scope_mode,''defaultWorkspaceGroupId'',a.default_workspace_group_id,\n      ''projectScopeMode'',a.project_scope_mode,''defaultProjectId'',a.default_project_id)\n      FROM assistants a WHERE a.id=$3),\n    ''member'', (SELECT jsonb_build_object(''role'',m.role,''clearance'',m.clearance,\n      ''readCompartments'',effective_member_read_compartments(m.user_id,m.workspace_id),\n      ''mutationCompartments'',effective_member_team_compartments(m.user_id,m.workspace_id),\n      ''departmentReadV2'',(SELECT to_jsonb(w)->>''department_read_v2'' FROM workspaces w WHERE w.id=$1))\n      FROM workspace_members m WHERE m.workspace_id=$1 AND m.user_id=$2),\n    ''department'', CASE WHEN $8::boolean AND EXISTS(SELECT 1 FROM workspaces WHERE id=$1 AND department_read_v2)\n      THEN (SELECT snapshot FROM (SELECT read_session_department_facts($1,$2,$3) AS snapshot) department_facts) ELSE NULL END,\n    ''credentialCurrent'', CASE WHEN $5::uuid IS NULL THEN true ELSE $7::uuid=$2 AND EXISTS(\n      SELECT 1 FROM users u JOIN auth_sessions s ON s.user_id=u.id\n      WHERE u.id=$2 AND u.auth_version=$6 AND s.id=$5 AND s.auth_version=$6\n        AND s.revoked_at IS NULL AND s.expires_at>clock_timestamp()) END\n    ) AS facts\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_session_context_revision(uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_session_context_revision","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","i"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE result jsonb;\nBEGIN\n -- Recording privacy admission precedes body selection.\n IF NOT recording_source_read_allowed(w,''session_context_revision'',i) THEN RETURN NULL;END IF;\n IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''session_context_revision_contents''::regclass\n   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))\n  OR session_context_revision_allowed(w,i) IS NOT TRUE THEN RETURN NULL;END IF;\n SELECT c.content INTO result FROM session_context_revision_contents c WHERE c.workspace_id=w AND c.revision_id=i;\n RETURN result;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_session_department_facts(uuid,uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"read_session_department_facts","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":false,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":["2950","2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nWITH member AS MATERIALIZED (\n    SELECT role, clearance FROM workspace_members WHERE workspace_id=$1 AND user_id=$2\n  ), active_projects AS MATERIALIZED (\n    SELECT s.project_id FROM project_shared_scopes s JOIN workspaces w ON w.id=s.workspace_id\n    WHERE s.workspace_id=$1 AND s.status=''active'' AND w.project_shared_spaces\n  ) SELECT jsonb_build_object(\n    ''member'', (SELECT to_jsonb(m) FROM member m),\n    ''assistant'', (SELECT jsonb_build_object(''clearance'',a.clearance) FROM assistants a\n      WHERE a.id=$3 AND a.workspace_id=$1 AND public.assistant_placement_visible($2,a.id)),\n    ''edges'', coalesce((SELECT jsonb_agg(jsonb_build_object(\n      ''kind'',e.principal_kind,''id'',coalesce(e.user_id,e.assistant_id),\n      ''departmentId'',e.department_id,''clearance'',e.clearance,''expiresAt'',e.expires_at))\n      FROM department_edges e WHERE e.workspace_id=$1\n        AND ((e.user_id=$2 AND EXISTS(SELECT 1 FROM member)) OR e.assistant_id=$3)), ''[]''::jsonb),\n    ''activeProjects'', coalesce((SELECT jsonb_agg(project_id ORDER BY project_id) FROM active_projects), ''[]''::jsonb),\n    ''projectEdges'', coalesce((SELECT jsonb_agg(jsonb_build_object(\n      ''kind'',e.principal_kind,''id'',coalesce(e.user_id,e.assistant_id),\n      ''projectId'',e.project_id,''expiresAt'',e.expires_at))\n      FROM project_shared_members e WHERE e.workspace_id=$1 AND EXISTS(SELECT 1 FROM active_projects)\n        AND ((e.user_id=$2 AND EXISTS(SELECT 1 FROM member)) OR e.assistant_id=$3)), ''[]''::jsonb)\n    ) AS snapshot\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"read_session_title_revision(uuid,uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"read_session_title_revision","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","s","i"],"proargtypes":["2950","2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE current_revision uuid;\nBEGIN\n -- Recording privacy admission precedes body selection.\n IF NOT session_recording_read_allowed(s) THEN RETURN NULL;END IF;\n PERFORM id FROM workspaces WHERE id=w FOR SHARE;\n SELECT h.scope_revision_id INTO current_revision FROM session_title_heads h\n  WHERE h.workspace_id=w AND h.session_id=s FOR SHARE;\n IF current_revision IS DISTINCT FROM i OR NOT EXISTS(SELECT 1 FROM session_context_scope_revisions r\n  WHERE r.workspace_id=w AND r.id=i AND r.session_id=s AND r.parent_kind=''session_title'' AND r.parent_id=s) THEN RETURN NULL;END IF;\n RETURN read_session_context_revision(w,i);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"recording_source_read_allowed(uuid,text,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"recording_source_read_allowed","prorows":0,"pronargs":3,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","k","i"],"proargtypes":["2950","25","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\n WITH RECURSIVE walk(frontier,visited) AS (\n  SELECT jsonb_build_array(jsonb_build_object(''kind'',k,''id'',i)), ''[]''::jsonb\n  UNION ALL\n  SELECT step.frontier,step.visited\n  FROM walk\n  CROSS JOIN LATERAL (\n   WITH frontier_nodes AS MATERIALIZED (\n    SELECT n.kind,n.id FROM jsonb_to_recordset(walk.frontier) n(kind text,id uuid)\n   ), visited_nodes AS MATERIALIZED (\n    SELECT n.kind,n.id FROM jsonb_to_recordset(walk.visited) n(kind text,id uuid)\n   ), reached(kind,id) AS (\n    SELECT s.source_kind,s.source_id\n     FROM frontier_nodes n JOIN scope_derivations d\n      ON d.workspace_id=w AND d.resource_kind=n.kind AND d.resource_id=n.id\n     JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id\n    UNION\n    SELECT o.source_kind,o.source_id FROM frontier_nodes n JOIN application_field_observations o\n     ON n.kind=''application_field'' AND o.workspace_id=w AND o.resource_id=n.id\n    UNION\n    SELECT s.source_kind,s.source_id FROM frontier_nodes n JOIN application_field_observation_sources s\n     ON n.kind=''application_field'' AND s.workspace_id=w AND s.resource_id=n.id\n    UNION\n    SELECT ''session_message'',f.resource_id FROM frontier_nodes n JOIN application_field_resources f\n     ON n.kind=''application_field'' AND f.workspace_id=w AND f.id=n.id\n      AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n      AND f.type_key IN(''session_message'',''session_message_annotation'')\n   ), unseen(kind,id) AS (\n    SELECT kind,id FROM reached\n    EXCEPT SELECT kind,id FROM visited_nodes\n    EXCEPT SELECT kind,id FROM frontier_nodes\n   ), completed(kind,id) AS (\n    SELECT kind,id FROM visited_nodes UNION SELECT kind,id FROM frontier_nodes\n   )\n   SELECT (SELECT coalesce(jsonb_agg(to_jsonb(n)),''[]''::jsonb) FROM unseen n) frontier,\n    (SELECT coalesce(jsonb_agg(to_jsonb(n)),''[]''::jsonb) FROM completed n) visited\n  ) step\n  WHERE jsonb_array_length(walk.frontier)>0\n ), nodes(kind,id) AS (\n  SELECT n.kind,n.id FROM walk CROSS JOIN LATERAL jsonb_to_recordset(walk.frontier) n(kind text,id uuid)\n ), parents AS MATERIALIZED (\n  SELECT s.id FROM nodes n JOIN sessions s ON n.kind=''session'' AND s.id=n.id AND s.workspace_id=w\n  UNION SELECT m.session_id FROM nodes n JOIN session_messages m ON n.kind=''session_message'' AND m.id=n.id\n    JOIN sessions s ON s.id=m.session_id WHERE s.workspace_id=w\n  UNION SELECT r.session_id FROM nodes n JOIN session_context_scope_revisions r ON n.kind=''session_context_revision'' AND r.id=n.id AND r.workspace_id=w\n  UNION SELECT s.session_id FROM nodes n JOIN session_state s ON n.kind=''session_state'' AND s.id=n.id\n  UNION SELECT e.session_id FROM nodes n JOIN episodic_memories e ON n.kind=''episodic_memory'' AND e.id=n.id\n  UNION SELECT e.session_id FROM nodes n JOIN analytics_events e ON n.kind=''feedback_event'' AND e.id=n.id\n ) SELECT NOT EXISTS(SELECT 1 FROM parents WHERE id IS NOT NULL AND NOT session_recording_read_allowed(id))\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"recording_transcript_file_allows(uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"recording_transcript_file_allows","prorows":0,"pronargs":1,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":[