antee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\n SELECT CASE k WHEN ''blueprint_record'' THEN ''blueprint_records''\n WHEN ''recording'' THEN ''recordings'' WHEN ''file_segment'' THEN ''file_segments''\n WHEN ''transcript_segment'' THEN ''transcript_segments'' ELSE scope_source_table_before_media(k) END\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"sensitivity_rank(text)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"sql","encoding":"string"}},"proname":"sensitivity_rank","prorows":0,"pronargs":1,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"23","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["s"],"proargtypes":["25"],"proisstrict":true,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"PUBLIC","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\n    SELECT CASE s\n      WHEN ''public''       THEN 1\n      WHEN ''internal''     THEN 2\n      WHEN ''confidential'' THEN 3\n    END\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"session_context_parent_snapshot(uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"session_context_parent_snapshot","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","i"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE s sessions;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n acting uuid:=nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid;\n live_floor text;invocation_floor text:=nullif(current_setting(''app.agent_clearance'',true),'''');\nBEGIN\n -- Recording privacy admission precedes body selection.\n IF NOT session_recording_read_allowed(i) THEN RETURN NULL;END IF;\n -- There is no application data grant for a raw native session. A canonical\n -- application-session port must be integrated before that lane is available.\n IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.agent_workspace_id'',true),'''') IS NOT NULL AND current_setting(''app.agent_workspace_id'',true)::uuid<>w\n  OR nullif(current_setting(''app.agent_actor_id'',true),'''') IS NOT NULL AND current_setting(''app.agent_actor_id'',true)::uuid<>actor\n  OR acting IS NOT NULL AND (NOT EXISTS(SELECT 1 FROM assistants a WHERE a.workspace_id=w AND a.id=acting)\n    OR assistant_placement_visible(actor,acting) IS NOT TRUE) THEN RETURN NULL;END IF;\n SELECT * INTO s FROM sessions WHERE workspace_id=w AND id=i FOR SHARE;\n IF NOT FOUND OR NOT coalesce(session_personal_audience(s) OR session_workspace_audience(s),false)\n  OR session_project_audience(s,false) IS NOT TRUE THEN RETURN NULL;END IF;\n -- Personal sessions inherit a current, persisted assistant/member ceiling.\n -- Shared/legacy unclassified rows remain held. The GUC can only narrow the\n -- real ceiling; it never supplies authority or a missing canonical label.\n live_floor:=s.effective_clearance;\n IF live_floor IS NULL AND s.visibility=''personal'' THEN\n  SELECT CASE WHEN sensitivity_rank(a.clearance)<=sensitivity_rank(wm.clearance) THEN a.clearance ELSE wm.clearance END\n   INTO live_floor FROM assistants a JOIN workspace_members wm ON wm.workspace_id=a.workspace_id\n   WHERE a.workspace_id=w AND a.id=coalesce(acting,s.assistant_id) AND wm.user_id=actor;\n  IF live_floor NOT IN(''public'',''internal'',''confidential'') OR live_floor IS NULL THEN RETURN NULL;END IF;\n  IF invocation_floor IS NOT NULL THEN\n   IF invocation_floor NOT IN(''public'',''internal'',''confidential'') THEN RETURN NULL;END IF;\n   IF sensitivity_rank(invocation_floor)<sensitivity_rank(live_floor) THEN live_floor:=invocation_floor;END IF;\n  END IF;\n END IF;\n IF live_floor IS NULL OR s.context_compartments IS NULL THEN RETURN NULL;END IF;\n RETURN jsonb_build_object(''workspaceId'',w,''userId'',CASE WHEN s.visibility=''personal'' THEN s.user_id ELSE NULL END,\n  ''assistantId'',NULL,''sensitivity'',live_floor,''compartments'',s.context_compartments,\n  ''projectIds'',CASE WHEN s.context_project_id IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array(s.context_project_id) END,\n  ''assistant'',s.assistant_id,''createdBy'',s.user_id);\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"session_context_payload_shape(text,jsonb)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"session_context_payload_shape","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["k","p"],"proargtypes":["25","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE item text;\nBEGIN\n IF jsonb_typeof(p) IS DISTINCT FROM ''object'' THEN RETURN false; END IF;\n IF k=''turn_frame'' THEN RETURN native_turn_frame_payload_shape(p);END IF;\n IF k=''session_title'' THEN\n  RETURN p ?& ARRAY[''title'',''manual''] AND p-ARRAY[''title'',''manual'']=''{}''::jsonb\n   AND jsonb_typeof(p->''title'')=''string'' AND length(btrim(p->>''title'')) BETWEEN 1 AND 200\n   AND jsonb_typeof(p->''manual'')=''boolean'';\n ELSIF k=''message_annotation'' THEN\n  RETURN p ?& ARRAY[''topicLabel'',''topicConfidence'',''replyToText'']\n   AND p-ARRAY[''topicLabel'',''topicConfidence'',''replyToText'']=''{}''::jsonb\n   AND jsonb_typeof(p->''topicLabel'')=''string'' AND length(p->>''topicLabel'') BETWEEN 1 AND 200\n   AND jsonb_typeof(p->''topicConfidence'')=''number''\n   AND (p->>''topicConfidence'')::numeric BETWEEN 0 AND 1\n   AND jsonb_typeof(p->''replyToText'') IN(''string'',''null'')\n   AND (jsonb_typeof(p->''replyToText'')=''null'' OR length(p->>''replyToText'')<=8000);\n ELSIF k=''compact_summary'' THEN\n  RETURN p ?& ARRAY[''summary'',''boundarySequence''] AND p-ARRAY[''summary'',''boundarySequence'']=''{}''::jsonb\n   AND jsonb_typeof(p->''summary'')=''string'' AND length(p->>''summary'')>0\n   AND jsonb_typeof(p->''boundarySequence'')=''number'' AND (p->>''boundarySequence'')::numeric>=0\n   AND trunc((p->>''boundarySequence'')::numeric)=(p->>''boundarySequence'')::numeric;\n ELSIF k=''session_state'' THEN\n  RETURN p ?& ARRAY[''key'',''status'',''summary'',''detail'',''source'',''createdAt'',''updatedAt'',''resolvedAt'']\n   AND p-ARRAY[''key'',''status'',''summary'',''detail'',''source'',''createdAt'',''updatedAt'',''resolvedAt'']=''{}''::jsonb\n   AND jsonb_typeof(p->''key'')=''string'' AND length(p->>''key'') BETWEEN 1 AND 200\n   AND jsonb_typeof(p->''summary'')=''string'' AND length(p->>''summary'') BETWEEN 1 AND 400\n   AND jsonb_typeof(p->''detail'') IN(''string'',''null'') AND (jsonb_typeof(p->''detail'')=''null'' OR length(p->>''detail'')<=8000)\n   AND p->>''status'' IN(''open'',''resolved'',''cancelled'')\n   AND p->>''source'' IN(''tool'',''diff-pass'',''scheduler'')\n   AND jsonb_typeof(p->''createdAt'')=''number'' AND jsonb_typeof(p->''updatedAt'')=''number''\n   AND jsonb_typeof(p->''resolvedAt'') IN(''number'',''null'');\n ELSIF k=''episodic_memory'' THEN\n  IF NOT (p ?& ARRAY[''topicLabel'',''summary'',''messageSpan'',''entityRefs''])\n   OR p-ARRAY[''topicLabel'',''summary'',''messageSpan'',''entityRefs'']<>''{}''::jsonb\n   OR jsonb_typeof(p->''topicLabel'') IS DISTINCT FROM ''string'' OR length(p->>''topicLabel'')=0\n   OR jsonb_typeof(p->''summary'') IS DISTINCT FROM ''string'' OR length(p->>''summary'')=0\n   OR jsonb_typeof(p->''messageSpan'') IS DISTINCT FROM ''object'' OR jsonb_typeof(p->''entityRefs'') NOT IN(''array'',''null'')\n  THEN RETURN false; END IF;\n  IF NOT ((p->''messageSpan'') ?& ARRAY[''fromSequence'',''toSequence'',''turnCount''])\n   OR (p->''messageSpan'')-ARRAY[''fromSequence'',''toSequence'',''turnCount'',''fromMsgId'',''toMsgId'']<>''{}''::jsonb THEN RETURN false; END IF;\n  FOREACH item IN ARRAY ARRAY[''fromSequence'',''toSequence'',''turnCount''] LOOP\n   IF jsonb_typeof(p->''messageSpan''->item) IS DISTINCT FROM ''number''\n    OR (p->''messageSpan''->>item)::numeric<0\n    OR trunc((p->''messageSpan''->>item)::numeric)<>(p->''messageSpan''->>item)::numeric THEN RETURN false; END IF;\n  END LOOP;\n  RETURN (p->''messageSpan''->>''toSequence'')::numeric >= (p->''messageSpan''->>''fromSequence'')::numeric\n   AND (NOT (p->''messageSpan'' ? ''fromMsgId'') OR jsonb_typeof(p->''messageSpan''->''fromMsgId'')=''string'')\n   AND (NOT (p->''messageSpan'' ? ''toMsgId'') OR jsonb_typeof(p->''messageSpan''->''toMsgId'')=''string'');\n END IF;\n RETURN false;\nEXCEPTION WHEN invalid_parameter_value OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"session_context_revision_allowed(uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"session_context_revision_allowed","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","i"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}],"bodyParts":["\nDECLARE root jsonb;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n child_kinds text[];child_ids uuid[];child_versions text[];eligible boolean;position integer;admitted jsonb;dependency record;\n seen jsonb:=''[]'';current_source jsonb;chat_nodes jsonb;chat_proof jsonb;\nBEGIN\n IF EXISTS(SELECT 1 FROM session_context_scope_revisions r WHERE r.workspace_id=w AND r.id=i AND r.parent_kind IN(''turn_frame'',''session_title''))\n  AND actor IS NOT NULL AND nullif(current_setting(''app.application_id'',true),'''') IS NULL\n  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL\n  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass\n   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN\n  chat_proof:=capture_conversation_evidence(w,jsonb_build_array(jsonb_build_object(''kind'',''session_context_revision'',''id'',i,''version'',''1'')));\n  IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>''admitted''=''true'') IS TRUE;END IF;\n END IF;\n -- Recording privacy admission precedes body selection.\n IF NOT recording_source_read_allowed(w,''session_context_revision'',i) THEN RETURN false;END IF;\n root:=read_entity_derivation_source(w,''session_context_revision'',i);\n IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' THEN RETURN false;END IF;\n IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)\n  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL\n  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL\n  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass WHERE login.rolname=session_user\n    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN\n\n SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),\n  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),\n  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind=''application_field'')\n   AND bool_or(s.source_kind=''application_field'' AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id\n    AND f.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}'' AND f.type_key=''memory'' AND f.selection=''history''))\n INTO child_kinds,child_ids,child_versions,eligible\n FROM session_context_scope_revisions r JOIN scope_derivations d ON d.workspace_id=r.workspace_id AND d.resource_kind=''session_context_revision''\n  AND d.resource_id=r.id AND d.resource_version=''1'' AND d.user_id IS NOT DISTINCT FROM r.user_id AND d.assistant_id IS NOT DISTINCT FROM r.assistant_id\n  AND d.sensitivity=r.sensitivity AND d.compartments=r.compartments AND d.project_ids=r.project_ids\n JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id\n WHERE r.workspace_id=w AND r.id=i AND r.parent_kind=''session_title'' AND r.parent_id=r.session_id AND r.scope_version=1;\n IF eligible IS TRUE AND EXISTS(SELECT 1 FROM application_scope_lineage(w,child_kinds,child_ids,child_versions) n WHERE n.kind=''session_context_revision'') THEN eligible:=false;END IF;\n\n  IF eligible IS TRUE THEN\n   IF root->>''version'' IS DISTINCT FROM ''1'' OR application_reader_envelope_visible(w,root) IS NOT TRUE THEN RETURN false;END IF;\n   FOR position IN 1..cardinality(child_ids) LOOP\n    admitted:=read_admitted_application_field_snapshot(w,child_ids[position],child_versions[position]);\n    IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM child_versions[position] THEN RETURN false;END IF;\n   END LOOP;\n   FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,child_kinds,child_ids,child_versions) LOOP\n    admitted:=read_admitted_application_field_snapshot(w,(dependency.source->>''resourceId'')::uuid,dependency.node_version);\n    IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM dependency.node_version THEN RETURN false;END IF;\n    seen:=seen||jsonb_build_array(jsonb_build_array(dependency.source->>''resourceId'',dependency.node_version));\n   END LOOP;\n   IF jsonb_array_length(seen)=0 THEN RETURN false;END IF;\n   FOR position IN 1..cardinality(child_ids) LOOP\n    IF NOT seen @> jsonb_build_array(jsonb_build_array(child_ids[position]::text,child_versions[position])) THEN RETURN false;END IF;\n   END LOOP;\n   FOR dependency IN SELECT * FROM read_external_source_dependencies(w,child_kinds,child_ids,child_versions) LOOP\n    current_source:=external_source_snapshot(w,(dependency.source->>''resourceId'')::uuid);\n    IF dependency.source IS NULL OR dependency.source->>''workspaceId'' IS DISTINCT FROM w::text\n     OR dependency.source->>''version'' IS DISTINCT FROM dependency.node_version\n     OR current_source IS NULL OR current_source->>''held'' IS DISTINCT FROM ''false''\n     OR current_source->>''version'' IS DISTINCT FROM dependency.node_version\n     OR application_reader_envelope_visible(w,dependency.source) IS NOT TRUE\n     OR application_reader_envelope_visible(w,current_source) IS NOT TRUE THEN RETURN false;END IF;\n   END LOOP;\n   RETURN true;\n  END IF;\n END IF;\n -- Keep the separate historical-purpose branch above. Ordinary current\n -- Memory domains can use the existing complete cohort proof, never a label\n -- or an envelope supplied by the caller. Its explicit denial stays denied.\n IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)\n  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL\n  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL\n  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass\n   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN\n  SELECT coalesce(jsonb_agg(to_jsonb(node)),''[]'') INTO chat_nodes\n   FROM application_scope_lineage(w,ARRAY[''session_context_revision''],ARRAY[i],ARRAY[''1'']) node;\n  IF EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node\n   JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>''id'')::uuid\n   WHERE node->>''kind''=''application_field'' AND resource.origin=''{\"kind\":\"native\",\"moduleKey\":\"native\"}''::jsonb\n    AND resource.type_key=''memory'' AND resource.selection=''query_domain'')\n   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node\n    JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>''id'')::uuid\n    WHERE node->>''kind''=''application_field'' AND resource.type_key=''memory''\n     AND(resource.selection<>''query_domain'' OR resource.selected_version IS NOT NULL)) THEN\n   chat_proof:=read_native_session_cohort_evidence(w,ARRAY[''session_context_revision''],ARRAY[i],ARRAY[''1''],true);\n   IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>''admitted''=''true'') IS TRUE;END IF;\n  END IF;\n END IF;\n RETURN root IS NOT NULL AND root->>''held''=''false''\n  AND application_canonical_ancestry_allowed(w,''session_context_revision'',i,''1'') IS TRUE;\nEND\n"],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"session_context_revision_native(uuid,uuid)","metadata":{"probin":null,"procost":100,"prokind":"f","prolang":{"$slot":{"kind":"language","identity":"plpgsql","encoding":"string"}},"proname":"session_context_revision_native","prorows":0,"pronargs":2,"proowner":{"$slot":{"kind":"owner","identity":"OWNER","encoding":"string"}},"proconfig":["search_path=pg_catalog, public, pg_temp"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["w","i"],"proargtypes":["2950","2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":{"$slot":{"kind":"namespace","identity":"public","encoding":"string"}},"proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantab