OM ''array''\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->''compartments'') x WHERE jsonb_typeof(x)<>''string'')\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(s->''projectIds'') x WHERE jsonb_typeof(x)<>''string'')\n  OR (s->>''userId'' IS NOT NULL AND s->>''userId''<>actor::text)\n  OR (s->>''userId'' IS NOT NULL AND current_setting(''app.agent_shared_audience'',true)=''true'')\n  OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)\n  THEN RETURN false; END IF;\n teams:=ARRAY(SELECT jsonb_array_elements_text(s->''compartments''));\n projects:=ARRAY(SELECT jsonb_array_elements_text(s->''projectIds'')::uuid);\n IF agent_visibility_allows(w,(s->>''userId'')::uuid,(s->>''assistantId'')::uuid) IS NOT TRUE\n  OR agent_scope_grant_allows(''app.agent_project_ids'',projects::text[]) IS NOT TRUE THEN RETURN false; END IF;\n SELECT department_read_v2 INTO v2 FROM workspaces WHERE id=w;\n IF v2 THEN\n  grants:=department_read_grants();\n  IF NOT(grants ? w::text) OR department_row_allows(grants,w,s->>''sensitivity'',teams,(s->>''userId'')::uuid) IS NOT TRUE THEN RETURN false; END IF;\n  IF nullif(current_setting(''app.agent_clearance'',true),'''') IS NOT NULL\n    AND current_setting(''app.v2_active'',true) IS DISTINCT FROM ''true''\n    AND nullif(current_setting(''app.v2_assistant_id'',true),'''') IS NULL THEN\n   IF cardinality(teams)>0 AND nullif(current_setting(''app.agent_compartments'',true),'''') IS NULL THEN RETURN false; END IF;\n   IF agent_read_scope_allows(s->>''sensitivity'',teams,projects) IS NOT TRUE THEN RETURN false; END IF;\n  END IF;\n ELSE\n  IF member_operation_scope_allows(w,s->>''sensitivity'',teams,false) IS NOT TRUE\n    OR agent_read_scope_allows(s->>''sensitivity'',teams,projects) IS NOT TRUE THEN RETURN false; END IF;\n END IF;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RETURN false;\nEND "],"hashLiteralReview":{"fingerprints":{},"frozen":{},"historical":{}}},{"signature":"native_conversation_publication_scope(uuid,uuid)","sourceSpec":{"profile":"new","name":"native_conversation_publication_scope","signature":"native_conversation_publication_scope(uuid,uuid)","argNames":["w","s"],"argTypes":["uuid","uuid"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n assistant uuid:=nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid;parent jsonb;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF actor IS NULL OR assistant IS NULL OR NOT EXISTS(SELECT 1 FROM sessions r WHERE r.workspace_id=w AND r.id=s AND (r.visibility = ''workspace'' AND r.channel_type = ''web'' AND r.anchor_kind = ''none'' AND r.app_origin = ''chat'' AND r.transient IS NOT TRUE))\n  OR NOT EXISTS(SELECT 1 FROM assistants a WHERE a.id=assistant AND a.workspace_id=w)\n  OR nullif(current_setting(''app.programmatic_candidate'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.programmatic_publication_batch'',true),'''') IS NOT NULL\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN jsonb_build_object(''actorUserId'',actor,''assistantId'',assistant);\nEND "},"bodyParts":["\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;\n assistant uuid:=nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid;parent jsonb;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF actor IS NULL OR assistant IS NULL OR NOT EXISTS(SELECT 1 FROM sessions r WHERE r.workspace_id=w AND r.id=s AND (r.visibility = ''workspace'' AND r.channel_type = ''web'' AND r.anchor_kind = ''none'' AND r.app_origin = ''chat'' AND r.transient IS NOT TRUE))\n  OR NOT EXISTS(SELECT 1 FROM assistants a WHERE a.id=assistant AND a.workspace_id=w)\n  OR nullif(current_setting(''app.programmatic_candidate'',true),'''') IS NOT NULL\n  OR nullif(current_setting(''app.programmatic_publication_batch'',true),'''') IS NOT NULL\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN jsonb_build_object(''actorUserId'',actor,''assistantId'',assistant);\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_publication_result(uuid,uuid,uuid)","sourceSpec":{"profile":"new","name":"native_conversation_publication_result","signature":"native_conversation_publication_result(uuid,uuid,uuid)","argNames":["w","s","i"],"argTypes":["uuid","uuid","uuid"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;scope jsonb;proof jsonb;roots jsonb;item jsonb;message session_messages;\n revision session_context_scope_revisions;payload jsonb;rows jsonb:=''[]'';annotation jsonb;source jsonb;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n SELECT * INTO r FROM native_conversation_publications WHERE workspace_id=w AND session_id=s AND id=i\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid;\n IF NOT FOUND THEN RETURN jsonb_build_object(''state'',''unknown'');END IF;\n IF r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array'' OR jsonb_array_length(r.outputs)<>r.expected_output_count\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_incomplete'');END IF;\n IF EXISTS(SELECT 1 FROM unnest(r.frame_ids) frame WHERE native_turn_frame_pair(w,frame) IS NOT TRUE)\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_frame_changed'');END IF;\n SELECT jsonb_agg(DISTINCT value) INTO roots FROM (\n  SELECT jsonb_build_object(''kind'',''session_context_revision'',''id'',frame,''version'',''1'') value FROM unnest(r.frame_ids) frame\n  UNION ALL SELECT jsonb_build_object(''kind'',CASE WHEN n->>''kind''=''message_annotation'' THEN ''session_context_revision'' ELSE ''session_message'' END,\n   ''id'',n->''id'',''version'',''1'') FROM jsonb_array_elements(r.outputs) n\n ) members;\n proof:=capture_conversation_evidence(w,roots);\n IF proof IS NULL THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');END IF;\n IF proof->>''admitted'' IS DISTINCT FROM ''true'' THEN\n  IF proof->>''admitted''=''false'' THEN RETURN jsonb_build_object(''state'',''denied'',''reason'',''source_access_denied'');END IF;\n  RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');\n END IF;\n FOR item IN SELECT value FROM jsonb_array_elements(r.outputs) ORDER BY coalesce((value->>''sequence'')::integer,0),value->>''id'' LOOP\n  IF NOT (item->>''frameId'')::uuid=ANY(r.frame_ids) THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n  IF item->>''kind''=''session_message'' THEN\n   SELECT * INTO message FROM session_messages WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   payload:=jsonb_build_object(''role'',message.role,''content'',message.content,''channelMessageId'',message.channel_message_id,\n    ''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments);\n   IF message.id IS NULL OR message.scope_version<>1 OR message.scope_held OR message.sequence_num<>(item->>''sequence'')::integer\n    OR item->>''version''<>''1'' OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_message'' AND d.resource_id=message.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',message.user_id,''assistantId'',message.assistant_id,''sensitivity'',message.sensitivity,\n    ''compartments'',message.compartments,''projectIds'',message.project_ids,''resourceKind'',''session_message'',''resourceId'',message.id,''version'',''1'');\n   rows:=rows||jsonb_build_array(jsonb_build_object(''message'',jsonb_build_object(''id'',message.id,''sessionId'',s,''role'',message.role,''content'',message.content,\n    ''sequenceNum'',message.sequence_num,''createdAt'',message.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n    ''channelMessageId'',message.channel_message_id,''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments),''source'',source));\n  ELSIF item->>''kind''=''message_annotation'' THEN\n   SELECT * INTO revision FROM session_context_scope_revisions WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;\n   IF revision.id IS NULL OR revision.parent_kind<>''message_annotation'' OR revision.parent_id::text IS DISTINCT FROM item->>''parentId''\n    OR revision.scope_version<>1 OR revision.scope_held OR item->>''version''<>''1''\n    OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_context_revision'' AND d.resource_id=revision.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',revision.user_id,''assistantId'',revision.assistant_id,''sensitivity'',revision.sensitivity,\n    ''compartments'',revision.compartments,''projectIds'',revision.project_ids,''resourceKind'',''session_context_revision'',''resourceId'',revision.id,''version'',''1'');\n   annotation:=jsonb_build_object(''source'',source,''createdAt'',revision.created_at,''userId'',r.annotation_user_id,''assistantId'',r.annotation_assistant_id);\n  ELSE RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n END LOOP;\n RETURN jsonb_build_object(''state'',''committed'',''outputs'',r.outputs,''value'',CASE WHEN annotation IS NULL THEN rows ELSE jsonb_build_object(''messages'',rows,''annotation'',annotation) END);\nEND "},"bodyParts":["\nDECLARE r native_conversation_publications;scope jsonb;proof jsonb;roots jsonb;item jsonb;message session_messages;\n revision session_context_scope_revisions;payload jsonb;rows jsonb:=''[]'';annotation jsonb;source jsonb;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n SELECT * INTO r FROM native_conversation_publications WHERE workspace_id=w AND session_id=s AND id=i\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid;\n IF NOT FOUND THEN RETURN jsonb_build_object(''state'',''unknown'');END IF;\n IF r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array'' OR jsonb_array_length(r.outputs)<>r.expected_output_count\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_incomplete'');END IF;\n IF EXISTS(SELECT 1 FROM unnest(r.frame_ids) frame WHERE native_turn_frame_pair(w,frame) IS NOT TRUE)\n THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_frame_changed'');END IF;\n SELECT jsonb_agg(DISTINCT value) INTO roots FROM (\n  SELECT jsonb_build_object(''kind'',''session_context_revision'',''id'',frame,''version'',''1'') value FROM unnest(r.frame_ids) frame\n  UNION ALL SELECT jsonb_build_object(''kind'',CASE WHEN n->>''kind''=''message_annotation'' THEN ''session_context_revision'' ELSE ''session_message'' END,\n   ''id'',n->''id'',''version'',''1'') FROM jsonb_array_elements(r.outputs) n\n ) members;\n proof:=capture_conversation_evidence(w,roots);\n IF proof IS NULL THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');END IF;\n IF proof->>''admitted'' IS DISTINCT FROM ''true'' THEN\n  IF proof->>''admitted''=''false'' THEN RETURN jsonb_build_object(''state'',''denied'',''reason'',''source_access_denied'');END IF;\n  RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable'');\n END IF;\n FOR item IN SELECT value FROM jsonb_array_elements(r.outputs) ORDER BY coalesce((value->>''sequence'')::integer,0),value->>''id'' LOOP\n  IF NOT (item->>''frameId'')::uuid=ANY(r.frame_ids) THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n  IF item->>''kind''=''session_message'' THEN\n   SELECT * INTO message FROM session_messages WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   payload:=jsonb_build_object(''role'',message.role,''content'',message.content,''channelMessageId'',message.channel_message_id,\n    ''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments);\n   IF message.id IS NULL OR message.scope_version<>1 OR message.scope_held OR message.sequence_num<>(item->>''sequence'')::integer\n    OR item->>''version''<>''1'' OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_message'' AND d.resource_id=message.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',message.user_id,''assistantId'',message.assistant_id,''sensitivity'',message.sensitivity,\n    ''compartments'',message.compartments,''projectIds'',message.project_ids,''resourceKind'',''session_message'',''resourceId'',message.id,''version'',''1'');\n   rows:=rows||jsonb_build_array(jsonb_build_object(''message'',jsonb_build_object(''id'',message.id,''sessionId'',s,''role'',message.role,''content'',message.content,\n    ''sequenceNum'',message.sequence_num,''createdAt'',message.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n    ''channelMessageId'',message.channel_message_id,''senderUserId'',message.sender_user_id,''senderAssistantId'',message.sender_assistant_id,''attachments'',message.attachments),''source'',source));\n  ELSIF item->>''kind''=''message_annotation'' THEN\n   SELECT * INTO revision FROM session_context_scope_revisions WHERE workspace_id=w AND session_id=s AND id=(item->>''id'')::uuid;\n   SELECT content INTO payload FROM session_context_revision_contents WHERE workspace_id=w AND revision_id=revision.id;\n   IF revision.id IS NULL OR revision.parent_kind<>''message_annotation'' OR revision.parent_id::text IS DISTINCT FROM item->>''parentId''\n    OR revision.scope_version<>1 OR revision.scope_held OR item->>''version''<>''1''\n    OR item->>''payloadDigest'' IS DISTINCT FROM encode(sha256(convert_to(payload::text,''UTF8'')),''hex'')\n    OR NOT EXISTS(SELECT 1 FROM scope_derivations d JOIN scope_derivation_sources e ON e.workspace_id=d.workspace_id AND e.derivation_id=d.id\n     WHERE d.workspace_id=w AND d.id=(item->>''derivationId'')::uuid AND d.resource_kind=''session_context_revision'' AND d.resource_id=revision.id\n     AND d.resource_version=''1'' AND e.source_kind=''session_context_revision'' AND e.source_id=(item->>''frameId'')::uuid AND e.source_version=''1'')\n   THEN RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n   source:=jsonb_build_object(''workspaceId'',w,''userId'',revision.user_id,''assistantId'',revision.assistant_id,''sensitivity'',revision.sensitivity,\n    ''compartments'',revision.compartments,''projectIds'',revision.project_ids,''resourceKind'',''session_context_revision'',''resourceId'',revision.id,''version'',''1'');\n   annotation:=jsonb_build_object(''source'',source,''createdAt'',revision.created_at,''userId'',r.annotation_user_id,''assistantId'',r.annotation_assistant_id);\n  ELSE RETURN jsonb_build_object(''state'',''unavailable'',''reason'',''publication_member_changed'');END IF;\n END LOOP;\n RETURN jsonb_build_object(''state'',''committed'',''outputs'',r.outputs,''value'',CASE WHEN annotation IS NULL THEN rows ELSE jsonb_build_object(''messages'',rows,''annotation'',annotation) END);\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_publication_enter(uuid,uuid,jsonb,jsonb)","sourceSpec":{"profile":"new","name":"native_conversation_publication_enter","signature":"native_conversation_publication_enter(uuid,uuid,jsonb,jsonb)","argNames":["w","s","operation","command"],"argTypes":["uuid","uuid","jsonb","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE scope jsonb;r native_conversation_publications;digest text;result jsonb;payloads jsonb;node jsonb;version integer;state text;effective_stopped boolean;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n version:=CASE operation->''version'' WHEN ''1''::jsonb THEN 1 WHEN ''2''::jsonb THEN 2 END;\n IF version IS NULL OR jsonb_typeof(operation) IS DISTINCT FROM ''object''\n  OR operation-(ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)<>''{}''\n  OR NOT operation ?& (ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)\n  OR operation->>''slot'' IS DISTINCT FROM ''buffered_transcript'' OR jsonb_typeof(operation->''stopped'') IS DISTINCT FROM ''boolean''\n  OR EXISTS(SELECT 1 FROM unnest(ARRAY[''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'']) key\n   WHERE jsonb_typeof(operation->key) IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(operation->>key,''uuid''))\n  OR jsonb_typeof(command) IS DISTINCT FROM ''object'' OR command-ARRAY[''payloads'',''producer'',''sources'',''target'']<>''{}''\n  OR NOT command ?& ARRAY[''payloads'',''producer'',''sources'',''target'']\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF operation->>''actorUserId'' IS DISTINCT FROM scope->>''actorUserId'' OR operation->>''assistantId'' IS DISTINCT FROM scope->>''assistantId''\n  OR NOT EXISTS(SELECT 1 FROM session_messages m WHERE m.workspace_id=w AND m.session_id=s AND m.id=(operation->>''inputMessageId'')::uuid\n   AND m.role=''user'' AND m.sender_user_id=(scope->>''actorUserId'')::uuid)\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n payloads:=command->''payloads'';\n IF jsonb_typeof(payloads)=''object'' THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n   OR (payloads->''annotation'')-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT (payloads->''annotation'') ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n   OR jsonb_typeof(payloads#>''{annotation,sources}'') IS DISTINCT FROM ''array''\n   OR payloads#>>''{annotation,kind}'' IS NOT NULL AND payloads#>>''{annotation,kind}''<>''message_annotation''\n   OR payloads#>>''{annotation,parentId}'' IS DISTINCT FROM operation->>''inputMessageId''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  payloads:=payloads->''messages'';\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND jsonb_typeof(command->''payloads'')<>''object''\n  OR jsonb_typeof(command->''sources'') IS DISTINCT FROM ''array''\n  OR jsonb_typeof(command->''target'') IS DISTINCT FROM ''object''\n  OR (command->''target'')-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'']<>''{}''\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n FOR node IN SELECT value FROM jsonb_array_elements(command->''sources'')\n  UNION ALL SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(command->''payloads'')=''object'' THEN command#>''{payloads,annotation,sources}'' ELSE ''[]''::jsonb END)\n LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object''\n   OR NOT node ?& ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']\n   OR node-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']<>''{}''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF version=2 AND native_conversation_terminal_candidate_valid(operation->''terminalCandidate'',payloads,(operation->>''assistantId'')::uuid) IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n digest:=encode(sha256(convert_to(jsonb_build_object(''format'',version,''workspaceId'',w,''sessionId'',s,''operation'',operation,''command'',command)::text,''UTF8'')),''hex'');\n SELECT * INTO r FROM native_conversation_publications WHERE id=(operation->>''operationId'')::uuid\n  OR workspace_id=w AND session_id=s AND turn_token=(operation->>''turnToken'')::uuid AND slot=''buffered_transcript'' FOR UPDATE;\n IF FOUND THEN\n  IF r.id<>(operation->>''operationId'')::uuid OR r.workspace_id<>w OR r.session_id<>s OR r.input_message_id<>(operation->>''inputMessageId'')::uuid\n   OR r.actor_user_id<>(scope->>''actorUserId'')::uuid OR r.assistant_id<>(scope->>''assistantId'')::uuid OR r.turn_token<>(operation->>''turnToken'')::uuid OR r.command_digest<>digest\n   OR r.command_format<>version OR version=1 AND r.stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n   OR version=2 AND r.requested_stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  result:=native_conversation_publication_result(w,s,r.id);\n  IF result->>''state''<>''committed'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  RETURN jsonb_build_object(''duplicate'',true,''value'',CASE WHEN version=2 THEN native_conversation_publication_packet(r.id,result->''value'') ELSE result->''value'' END);\n END IF;\n IF version=2 THEN\n  state:=native_session_turn_publication_state(w,s,(operation->>''turnToken'')::uuid);\n  IF state NOT IN(''active'',''stopping'',''stopped'') THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean OR state IN(''stopping'',''stopped'');\n ELSE\n  IF native_session_turn_publication_allowed(w,s,(operation->>''turnToken'')::uuid,(operation->>''stopped'')::boolean) IS NOT TRUE\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean;\n END IF;\n RETURN jsonb_build_object(''duplicate'',false,''digest'',digest,''effectiveStopped'',effective_stopped);\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';\nEND "},"bodyParts":["\nDECLARE scope jsonb;r native_conversation_publications;digest text;result jsonb;payloads jsonb;node jsonb;version integer;state text;effective_stopped boolean;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n version:=CASE operation->''version'' WHEN ''1''::jsonb THEN 1 WHEN ''2''::jsonb THEN 2 END;\n IF version IS NULL OR jsonb_typeof(operation) IS DISTINCT FROM ''object''\n  OR operation-(ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)<>''{}''\n  OR NOT operation ?& (ARRAY[''version'',''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'',''slot'',''stopped'']||CASE WHEN version=2 THEN ARRAY[''terminalCandidate''] ELSE ''{}''::text[] END)\n  OR operation->>''slot'' IS DISTINCT FROM ''buffered_transcript'' OR jsonb_typeof(operation->''stopped'') IS DISTINCT FROM ''boolean''\n  OR EXISTS(SELECT 1 FROM unnest(ARRAY[''operationId'',''inputMessageId'',''actorUserId'',''assistantId'',''turnToken'']) key\n   WHERE jsonb_typeof(operation->key) IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(operation->>key,''uuid''))\n  OR jsonb_typeof(command) IS DISTINCT FROM ''object'' OR command-ARRAY[''payloads'',''producer'',''sources'',''target'']<>''{}''\n  OR NOT command ?& ARRAY[''payloads'',''producer'',''sources'',''target'']\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF operation->>''actorUserId'' IS DISTINCT FROM scope->>''actorUserId'' OR operation->>''assistantId'' IS DISTINCT FROM scope->>''assistantId''\n  OR NOT EXISTS(SELECT 1 FROM session_messages m WHERE m.workspace_id=w AND m.session_id=s AND m.id=(operation->>''inputMessageId'')::uuid\n   AND m.role=''user'' AND m.sender_user_id=(scope->>''actorUserId'')::uuid)\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n payloads:=command->''payloads'';\n IF jsonb_typeof(payloads)=''object'' THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n   OR (payloads->''annotation'')-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT (payloads->''annotation'') ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n   OR jsonb_typeof(payloads#>''{annotation,sources}'') IS DISTINCT FROM ''array''\n   OR payloads#>>''{annotation,kind}'' IS NOT NULL AND payloads#>>''{annotation,kind}''<>''message_annotation''\n   OR payloads#>>''{annotation,parentId}'' IS DISTINCT FROM operation->>''inputMessageId''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  payloads:=payloads->''messages'';\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND jsonb_typeof(command->''payloads'')<>''object''\n  OR jsonb_typeof(command->''sources'') IS DISTINCT FROM ''array''\n  OR jsonb_typeof(command->''target'') IS DISTINCT FROM ''object''\n  OR (command->''target'')-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'']<>''{}''\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n FOR node IN SELECT value FROM jsonb_array_elements(command->''sources'')\n  UNION ALL SELECT value FROM jsonb_array_elements(CASE WHEN jsonb_typeof(command->''payloads'')=''object'' THEN command#>''{payloads,annotation,sources}'' ELSE ''[]''::jsonb END)\n LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object''\n   OR NOT node ?& ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']\n   OR node-ARRAY[''workspaceId'',''userId'',''assistantId'',''sensitivity'',''compartments'',''projectIds'',''resourceKind'',''resourceId'',''version'']<>''{}''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF version=2 AND native_conversation_terminal_candidate_valid(operation->''terminalCandidate'',payloads,(operation->>''assistantId'')::uuid) IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n digest:=encode(sha256(convert_to(jsonb_build_object(''format'',version,''workspaceId'',w,''sessionId'',s,''operation'',operation,''command'',command)::text,''UTF8'')),''hex'');\n SELECT * INTO r FROM native_conversation_publications WHERE id=(operation->>''operationId'')::uuid\n  OR workspace_id=w AND session_id=s AND turn_token=(operation->>''turnToken'')::uuid AND slot=''buffered_transcript'' FOR UPDATE;\n IF FOUND THEN\n  IF r.id<>(operation->>''operationId'')::uuid OR r.workspace_id<>w OR r.session_id<>s OR r.input_message_id<>(operation->>''inputMessageId'')::uuid\n   OR r.actor_user_id<>(scope->>''actorUserId'')::uuid OR r.assistant_id<>(scope->>''assistantId'')::uuid OR r.turn_token<>(operation->>''turnToken'')::uuid OR r.command_digest<>digest\n   OR r.command_format<>version OR version=1 AND r.stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n   OR version=2 AND r.requested_stopped IS DISTINCT FROM (operation->>''stopped'')::boolean\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  result:=native_conversation_publication_result(w,s,r.id);\n  IF result->>''state''<>''committed'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  RETURN jsonb_build_object(''duplicate'',true,''value'',CASE WHEN version=2 THEN native_conversation_publication_packet(r.id,result->''value'') ELSE result->''value'' END);\n END IF;\n IF version=2 THEN\n  state:=native_session_turn_publication_state(w,s,(operation->>''turnToken'')::uuid);\n  IF state NOT IN(''active'',''stopping'',''stopped'') THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean OR state IN(''stopping'',''stopped'');\n ELSE\n  IF native_session_turn_publication_allowed(w,s,(operation->>''turnToken'')::uuid,(operation->>''stopped'')::boolean) IS NOT TRUE\n  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n  effective_stopped:=(operation->>''stopped'')::boolean;\n END IF;\n RETURN jsonb_build_object(''duplicate'',false,''digest'',digest,''effectiveStopped'',effective_stopped);\nEXCEPTION WHEN invalid_text_representation OR invalid_parameter_value THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_publication_complete()","sourceSpec":{"profile":"new","name":"native_conversation_publication_complete","signature":"native_conversation_publication_complete()","argNames":[],"argTypes":[],"returnType":"trigger","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO r FROM native_conversation_publications WHERE id=NEW.id;\n IF NOT FOUND THEN RETURN NULL;END IF; -- an authorized cascading erasure owns deletion\n IF r.outputs IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(r.outputs)<>r.expected_output_count OR NOT r.leader_frame_id=ANY(r.frame_ids)\n  OR cardinality(r.frame_ids)<>(SELECT count(DISTINCT value) FROM unnest(r.frame_ids) value)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.outputs) n WHERE NOT (n->>''frameId'')::uuid=ANY(r.frame_ids))\n  OR r.command_format=2 AND (r.stopped AND r.terminal_descriptor IS NOT NULL\n   OR native_conversation_terminal_subset(r.terminal_descriptor,r.terminal_outputs,r.outputs) IS NOT TRUE)\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NULL;\nEND "},"bodyParts":["\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO r FROM native_conversation_publications WHERE id=NEW.id;\n IF NOT FOUND THEN RETURN NULL;END IF; -- an authorized cascading erasure owns deletion\n IF r.outputs IS NULL OR r.completed_at IS NULL OR jsonb_typeof(r.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(r.outputs)<>r.expected_output_count OR NOT r.leader_frame_id=ANY(r.frame_ids)\n  OR cardinality(r.frame_ids)<>(SELECT count(DISTINCT value) FROM unnest(r.frame_ids) value)\n  OR EXISTS(SELECT 1 FROM jsonb_array_elements(r.outputs) n WHERE NOT (n->>''frameId'')::uuid=ANY(r.frame_ids))\n  OR r.command_format=2 AND (r.stopped AND r.terminal_descriptor IS NOT NULL\n   OR native_conversation_terminal_subset(r.terminal_descriptor,r.terminal_outputs,r.outputs) IS NOT TRUE)\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NULL;\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_publication_immutable()","sourceSpec":{"profile":"new","name":"native_conversation_publication_immutable","signature":"native_conversation_publication_immutable()","argNames":[],"argTypes":[],"returnType":"trigger","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nBEGIN\n IF (to_jsonb(NEW)-ARRAY[''outputs'',''completed_at'']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY[''outputs'',''completed_at''])\n  OR OLD.outputs IS NOT NULL OR NEW.outputs IS NULL OR NEW.completed_at IS NULL\n  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_work work JOIN native_turn_publication_seals seal\n   ON seal.transaction_id=work.transaction_id AND seal.frame_id=work.frame_id\n   WHERE work.transaction_id=txid_current() AND work.frame_id=OLD.leader_frame_id AND work.publication_id=OLD.id\n    AND work.workspace_id=OLD.workspace_id AND work.session_id=OLD.session_id AND work.context=native_turn_context())\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NEW;\nEND "},"bodyParts":["\nBEGIN\n IF (to_jsonb(NEW)-ARRAY[''outputs'',''completed_at'']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY[''outputs'',''completed_at''])\n  OR OLD.outputs IS NOT NULL OR NEW.outputs IS NULL OR NEW.completed_at IS NULL\n  OR NOT EXISTS(SELECT 1 FROM native_turn_publication_work work JOIN native_turn_publication_seals seal\n   ON seal.transaction_id=work.transaction_id AND seal.frame_id=work.frame_id\n   WHERE work.transaction_id=txid_current() AND work.frame_id=OLD.leader_frame_id AND work.publication_id=OLD.id\n    AND work.workspace_id=OLD.workspace_id AND work.session_id=OLD.session_id AND work.context=native_turn_context())\n  OR native_turn_helpers_current() IS NOT TRUE\n THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN NEW;\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"read_native_conversation_publications(uuid,uuid,jsonb,integer)","sourceSpec":{"profile":"new","name":"read_native_conversation_publications","signature":"read_native_conversation_publications(uuid,uuid,jsonb,integer)","argNames":["w","s","after","maximum"],"argTypes":["uuid","uuid","jsonb","integer"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":"NULL::jsonb, 20","appExecute":true,"body":"\nDECLARE scope jsonb;cursor_at timestamptz;cursor_id uuid;r native_conversation_publications;result jsonb;items jsonb:=''[]'';next_cursor jsonb;count integer:=0;diagnostic text;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n IF maximum IS NULL OR maximum NOT BETWEEN 1 AND 50 OR after IS NOT NULL AND\n  (jsonb_typeof(after) IS DISTINCT FROM ''object'' OR after-ARRAY[''createdAt'',''operationId'']<>''{}'' OR NOT after ?& ARRAY[''createdAt'',''operationId'']\n   OR jsonb_typeof(after->''createdAt'') IS DISTINCT FROM ''string'' OR jsonb_typeof(after->''operationId'') IS DISTINCT FROM ''string''\n   OR NOT pg_input_is_valid(after->>''createdAt'',''timestamptz'') OR NOT pg_input_is_valid(after->>''operationId'',''uuid''))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF after IS NOT NULL THEN cursor_at:=(after->>''createdAt'')::timestamptz;cursor_id:=(after->>''operationId'')::uuid;END IF;\n FOR r IN SELECT * FROM native_conversation_publications WHERE workspace_id=w AND session_id=s\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid\n  AND (after IS NULL OR (created_at,id)<(cursor_at,cursor_id)) ORDER BY created_at DESC,id DESC LIMIT maximum+1\n LOOP\n  count:=count+1;IF count>maximum THEN EXIT;END IF;\n  BEGIN\n   result:=native_conversation_publication_result(w,s,r.id)-''value'';\n   IF result->>''state''=''unknown'' THEN result:=jsonb_build_object(''state'',''unavailable'',''reason'',''publication_changed'');END IF;\n  EXCEPTION WHEN SQLSTATE ''42501'' OR SQLSTATE ''22023'' OR lock_not_available THEN\n   GET STACKED DIAGNOSTICS diagnostic=RETURNED_SQLSTATE;\n   result:=jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable:''||diagnostic);\n  END;\n  items:=items||jsonb_build_array(result||jsonb_build_object(''operationId'',r.id,''inputMessageId'',r.input_message_id,''assistantId'',r.assistant_id));\n  next_cursor:=jsonb_build_object(''createdAt'',r.created_at,''operationId'',r.id);\n END LOOP;\n IF count<=maximum THEN next_cursor:=NULL;END IF;\n RETURN jsonb_build_object(''version'',1,''scope'',scope,''items'',items,''nextCursor'',next_cursor);\nEND "},"bodyParts":["\nDECLARE scope jsonb;cursor_at timestamptz;cursor_id uuid;r native_conversation_publications;result jsonb;items jsonb:=''[]'';next_cursor jsonb;count integer:=0;diagnostic text;\nBEGIN\n scope:=native_conversation_publication_scope(w,s);\n IF maximum IS NULL OR maximum NOT BETWEEN 1 AND 50 OR after IS NOT NULL AND\n  (jsonb_typeof(after) IS DISTINCT FROM ''object'' OR after-ARRAY[''createdAt'',''operationId'']<>''{}'' OR NOT after ?& ARRAY[''createdAt'',''operationId'']\n   OR jsonb_typeof(after->''createdAt'') IS DISTINCT FROM ''string'' OR jsonb_typeof(after->''operationId'') IS DISTINCT FROM ''string''\n   OR NOT pg_input_is_valid(after->>''createdAt'',''timestamptz'') OR NOT pg_input_is_valid(after->>''operationId'',''uuid''))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n IF after IS NOT NULL THEN cursor_at:=(after->>''createdAt'')::timestamptz;cursor_id:=(after->>''operationId'')::uuid;END IF;\n FOR r IN SELECT * FROM native_conversation_publications WHERE workspace_id=w AND session_id=s\n  AND actor_user_id=(scope->>''actorUserId'')::uuid AND assistant_id=(scope->>''assistantId'')::uuid\n  AND (after IS NULL OR (created_at,id)<(cursor_at,cursor_id)) ORDER BY created_at DESC,id DESC LIMIT maximum+1\n LOOP\n  count:=count+1;IF count>maximum THEN EXIT;END IF;\n  BEGIN\n   result:=native_conversation_publication_result(w,s,r.id)-''value'';\n   IF result->>''state''=''unknown'' THEN result:=jsonb_build_object(''state'',''unavailable'',''reason'',''publication_changed'');END IF;\n  EXCEPTION WHEN SQLSTATE ''42501'' OR SQLSTATE ''22023'' OR lock_not_available THEN\n   GET STACKED DIAGNOSTICS diagnostic=RETURNED_SQLSTATE;\n   result:=jsonb_build_object(''state'',''unavailable'',''reason'',''source_proof_unavailable:''||diagnostic);\n  END;\n  items:=items||jsonb_build_array(result||jsonb_build_object(''operationId'',r.id,''inputMessageId'',r.input_message_id,''assistantId'',r.assistant_id));\n  next_cursor:=jsonb_build_object(''createdAt'',r.created_at,''operationId'',r.id);\n END LOOP;\n IF count<=maximum THEN next_cursor:=NULL;END IF;\n RETURN jsonb_build_object(''version'',1,''scope'',scope,''items'',items,''nextCursor'',next_cursor);\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_session_turn_publication_state(uuid,uuid,uuid)","sourceSpec":{"profile":"new","name":"native_session_turn_publication_state","signature":"native_session_turn_publication_state(uuid,uuid,uuid)","argNames":["w","s","t"],"argTypes":["uuid","uuid","uuid"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":true,"body":"\nDECLARE r sessions;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n PERFORM lock_native_session_context_publication(w,s);\n SELECT * INTO r FROM sessions WHERE workspace_id=w AND id=s;\n IF NOT FOUND OR t IS NULL OR r.last_turn_lease_token IS DISTINCT FROM t THEN RETURN ''superseded'';END IF;\n IF r.turn_lease_token=t AND r.status=''running'' THEN\n  RETURN CASE WHEN r.cancel_requested_at IS NULL THEN ''active'' ELSE ''stopping'' END;\n END IF;\n IF r.turn_lease_token IS NULL AND r.turn_end_reason=''stopped_by_user'' THEN RETURN ''stopped'';END IF;\n RETURN ''superseded'';\nEND "},"bodyParts":["\nDECLARE r sessions;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n PERFORM lock_native_session_context_publication(w,s);\n SELECT * INTO r FROM sessions WHERE workspace_id=w AND id=s;\n IF NOT FOUND OR t IS NULL OR r.last_turn_lease_token IS DISTINCT FROM t THEN RETURN ''superseded'';END IF;\n IF r.turn_lease_token=t AND r.status=''running'' THEN\n  RETURN CASE WHEN r.cancel_requested_at IS NULL THEN ''active'' ELSE ''stopping'' END;\n END IF;\n IF r.turn_lease_token IS NULL AND r.turn_end_reason=''stopped_by_user'' THEN RETURN ''stopped'';END IF;\n RETURN ''superseded'';\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_terminal_candidate_valid(jsonb,jsonb,uuid)","sourceSpec":{"profile":"new","name":"native_conversation_terminal_candidate_valid","signature":"native_conversation_terminal_candidate_valid(jsonb,jsonb,uuid)","argNames":["candidate","payloads","answering"],"argTypes":["jsonb","jsonb","uuid"],"returnType":"boolean","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE m jsonb;row jsonb;previous integer:=-1;ordinal integer;origins text[]:=''{}'';\nBEGIN\n IF candidate IS NULL OR candidate=''null''::jsonb THEN RETURN true;END IF;\n IF jsonb_typeof(candidate) IS DISTINCT FROM ''object''\n  OR candidate-ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']<>''{}''\n  OR NOT candidate ?& ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']\n  OR candidate->''version''<>''1''::jsonb OR candidate->>''disposition'' IS DISTINCT FROM ''reply''\n  OR candidate->>''projection'' IS DISTINCT FROM ''persistable_response_v1'' OR candidate->>''formatter'' IS DISTINCT FROM ''turn_output_v1''\n  OR candidate->>''format'' NOT IN(''compact'',''channel'') OR candidate->>''format'' IS NULL\n  OR jsonb_typeof(candidate->''invocationId'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(candidate->>''invocationId'',''uuid'') OR length(candidate->>''invocationId'')<>36\n  OR candidate->>''textDigest'' !~ ''^[a-f0-9]{64}$'' OR candidate->>''textDigest'' IS NULL\n  OR jsonb_typeof(candidate->''members'') IS DISTINCT FROM ''array'' OR jsonb_array_length(candidate->''members'') NOT BETWEEN 1 AND 512\n  OR jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(candidate->''members'') LOOP\n  IF jsonb_typeof(m) IS DISTINCT FROM ''object'' OR m-ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']<>''{}''\n   OR NOT m ?& ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']\n   OR jsonb_typeof(m->''origin'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(m->>''origin'',''uuid'') OR length(m->>''origin'')<>36 OR m->>''origin''=ANY(origins)\n   OR jsonb_typeof(m->''revision'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''revision'',''integer'')\n   OR jsonb_typeof(m->''commandOrdinal'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''commandOrdinal'',''integer'')\n   OR m->>''snapshotDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''snapshotDigest'' IS NULL\n   OR m->>''contentDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''contentDigest'' IS NULL\n  THEN RETURN false;END IF;\n  ordinal:=(m->>''commandOrdinal'')::integer;\n  IF (m->>''revision'')::integer<1 OR ordinal<=previous OR ordinal>=jsonb_array_length(payloads) THEN RETURN false;END IF;\n  previous:=ordinal;origins:=origins||(m->>''origin'');row:=payloads->ordinal;\n  IF row->>''role'' IS DISTINCT FROM ''assistant'' OR row->>''senderAssistantId'' IS DISTINCT FROM answering::text\n   OR jsonb_typeof(row->''content'') IS DISTINCT FROM ''array''\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(row->''content'') b WHERE b->>''type'' IN(''tool_use'',''host_observation''))\n  THEN RETURN false;END IF;\n END LOOP;\n RETURN true;\nEND "},"bodyParts":["\nDECLARE m jsonb;row jsonb;previous integer:=-1;ordinal integer;origins text[]:=''{}'';\nBEGIN\n IF candidate IS NULL OR candidate=''null''::jsonb THEN RETURN true;END IF;\n IF jsonb_typeof(candidate) IS DISTINCT FROM ''object''\n  OR candidate-ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']<>''{}''\n  OR NOT candidate ?& ARRAY[''version'',''disposition'',''invocationId'',''projection'',''formatter'',''format'',''textDigest'',''members'']\n  OR candidate->''version''<>''1''::jsonb OR candidate->>''disposition'' IS DISTINCT FROM ''reply''\n  OR candidate->>''projection'' IS DISTINCT FROM ''persistable_response_v1'' OR candidate->>''formatter'' IS DISTINCT FROM ''turn_output_v1''\n  OR candidate->>''format'' NOT IN(''compact'',''channel'') OR candidate->>''format'' IS NULL\n  OR jsonb_typeof(candidate->''invocationId'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(candidate->>''invocationId'',''uuid'') OR length(candidate->>''invocationId'')<>36\n  OR candidate->>''textDigest'' !~ ''^[a-f0-9]{64}$'' OR candidate->>''textDigest'' IS NULL\n  OR jsonb_typeof(candidate->''members'') IS DISTINCT FROM ''array'' OR jsonb_array_length(candidate->''members'') NOT BETWEEN 1 AND 512\n  OR jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(candidate->''members'') LOOP\n  IF jsonb_typeof(m) IS DISTINCT FROM ''object'' OR m-ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']<>''{}''\n   OR NOT m ?& ARRAY[''origin'',''revision'',''snapshotDigest'',''contentDigest'',''commandOrdinal'']\n   OR jsonb_typeof(m->''origin'') IS DISTINCT FROM ''string'' OR NOT pg_input_is_valid(m->>''origin'',''uuid'') OR length(m->>''origin'')<>36 OR m->>''origin''=ANY(origins)\n   OR jsonb_typeof(m->''revision'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''revision'',''integer'')\n   OR jsonb_typeof(m->''commandOrdinal'') IS DISTINCT FROM ''number'' OR NOT pg_input_is_valid(m->>''commandOrdinal'',''integer'')\n   OR m->>''snapshotDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''snapshotDigest'' IS NULL\n   OR m->>''contentDigest'' !~ ''^[a-f0-9]{64}$'' OR m->>''contentDigest'' IS NULL\n  THEN RETURN false;END IF;\n  ordinal:=(m->>''commandOrdinal'')::integer;\n  IF (m->>''revision'')::integer<1 OR ordinal<=previous OR ordinal>=jsonb_array_length(payloads) THEN RETURN false;END IF;\n  previous:=ordinal;origins:=origins||(m->>''origin'');row:=payloads->ordinal;\n  IF row->>''role'' IS DISTINCT FROM ''assistant'' OR row->>''senderAssistantId'' IS DISTINCT FROM answering::text\n   OR jsonb_typeof(row->''content'') IS DISTINCT FROM ''array''\n   OR EXISTS(SELECT 1 FROM jsonb_array_elements(row->''content'') b WHERE b->>''type'' IN(''tool_use'',''host_observation''))\n  THEN RETURN false;END IF;\n END LOOP;\n RETURN true;\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_terminal_subset(jsonb,jsonb,jsonb)","sourceSpec":{"profile":"new","name":"native_conversation_terminal_subset","signature":"native_conversation_terminal_subset(jsonb,jsonb,jsonb)","argNames":["descriptor","selected","outputs"],"argTypes":["jsonb","jsonb","jsonb"],"returnType":"boolean","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE m jsonb;n jsonb;position integer:=0;seen uuid[]:=''{}'';\nBEGIN\n IF descriptor IS NULL THEN RETURN selected IS NULL;END IF;\n IF jsonb_typeof(selected) IS DISTINCT FROM ''array'' OR jsonb_array_length(selected)<>jsonb_array_length(descriptor->''members'')\n  OR jsonb_array_length(selected) NOT BETWEEN 1 AND 512 THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(descriptor->''members'') LOOP\n  n:=selected->position;position:=position+1;\n  IF n-ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']<>''{}''\n   OR NOT n ?& ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']\n   OR n->''origin'' IS DISTINCT FROM m->''origin'' OR n->''revision'' IS DISTINCT FROM m->''revision''\n   OR n->''commandOrdinal'' IS DISTINCT FROM m->''commandOrdinal'' OR n->>''kind'' IS DISTINCT FROM ''session_message''\n   OR NOT pg_input_is_valid(n->>''id'',''uuid'') OR (n->>''id'')::uuid=ANY(seen)\n   OR (SELECT count(*) FROM jsonb_array_elements(outputs) o WHERE o=n-ARRAY[''origin'',''revision'',''commandOrdinal''])<>1\n  THEN RETURN false;END IF;\n  seen:=seen||(n->>''id'')::uuid;\n END LOOP;\n RETURN true;\nEND "},"bodyParts":["\nDECLARE m jsonb;n jsonb;position integer:=0;seen uuid[]:=''{}'';\nBEGIN\n IF descriptor IS NULL THEN RETURN selected IS NULL;END IF;\n IF jsonb_typeof(selected) IS DISTINCT FROM ''array'' OR jsonb_array_length(selected)<>jsonb_array_length(descriptor->''members'')\n  OR jsonb_array_length(selected) NOT BETWEEN 1 AND 512 THEN RETURN false;END IF;\n FOR m IN SELECT value FROM jsonb_array_elements(descriptor->''members'') LOOP\n  n:=selected->position;position:=position+1;\n  IF n-ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']<>''{}''\n   OR NOT n ?& ARRAY[''origin'',''revision'',''commandOrdinal'',''kind'',''id'',''version'',''frameId'',''derivationId'',''sequence'',''payloadDigest'']\n   OR n->''origin'' IS DISTINCT FROM m->''origin'' OR n->''revision'' IS DISTINCT FROM m->''revision''\n   OR n->''commandOrdinal'' IS DISTINCT FROM m->''commandOrdinal'' OR n->>''kind'' IS DISTINCT FROM ''session_message''\n   OR NOT pg_input_is_valid(n->>''id'',''uuid'') OR (n->>''id'')::uuid=ANY(seen)\n   OR (SELECT count(*) FROM jsonb_array_elements(outputs) o WHERE o=n-ARRAY[''origin'',''revision'',''commandOrdinal''])<>1\n  THEN RETURN false;END IF;\n  seen:=seen||(n->>''id'')::uuid;\n END LOOP;\n RETURN true;\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_conversation_publication_packet(uuid,jsonb)","sourceSpec":{"profile":"new","name":"native_conversation_publication_packet","signature":"native_conversation_publication_packet(uuid,jsonb)","argNames":["i","value"],"argTypes":["uuid","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO STRICT r FROM native_conversation_publications WHERE id=i;\n IF r.command_format<>2 THEN RETURN value;END IF;\n RETURN jsonb_build_object(''value'',value,''publication'',jsonb_build_object(''operationId'',r.id,''commandDigest'',r.command_digest,\n  ''requestedStopped'',r.requested_stopped,''stopped'',r.stopped,''terminalDescriptor'',r.terminal_descriptor,''terminalOutputs'',r.terminal_outputs));\nEND "},"bodyParts":["\nDECLARE r native_conversation_publications;\nBEGIN\n SELECT * INTO STRICT r FROM native_conversation_publications WHERE id=i;\n IF r.command_format<>2 THEN RETURN value;END IF;\n RETURN jsonb_build_object(''value'',value,''publication'',jsonb_build_object(''operationId'',r.id,''commandDigest'',r.command_digest,\n  ''requestedStopped'',r.requested_stopped,''stopped'',r.stopped,''terminalDescriptor'',r.terminal_descriptor,''terminalOutputs'',r.terminal_outputs));\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_session_public_turn_id(uuid,uuid,uuid)","sourceSpec":{"profile":"new","name":"native_session_public_turn_id","signature":"native_session_public_turn_id(uuid,uuid,uuid)","argNames":["w","s","t"],"argTypes":["uuid","uuid","uuid"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nBEGIN\n RETURN CASE WHEN w IS NULL OR s IS NULL OR t IS NULL THEN NULL ELSE\n  encode(sha256(convert_to(''use-brian/session-turn/v1:''||w::text||'':''||s::text||'':''||t::text,''UTF8'')),''hex'') END;\nEND "},"bodyParts":["\nBEGIN\n RETURN CASE WHEN w IS NULL OR s IS NULL OR t IS NULL THEN NULL ELSE\n  encode(sha256(convert_to(''use-brian/session-turn/v1:''||w::text||'':''||s::text||'':''||t::text,''UTF8'')),''hex'') END;\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)","sourceSpec":{"profile":"new","name":"native_session_expired_turn_outcome","signature":"native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)","argNames":["w","s","t","a","cancelled"],"argTypes":["uuid","uuid","uuid","uuid","boolean"],"returnType":"text","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE publication public.native_conversation_publications;\nBEGIN\n IF cancelled THEN RETURN ''stopped_by_user'';END IF;\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF w IS NULL OR t IS NULL OR a IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n SELECT * INTO publication FROM public.native_conversation_publications p\n  WHERE p.workspace_id=w AND p.session_id=s AND p.turn_token=t\n   AND p.slot=''buffered_transcript'';\n IF NOT FOUND OR publication.command_format=1 THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.command_format<>2 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.completed_at IS NULL OR publication.outputs IS NULL OR jsonb_typeof(publication.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.outputs)<>publication.expected_output_count\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.assistant_id<>a OR publication.stopped OR publication.terminal_descriptor IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.outputs IS NULL OR publication.terminal_outputs IS NULL\n  OR jsonb_typeof(publication.terminal_outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.terminal_outputs)=0\n  OR jsonb_array_length(publication.terminal_outputs)<>jsonb_array_length(publication.terminal_descriptor->''members'')\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n -- The authenticated independent completion owner validates descriptor/member\n -- shape, exact roots/native references and the entire actual output closure\n -- before this immutable row can commit. Current access does not alter that fact.\n RETURN ''publication_recovered'';\nEND "},"bodyParts":["\nDECLARE publication public.native_conversation_publications;\nBEGIN\n IF cancelled THEN RETURN ''stopped_by_user'';END IF;\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF w IS NULL OR t IS NULL OR a IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n SELECT * INTO publication FROM public.native_conversation_publications p\n  WHERE p.workspace_id=w AND p.session_id=s AND p.turn_token=t\n   AND p.slot=''buffered_transcript'';\n IF NOT FOUND OR publication.command_format=1 THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.command_format<>2 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.completed_at IS NULL OR publication.outputs IS NULL OR jsonb_typeof(publication.outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.outputs)<>publication.expected_output_count\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF publication.assistant_id<>a OR publication.stopped OR publication.terminal_descriptor IS NULL THEN RETURN ''stalled_reclaimed'';END IF;\n IF publication.outputs IS NULL OR publication.terminal_outputs IS NULL\n  OR jsonb_typeof(publication.terminal_outputs) IS DISTINCT FROM ''array''\n  OR jsonb_array_length(publication.terminal_outputs)=0\n  OR jsonb_array_length(publication.terminal_outputs)<>jsonb_array_length(publication.terminal_descriptor->''members'')\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n -- The authenticated independent completion owner validates descriptor/member\n -- shape, exact roots/native references and the entire actual output closure\n -- before this immutable row can commit. Current access does not alter that fact.\n RETURN ''publication_recovered'';\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_session_turn_transition(uuid,text,uuid,timestamp with time zone,integer,uuid,text,boolean)","sourceSpec":{"profile":"new","name":"native_session_turn_transition","signature":"native_session_turn_transition(uuid,text,uuid,timestamp with time zone,integer,uuid,text,boolean)","argNames":["s","action","answering_assistant","started_at","stale_after_ms","expected_token","expected_public_turn_id","fence_token"],"argTypes":["uuid","text","uuid","timestamp with time zone","integer","uuid","text","boolean"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r public.sessions;w uuid;original_token uuid;original_public_id text;outcome text;\n recovered jsonb;next_token uuid;resting text;now_at timestamptz;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF action IS NULL OR action NOT IN(''claim'',''reclaim'',''cancel'') OR stale_after_ms IS NULL OR stale_after_ms<1\n  OR fence_token IS NULL OR current_setting(''transaction_isolation'')<>''read committed''\n THEN RAISE EXCEPTION ''invalid_turn_transition'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n -- Same order as canonical native publication, never session then workspace.\n IF w IS NOT NULL THEN\n  PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;\n  IF NOT FOUND THEN RETURN NULL;END IF;\n END IF;\n -- VOLATILE PL/pgSQL uses a new READ COMMITTED snapshot here after lock wait.\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n now_at:=clock_timestamp();original_token:=r.turn_lease_token;\n original_public_id:=public.native_session_public_turn_id(w,s,original_token);\n IF fence_token AND original_token IS DISTINCT FROM expected_token\n  OR expected_public_turn_id IS NOT NULL AND original_public_id IS DISTINCT FROM expected_public_turn_id\n THEN RETURN jsonb_build_object(''state'',''superseded'');END IF;\n IF action=''cancel'' THEN\n  IF r.status<>''running'' THEN RETURN jsonb_build_object(''state'',''not_running'');END IF;\n  IF original_token IS NULL THEN\n   UPDATE public.sessions SET status=''idle'',turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=''stopped_by_user'',last_active_at=now_at WHERE id=s;\n   RETURN jsonb_build_object(''state'',''stopped_legacy'',''turnId'',NULL,''reason'',''stopped_by_user'');\n  END IF;\n  UPDATE public.sessions SET cancel_requested_at=coalesce(cancel_requested_at,now_at)\n   WHERE id=s AND turn_lease_token=original_token AND status=''running'';\n  RETURN jsonb_build_object(''state'',''cancel_requested'',''token'',original_token,''turnId'',original_public_id,\n   ''stale'',coalesce(r.turn_heartbeat_at,r.last_active_at)<now_at-make_interval(secs=>stale_after_ms/1000.0));\n END IF;\n IF r.status=''running'' THEN\n  IF coalesce(r.turn_heartbeat_at,r.last_active_at)>=now_at-make_interval(secs=>stale_after_ms/1000.0)\n  THEN RETURN jsonb_build_object(''state'',''busy'');END IF;\n  outcome:=public.native_session_expired_turn_outcome(r.workspace_id,r.id,r.turn_lease_token,\n   CASE WHEN r.last_turn_lease_token=r.turn_lease_token THEN r.turn_assistant_id END,r.cancel_requested_at IS NOT NULL);\n  resting:=CASE WHEN outcome IN(''publication_recovered'',''stopped_by_user'') THEN ''idle'' ELSE ''timeout'' END;\n  UPDATE public.sessions SET status=resting,turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,\n   turn_end_reason=outcome,last_active_at=now_at WHERE id=s;\n  recovered:=jsonb_build_object(''turnId'',original_public_id,''reason'',outcome);\n ELSIF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''not_running'');\n END IF;\n IF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''recovered'',''recovered'',recovered);END IF;\n next_token:=gen_random_uuid();\n UPDATE public.sessions SET status=''running'',last_active_at=now_at,turn_lease_token=next_token,\n  turn_started_at=coalesce(started_at,now_at),turn_heartbeat_at=now_at,cancel_requested_at=NULL,\n  turn_end_reason=NULL,turn_assistant_id=answering_assistant WHERE id=s;\n RETURN jsonb_build_object(''state'',''claimed'',''token'',next_token,\n  ''turnId'',public.native_session_public_turn_id(w,s,next_token),''recovered'',recovered);\nEND "},"bodyParts":["\nDECLARE r public.sessions;w uuid;original_token uuid;original_public_id text;outcome text;\n recovered jsonb;next_token uuid;resting text;now_at timestamptz;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF action IS NULL OR action NOT IN(''claim'',''reclaim'',''cancel'') OR stale_after_ms IS NULL OR stale_after_ms<1\n  OR fence_token IS NULL OR current_setting(''transaction_isolation'')<>''read committed''\n THEN RAISE EXCEPTION ''invalid_turn_transition'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n -- Same order as canonical native publication, never session then workspace.\n IF w IS NOT NULL THEN\n  PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;\n  IF NOT FOUND THEN RETURN NULL;END IF;\n END IF;\n -- VOLATILE PL/pgSQL uses a new READ COMMITTED snapshot here after lock wait.\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n now_at:=clock_timestamp();original_token:=r.turn_lease_token;\n original_public_id:=public.native_session_public_turn_id(w,s,original_token);\n IF fence_token AND original_token IS DISTINCT FROM expected_token\n  OR expected_public_turn_id IS NOT NULL AND original_public_id IS DISTINCT FROM expected_public_turn_id\n THEN RETURN jsonb_build_object(''state'',''superseded'');END IF;\n IF action=''cancel'' THEN\n  IF r.status<>''running'' THEN RETURN jsonb_build_object(''state'',''not_running'');END IF;\n  IF original_token IS NULL THEN\n   UPDATE public.sessions SET status=''idle'',turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=''stopped_by_user'',last_active_at=now_at WHERE id=s;\n   RETURN jsonb_build_object(''state'',''stopped_legacy'',''turnId'',NULL,''reason'',''stopped_by_user'');\n  END IF;\n  UPDATE public.sessions SET cancel_requested_at=coalesce(cancel_requested_at,now_at)\n   WHERE id=s AND turn_lease_token=original_token AND status=''running'';\n  RETURN jsonb_build_object(''state'',''cancel_requested'',''token'',original_token,''turnId'',original_public_id,\n   ''stale'',coalesce(r.turn_heartbeat_at,r.last_active_at)<now_at-make_interval(secs=>stale_after_ms/1000.0));\n END IF;\n IF r.status=''running'' THEN\n  IF coalesce(r.turn_heartbeat_at,r.last_active_at)>=now_at-make_interval(secs=>stale_after_ms/1000.0)\n  THEN RETURN jsonb_build_object(''state'',''busy'');END IF;\n  outcome:=public.native_session_expired_turn_outcome(r.workspace_id,r.id,r.turn_lease_token,\n   CASE WHEN r.last_turn_lease_token=r.turn_lease_token THEN r.turn_assistant_id END,r.cancel_requested_at IS NOT NULL);\n  resting:=CASE WHEN outcome IN(''publication_recovered'',''stopped_by_user'') THEN ''idle'' ELSE ''timeout'' END;\n  UPDATE public.sessions SET status=resting,turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,\n   turn_end_reason=outcome,last_active_at=now_at WHERE id=s;\n  recovered:=jsonb_build_object(''turnId'',original_public_id,''reason'',outcome);\n ELSIF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''not_running'');\n END IF;\n IF action=''reclaim'' THEN RETURN jsonb_build_object(''state'',''recovered'',''recovered'',recovered);END IF;\n next_token:=gen_random_uuid();\n UPDATE public.sessions SET status=''running'',last_active_at=now_at,turn_lease_token=next_token,\n  turn_started_at=coalesce(started_at,now_at),turn_heartbeat_at=now_at,cancel_requested_at=NULL,\n  turn_end_reason=NULL,turn_assistant_id=answering_assistant WHERE id=s;\n RETURN jsonb_build_object(''state'',''claimed'',''token'',next_token,\n  ''turnId'',public.native_session_public_turn_id(w,s,next_token),''recovered'',recovered);\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"native_session_release_turn(uuid,uuid,text)","sourceSpec":{"profile":"new","name":"native_session_release_turn","signature":"native_session_release_turn(uuid,uuid,text)","argNames":["s","t","requested_reason"],"argTypes":["uuid","uuid","text"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp"],"defaultsSQL":null,"appExecute":false,"body":"\nDECLARE r public.sessions;w uuid;reason text;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF t IS NULL OR requested_reason IS NULL OR requested_reason NOT IN(''completed'',''failed'',''stopped_by_user'',''stalled_reclaimed'',''timeout'')\n THEN RAISE EXCEPTION ''invalid_turn_release'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF w IS NOT NULL THEN PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;END IF;\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND OR r.status<>''running'' OR r.turn_lease_token IS DISTINCT FROM t THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n reason:=CASE WHEN r.cancel_requested_at IS NOT NULL THEN ''stopped_by_user'' ELSE requested_reason END;\n UPDATE public.sessions SET status=CASE WHEN reason=''failed'' THEN ''failed'' WHEN reason IN(''completed'',''stopped_by_user'',''publication_recovered'') THEN ''idle'' ELSE ''timeout'' END,\n  turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=reason,last_active_at=clock_timestamp()\n  WHERE id=s AND turn_lease_token=t;\n RETURN jsonb_build_object(''turnId'',public.native_session_public_turn_id(w,s,t),''reason'',reason);\nEND "},"bodyParts":["\nDECLARE r public.sessions;w uuid;reason text;\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE\n THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;\n IF t IS NULL OR requested_reason IS NULL OR requested_reason NOT IN(''completed'',''failed'',''stopped_by_user'',''stalled_reclaimed'',''timeout'')\n THEN RAISE EXCEPTION ''invalid_turn_release'' USING ERRCODE=''22023'';END IF;\n SELECT workspace_id INTO w FROM public.sessions WHERE id=s;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF w IS NOT NULL THEN PERFORM id FROM public.workspaces WHERE id=w FOR NO KEY UPDATE;END IF;\n SELECT * INTO r FROM public.sessions WHERE id=s FOR UPDATE;\n IF NOT FOUND OR r.status<>''running'' OR r.turn_lease_token IS DISTINCT FROM t THEN RETURN NULL;END IF;\n IF r.workspace_id IS DISTINCT FROM w THEN RAISE EXCEPTION ''turn_scope_changed'' USING ERRCODE=''40001'';END IF;\n reason:=CASE WHEN r.cancel_requested_at IS NOT NULL THEN ''stopped_by_user'' ELSE requested_reason END;\n UPDATE public.sessions SET status=CASE WHEN reason=''failed'' THEN ''failed'' WHEN reason IN(''completed'',''stopped_by_user'',''publication_recovered'') THEN ''idle'' ELSE ''timeout'' END,\n  turn_lease_token=NULL,turn_heartbeat_at=NULL,cancel_requested_at=NULL,turn_end_reason=reason,last_active_at=clock_timestamp()\n  WHERE id=s AND turn_lease_token=t;\n RETURN jsonb_build_object(''turnId'',public.native_session_public_turn_id(w,s,t),''reason'',reason);\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]},{"signature":"publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)","sourceSpec":{"profile":"new","name":"publish_native_session_message_batch","signature":"publish_native_session_message_batch(uuid,uuid,jsonb,text,jsonb,jsonb,jsonb)","argNames":["w","s","payloads","producer","sources","target","operation"],"argTypes":["uuid","uuid","jsonb","text","jsonb","jsonb","jsonb"],"returnType":"jsonb","language":"plpgsql","volatility":"v","secdef":true,"config":["search_path=pg_catalog, public, pg_temp","plan_cache_mode=force_generic_plan"],"defaultsSQL":null,"appExecute":true,"body":"\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;parent jsonb;payload jsonb;node jsonb;\n envelope boolean:=jsonb_typeof(payloads)=''object'';annotation_command jsonb;session_row sessions;previous uuid;\n a_kind text:=''message_annotation'';a_parent uuid;a_id uuid;a_payload jsonb;a_producer text;a_sources jsonb;a_revision uuid;a_generation bigint;a_target jsonb;\n commands jsonb:=''[]'';prepared jsonb;a_prepared jsonb;t_prepared jsonb;\n a_frame uuid:=gen_random_uuid();t_frame uuid:=gen_random_uuid();leader uuid;compound boolean;\n a_frame_payload jsonb;t_frame_payload jsonb;a_scope jsonb;t_scope jsonb;a_retained jsonb;t_retained jsonb;\n a_tier text;t_tier text;a_teams text[];t_teams text[];a_projects uuid[];t_projects uuid[];\n next_sequence integer;results jsonb;annotation_result jsonb;registration jsonb;original_command jsonb:=jsonb_build_object(''payloads'',payloads,''producer'',producer,''sources'',sources,''target'',target);\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF operation IS NOT NULL THEN\n  registration:=native_conversation_publication_enter(w,s,operation,original_command);\n  IF registration->>''duplicate''=''true'' THEN RETURN registration->''value'';END IF;\n END IF;\n IF envelope THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  annotation_command:=payloads->''annotation'';payloads:=payloads->''messages'';\n  IF annotation_command-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT annotation_command ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  IF annotation_command ? ''kind'' THEN a_kind:=annotation_command->>''kind'';END IF;\n  IF a_kind IS NULL OR a_kind NOT IN(''message_annotation'',''session_title'')\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  a_parent:=(annotation_command->>''parentId'')::uuid;a_id:=(annotation_command->>''id'')::uuid;\n  a_payload:=annotation_command->''content'';a_producer:=annotation_command->>''producer'';a_sources:=annotation_command->''sources'';\n  a_revision:=(annotation_command->>''expectedRevision'')::uuid;a_generation:=(annotation_command->>''expectedGeneration'')::bigint;\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND annotation_command IS NULL\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF annotation_command IS NOT NULL THEN\n IF a_parent IS NULL OR a_id IS NULL OR session_context_payload_shape(a_kind,a_payload) IS NOT TRUE\n  OR length(btrim(a_producer)) NOT BETWEEN 1 AND 256\n  OR jsonb_typeof(a_sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(a_sources) NOT BETWEEN 1 AND 4096\n  OR (SELECT count(DISTINCT(n->>''resourceKind'',n->>''resourceId'')) FROM jsonb_array_elements(a_sources) n)<>jsonb_array_length(a_sources)\n  OR a_kind=''session_title'' AND jsonb_array_length(payloads)<>0\n  OR a_kind=''message_annotation'' AND (NOT EXISTS(SELECT 1 FROM session_messages WHERE workspace_id=w AND session_id=s AND id=a_parent)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a_sources) n WHERE n->>''resourceKind''=''session_message'' AND n->>''resourceId''=a_parent::text))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO STRICT session_row FROM sessions WHERE workspace_id=w AND id=s;\n IF a_kind=''session_title'' THEN\n  IF a_parent<>s OR (a_payload->>''manual'')::boolean IS FALSE AND session_row.title_manually_set THEN\n   RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n  SELECT scope_revision_id INTO previous FROM session_title_heads WHERE workspace_id=w AND session_id=s;\n ELSE\n  SELECT scope_revision_id INTO previous FROM session_message_annotation_heads WHERE workspace_id=w AND session_id=s AND message_id=a_parent;\n END IF;\n IF a_generation IS NOT NULL AND session_row.session_context_generation<>a_generation OR previous IS DISTINCT FROM a_revision\n THEN RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO a_sources FROM jsonb_array_elements(a_sources) WITH ORDINALITY original(n,ordinal);\n\n  a_target:=jsonb_build_object(''workspaceId'',w,''userId'',parent->''userId'',''assistantId'',NULL,''sensitivity'',parent->''sensitivity'',''compartments'',parent->''compartments'',''projectIds'',parent->''projectIds'');\n  commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',a_producer,''sources'',a_sources,''target'',a_target)\n   ||CASE WHEN a_kind=''session_title'' THEN jsonb_build_object(''purpose'',a_kind) ELSE ''{}''::jsonb END);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n IF jsonb_typeof(payload) IS DISTINCT FROM ''object'' OR NOT payload ?& ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']\n  OR payload-ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']<>''{}''\n  OR payload->>''role'' NOT IN(''user'',''assistant'') OR jsonb_typeof(payload->''role'') IS DISTINCT FROM ''string''\n  OR jsonb_typeof(payload->''attachments'') IS DISTINCT FROM ''array'' OR jsonb_array_length(payload->''attachments'')>100\n  OR jsonb_typeof(payload->''channelMessageId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(payload->''senderUserId'') NOT IN(''null'',''string'') OR jsonb_typeof(payload->''senderAssistantId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096\n  OR length(btrim(producer)) NOT BETWEEN 1 AND 256\n  OR entity_derivation_envelope_valid(target) IS NOT TRUE OR target->>''workspaceId'' IS DISTINCT FROM w::text\n  OR target->>''assistantId'' IS NOT NULL OR target->>''userId'' IS NOT NULL AND target->>''userId'' IS DISTINCT FROM actor::text\n  OR parent->>''userId'' IS NOT NULL AND parent->>''userId'' IS DISTINCT FROM target->>''userId''\n  OR payload->>''senderUserId'' IS NOT NULL AND payload->>''senderUserId'' IS DISTINCT FROM actor::text\n  OR payload->>''senderAssistantId'' IS NOT NULL AND (payload->>''role''<>''assistant''\n   OR payload->>''senderAssistantId'' IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')) THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF jsonb_array_length(payloads)>0 THEN\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO sources FROM jsonb_array_elements(sources) WITH ORDINALITY original(n,ordinal);\n commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',producer,''sources'',sources,''target'',target));\n END IF;\n prepared:=conversation_prepare_publications(w,s,commands);\n IF prepared IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF annotation_command IS NOT NULL THEN\n  a_prepared:=prepared->0;a_scope:=a_prepared->''scope'';a_retained:=a_prepared->''retained'';a_tier:=a_scope->>''sensitivity'';\n  a_teams:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''compartments''));a_projects:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''projectIds'')::uuid);\n  a_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',a_sources,''declaredSources'',a_retained);\n END IF;\n IF jsonb_array_length(payloads)>0 THEN\n  t_prepared:=prepared->(jsonb_array_length(prepared)-1);t_scope:=t_prepared->''scope'';t_retained:=t_prepared->''retained'';t_tier:=t_scope->>''sensitivity'';\n  t_teams:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''compartments''));t_projects:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''projectIds'')::uuid);\n  t_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',sources,''declaredSources'',t_retained);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n FOR node IN SELECT value FROM jsonb_array_elements(payload->''attachments'') LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object'' OR node->>''workspaceId'' IS DISTINCT FROM w::text\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t_retained) input WHERE input->>''resourceKind''=''workspace_file'' AND input->>''resourceId''=node->>''fileId'') THEN\n   RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n END LOOP;\n\n compound:=annotation_command IS NOT NULL AND jsonb_array_length(payloads)>0;\n leader:=CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame ELSE a_frame END;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation DEFERRED;END IF;\n INSERT INTO native_turn_publication_work(transaction_id,workspace_id,frame_id,session_id,context,original_sources,prepared,completion_owner,publication_id)\n SELECT txid_current(),w,a_frame,s,native_turn_context(),a_sources,a_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE annotation_command IS NOT NULL\n UNION ALL SELECT txid_current(),w,t_frame,s,native_turn_context(),sources,t_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE jsonb_array_length(payloads)>0;\n INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;\n SELECT coalesce(max(sequence_num),0) INTO next_sequence FROM session_messages WHERE session_id=s;\n WITH a_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_frame,w,s,''turn_frame'',a_frame,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') WHERE annotation_command IS NOT NULL RETURNING id\n ), a_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT id_workspace,id_frame,s,2,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') FROM (SELECT w id_workspace,id id_frame FROM a_frame_revision) ready RETURNING id\n ), a_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,a_frame_payload FROM a_frame_record RETURNING revision_id\n ), a_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_frame,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_frame_contents) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM a_frame_declaration d CROSS JOIN jsonb_array_elements(a_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), a_annotation AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_id,w,s,a_kind,a_parent,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')\n  FROM(SELECT count(*) FROM a_frame_edges) ready WHERE annotation_command IS NOT NULL RETURNING id,created_at\n ), a_annotation_content AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content) SELECT w,id,a_payload FROM a_annotation RETURNING revision_id\n ), a_head AS (\n  INSERT INTO session_message_annotation_heads(message_id,workspace_id,session_id,scope_revision_id)\n  SELECT a_parent,w,s,revision_id FROM a_annotation_content WHERE a_kind=''message_annotation'' ON CONFLICT(message_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING message_id\n ), a_title_head AS (\n  INSERT INTO session_title_heads(workspace_id,session_id,scope_revision_id)\n  SELECT w,s,revision_id FROM a_annotation_content WHERE a_kind=''session_title''\n  ON CONFLICT(session_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING session_id\n ), a_generation AS (\n  UPDATE sessions SET session_context_generation=session_context_generation+1,\n   title=CASE WHEN a_kind=''session_title'' THEN NULL ELSE title END,\n   title_manually_set=CASE WHEN a_kind=''session_title'' THEN (a_payload->>''manual'')::boolean ELSE title_manually_set END\n  FROM(SELECT count(*) FROM a_head) ready CROSS JOIN(SELECT count(*) FROM a_title_head) title_ready\n  WHERE workspace_id=w AND id=s AND annotation_command IS NOT NULL RETURNING id\n ), a_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_id,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_generation) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_annotation_edge AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',a_frame,''1'' FROM a_declaration RETURNING derivation_id\n ), t_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT t_frame,w,s,''turn_frame'',t_frame,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') WHERE jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT w,id,s,2,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') FROM t_frame_revision RETURNING id\n ), t_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,t_frame_payload FROM t_frame_record RETURNING revision_id\n ), t_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',t_frame,''1'',producer,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM t_frame_contents) ready WHERE workspace_id=w AND jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM t_frame_declaration d CROSS JOIN jsonb_array_elements(t_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), t_written AS (\n  INSERT INTO session_messages(session_id,role,content,sequence_num,channel_message_id,sender_user_id,sender_assistant_id,attachments,\n   workspace_id,user_id,assistant_id,sensitivity,compartments,project_ids,scope_version,scope_held)\n  SELECT s,n.value->>''role'',n.value->''content'',next_sequence+n.ordinality,n.value->>''channelMessageId'',\n   (n.value->>''senderUserId'')::uuid,(n.value->>''senderAssistantId'')::uuid,n.value->''attachments'',w,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,1,false\n  FROM jsonb_array_elements(payloads) WITH ORDINALITY n(value,ordinality) CROSS JOIN(SELECT count(*) FROM t_frame_edges) ready\n  ORDER BY n.ordinality RETURNING *\n ), t_declarations AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_message'',m.id,''1'',producer,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,p.revision\n  FROM t_written m CROSS JOIN workspace_access_policies p WHERE p.workspace_id=w RETURNING id,resource_id\n ), t_message_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',t_frame,''1'' FROM t_declarations RETURNING derivation_id\n ), output_rows AS (\n  SELECT a_frame frame_id,jsonb_build_object(''kind'',a_kind,''id'',a_id,''parentId'',a_parent,''derivationId'',d.id,\n   ''payloadDigest'',encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')) value\n  FROM a_declaration d CROSS JOIN(SELECT count(*) FROM a_annotation_edge) ready\n  UNION ALL SELECT t_frame,jsonb_build_object(''id'',m.id,''derivationId'',d.id,''sequence'',m.sequence_num,\n   ''payloadDigest'',encode(sha256(convert_to(jsonb_build_object(''role'',m.role,''content'',m.content,''channelMessageId'',m.channel_message_id,\n    ''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments)::text,''UTF8'')),''hex''))\n  FROM t_written m JOIN t_declarations d ON d.resource_id=m.id CROSS JOIN(SELECT count(*) FROM t_message_edges) ready\n ), seal AS (\n  INSERT INTO native_turn_publication_seals(transaction_id,frame_id,outputs)\n  SELECT txid_current(),leader,jsonb_agg(value||CASE WHEN compound THEN jsonb_build_object(''frameId'',frame_id) ELSE ''{}''::jsonb END ORDER BY frame_id,value::text) FROM output_rows\n  RETURNING native_turn_publication_seals.transaction_id,native_turn_publication_seals.frame_id\n ), debt AS (\n  INSERT INTO native_turn_publication_debt SELECT seal.transaction_id,o.frame_id FROM seal CROSS JOIN(SELECT DISTINCT frame_id FROM output_rows) o\n  RETURNING native_turn_publication_debt.frame_id\n ), registration AS (\n  INSERT INTO native_conversation_publications(id,workspace_id,session_id,input_message_id,actor_user_id,assistant_id,turn_token,slot,\n   command_format,command_digest,stopped,frame_ids,leader_frame_id,expected_output_count,annotation_user_id,annotation_assistant_id,requested_stopped,terminal_descriptor,terminal_outputs)\n  SELECT (operation->>''operationId'')::uuid,w,s,(operation->>''inputMessageId'')::uuid,(operation->>''actorUserId'')::uuid,(operation->>''assistantId'')::uuid,\n   (operation->>''turnToken'')::uuid,''buffered_transcript'',(operation->>''version'')::integer,registration->>''digest'',(registration->>''effectiveStopped'')::boolean,\n   ARRAY(SELECT frame FROM unnest(ARRAY[CASE WHEN annotation_command IS NOT NULL THEN a_frame END,CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame END]) frame WHERE frame IS NOT NULL ORDER BY frame),\n   leader,jsonb_array_length(payloads)+CASE WHEN annotation_command IS NOT NULL THEN 1 ELSE 0 END,session_row.user_id,session_row.assistant_id,\n   CASE WHEN operation->''version''=''2''::jsonb THEN (operation->>''stopped'')::boolean END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' THEN nullif(operation->''terminalCandidate'',''null''::jsonb) END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' AND nullif(operation->''terminalCandidate'',''null''::jsonb) IS NOT NULL THEN\n    (SELECT jsonb_agg(jsonb_build_object(''origin'',m.n->''origin'',''revision'',m.n->''revision'',''commandOrdinal'',m.n->''commandOrdinal'',\n      ''kind'',''session_message'',''version'',''1'',''id'',written.id,''frameId'',t_frame,''derivationId'',d.id,''sequence'',written.sequence_num,\n      ''payloadDigest'',o.value->''payloadDigest'') ORDER BY m.ordinal)\n     FROM jsonb_array_elements(operation#>''{terminalCandidate,members}'') WITH ORDINALITY m(n,ordinal)\n     JOIN t_written written ON written.sequence_num=next_sequence+(m.n->>''commandOrdinal'')::integer+1\n     JOIN t_declarations d ON d.resource_id=written.id JOIN output_rows o ON o.frame_id=t_frame AND o.value->>''id''=written.id::text) END\n  FROM seal CROSS JOIN(SELECT count(*) FROM debt) ready WHERE operation IS NOT NULL RETURNING id\n ) SELECT\n  (SELECT coalesce(jsonb_agg(jsonb_build_object(''message'',jsonb_build_object(''id'',m.id,''sessionId'',s,''role'',m.role,''content'',m.content,\n   ''sequenceNum'',m.sequence_num,''createdAt'',m.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n   ''channelMessageId'',m.channel_message_id,''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments),\n   ''source'',t_scope||jsonb_build_object(''resourceKind'',''session_message'',''resourceId'',m.id,''version'',''1'')) ORDER BY m.sequence_num),''[]'') FROM t_written m),\n  (SELECT jsonb_build_object(''source'',a_scope||jsonb_build_object(''resourceKind'',''session_context_revision'',''resourceId'',a_id,''version'',''1''),\n   ''createdAt'',a.created_at,''userId'',session_row.user_id,''assistantId'',session_row.assistant_id) FROM a_annotation a)\n INTO results,annotation_result FROM(SELECT count(*) FROM debt) ready CROSS JOIN(SELECT count(*) FROM registration) registered;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation IMMEDIATE;END IF;\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN CASE WHEN operation->''version''=''2''::jsonb THEN native_conversation_publication_packet((operation->>''operationId'')::uuid,CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END) ELSE CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END END;\nEXCEPTION WHEN SQLSTATE ''PNT02'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';\nEND "},"bodyParts":["\nDECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;parent jsonb;payload jsonb;node jsonb;\n envelope boolean:=jsonb_typeof(payloads)=''object'';annotation_command jsonb;session_row sessions;previous uuid;\n a_kind text:=''message_annotation'';a_parent uuid;a_id uuid;a_payload jsonb;a_producer text;a_sources jsonb;a_revision uuid;a_generation bigint;a_target jsonb;\n commands jsonb:=''[]'';prepared jsonb;a_prepared jsonb;t_prepared jsonb;\n a_frame uuid:=gen_random_uuid();t_frame uuid:=gen_random_uuid();leader uuid;compound boolean;\n a_frame_payload jsonb;t_frame_payload jsonb;a_scope jsonb;t_scope jsonb;a_retained jsonb;t_retained jsonb;\n a_tier text;t_tier text;a_teams text[];t_teams text[];a_projects uuid[];t_projects uuid[];\n next_sequence integer;results jsonb;annotation_result jsonb;registration jsonb;original_command jsonb:=jsonb_build_object(''payloads'',payloads,''producer'',producer,''sources'',sources,''target'',target);\nBEGIN\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF operation IS NOT NULL THEN\n  registration:=native_conversation_publication_enter(w,s,operation,original_command);\n  IF registration->>''duplicate''=''true'' THEN RETURN registration->''value'';END IF;\n END IF;\n IF envelope THEN\n  IF payloads-ARRAY[''messages'',''annotation'']<>''{}'' OR NOT payloads ?& ARRAY[''messages'',''annotation'']\n   OR jsonb_typeof(payloads->''annotation'') IS DISTINCT FROM ''object''\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  annotation_command:=payloads->''annotation'';payloads:=payloads->''messages'';\n  IF annotation_command-ARRAY[''kind'',''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']<>''{}''\n   OR NOT annotation_command ?& ARRAY[''parentId'',''id'',''content'',''producer'',''sources'',''expectedRevision'',''expectedGeneration'']\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  IF annotation_command ? ''kind'' THEN a_kind:=annotation_command->>''kind'';END IF;\n  IF a_kind IS NULL OR a_kind NOT IN(''message_annotation'',''session_title'')\n  THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n  a_parent:=(annotation_command->>''parentId'')::uuid;a_id:=(annotation_command->>''id'')::uuid;\n  a_payload:=annotation_command->''content'';a_producer:=annotation_command->>''producer'';a_sources:=annotation_command->''sources'';\n  a_revision:=(annotation_command->>''expectedRevision'')::uuid;a_generation:=(annotation_command->>''expectedGeneration'')::bigint;\n END IF;\n IF jsonb_typeof(payloads) IS DISTINCT FROM ''array'' OR jsonb_array_length(payloads)>512\n  OR jsonb_array_length(payloads)=0 AND annotation_command IS NULL\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n parent:=lock_native_session_context_publication(w,s);\n IF annotation_command IS NOT NULL THEN\n IF a_parent IS NULL OR a_id IS NULL OR session_context_payload_shape(a_kind,a_payload) IS NOT TRUE\n  OR length(btrim(a_producer)) NOT BETWEEN 1 AND 256\n  OR jsonb_typeof(a_sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(a_sources) NOT BETWEEN 1 AND 4096\n  OR (SELECT count(DISTINCT(n->>''resourceKind'',n->>''resourceId'')) FROM jsonb_array_elements(a_sources) n)<>jsonb_array_length(a_sources)\n  OR a_kind=''session_title'' AND jsonb_array_length(payloads)<>0\n  OR a_kind=''message_annotation'' AND (NOT EXISTS(SELECT 1 FROM session_messages WHERE workspace_id=w AND session_id=s AND id=a_parent)\n  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(a_sources) n WHERE n->>''resourceKind''=''session_message'' AND n->>''resourceId''=a_parent::text))\n THEN RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO STRICT session_row FROM sessions WHERE workspace_id=w AND id=s;\n IF a_kind=''session_title'' THEN\n  IF a_parent<>s OR (a_payload->>''manual'')::boolean IS FALSE AND session_row.title_manually_set THEN\n   RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n  SELECT scope_revision_id INTO previous FROM session_title_heads WHERE workspace_id=w AND session_id=s;\n ELSE\n  SELECT scope_revision_id INTO previous FROM session_message_annotation_heads WHERE workspace_id=w AND session_id=s AND message_id=a_parent;\n END IF;\n IF a_generation IS NOT NULL AND session_row.session_context_generation<>a_generation OR previous IS DISTINCT FROM a_revision\n THEN RETURN jsonb_build_object(''messages'',''[]''::jsonb,''annotation'',NULL);END IF;\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO a_sources FROM jsonb_array_elements(a_sources) WITH ORDINALITY original(n,ordinal);\n\n  a_target:=jsonb_build_object(''workspaceId'',w,''userId'',parent->''userId'',''assistantId'',NULL,''sensitivity'',parent->''sensitivity'',''compartments'',parent->''compartments'',''projectIds'',parent->''projectIds'');\n  commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',a_producer,''sources'',a_sources,''target'',a_target)\n   ||CASE WHEN a_kind=''session_title'' THEN jsonb_build_object(''purpose'',a_kind) ELSE ''{}''::jsonb END);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n IF jsonb_typeof(payload) IS DISTINCT FROM ''object'' OR NOT payload ?& ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']\n  OR payload-ARRAY[''role'',''content'',''channelMessageId'',''senderUserId'',''senderAssistantId'',''attachments'']<>''{}''\n  OR payload->>''role'' NOT IN(''user'',''assistant'') OR jsonb_typeof(payload->''role'') IS DISTINCT FROM ''string''\n  OR jsonb_typeof(payload->''attachments'') IS DISTINCT FROM ''array'' OR jsonb_array_length(payload->''attachments'')>100\n  OR jsonb_typeof(payload->''channelMessageId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(payload->''senderUserId'') NOT IN(''null'',''string'') OR jsonb_typeof(payload->''senderAssistantId'') NOT IN(''null'',''string'')\n  OR jsonb_typeof(sources) IS DISTINCT FROM ''array'' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 4096\n  OR length(btrim(producer)) NOT BETWEEN 1 AND 256\n  OR entity_derivation_envelope_valid(target) IS NOT TRUE OR target->>''workspaceId'' IS DISTINCT FROM w::text\n  OR target->>''assistantId'' IS NOT NULL OR target->>''userId'' IS NOT NULL AND target->>''userId'' IS DISTINCT FROM actor::text\n  OR parent->>''userId'' IS NOT NULL AND parent->>''userId'' IS DISTINCT FROM target->>''userId''\n  OR payload->>''senderUserId'' IS NOT NULL AND payload->>''senderUserId'' IS DISTINCT FROM actor::text\n  OR payload->>''senderAssistantId'' IS NOT NULL AND (payload->>''role''<>''assistant''\n   OR payload->>''senderAssistantId'' IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')) THEN\n  RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n IF jsonb_array_length(payloads)>0 THEN\n SELECT jsonb_agg(jsonb_build_object(''workspaceId'',n->''workspaceId'',''userId'',n->''userId'',''assistantId'',n->''assistantId'',\n  ''sensitivity'',n->''sensitivity'',''compartments'',n->''compartments'',''projectIds'',n->''projectIds'',\n  ''resourceKind'',n->''resourceKind'',''resourceId'',n->''resourceId'',''version'',n->''version'') ORDER BY ordinal)\n INTO sources FROM jsonb_array_elements(sources) WITH ORDINALITY original(n,ordinal);\n commands:=commands||jsonb_build_array(jsonb_build_object(''producer'',producer,''sources'',sources,''target'',target));\n END IF;\n prepared:=conversation_prepare_publications(w,s,commands);\n IF prepared IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n IF annotation_command IS NOT NULL THEN\n  a_prepared:=prepared->0;a_scope:=a_prepared->''scope'';a_retained:=a_prepared->''retained'';a_tier:=a_scope->>''sensitivity'';\n  a_teams:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''compartments''));a_projects:=ARRAY(SELECT jsonb_array_elements_text(a_scope->''projectIds'')::uuid);\n  a_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',a_sources,''declaredSources'',a_retained);\n END IF;\n IF jsonb_array_length(payloads)>0 THEN\n  t_prepared:=prepared->(jsonb_array_length(prepared)-1);t_scope:=t_prepared->''scope'';t_retained:=t_prepared->''retained'';t_tier:=t_scope->>''sensitivity'';\n  t_teams:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''compartments''));t_projects:=ARRAY(SELECT jsonb_array_elements_text(t_scope->''projectIds'')::uuid);\n  t_frame_payload:=jsonb_build_object(''kind'',''native_turn_frame_v2'',''originalSources'',sources,''declaredSources'',t_retained);\n END IF;\n FOR payload IN SELECT value FROM jsonb_array_elements(payloads) LOOP\n FOR node IN SELECT value FROM jsonb_array_elements(payload->''attachments'') LOOP\n  IF jsonb_typeof(node) IS DISTINCT FROM ''object'' OR node->>''workspaceId'' IS DISTINCT FROM w::text\n   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(t_retained) input WHERE input->>''resourceKind''=''workspace_file'' AND input->>''resourceId''=node->>''fileId'') THEN\n   RAISE EXCEPTION ''scope_evidence_missing'' USING ERRCODE=''22023'';END IF;\n END LOOP;\n END LOOP;\n\n compound:=annotation_command IS NOT NULL AND jsonb_array_length(payloads)>0;\n leader:=CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame ELSE a_frame END;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation DEFERRED;END IF;\n INSERT INTO native_turn_publication_work(transaction_id,workspace_id,frame_id,session_id,context,original_sources,prepared,completion_owner,publication_id)\n SELECT txid_current(),w,a_frame,s,native_turn_context(),a_sources,a_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE annotation_command IS NOT NULL\n UNION ALL SELECT txid_current(),w,t_frame,s,native_turn_context(),sources,t_prepared-''proof'',CASE WHEN compound THEN leader END,(operation->>''operationId'')::uuid WHERE jsonb_array_length(payloads)>0;\n INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;\n SELECT coalesce(max(sequence_num),0) INTO next_sequence FROM session_messages WHERE session_id=s;\n WITH a_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_frame,w,s,''turn_frame'',a_frame,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') WHERE annotation_command IS NOT NULL RETURNING id\n ), a_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT id_workspace,id_frame,s,2,encode(sha256(convert_to(a_frame_payload::text,''UTF8'')),''hex'') FROM (SELECT w id_workspace,id id_frame FROM a_frame_revision) ready RETURNING id\n ), a_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,a_frame_payload FROM a_frame_record RETURNING revision_id\n ), a_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_frame,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_frame_contents) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM a_frame_declaration d CROSS JOIN jsonb_array_elements(a_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), a_annotation AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT a_id,w,s,a_kind,a_parent,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')\n  FROM(SELECT count(*) FROM a_frame_edges) ready WHERE annotation_command IS NOT NULL RETURNING id,created_at\n ), a_annotation_content AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content) SELECT w,id,a_payload FROM a_annotation RETURNING revision_id\n ), a_head AS (\n  INSERT INTO session_message_annotation_heads(message_id,workspace_id,session_id,scope_revision_id)\n  SELECT a_parent,w,s,revision_id FROM a_annotation_content WHERE a_kind=''message_annotation'' ON CONFLICT(message_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING message_id\n ), a_title_head AS (\n  INSERT INTO session_title_heads(workspace_id,session_id,scope_revision_id)\n  SELECT w,s,revision_id FROM a_annotation_content WHERE a_kind=''session_title''\n  ON CONFLICT(session_id) DO UPDATE SET scope_revision_id=EXCLUDED.scope_revision_id RETURNING session_id\n ), a_generation AS (\n  UPDATE sessions SET session_context_generation=session_context_generation+1,\n   title=CASE WHEN a_kind=''session_title'' THEN NULL ELSE title END,\n   title_manually_set=CASE WHEN a_kind=''session_title'' THEN (a_payload->>''manual'')::boolean ELSE title_manually_set END\n  FROM(SELECT count(*) FROM a_head) ready CROSS JOIN(SELECT count(*) FROM a_title_head) title_ready\n  WHERE workspace_id=w AND id=s AND annotation_command IS NOT NULL RETURNING id\n ), a_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',a_id,''1'',a_producer,(a_scope->>''userId'')::uuid,NULL,a_tier,a_teams,a_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM a_generation) ready WHERE workspace_id=w AND annotation_command IS NOT NULL RETURNING id\n ), a_annotation_edge AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',a_frame,''1'' FROM a_declaration RETURNING derivation_id\n ), t_frame_revision AS (\n  INSERT INTO session_context_scope_revisions(id,workspace_id,session_id,parent_kind,parent_id,user_id,assistant_id,sensitivity,compartments,project_ids,payload_sha256)\n  SELECT t_frame,w,s,''turn_frame'',t_frame,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') WHERE jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_record AS (\n  INSERT INTO native_turn_frames(workspace_id,id,session_id,format,manifest_digest)\n  SELECT w,id,s,2,encode(sha256(convert_to(t_frame_payload::text,''UTF8'')),''hex'') FROM t_frame_revision RETURNING id\n ), t_frame_contents AS (\n  INSERT INTO session_context_revision_contents(workspace_id,revision_id,content)\n  SELECT w,id,t_frame_payload FROM t_frame_record RETURNING revision_id\n ), t_frame_declaration AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_context_revision'',t_frame,''1'',producer,(t_scope->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,revision\n  FROM workspace_access_policies CROSS JOIN(SELECT count(*) FROM t_frame_contents) ready WHERE workspace_id=w AND jsonb_array_length(payloads)>0 RETURNING id\n ), t_frame_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,d.id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'' FROM t_frame_declaration d CROSS JOIN jsonb_array_elements(t_retained) n\n  ORDER BY n->>''resourceKind'',n->>''resourceId'' RETURNING derivation_id\n ), t_written AS (\n  INSERT INTO session_messages(session_id,role,content,sequence_num,channel_message_id,sender_user_id,sender_assistant_id,attachments,\n   workspace_id,user_id,assistant_id,sensitivity,compartments,project_ids,scope_version,scope_held)\n  SELECT s,n.value->>''role'',n.value->''content'',next_sequence+n.ordinality,n.value->>''channelMessageId'',\n   (n.value->>''senderUserId'')::uuid,(n.value->>''senderAssistantId'')::uuid,n.value->''attachments'',w,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,1,false\n  FROM jsonb_array_elements(payloads) WITH ORDINALITY n(value,ordinality) CROSS JOIN(SELECT count(*) FROM t_frame_edges) ready\n  ORDER BY n.ordinality RETURNING *\n ), t_declarations AS (\n  INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)\n  SELECT w,''session_message'',m.id,''1'',producer,(target->>''userId'')::uuid,NULL,t_tier,t_teams,t_projects,p.revision\n  FROM t_written m CROSS JOIN workspace_access_policies p WHERE p.workspace_id=w RETURNING id,resource_id\n ), t_message_edges AS (\n  INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)\n  SELECT w,id,''session_context_revision'',t_frame,''1'' FROM t_declarations RETURNING derivation_id\n ), output_rows AS (\n  SELECT a_frame frame_id,jsonb_build_object(''kind'',a_kind,''id'',a_id,''parentId'',a_parent,''derivationId'',d.id,\n   ''payloadDigest'',encode(sha256(convert_to(a_payload::text,''UTF8'')),''hex'')) value\n  FROM a_declaration d CROSS JOIN(SELECT count(*) FROM a_annotation_edge) ready\n  UNION ALL SELECT t_frame,jsonb_build_object(''id'',m.id,''derivationId'',d.id,''sequence'',m.sequence_num,\n   ''payloadDigest'',encode(sha256(convert_to(jsonb_build_object(''role'',m.role,''content'',m.content,''channelMessageId'',m.channel_message_id,\n    ''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments)::text,''UTF8'')),''hex''))\n  FROM t_written m JOIN t_declarations d ON d.resource_id=m.id CROSS JOIN(SELECT count(*) FROM t_message_edges) ready\n ), seal AS (\n  INSERT INTO native_turn_publication_seals(transaction_id,frame_id,outputs)\n  SELECT txid_current(),leader,jsonb_agg(value||CASE WHEN compound THEN jsonb_build_object(''frameId'',frame_id) ELSE ''{}''::jsonb END ORDER BY frame_id,value::text) FROM output_rows\n  RETURNING native_turn_publication_seals.transaction_id,native_turn_publication_seals.frame_id\n ), debt AS (\n  INSERT INTO native_turn_publication_debt SELECT seal.transaction_id,o.frame_id FROM seal CROSS JOIN(SELECT DISTINCT frame_id FROM output_rows) o\n  RETURNING native_turn_publication_debt.frame_id\n ), registration AS (\n  INSERT INTO native_conversation_publications(id,workspace_id,session_id,input_message_id,actor_user_id,assistant_id,turn_token,slot,\n   command_format,command_digest,stopped,frame_ids,leader_frame_id,expected_output_count,annotation_user_id,annotation_assistant_id,requested_stopped,terminal_descriptor,terminal_outputs)\n  SELECT (operation->>''operationId'')::uuid,w,s,(operation->>''inputMessageId'')::uuid,(operation->>''actorUserId'')::uuid,(operation->>''assistantId'')::uuid,\n   (operation->>''turnToken'')::uuid,''buffered_transcript'',(operation->>''version'')::integer,registration->>''digest'',(registration->>''effectiveStopped'')::boolean,\n   ARRAY(SELECT frame FROM unnest(ARRAY[CASE WHEN annotation_command IS NOT NULL THEN a_frame END,CASE WHEN jsonb_array_length(payloads)>0 THEN t_frame END]) frame WHERE frame IS NOT NULL ORDER BY frame),\n   leader,jsonb_array_length(payloads)+CASE WHEN annotation_command IS NOT NULL THEN 1 ELSE 0 END,session_row.user_id,session_row.assistant_id,\n   CASE WHEN operation->''version''=''2''::jsonb THEN (operation->>''stopped'')::boolean END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' THEN nullif(operation->''terminalCandidate'',''null''::jsonb) END,\n   CASE WHEN operation->''version''=''2''::jsonb AND registration->>''effectiveStopped''=''false'' AND nullif(operation->''terminalCandidate'',''null''::jsonb) IS NOT NULL THEN\n    (SELECT jsonb_agg(jsonb_build_object(''origin'',m.n->''origin'',''revision'',m.n->''revision'',''commandOrdinal'',m.n->''commandOrdinal'',\n      ''kind'',''session_message'',''version'',''1'',''id'',written.id,''frameId'',t_frame,''derivationId'',d.id,''sequence'',written.sequence_num,\n      ''payloadDigest'',o.value->''payloadDigest'') ORDER BY m.ordinal)\n     FROM jsonb_array_elements(operation#>''{terminalCandidate,members}'') WITH ORDINALITY m(n,ordinal)\n     JOIN t_written written ON written.sequence_num=next_sequence+(m.n->>''commandOrdinal'')::integer+1\n     JOIN t_declarations d ON d.resource_id=written.id JOIN output_rows o ON o.frame_id=t_frame AND o.value->>''id''=written.id::text) END\n  FROM seal CROSS JOIN(SELECT count(*) FROM debt) ready WHERE operation IS NOT NULL RETURNING id\n ) SELECT\n  (SELECT coalesce(jsonb_agg(jsonb_build_object(''message'',jsonb_build_object(''id'',m.id,''sessionId'',s,''role'',m.role,''content'',m.content,\n   ''sequenceNum'',m.sequence_num,''createdAt'',m.created_at,''replyToText'',NULL,''topicLabel'',NULL,''topicConfidence'',NULL,\n   ''channelMessageId'',m.channel_message_id,''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,''attachments'',m.attachments),\n   ''source'',t_scope||jsonb_build_object(''resourceKind'',''session_message'',''resourceId'',m.id,''version'',''1'')) ORDER BY m.sequence_num),''[]'') FROM t_written m),\n  (SELECT jsonb_build_object(''source'',a_scope||jsonb_build_object(''resourceKind'',''session_context_revision'',''resourceId'',a_id,''version'',''1''),\n   ''createdAt'',a.created_at,''userId'',session_row.user_id,''assistantId'',session_row.assistant_id) FROM a_annotation a)\n INTO results,annotation_result FROM(SELECT count(*) FROM debt) ready CROSS JOIN(SELECT count(*) FROM registration) registered;\n IF operation IS NOT NULL THEN SET CONSTRAINTS native_turn_publication_operation IMMEDIATE;END IF;\n IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;\n RETURN CASE WHEN operation->''version''=''2''::jsonb THEN native_conversation_publication_packet((operation->>''operationId'')::uuid,CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END) ELSE CASE WHEN envelope THEN jsonb_build_object(''messages'',results,''annotation'',annotation_result) ELSE results END END;\nEXCEPTION WHEN SQLSTATE ''PNT02'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';\nEND "],"acl":[{"grantee":"OWNER","grantor":"OWNER","privilege":"EXECUTE","grantable":false},{"grantee":"app_user","grantor":"OWNER","privilege":"EXECUTE","grantable":false}]}]'::jsonb) LOOP
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.'||(expected->>'signature'));
  IF actual.oid IS NULL OR actual.proowner<>owner_id THEN RAISE EXCEPTION 'conversion_predecessor_missing: %',expected->>'signature';END IF;
  body:=pg_temp.a8314_conversion_predecessor_body(expected->>'signature',expected->'bodyParts');
  IF expected->>'signature' IN('application_memory_historical_query_scan(uuid,text[],jsonb,boolean,jsonb)','application_memory_statement_scan(uuid,text[],jsonb,boolean,jsonb,jsonb)') THEN
   IF (length(body)-length(replace(body,'AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text AND c->>''version''=memories.scope_version::text)) ORDER BY id LOOP','')))/length('AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text AND c->>''version''=memories.scope_version::text)) ORDER BY id LOOP')<>1 THEN RAISE EXCEPTION 'memory_query_write_scan_source_changed';END IF;
   body:=replace(body,'AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text AND c->>''version''=memories.scope_version::text)) ORDER BY id LOOP','AND (valid_to IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text AND c->>''version''=memories.scope_version::text))
  AND (EXISTS(SELECT 1 FROM jsonb_array_elements(frozen->''candidates'') c WHERE c->>''id''=memories.id::text)
   OR NOT EXISTS(SELECT 1 FROM scope_derivations d
    JOIN LATERAL(SELECT s.source_id FROM scope_derivation_sources s
      WHERE s.workspace_id=d.workspace_id AND s.derivation_id=d.id AND s.source_kind=''application_field''
     UNION SELECT pending.field_id FROM native_memory_query_write_intents pending
      WHERE pending.workspace_id=d.workspace_id AND pending.derivation_id=d.id
       AND pending.transaction_id=pg_current_xact_id_if_assigned()) input ON true
    JOIN application_field_resources f ON f.workspace_id=d.workspace_id AND f.id=input.source_id
    WHERE d.workspace_id=w AND d.resource_kind=''memory'' AND d.resource_id=memories.id
     AND f.origin=''{"kind":"native","moduleKey":"native"}''::jsonb AND f.type_key=''memory'' AND f.selection=''query_domain''
     AND f.resource_id=application_field_resource_uuid(application_field_digest(
      jsonb_build_object(''kind'',''memory_query_domain_v1'',''workspaceId'',w,''domain'',frozen))))) ORDER BY id LOOP');
  END IF;
  spec:=expected->'sourceSpec';
  IF spec IS NOT NULL THEN
   SELECT coalesce(string_agg(format('%I %s',n.value,t.value)||CASE WHEN spec->>'signature'='read_native_conversation_publications(uuid,uuid,jsonb,integer)' AND t.ordinal=3 THEN ' DEFAULT NULL::jsonb' WHEN spec->>'signature'='read_native_conversation_publications(uuid,uuid,jsonb,integer)' AND t.ordinal=4 THEN ' DEFAULT 20' ELSE '' END,',' ORDER BY t.ordinal),'') INTO declaration
   FROM jsonb_array_elements_text(spec->'argTypes') WITH ORDINALITY t(value,ordinal) JOIN jsonb_array_elements_text(spec->'argNames') WITH ORDINALITY n(value,ordinal) USING(ordinal);
   EXECUTE format('CREATE FUNCTION pg_temp.a8314_conversion_function_reference(%s) RETURNS %s LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp %s AS %L',declaration,spec->>'returnType',CASE WHEN spec->>'name'='publish_native_session_message_batch' THEN 'SET plan_cache_mode=force_generic_plan' ELSE '' END,body);
   SELECT * INTO STRICT reference FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname='a8314_conversion_function_reference';
   expected_metadata:=to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl','prosrc'];
   expected_metadata:=expected_metadata||jsonb_build_object('proname',spec->>'name','pronamespace','public'::regnamespace::oid,'proowner',owner_id);
   EXECUTE format('DROP FUNCTION pg_temp.a8314_conversion_function_reference(%s)',(SELECT coalesce(string_agg(value,',' ORDER BY ordinal),'') FROM jsonb_array_elements_text(spec->'argTypes') WITH ORDINALITY t(value,ordinal)));
  ELSE expected_metadata:=pg_temp.a8314_publication_json(expected->'metadata');END IF;
  IF expected->>'signature'='native_turn_helpers_current()' THEN expected_metadata:=jsonb_set(expected_metadata,'{prolang}',to_jsonb((SELECT oid FROM pg_language WHERE lanname='plpgsql')));END IF;
  IF ((expected->>'signature') NOT IN('native_turn_frame_pair(uuid,uuid)','native_conversation_frame_requirement_input(uuid,uuid)','native_conversation_compiled_frame_pair(uuid,uuid)','media_parent_visible(text,uuid)','conversation_message_snapshot(uuid,uuid,jsonb)','session_context_parent_snapshot(uuid,uuid)','capture_native_session_projection_batch(uuid,uuid,integer,text)','capture_native_session_query_stage(uuid,uuid,integer,text,jsonb,jsonb)','native_turn_context()','native_worklist_context(uuid,jsonb)','conversation_prepare_publications(uuid,uuid,jsonb)','validate_scope_resource_reference()','native_turn_frame_payload_shape(jsonb)','native_conversation_compiled_frame_pair(uuid,uuid)','native_turn_helpers_current()','native_turn_publication_contract()','native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)','conversation_dag_domain(uuid,text,uuid,text[],jsonb,jsonb,jsonb[])','session_context_revision_allowed(uuid,uuid)','capture_conversation_evidence(uuid,jsonb,jsonb,jsonb)','read_entity_derivation_source_before_capture(uuid,text,uuid)','native_worklist_source_capture(uuid,text,uuid,jsonb)','native_conversation_publication_result(uuid,uuid,uuid)','conversation_dag(uuid,jsonb,jsonb)','native_turn_frame_payload_shape(jsonb)','conversation_capture_privacy(uuid,jsonb)','recording_source_read_allowed(uuid,text,uuid)','scope_source_ancestors_before_browser_profile(uuid,text,uuid)','application_scope_lineage(uuid,text[],uuid[],text[])','read_scope_source_before_knowledge_binding(uuid,text,uuid)') AND (actual.prosrc COLLATE "C") IS DISTINCT FROM (body COLLATE "C"))
   OR (to_jsonb(actual)-ARRAY['oid','prosrc','proacl']) IS DISTINCT FROM expected_metadata
  THEN RAISE EXCEPTION 'conversion_predecessor_changed: %',expected->>'signature';END IF;
  SELECT jsonb_agg(jsonb_build_object('grantee',grantee,'grantor',grantor,'privilege',privilege,'grantable',grantable) ORDER BY grantee COLLATE "C") INTO acl
  FROM(SELECT CASE WHEN a.grantee=owner_id THEN 'OWNER' WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=runtime_id THEN 'app_user' ELSE 'UNREVIEWED_OID:'||a.grantee::text END grantee,
   CASE WHEN a.grantor=owner_id THEN 'OWNER' ELSE 'UNREVIEWED_OID:'||a.grantor::text END grantor,a.privilege_type privilege,a.is_grantable grantable
   FROM aclexplode(coalesce(actual.proacl,acldefault('f',owner_id))) a) grants;
  IF acl IS DISTINCT FROM expected->'acl' THEN RAISE EXCEPTION 'conversion_predecessor_acl_changed: %',expected->>'signature';END IF;
  INSERT INTO pg_temp.a8314_publication_expected_current VALUES(expected->>'signature',to_jsonb(actual)) ON CONFLICT(signature) DO UPDATE SET metadata=EXCLUDED.metadata;
  INSERT INTO pg_temp.a8314_publication_successor_templates VALUES(expected->>'signature',expected->'bodyParts') ON CONFLICT(signature) DO UPDATE SET parts=EXCLUDED.parts;
 END LOOP;

END $conversion_authenticate_poststate$;
CREATE TEMP TABLE pg_temp.a8314_conversion_verified_runtime_snapshot(snapshot jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO pg_temp.a8314_conversion_verified_runtime_snapshot WITH relations AS(SELECT c.* FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY[
 'native_conversation_frame_requirements','native_conversation_conversion_runs','native_conversation_conversion_inputs','native_conversation_conversion_pending','native_conversation_conversion_pages'])),
