DO $conversion_table_templates$
DECLARE parts jsonb;part jsonb;original jsonb;added jsonb;next_parts jsonb:='[]';index integer:=0;
BEGIN
 SELECT t.parts INTO STRICT parts FROM pg_temp.a8314_publication_successor_templates t WHERE signature='native_turn_helpers_current()';
 FOR part IN SELECT value FROM jsonb_array_elements(parts) LOOP
  IF index=1 THEN
   original:=pg_temp.a8314_publication_json(part#>'{slot,template}');
   SELECT coalesce(jsonb_agg(metadata),'[]') INTO added FROM pg_temp.a8314_conversion_source_added_triggers WHERE metadata->>'tgrelid'='public.scope_derivation_sources'::regclass::oid::text;
   SELECT jsonb_agg(value ORDER BY (value->>'oid')::oid) INTO original FROM jsonb_array_elements(original||added);
   part:=to_jsonb(quote_literal(original::text));
  END IF;
  next_parts:=next_parts||jsonb_build_array(part);index:=index+1;
 END LOOP;
 UPDATE pg_temp.a8314_publication_successor_templates SET parts=next_parts WHERE signature='native_turn_helpers_current()';
 SELECT snapshot INTO STRICT original FROM pg_temp.a8314_publication_before_installer_schema;
 SELECT coalesce(jsonb_agg(metadata),'[]') INTO added FROM pg_temp.a8314_conversion_source_added_triggers
  WHERE metadata->>'tgrelid' IN(SELECT value->>'oid' FROM jsonb_array_elements(original->'tables'));
 added:=original->'triggers';
 original:=jsonb_set(original,'{triggers}',added);next_parts:='[]';
 SELECT t.parts INTO STRICT parts FROM pg_temp.a8314_publication_successor_templates t WHERE signature='native_turn_publication_contract()';
 FOR part IN SELECT value FROM jsonb_array_elements(parts) LOOP
  IF part#>>'{slot,kind}'='conversionVerifiedPublicationTables' THEN part:=to_jsonb(quote_literal(original::text));END IF;
  next_parts:=next_parts||jsonb_build_array(part);
 END LOOP;
 UPDATE pg_temp.a8314_publication_successor_templates SET parts=next_parts WHERE signature='native_turn_publication_contract()';
END $conversion_table_templates$;
