CREATE FUNCTION pg_temp.a8314_registry_typed_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $typed$
DECLARE body text;BEGIN
 body:=pg_temp.a8314_typed_original_source_body(routine,parts,successor);
 IF routine='native_turn_helpers_current()' THEN
  IF(length(body)-length(replace(body,'p IS NOT DISTINCT FROM h.contract','')))/length('p IS NOT DISTINCT FROM h.contract')<>1 THEN RAISE EXCEPTION 'executable_root_comparison_source_changed';END IF;
  body:='BEGIN
 IF (
 SELECT t.typtype=''c'' AND t.typnamespace=''public''::regnamespace
 AND t.typowner=(SELECT relowner FROM pg_class WHERE oid=''public.sessions''::regclass)
 AND t.typinput=''pg_catalog.record_in''::regproc AND t.typoutput=''pg_catalog.record_out''::regproc
 AND t.typreceive=''pg_catalog.record_recv''::regproc AND t.typsend=''pg_catalog.record_send''::regproc
 AND t.typmodin=0 AND t.typmodout=0 AND t.typsubscript=0 AND t.typanalyze=0
 AND t.typelem=0 AND t.typbasetype=0 AND t.typnotnull=false AND t.typisdefined
 AND t.typcategory=''C'' AND t.typlen=-1 AND NOT t.typbyval AND t.typalign=''d'' AND t.typstorage=''x''
 AND t.typcollation=0 AND t.typdefault IS NULL AND t.typdefaultbin IS NULL
 AND t.typacl IS NOT DISTINCT FROM ARRAY[makeaclitem(t.typowner,t.typowner,''USAGE'',false)]
 AND EXISTS(SELECT 1 FROM pg_attribute registry_column WHERE registry_column.attrelid=''public.native_turn_contract_helpers''::regclass
  AND registry_column.attname=''contract'' AND registry_column.atttypid=t.oid AND registry_column.attnotnull
  AND NOT registry_column.attisdropped AND NOT registry_column.atthasdef AND registry_column.attacl IS NULL)
 AND(SELECT count(*) FROM pg_attribute a WHERE a.attrelid=t.typrelid AND a.attnum>0)=30
 AND NOT EXISTS(SELECT 1 FROM pg_attribute a FULL JOIN(VALUES
 (1,''oid'',''pg_catalog.oid''::regtype::oid,0::oid),
 (2,''proname'',''pg_catalog.name''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (3,''pronamespace'',''pg_catalog.oid''::regtype::oid,0::oid),
 (4,''proowner'',''pg_catalog.oid''::regtype::oid,0::oid),
 (5,''prolang'',''pg_catalog.oid''::regtype::oid,0::oid),
 (6,''procost'',''pg_catalog.float4''::regtype::oid,0::oid),
 (7,''prorows'',''pg_catalog.float4''::regtype::oid,0::oid),
 (8,''provariadic'',''pg_catalog.oid''::regtype::oid,0::oid),
 (9,''prosupport'',''pg_catalog.regproc''::regtype::oid,0::oid),
 (10,''prokind'',''pg_catalog."char"''::regtype::oid,0::oid),
 (11,''prosecdef'',''pg_catalog.bool''::regtype::oid,0::oid),
 (12,''proleakproof'',''pg_catalog.bool''::regtype::oid,0::oid),
 (13,''proisstrict'',''pg_catalog.bool''::regtype::oid,0::oid),
 (14,''proretset'',''pg_catalog.bool''::regtype::oid,0::oid),
 (15,''provolatile'',''pg_catalog."char"''::regtype::oid,0::oid),
 (16,''proparallel'',''pg_catalog."char"''::regtype::oid,0::oid),
 (17,''pronargs'',''pg_catalog.int2''::regtype::oid,0::oid),
 (18,''pronargdefaults'',''pg_catalog.int2''::regtype::oid,0::oid),
 (19,''prorettype'',''pg_catalog.oid''::regtype::oid,0::oid),
 (20,''proargtypes'',''pg_catalog.oidvector''::regtype::oid,0::oid),
 (21,''proallargtypes'',''pg_catalog.oid[]''::regtype::oid,0::oid),
 (22,''proargmodes'',''pg_catalog."char"[]''::regtype::oid,0::oid),
 (23,''proargnames'',''pg_catalog.text[]''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (24,''proargdefaults'',''pg_catalog.text''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (25,''protrftypes'',''pg_catalog.oid[]''::regtype::oid,0::oid),
 (26,''prosrc'',''pg_catalog.text''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (27,''probin'',''pg_catalog.text''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (28,''prosqlbody'',''pg_catalog.text''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (29,''proconfig'',''pg_catalog.text[]''::regtype::oid,''pg_catalog."C"''::regcollation::oid),
 (30,''proacl'',''pg_catalog.aclitem[]''::regtype::oid,0::oid)
 ) expected(position,name,type_oid,collation_oid) ON a.attnum=expected.position
 WHERE a.attrelid=t.typrelid AND a.attnum>0 AND(a.attname::text IS DISTINCT FROM expected.name OR a.atttypid IS DISTINCT FROM expected.type_oid
 OR a.attcollation IS DISTINCT FROM expected.collation_oid OR a.atttypmod<>-1 OR a.attnotnull OR a.attisdropped
 OR a.atthasdef OR a.atthasmissing OR a.attgenerated<>'''' OR a.attidentity<>'''' OR a.attacl IS NOT NULL))
 FROM pg_type t WHERE t.oid=''public.native_executable_contract_v1''::regtype
) IS NOT TRUE THEN RETURN false;END IF;
 RETURN ('||replace(body,'p IS NOT DISTINCT FROM h.contract','ROW(p.oid,p.proname,p.pronamespace,p.proowner,p.prolang,p.procost,p.prorows,p.provariadic,p.prosupport,p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.pronargs,p.pronargdefaults,p.prorettype,p.proargtypes,p.proallargtypes,p.proargmodes,p.proargnames,p.proargdefaults::text,p.protrftypes,p.prosrc,p.probin,p.prosqlbody::text,p.proconfig,p.proacl)::public.native_executable_contract_v1 IS NOT DISTINCT FROM h.contract')||');
END';
 END IF;RETURN body;
END $typed$;
CREATE FUNCTION pg_temp.a8314_witness_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $witness$
DECLARE body text;anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';start_at integer;end_at integer;old_array text;names text[];rendered text;
BEGIN
 body:=pg_temp.a8314_registry_typed_source_body(routine,parts,successor);
 IF routine='native_turn_helpers_current()' THEN
  IF left(body,6)<>'BEGIN'||chr(10) OR (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 OR strpos(body,'native_turn_contract_witness')>0 THEN RAISE EXCEPTION 'witness_root_source_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  old_array:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO names FROM regexp_matches(old_array,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF old_array IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(names) s) OR names&&ARRAY['capture_conversation_preparation(uuid,jsonb,jsonb,jsonb)','native_turn_contract_witness_refresh()']::text[]
  THEN RAISE EXCEPTION 'witness_root_roster_changed';END IF;
  SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' INTO rendered FROM unnest(names||ARRAY['capture_conversation_preparation(uuid,jsonb,jsonb,jsonb)','native_turn_contract_witness_refresh()']::text[]) s;
  body:='BEGIN'||chr(10)||' IF EXISTS(SELECT 1 FROM public.native_turn_contract_witness w CROSS JOIN LATERAL(SELECT array_agg(s.t ORDER BY s.f,s.k1,s.k2,s.t) tids,array_agg(s.x ORDER BY s.f,s.k1,s.k2,s.t) xmins,coalesce(string_agg(s.fl,'''' ORDER BY s.f,s.k1,s.k2,s.t),'''') flags FROM(
  SELECT 1 f,0::oid k1,0 k2,h.ctid t,h.xmin x,NULL::text fl FROM public.native_turn_contract_helpers h
  UNION ALL SELECT 2,p.oid,0,p.ctid,p.xmin,NULL FROM pg_catalog.pg_proc p WHERE p.oid=ANY(w.procs)
  UNION ALL SELECT 3,c.oid,0,c.ctid,c.xmin,concat(c.relhasindex::int,c.relhasrules::int,c.relhastriggers::int,c.relhassubclass::int) FROM pg_catalog.pg_class c WHERE c.oid=ANY(w.relations||w.class_only)
  UNION ALL SELECT 4,a.attrelid,a.attnum,a.ctid,a.xmin,NULL FROM pg_catalog.pg_attribute a WHERE a.attrelid=ANY(w.relations)
  UNION ALL SELECT 5,k.oid,0,k.ctid,k.xmin,NULL FROM pg_catalog.pg_constraint k WHERE k.conrelid=ANY(w.relations)
  UNION ALL SELECT 6,g.oid,0,g.ctid,g.xmin,NULL FROM pg_catalog.pg_trigger g WHERE g.tgrelid=ANY(w.relations)
  UNION ALL SELECT 7,d.oid,0,d.ctid,d.xmin,NULL FROM pg_catalog.pg_attrdef d WHERE d.adrelid=ANY(w.relations)
  UNION ALL SELECT 8,y.oid,0,y.ctid,y.xmin,NULL FROM pg_catalog.pg_policy y WHERE y.polrelid=ANY(w.relations)
  UNION ALL SELECT 9,r.oid,0,r.ctid,r.xmin,NULL FROM pg_catalog.pg_rewrite r WHERE r.ev_class=ANY(w.relations)
  UNION ALL SELECT 10,i.indexrelid,0,i.ctid,i.xmin,concat(i.indisunique::int,i.indnullsnotdistinct::int,i.indisprimary::int,i.indisexclusion::int,i.indimmediate::int,i.indisclustered::int,i.indisvalid::int,i.indcheckxmin::int,i.indisready::int,i.indislive::int,i.indisreplident::int) FROM pg_catalog.pg_index i WHERE i.indrelid=ANY(w.relations)
  UNION ALL SELECT 11,n.inhrelid,n.inhseqno,n.ctid,n.xmin,NULL FROM pg_catalog.pg_inherits n WHERE n.inhrelid=ANY(w.relations) OR n.inhparent=ANY(w.relations)
  UNION ALL SELECT 12,y.oid,0,y.ctid,y.xmin,NULL FROM pg_catalog.pg_type y WHERE y.oid=ANY(w.types)
  UNION ALL SELECT 13,e.oid,0,e.ctid,e.xmin,NULL FROM pg_catalog.pg_enum e WHERE e.enumtypid=ANY(w.types)
  UNION ALL SELECT 14,0,0,j.ctid,j.xmin,NULL FROM public.crm_erasure_journal_targets j WHERE j.table_name IN(SELECT c.relname FROM pg_catalog.pg_class c WHERE c.oid=ANY(w.relations))
 ) s) l
  WHERE w.singleton AND l.tids=w.tids AND l.xmins=w.xmins AND l.flags=w.flags) THEN RETURN true;END IF;
'||substring(body FROM 7 FOR start_at-7)||rendered||substring(body FROM end_at);
 END IF;
 RETURN body;
END $witness$;
CREATE FUNCTION pg_temp.a8314_completion_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $completion_render$
DECLARE body text;anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';start_at integer;end_at integer;old_array text;names text[];rendered text;
BEGIN
 body:=pg_temp.a8314_witness_source_body(routine,parts,successor);
 IF routine='native_turn_helpers_current()' THEN
  IF strpos(body,'native_turn_contract_witness')=0 OR (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 THEN RAISE EXCEPTION 'completion_root_source_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  old_array:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO names FROM regexp_matches(old_array,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF old_array IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(names) s) OR names&&ARRAY['native_turn_completion_scope(uuid,uuid)','record_native_turn_completion(uuid,uuid,uuid,jsonb)','read_native_turn_completion(uuid,uuid,uuid,jsonb)','native_turn_completion_immutable()']::text[]
  THEN RAISE EXCEPTION 'completion_root_roster_changed';END IF;
  SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' INTO rendered FROM unnest(names||ARRAY['native_turn_completion_scope(uuid,uuid)','record_native_turn_completion(uuid,uuid,uuid,jsonb)','read_native_turn_completion(uuid,uuid,uuid,jsonb)','native_turn_completion_immutable()']::text[]) s;
  body:=substring(body FROM 1 FOR start_at-1)||rendered||substring(body FROM end_at);
 ELSIF routine='native_session_expired_turn_outcome(uuid,uuid,uuid,uuid,boolean)' THEN
  IF encode(sha256(convert_to(body,'UTF8')),'hex')<>'7a4640ba740eb34854488d128598d5ab65ef26fdb965054bc3b0570c9f1790bd' THEN RAISE EXCEPTION 'completion_outcome_predecessor_changed';END IF;
  body:='
DECLARE publication public.native_conversation_publications;completion public.native_turn_completions;
BEGIN
 IF cancelled THEN RETURN ''stopped_by_user'';END IF;
 IF native_turn_helpers_current() IS NOT TRUE OR native_turn_publication_contract() IS NOT TRUE
 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;
 IF t IS NULL OR a IS NULL THEN RETURN ''stalled_reclaimed'';END IF;
 SELECT * INTO publication FROM public.native_conversation_publications p
  WHERE p.workspace_id=w AND p.session_id=s AND p.turn_token=t
   AND p.slot=''buffered_transcript'';
 -- The shared-web buffered receipt (8272) keeps its exact terminal rule.
 IF FOUND THEN
  IF publication.command_format=1 THEN RETURN ''stalled_reclaimed'';END IF;
  IF publication.command_format<>2 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;
  IF publication.completed_at IS NULL OR publication.outputs IS NULL OR jsonb_typeof(publication.outputs) IS DISTINCT FROM ''array''
   OR jsonb_array_length(publication.outputs)<>publication.expected_output_count
  THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;
  IF publication.assistant_id<>a OR publication.stopped OR publication.terminal_descriptor IS NULL THEN RETURN ''stalled_reclaimed'';END IF;
  IF publication.outputs IS NULL OR publication.terminal_outputs IS NULL
   OR jsonb_typeof(publication.terminal_outputs) IS DISTINCT FROM ''array''
   OR jsonb_array_length(publication.terminal_outputs)=0
   OR jsonb_array_length(publication.terminal_outputs)<>jsonb_array_length(publication.terminal_descriptor->''members'')
  THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;
  -- The authenticated independent completion owner validates descriptor/member
  -- shape, exact roots/native references and the entire actual output closure
  -- before this immutable row can commit. Current access does not alter that fact.
  RETURN ''publication_recovered'';
 END IF;
 -- Every other lane and edition: the per-turn completion header (8277), written
 -- in the same transaction as the reply. Its absence is never a commit.
 SELECT * INTO completion FROM public.native_turn_completions c WHERE c.session_id=s AND c.turn_token=t;
 IF NOT FOUND THEN RETURN ''stalled_reclaimed'';END IF;
 IF completion.workspace_id IS DISTINCT FROM w OR jsonb_typeof(completion.outputs) IS DISTINCT FROM ''array''
  OR jsonb_array_length(completion.outputs)=0
 THEN RAISE EXCEPTION ''terminal_control_unavailable'' USING ERRCODE=''55000'';END IF;
 IF completion.assistant_id<>a OR completion.stopped OR NOT completion.published_reply THEN RETURN ''stalled_reclaimed'';END IF;
 RETURN ''publication_recovered'';
END ';
 END IF;
 RETURN body;
END $completion_render$;
CREATE FUNCTION pg_temp.a8314_page_closure_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $page_closure_render$
DECLARE body text;anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';start_at integer;end_at integer;old_array text;names text[];rendered text;
BEGIN
 body:=pg_temp.a8314_completion_source_body(routine,parts,successor);
 IF routine='native_turn_helpers_current()' THEN
  IF strpos(body,'native_turn_contract_witness')=0 OR (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 THEN RAISE EXCEPTION 'page_closure_root_source_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  old_array:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO names FROM regexp_matches(old_array,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF old_array IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(names) s) OR names&&ARRAY['capture_page_closure_evidence(uuid,jsonb,uuid)']::text[]
  THEN RAISE EXCEPTION 'page_closure_root_roster_changed';END IF;
  SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' INTO rendered FROM unnest(names||ARRAY['capture_page_closure_evidence(uuid,jsonb,uuid)']::text[]) s;
  body:=substring(body FROM 1 FOR start_at-1)||rendered||substring(body FROM end_at);
 END IF;
 RETURN body;
END $page_closure_render$;
CREATE FUNCTION pg_temp.a8314_domain_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $domain_render$
DECLARE body text;
BEGIN
 body:=pg_temp.a8314_page_closure_source_body(routine,parts,successor);
 IF routine='conversation_dag_domain(uuid,text,uuid,text[],jsonb,jsonb,jsonb[])' THEN
  IF encode(sha256(convert_to(body,'UTF8')),'hex')<>'46e977d09bff6fdc6f43c4708ceeeae18b5d87f861d0bb58d585802440b754b6' THEN RAISE EXCEPTION 'query_domain_predecessor_changed';END IF;
  body:='
DECLARE frozen application_query_domains;parent jsonb;current_bounds jsonb;visibility jsonb;result jsonb;scanned jsonb;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;state jsonb;
BEGIN
 SELECT * INTO frozen FROM application_query_domains WHERE workspace_id=w AND id=i AND origin=''{"kind":"native","moduleKey":"native"}'' AND type_key=t;
 IF NOT FOUND OR frozen.domain->>''kind'' IS DISTINCT FROM ''session_query_domain_v1''
  OR frozen.domain-ARRAY[''kind'',''sessionId'',''throughSequence'',''fields'',''bounds'',''visibility'',''parentFingerprint'',''candidates'',''points'']<>''{}''
  OR frozen.domain->''fields'' IS DISTINCT FROM to_jsonb(fields) THEN RETURN ''{}''::jsonb;END IF;
 parent:=application_session_query_parent(w,(frozen.domain->>''sessionId'')::uuid);
 IF parent IS NULL OR parent->''fingerprint'' IS DISTINCT FROM frozen.domain->''parentFingerprint'' THEN RETURN ''{}''::jsonb;END IF;
 current_bounds:=application_session_query_bounds(w,parent);
 IF current_bounds IS NULL OR application_query_scope_union_contains(frozen.domain->''bounds'',jsonb_build_array(current_bounds),4096)->>''contains'' IS DISTINCT FROM ''true'' THEN RETURN ''{}''::jsonb;END IF;
 visibility:=jsonb_build_object(''userId'',CASE WHEN current_setting(''app.agent_shared_audience'',true)=''true'' THEN NULL ELSE actor END,
  ''assistants'',coalesce(nullif(current_setting(''app.agent_visibility_assistants'',true),'''')::jsonb,''null''::jsonb));
 -- The frozen assistant visibility is capture metadata, not authority. A reader
 -- whose visibility does not contain it admits the domain only when every frozen
 -- point is unscoped or visible to it; the rescan below then reproduces every
 -- candidate and point from this reader''s own current admission, or refuses.
 -- The point check runs only when containment fails, so the contained path keeps
 -- the original simple expressions.
 IF frozen.domain#>>''{visibility,userId}'' IS NOT NULL AND frozen.domain#>>''{visibility,userId}'' IS DISTINCT FROM visibility->>''userId'' THEN RETURN ''{}''::jsonb;END IF;
 IF visibility->''assistants''<>''null''::jsonb AND (frozen.domain#>''{visibility,assistants}''=''null''::jsonb
   OR NOT coalesce(frozen.domain#>''{visibility,assistants}''<@(visibility->''assistants''),false)) THEN
  IF jsonb_typeof(frozen.domain->''points'') IS DISTINCT FROM ''array'' OR EXISTS(SELECT 1 FROM jsonb_array_elements(frozen.domain->''points'') point
   WHERE jsonb_typeof(point->''source'') IS DISTINCT FROM ''object'' OR point#>>''{source,assistantId}'' IS NOT NULL
    AND NOT coalesce(visibility->''assistants'' ? (point#>>''{source,assistantId}''),false)) THEN RETURN ''{}''::jsonb;END IF;
 END IF;
 result:=conversation_dag_scan(w,(frozen.domain->>''sessionId'')::uuid,t,(frozen.domain->>''throughSequence'')::integer,fields,frozen.domain->''bounds'',frozen.domain->''visibility'',memo,slots,completed);

 memo:=coalesce(result->''memo'',memo);scanned:=result->''value'';
 IF scanned IS NULL OR scanned->''candidates'' IS DISTINCT FROM frozen.domain->''candidates'' OR scanned->''points'' IS DISTINCT FROM frozen.domain->''points'' THEN RETURN ''{}''::jsonb;END IF;
 state:=jsonb_build_object(''values'',''{}''::jsonb,''source'',parent->''scope'',''recordVersion'',''1'',
  ''sourceKind'',''application_query_domain'',''sourceId'',i,''sourceVersion'',frozen.identity,''ownerId'',NULL,
  ''fieldIdentity'',application_field_digest(jsonb_build_object(''kind'',''session_query_domain_v1'',''identity'',frozen.identity,''fields'',fields)),
  ''policyVersion'',application_field_digest(jsonb_build_object(''kind'',''session_query_domain_v1'',''identity'',frozen.identity,''policies'',scanned->''policies'')),
  ''references'',''[]''::jsonb,''queryPoints'',frozen.domain->''points'');
 RETURN jsonb_build_object(''value'',state,''children'',result->''children'');
END ';
 END IF;
 RETURN body;
END $domain_render$;
CREATE FUNCTION pg_temp.a8314_fused_pred_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $admission_render$
DECLARE body text;
BEGIN
 body:=pg_temp.a8314_domain_source_body(routine,parts,successor);
 IF routine='session_context_revision_allowed(uuid,uuid)' THEN
  IF encode(sha256(convert_to(body,'UTF8')),'hex')<>'eece218fb5e8f2c9f589601fd66a73e6151574152e6f176f8148b182e2bffc0b' THEN RAISE EXCEPTION 'title_admission_predecessor_changed';END IF;
  body:='
DECLARE root jsonb;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 child_kinds text[];child_ids uuid[];child_versions text[];eligible boolean;position integer;admitted jsonb;dependency record;
 seen jsonb:=''[]'';current_source jsonb;chat_nodes jsonb;chat_proof jsonb;
BEGIN
 IF EXISTS(SELECT 1 FROM session_context_scope_revisions r WHERE r.workspace_id=w AND r.id=i AND r.parent_kind IN(''turn_frame'',''session_title''))
  AND actor IS NOT NULL AND nullif(current_setting(''app.application_id'',true),'''') IS NULL
  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass
   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN
  chat_proof:=capture_conversation_evidence(w,jsonb_build_array(jsonb_build_object(''kind'',''session_context_revision'',''id'',i,''version'',''1'')));
  IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>''admitted''=''true'') IS TRUE;END IF;
  -- Page source family (8278 adapter): a closure the ordinary capture declines
  -- because it reaches a Page receipt is admitted for this principal only when
  -- the adapter proves it now and every source it names is visible to the
  -- current reader; anything else keeps the original evaluation below.
  chat_proof:=capture_page_closure_evidence(w,jsonb_build_array(jsonb_build_object(''kind'',''session_context_revision'',''id'',i,''version'',''1'')),actor);
  IF chat_proof->>''admitted''=''true'' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(chat_proof->''immutable'',''[]'')||coalesce(chat_proof->''current'',''[]'')) c
   WHERE workflow_evidence_envelope_visible(w,c) IS NOT TRUE) THEN RETURN true;END IF;
 END IF;
 -- Recording privacy admission precedes body selection.
 IF NOT recording_source_read_allowed(w,''session_context_revision'',i) THEN RETURN false;END IF;
 root:=read_entity_derivation_source(w,''session_context_revision'',i);
 IF root IS NULL OR root->>''held'' IS DISTINCT FROM ''false'' THEN RETURN false;END IF;
 IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL
  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass WHERE login.rolname=session_user
    AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN

 SELECT array_agg(s.source_kind ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_id ORDER BY s.source_kind,s.source_id,s.source_version),
  array_agg(s.source_version ORDER BY s.source_kind,s.source_id,s.source_version),
  count(*) BETWEEN 1 AND 100 AND bool_and(s.source_kind=''application_field'')
   AND bool_or(s.source_kind=''application_field'' AND EXISTS(SELECT 1 FROM application_field_resources f WHERE f.workspace_id=w AND f.id=s.source_id
    AND f.origin=''{"kind":"native","moduleKey":"native"}'' AND f.type_key=''memory'' AND f.selection=''history''))
 INTO child_kinds,child_ids,child_versions,eligible
 FROM session_context_scope_revisions r JOIN scope_derivations d ON d.workspace_id=r.workspace_id AND d.resource_kind=''session_context_revision''
  AND d.resource_id=r.id AND d.resource_version=''1'' AND d.user_id IS NOT DISTINCT FROM r.user_id AND d.assistant_id IS NOT DISTINCT FROM r.assistant_id
  AND d.sensitivity=r.sensitivity AND d.compartments=r.compartments AND d.project_ids=r.project_ids
 JOIN scope_derivation_sources s ON s.workspace_id=d.workspace_id AND s.derivation_id=d.id
 WHERE r.workspace_id=w AND r.id=i AND r.parent_kind=''session_title'' AND r.parent_id=r.session_id AND r.scope_version=1;
 IF eligible IS TRUE AND EXISTS(SELECT 1 FROM application_scope_lineage(w,child_kinds,child_ids,child_versions) n WHERE n.kind=''session_context_revision'') THEN eligible:=false;END IF;

  IF eligible IS TRUE THEN
   IF root->>''version'' IS DISTINCT FROM ''1'' OR application_reader_envelope_visible(w,root) IS NOT TRUE THEN RETURN false;END IF;
   FOR position IN 1..cardinality(child_ids) LOOP
    admitted:=read_admitted_application_field_snapshot(w,child_ids[position],child_versions[position]);
    IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM child_versions[position] THEN RETURN false;END IF;
   END LOOP;
   FOR dependency IN SELECT * FROM read_native_session_field_dependencies(w,child_kinds,child_ids,child_versions) LOOP
    admitted:=read_admitted_application_field_snapshot(w,(dependency.source->>''resourceId'')::uuid,dependency.node_version);
    IF admitted IS NULL OR admitted->>''held'' IS DISTINCT FROM ''false'' OR admitted->>''version'' IS DISTINCT FROM dependency.node_version THEN RETURN false;END IF;
    seen:=seen||jsonb_build_array(jsonb_build_array(dependency.source->>''resourceId'',dependency.node_version));
   END LOOP;
   IF jsonb_array_length(seen)=0 THEN RETURN false;END IF;
   FOR position IN 1..cardinality(child_ids) LOOP
    IF NOT seen @> jsonb_build_array(jsonb_build_array(child_ids[position]::text,child_versions[position])) THEN RETURN false;END IF;
   END LOOP;
   FOR dependency IN SELECT * FROM read_external_source_dependencies(w,child_kinds,child_ids,child_versions) LOOP
    current_source:=external_source_snapshot(w,(dependency.source->>''resourceId'')::uuid);
    IF dependency.source IS NULL OR dependency.source->>''workspaceId'' IS DISTINCT FROM w::text
     OR dependency.source->>''version'' IS DISTINCT FROM dependency.node_version
     OR current_source IS NULL OR current_source->>''held'' IS DISTINCT FROM ''false''
     OR current_source->>''version'' IS DISTINCT FROM dependency.node_version
     OR application_reader_envelope_visible(w,dependency.source) IS NOT TRUE
     OR application_reader_envelope_visible(w,current_source) IS NOT TRUE THEN RETURN false;END IF;
   END LOOP;
   RETURN true;
  END IF;
 END IF;
 -- Keep the separate historical-purpose branch above. Ordinary current
 -- Memory domains can use the existing complete cohort proof, never a label
 -- or an envelope supplied by the caller. Its explicit denial stays denied.
 IF actor IS NOT NULL AND EXISTS(SELECT 1 FROM workspace_members member WHERE member.workspace_id=w AND member.user_id=actor)
  AND nullif(current_setting(''app.application_id'',true),'''') IS NULL
  AND nullif(current_setting(''app.public_share_root'',true),'''') IS NULL
  AND NOT EXISTS(SELECT 1 FROM pg_roles login JOIN pg_class owned ON owned.oid=''public.session_messages''::regclass
   WHERE login.rolname=session_user AND(login.rolsuper OR login.rolbypassrls OR pg_has_role(login.oid,owned.relowner,''USAGE''))) THEN
  SELECT coalesce(jsonb_agg(to_jsonb(node)),''[]'') INTO chat_nodes
   FROM application_scope_lineage(w,ARRAY[''session_context_revision''],ARRAY[i],ARRAY[''1'']) node;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node
   JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>''id'')::uuid
   WHERE node->>''kind''=''application_field'' AND resource.origin=''{"kind":"native","moduleKey":"native"}''::jsonb
    AND resource.type_key=''memory'' AND resource.selection=''query_domain'')
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(chat_nodes) node
    JOIN application_field_resources resource ON resource.workspace_id=w AND resource.id=(node->>''id'')::uuid
    WHERE node->>''kind''=''application_field'' AND resource.type_key=''memory''
     AND(resource.selection<>''query_domain'' OR resource.selected_version IS NOT NULL)) THEN
   chat_proof:=read_native_session_cohort_evidence(w,ARRAY[''session_context_revision''],ARRAY[i],ARRAY[''1''],true);
   IF chat_proof IS NOT NULL THEN RETURN (chat_proof->>''admitted''=''true'') IS TRUE;END IF;
  END IF;
 END IF;
 RETURN root IS NOT NULL AND root->>''held''=''false''
  AND application_canonical_ancestry_allowed(w,''session_context_revision'',i,''1'') IS TRUE;
END
';
 END IF;
 RETURN body;
END $admission_render$;
CREATE FUNCTION pg_temp.a8314_participation_pred_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $fused_render$
DECLARE body text;anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';start_at integer;end_at integer;old_array text;names text[];rendered text;fingerprint text;
BEGIN
