 IF routine='native_turn_helpers_current()' THEN
  IF strpos(body,'native_turn_contract_witness')=0 OR (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 THEN RAISE EXCEPTION 'fused_admission_root_source_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  old_array:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO names FROM regexp_matches(old_array,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF old_array IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(names) s) OR names&&ARRAY['fused_c_admits_point(jsonb,jsonb)','fused_c_agent_read_scope(text,text[],uuid[])','fused_c_agent_scope_grant(text,text[])','fused_c_authority_facts(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean)','fused_c_decline(text,anyelement)','fused_c_dept_grants()','fused_c_dept_grants_for(uuid)','fused_c_dept_row_allows(jsonb,uuid,text,text[],uuid)','fused_c_dept_snapshot(uuid)','fused_c_envelope_valid(jsonb)','fused_c_facts4(uuid,boolean)','fused_c_member_field_permissions(uuid,jsonb,uuid)','fused_c_member_operation_grants(boolean,uuid)','fused_c_member_principal_grants(uuid,boolean,uuid)','fused_c_member_read(uuid,uuid)','fused_c_member_row_allows(jsonb,uuid,text,text[])','fused_c_member_team(uuid,uuid)','fused_c_memory_catalog(uuid)','fused_c_memory_context(uuid,jsonb)','fused_c_memory_field_keys()','fused_c_normalize(jsonb)','fused_c_parent_from_row(uuid,sessions)','fused_c_parent_precheck(uuid,uuid)','fused_c_personal_audience(sessions)','fused_c_placement_visible(uuid,uuid)','fused_c_policy_epoch(uuid,uuid,uuid)','fused_c_principal_facts(uuid)','fused_c_principal_query_bounds(uuid,uuid,jsonb)','fused_c_project_audience(sessions,boolean)','fused_c_project_labels_allowed(jsonb,uuid,text[],boolean)','fused_c_project_member_live(uuid,text,uuid)','fused_c_query_parent(jsonb,uuid,boolean,sessions)','fused_c_scope_cap(integer,jsonb,jsonb)','fused_c_scope_valid(jsonb)','fused_c_session_department_facts(uuid,uuid,uuid)','fused_c_session_query_bounds(uuid,jsonb)','fused_c_set_intersection(jsonb,jsonb)','fused_c_union_contains(jsonb,jsonb,integer)','fused_c_uuidp(text)','fused_c_visible(jsonb,uuid,jsonb)','fused_c_workspace_audience(sessions)','fused_f_adjacent(uuid,jsonb)','fused_f_agent_read_scope_allows(text,text[],uuid[])','fused_f_capture(uuid,jsonb,jsonb,jsonb,text)','fused_f_cohort_membership(jsonb,jsonb)','fused_f_dag(jsonb,uuid,jsonb,jsonb,jsonb,boolean,jsonb,integer[],jsonb,jsonb,timestamp with time zone,bigint,jsonb,bigint,jsonb,boolean,fused_node_pre[])','fused_f_deadline(uuid,jsonb)','fused_f_dept_grants()','fused_f_dept_grants_for(uuid)','fused_f_dept_row_allows(jsonb,uuid,text,text[],uuid)','fused_f_dept_snapshot(uuid)','fused_f_digest(jsonb)','fused_f_fence(text)','fused_f_graph_t(uuid,jsonb)','fused_f_member_operation_grants(boolean,uuid)','fused_f_member_principal_grants(uuid,boolean,uuid)','fused_f_member_row_allows(jsonb,uuid,text,text[])','fused_f_prefetch(uuid,jsonb)','fused_f_privacy(uuid,jsonb)','fused_f_rank(text)','fused_f_recording_candidates(uuid,jsonb)','fused_f_sst(text)','fused_f_sst_kv(text)','fused_f_sst_media(text)','fused_f_sst_pc(text)','fused_f_structure(jsonb,jsonb)','fused_f_turn_key(jsonb)','fused_f_uuid(text)','fused_f_visible(jsonb,uuid,jsonb)','fused_l_domain(jsonb,uuid,text,uuid,text[],jsonb,jsonb,jsonb[])','fused_l_envelope_memory(jsonb,uuid,text,uuid,text,text[],jsonb,jsonb)','fused_l_envelope_session(jsonb,uuid,text,uuid,text,text[],jsonb,jsonb,jsonb[],jsonb)','fused_l_message_snapshot(jsonb,uuid,uuid,jsonb)','fused_l_point(jsonb,uuid,text,uuid,text[],jsonb,jsonb,jsonb[])','fused_l_transcript(uuid,uuid)','capture_conversation_evidence_generic(uuid,jsonb,jsonb,jsonb)']::text[]
  THEN RAISE EXCEPTION 'fused_admission_root_roster_changed';END IF;
