b,integer[],jsonb,jsonb,timestamp with time zone,bigint,jsonb,bigint,jsonb,boolean,fused_node_pre[])','fused_f_deadline(uuid,jsonb)','fused_f_dept_grants()','fused_f_dept_grants_for(uuid)','fused_f_dept_row_allows(jsonb,uuid,text,text[],uuid)','fused_f_dept_snapshot(uuid)','fused_f_digest(jsonb)','fused_f_fence(text)','fused_f_graph_t(uuid,jsonb)','fused_f_member_operation_grants(boolean,uuid)','fused_f_member_principal_grants(uuid,boolean,uuid)','fused_f_member_row_allows(jsonb,uuid,text,text[])','fused_f_prefetch(uuid,jsonb)','fused_f_privacy(uuid,jsonb)','fused_f_rank(text)','fused_f_recording_candidates(uuid,jsonb)','fused_f_sst(text)','fused_f_sst_kv(text)','fused_f_sst_media(text)','fused_f_sst_pc(text)','fused_f_structure(jsonb,jsonb)','fused_f_turn_key(jsonb)','fused_f_uuid(text)','fused_f_visible(jsonb,uuid,jsonb)','fused_l_domain(jsonb,uuid,text,uuid,text[],jsonb,jsonb,jsonb[])','fused_l_envelope_memory(jsonb,uuid,text,uuid,text,text[],jsonb,jsonb)','fused_l_envelope_session(jsonb,uuid,text,uuid,text,text[],jsonb,jsonb,jsonb[],jsonb)','fused_l_message_snapshot(jsonb,uuid,uuid,jsonb)','fused_l_point(jsonb,uuid,text,uuid,text[],jsonb,jsonb,jsonb[])','fused_l_transcript(uuid,uuid)','capture_conversation_evidence_generic(uuid,jsonb,jsonb,jsonb)']::text[]) s;
  body:=substring(body FROM 1 FOR start_at-1)||rendered||substring(body FROM end_at);
 ELSIF routine='capture_conversation_evidence(uuid,jsonb,jsonb,jsonb)' THEN
  IF (SELECT count(*) FROM regexp_matches(body,'IS DISTINCT FROM ''([0-9a-f]{64})'' THEN','g'))<>2
  OR (SELECT count(DISTINCT m[1]) FROM regexp_matches(body,'IS DISTINCT FROM ''([0-9a-f]{64})'' THEN','g') m)<>1
  OR encode(sha256(convert_to(regexp_replace(body,'IS DISTINCT FROM ''([0-9a-f]{64})'' THEN','IS DISTINCT FROM ''__CAPTURE_GUARD_FINGERPRINT__'' THEN','g'),'UTF8')),'hex')<>'94217da392eb7263a51f4e67dc4447f4aac8bf55b17b659724b60f14594fd223' THEN RAISE EXCEPTION 'fused_admission_capture_source_changed';END IF;
  SELECT m[1] INTO STRICT fingerprint FROM regexp_matches(body,'IS DISTINCT FROM ''([0-9a-f]{64})'' THEN') m;
  body:=replace('
DECLARE result jsonb;routed boolean:=false;
BEGIN
 -- Entry fence, as the predecessor: a changed guard refuses before any evaluation.
 -- The joint preparation owner (8275) reads this pinned guard fingerprint.
 IF (SELECT encode(sha256(convert_to(to_jsonb(p)::text,''UTF8'')),''hex'') FROM pg_proc p WHERE p.oid=''native_turn_helpers_current()''::regprocedure)
  IS DISTINCT FROM ''__CAPTURE_GUARD_FINGERPRINT__'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 -- Fused admission owner (8289). The compiled statements of fused_f_capture
 -- evaluate this boundary. A shape it does not compile (Memory candidates and
 -- history, foreign families, annotation points, history-bearing messages, any
 -- branch whose compiled form declines) is answered by the generic owner, the
 -- unchanged predecessor body, as one whole capture. Availability failures
 -- propagate; nothing is stored or reused.
 BEGIN
  result:=fused_f_capture(w,roots,authority,cohorts,''__CAPTURE_GUARD_FINGERPRINT__'');
 EXCEPTION WHEN transaction_rollback OR insufficient_resources OR program_limit_exceeded OR object_not_in_prerequisite_state
  OR operator_intervention OR system_error OR internal_error THEN RAISE;
  WHEN OTHERS THEN routed:=true;
 END;
 IF routed OR result IS NOT DISTINCT FROM ''{"fusedRoute":"generic"}''::jsonb THEN
  RETURN capture_conversation_evidence_generic(w,roots,authority,cohorts);
 END IF;
 RETURN result;
END ','__CAPTURE_GUARD_FINGERPRINT__',fingerprint);
 END IF;
 RETURN body;
END $fused_render$;
CREATE FUNCTION pg_temp.a8314_configured_pred_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $participation_render$
DECLARE body text;
BEGIN
 body:=pg_temp.a8314_participation_pred_source_body(routine,parts,successor);
 IF routine IN('read_entity_derivation_source_before_capture(uuid,text,uuid)','native_worklist_source_capture(uuid,text,uuid,jsonb)') THEN
  IF encode(sha256(convert_to(body,'UTF8')),'hex')<>'cdc03dd1c41f3a47d810a4f3acc0e53d2697e255a74b461b6fa4194b89419333' THEN RAISE EXCEPTION 'participation_retirement_predecessor_changed';END IF;
  body:='
DECLARE s jsonb; actor uuid := nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
  teams text[]; projects uuid[]; visible jsonb;
BEGIN
  IF actor IS NULL OR k NOT IN (''entity'',''entity_link'',''episode'',''memory'',''knowledge_entry'',''kb_chunk'',''task'',''workspace_file'')
    OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
    OR (nullif(current_setting(''app.agent_workspace_id'',true),'''') IS NOT NULL
      AND current_setting(''app.agent_workspace_id'',true)::uuid<>w) THEN RETURN NULL; END IF;
  s:=read_scope_source(w,k,i);
  IF s IS NULL OR ((s->>''userId'') IS NOT NULL AND ((s->>''userId''))::uuid<>actor) THEN RETURN NULL; END IF;
  teams:=ARRAY(SELECT jsonb_array_elements_text((s->''compartments'')));
  projects:=ARRAY(SELECT jsonb_array_elements_text((s->''projectIds''))::uuid);
  visible:=nullif(current_setting(''app.agent_visibility_assistants'',true),'''')::jsonb;
  IF visible IS NOT NULL AND visible<>''null''::jsonb AND (s->>''assistantId'') IS NOT NULL
    AND NOT visible ? ((s->>''assistantId'')) THEN RETURN NULL; END IF;
  IF NOT member_operation_scope_allows(w,(s->>''sensitivity''),teams,false)
    OR NOT agent_read_scope_allows((s->>''sensitivity''),teams,projects) THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM unnest(projects) pid WHERE NOT EXISTS(
    SELECT 1 FROM workspace_projects pr WHERE pr.workspace_id=w AND pr.id=pid AND pr.status=''active'')) THEN RETURN NULL; END IF;
  RETURN s;
END ';
 END IF;
 RETURN body;
END $participation_render$;
CREATE FUNCTION pg_temp.a8314_record_pred_source_body(routine text,parts jsonb,successor boolean) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $configured_renderer$
DECLARE body text;anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';start_at integer;end_at integer;old_array text;names text[];rendered text;
BEGIN
 body:=pg_temp.a8314_configured_pred_source_body(routine,parts,successor);
 IF routine='native_turn_helpers_current()' THEN
  IF (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 THEN RAISE EXCEPTION 'configured_task_root_source_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  old_array:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO names FROM regexp_matches(old_array,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF old_array IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(names) s)
   OR names&&ARRAY['protect_configured_task_receipt()','seal_configured_task_candidate()','assert_programmatic_publication_current(uuid,uuid)','configured_task_source_commit_allowed(uuid,uuid,text,jsonb)']::text[] THEN RAISE EXCEPTION 'configured_task_root_roster_changed';END IF;
  SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' INTO rendered FROM unnest(names||ARRAY['protect_configured_task_receipt()','seal_configured_task_candidate()','assert_programmatic_publication_current(uuid,uuid)','configured_task_source_commit_allowed(uuid,uuid,text,jsonb)']::text[]) s;
  body:=substring(body FROM 1 FOR start_at-1)||rendered||substring(body FROM end_at);
 END IF;
 RETURN body;
END $configured_renderer$;
CREATE FUNCTION pg_temp.a8314_bypass_pred_source_body(signature text,template jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $record_publication_renderer$
 DECLARE body text:=pg_temp.a8314_record_pred_source_body(signature,template,successor);marker text;
 BEGIN
 CASE signature
  WHEN 'conversation_prepare_publications(uuid,uuid,jsonb)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='FROM jsonb_array_elements(compiled) c CROSS JOIN LATERAL jsonb_array_elements(c->''expanded'') n';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'FROM jsonb_array_elements(compiled) c CROSS JOIN LATERAL jsonb_array_elements(c->''expanded'') n
  WHERE n->>''resourceKind''<>''conversation_record''');
   marker:='  ELSIF node->>''resourceKind''=''external_source'' THEN';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  ELSIF node->>''resourceKind''=''conversation_record'' THEN
   current_source:=public.conversation_record_publication_source(w,(node->>''resourceId'')::uuid,s,actor,coalesce(command->>''purpose''=''session_title'',false));
  ELSIF node->>''resourceKind''=''external_source'' THEN');
   marker:='''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>2 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record''');
   marker:=' source_scope:=jsonb_build_object(''workspaceId'',w,''userId'',target->''userId''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,' IF EXISTS(SELECT 1 FROM jsonb_array_elements(sources) origin WHERE origin->>''resourceKind''=''conversation_record'')
  AND NOT EXISTS(SELECT 1 FROM public.conversation_envelopes e WHERE e.session_id=s AND e.workspace_id=w
   AND sensitivity_rank(floor_tier)<=sensitivity_rank(e.cap) AND teams<@e.compartments
   AND projects<@public.conversation_hard_project_ids(e.compartments))
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 source_scope:=jsonb_build_object(''workspaceId'',w,''userId'',target->''userId''');
  WHEN 'validate_scope_resource_reference()' THEN
   marker:='  source_row=CASE WHEN TG_TABLE_NAME=''scope_resource_states''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  IF TG_TABLE_NAME=''scope_derivation_sources'' AND expected_kind=''conversation_record'' THEN
    PERFORM public.require_conversation_record_edge(NEW.workspace_id,NEW.derivation_id,expected_id,expected_version);
    RETURN NEW;
  END IF;
  source_row=CASE WHEN TG_TABLE_NAME=''scope_resource_states''');
  WHEN 'native_turn_frame_payload_shape(jsonb)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='   IF n-ARRAY[''workspaceId''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'   IF n->>''resourceKind''=''conversation_record'' AND (n->>''version'' IS DISTINCT FROM ''1''
    OR n->>''userId'' IS NOT NULL OR n->>''assistantId'' IS NOT NULL) THEN RETURN false;END IF;
   IF n-ARRAY[''workspaceId''');
  WHEN 'native_conversation_compiled_frame_pair(uuid,uuid)' THEN
   marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''page_event_changed''';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed''');
   marker:='  IF n.workspace_id IS DISTINCT FROM w';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_record_publication_predecessor_changed: %',signature;END IF;
   body:=replace(body,marker,'  IF n.kind=''conversation_record'' AND (n.version IS DISTINCT FROM ''1''
   OR n.user_id IS NOT NULL OR n.assistant_id IS NOT NULL) THEN RETURN false;END IF;
  IF n.workspace_id IS DISTINCT FROM w');
  ELSE NULL;
 END CASE;
 RETURN body;
 END $record_publication_renderer$;
CREATE FUNCTION pg_temp.a8314_record_conversion_pred_body(routine text,parts jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $legacy_bypass_renderer$
 DECLARE body text;declared_count integer;retired constant text:='''app.system_bypass'',';
 BEGIN
  body:=pg_temp.a8314_bypass_pred_source_body(routine,parts,successor);
  SELECT reads INTO declared_count FROM (VALUES ('capture_native_session_projection_batch(uuid,uuid,integer,text)',6),('capture_native_session_query_stage(uuid,uuid,integer,text,jsonb,jsonb)',1),('native_turn_context()',1),('native_worklist_context(uuid,jsonb)',1)) decl(signature,reads)
   WHERE signature=routine;
  IF declared_count IS NULL THEN RETURN body; END IF;
  IF (length(body)-length(replace(body,retired,'')))/length(retired) IS DISTINCT FROM declared_count THEN
   RAISE EXCEPTION 'legacy_bypass_context_source_changed: %',routine;
  END IF;
  RETURN replace(body,retired,'');
 END $legacy_bypass_renderer$;
CREATE FUNCTION pg_temp.a8314_record_floor_pred_source_body(routine text,parts jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $record_conversion_renderer$
 DECLARE body text:=pg_temp.a8314_record_conversion_pred_body(routine,parts,successor);
  anchor constant text:='array_agg(h.signature ORDER BY h.signature)=';
  start_at integer;end_at integer;roster text;existing text[];next_roster text;
  new_members constant text[]:=ARRAY['protect_compiled_conversation_payload()','conversation_record_conversion_compiler()','enqueue_conversation_record_conversion()','enroll_existing_conversation_records(integer)','enqueue_exact_conversation_record(conversation_envelopes,integer,integer,integer,boolean)','compile_conversation_record_page(integer,integer)','read_compiled_conversation_payload(conversation_envelopes,integer,integer,integer,boolean,uuid,text)'];
 BEGIN
  IF routine<>'native_turn_helpers_current()' THEN RETURN body;END IF;
  IF (length(body)-length(replace(body,anchor,'')))/length(anchor)<>1 THEN RAISE EXCEPTION 'record_conversion_registry_shape_changed';END IF;
  start_at:=strpos(body,anchor)+length(anchor);end_at:=strpos(substring(body FROM start_at),'::text[]')+start_at-1;
  roster:=substring(body FROM start_at FOR end_at-start_at);
  SELECT array_agg(replace(m[1],'''''','''') ORDER BY o) INTO existing
   FROM regexp_matches(roster,'''((?:[^'']|'''')*)''','g') WITH ORDINALITY x(m,o);
  IF roster IS DISTINCT FROM (SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' FROM unnest(existing) s)
   OR existing&&new_members THEN RAISE EXCEPTION 'record_conversion_registry_roster_changed';END IF;
  SELECT 'ARRAY['||string_agg(quote_literal(s),',' ORDER BY s)||']' INTO next_roster FROM unnest(existing||new_members) s;
  RETURN substring(body FROM 1 FOR start_at-1)||next_roster||substring(body FROM end_at);
 END $record_conversion_renderer$;
CREATE FUNCTION pg_temp.a8314_record_lineage_predecessor_body(signature text,parts jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $record_floor_renderer$
 DECLARE body text:=pg_temp.a8314_record_floor_pred_source_body(signature,parts,successor);marker text;
 BEGIN
 CASE signature
  WHEN 'conversation_message_snapshot(uuid,uuid,jsonb)' THEN
   marker:=' IF parent.context_group_id IS NOT NULL THEN';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_floor_predecessor_changed: %',signature;
   END IF;
   RETURN replace(body,marker,' IF parent.visibility=''personal'' AND parent.workspace_id=w AND parent.context_project_id IS NOT NULL
  AND EXISTS(SELECT 1 FROM public.conversation_envelopes e
   WHERE e.session_id=parent.id AND e.workspace_id=w AND e.visibility=''private_by_kind''
    AND NOT parent.context_project_id=ANY(public.conversation_hard_project_ids(e.compartments))) THEN
  parent.context_project_id:=NULL;
 END IF;
 IF parent.context_group_id IS NOT NULL THEN');
  WHEN 'session_context_parent_snapshot(uuid,uuid)' THEN
   marker:='CASE WHEN s.context_project_id IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array(s.context_project_id) END';
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_floor_predecessor_changed: %',signature;
   END IF;
   RETURN replace(body,marker,'coalesce((SELECT to_jsonb(public.conversation_hard_project_ids(e.compartments))
   FROM public.conversation_envelopes e WHERE e.session_id=s.id AND e.workspace_id=w
    AND s.visibility=''personal'' AND e.visibility=''private_by_kind''),
   CASE WHEN s.context_project_id IS NULL THEN ''[]''::jsonb ELSE jsonb_build_array(s.context_project_id) END)');
  ELSE RETURN body;
 END CASE;
 END $record_floor_renderer$;
CREATE FUNCTION pg_temp.a8314_page_delivery_predecessor_body(routine text,parts jsonb,successor boolean) RETURNS text
 LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $record_lineage_renderer$
 DECLARE body text:=pg_temp.a8314_record_lineage_predecessor_body(routine,parts,successor);marker constant text:='   snapshot:=read_media_parent_snapshot(w,item->>''kind'',(item->>''id'')::uuid);';
 BEGIN
  IF routine='media_parent_visible(text,uuid)' THEN
   IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
    RAISE EXCEPTION 'conversation_lineage_media_predecessor_changed';END IF;
   body:=replace(body,marker,'   IF item->>''kind''=''conversation_record'' THEN
    IF item->>''version'' IS DISTINCT FROM ''1'' OR public.conversation_record_member_allowed(w,(item->>''id'')::uuid,
     nullif(current_setting(''app.current_user_id'',true),'''')::uuid) IS NOT TRUE THEN RETURN false; END IF;
    snapshot:=public.read_conversation_record_source(w,(item->>''id'')::uuid);
   ELSE
   snapshot:=read_media_parent_snapshot(w,item->>''kind'',(item->>''id'')::uuid);
   END IF;');
  END IF;
  RETURN body;
 END $record_lineage_renderer$;
CREATE FUNCTION pg_temp.a8314_conversion_source_body(signature text,parts jsonb,successor boolean) RETURNS text
LANGUAGE plpgsql SET search_path=pg_catalog,public,pg_temp AS $private_page_body$
DECLARE body text:=pg_temp.a8314_page_delivery_predecessor_body(signature,parts,successor);marker text;
BEGIN CASE signature
WHEN 'native_turn_frame_pair(uuid,uuid)' THEN marker:='n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text
   AND NOT (f.format=2 AND r.user_id IS NULL AND n->>''assistantId'' IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'',(n->>''userId'')::uuid))');
WHEN 'native_conversation_frame_requirement_input(uuid,uuid)' THEN marker:='n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n->>''userId'' IS NOT NULL AND n->>''userId'' IS DISTINCT FROM r.user_id::text
   AND NOT (f.format=2 AND r.user_id IS NULL AND n->>''assistantId'' IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n->>''resourceKind'',(n->>''resourceId'')::uuid,n->>''version'',(n->>''userId'')::uuid))');
WHEN 'native_conversation_compiled_frame_pair(uuid,uuid)' THEN marker:='n.user_id IS NOT NULL AND n.user_id IS DISTINCT FROM r.user_id';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'private_page_frame_source_changed: %',signature; END IF;
 body:=replace(body,marker,'n.user_id IS NOT NULL AND n.user_id IS DISTINCT FROM r.user_id
   AND NOT (f.format=2 AND r.user_id IS NULL AND n.assistant_id IS NULL AND
    public.private_conversation_page_frame_source(w,r.session_id,n.kind,n.id,n.version,n.user_id))');
 marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''office_observation'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''');
WHEN 'conversation_prepare_publications(uuid,uuid,jsonb)' THEN
 marker:=' FOR dependency IN
  WITH history_roots AS MATERIALIZED(';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_page_publication_placement_changed';END IF;
 body:=replace(body,marker,' -- A canonical frame can retain Page roots from another frame. Match every
 -- immutable Page root to this thread before the native seal can accept it.
 DECLARE page_roots jsonb;page_boundary jsonb;
 BEGIN
  SELECT jsonb_agg(n) INTO page_roots FROM jsonb_array_elements(lineage) n
   WHERE n->>''kind'' IN(''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'');
  IF page_roots IS NOT NULL THEN
   IF public.lock_conversation_member_read(w,s,actor) IS NOT TRUE THEN
    RAISE EXCEPTION ''page_derivation_output_not_integrated'' USING ERRCODE=''42501'';END IF;
   SELECT public.workflow_page_event_boundary(p) INTO page_boundary FROM public.sessions session
    JOIN public.comment_threads ct ON ct.workspace_id=w AND ct.session_id=session.id
    JOIN public.saved_views p ON p.workspace_id=w AND p.id=ct.page_id
    WHERE session.workspace_id=w AND session.id=s AND session.visibility=''workspace'' AND session.anchor_kind=''doc_thread'';
   IF public.page_event_principal_allows(w,actor,page_boundary) IS NOT TRUE OR EXISTS(
    SELECT 1 FROM (
     SELECT root.*,root.kind IN(''page_live_changed'',''page_live_destination'') AS live,
      CASE WHEN root.kind IN(''page_event_destination'',''page_live_destination'') THEN ''destination'' ELSE ''changed'' END AS role
     FROM jsonb_to_recordset(page_roots) AS root(kind text,id uuid,version text)
    ) source
    LEFT JOIN public.workflow_page_event_observations o ON source.live AND o.workspace_id=w AND o.id=source.id AND o.role=source.role
    LEFT JOIN public.workflow_page_event_receipts r ON r.workspace_id=w AND r.page_id=(page_boundary->>''pageId'')::uuid
     AND r.revision=CASE WHEN source.live THEN o.receipt_id ELSE source.id END
    WHERE r.revision IS NULL OR source.role=''destination'' AND r.metadata->>''action'' NOT IN(''created'',''moved'')
     OR public.page_event_scope_descriptor(source.id,source.role,
      CASE WHEN source.live THEN o.boundary ELSE r.boundaries->source.role END,source.live)->>''version'' IS DISTINCT FROM source.version
     OR EXISTS(SELECT 1 FROM (
      SELECT value FROM jsonb_each(r.boundaries)
      UNION ALL SELECT o.boundary WHERE source.live
     ) boundary WHERE boundary.value->>''unavailable'' IS DISTINCT FROM ''false''
      OR boundary.value->>''pageId'' IS DISTINCT FROM page_boundary->>''pageId''
      OR boundary.value->>''workspaceId'' IS DISTINCT FROM w::text
      OR boundary.value->>''principalBoundary'' IS DISTINCT FROM page_boundary->>''principalBoundary''
      OR CASE page_boundary->>''principalBoundary''
       WHEN ''private'' THEN boundary.value->>''creatorId'' IS DISTINCT FROM page_boundary->>''creatorId''
       WHEN ''teamspace'' THEN boundary.value->>''teamspaceId'' IS DISTINCT FROM page_boundary->>''teamspaceId''
       WHEN ''department'' THEN boundary.value->>''departmentId'' IS DISTINCT FROM page_boundary->>''departmentId''
       ELSE true END)) THEN
    RAISE EXCEPTION ''page_derivation_output_not_integrated'' USING ERRCODE=''42501'';END IF;
  END IF;
 END;
 FOR dependency IN
  WITH history_roots AS MATERIALIZED(');
 marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''office_observation'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''');
 marker:='    FROM jsonb_array_elements(lineage) n WHERE n->>''kind''=''session_context_revision''';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'    FROM jsonb_array_elements(lineage) n WHERE n->>''kind'' IN(''session_context_revision'',''office_observation'')');
 marker:='OR node->>''resourceKind'' IN(''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record'')';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'OR node->>''resourceKind'' IN(''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record'',''office_observation'')');
 marker:='WHERE obligation.value->>''resourceKind'' IN(''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record'')';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'WHERE obligation.value->>''resourceKind'' IN(''application_field'',''external_source'',''session_context_revision'',''crm_event'',''private_transcript'',''conversation_record'',''office_observation'')');
WHEN 'native_conversation_publication_result(uuid,uuid,uuid)' THEN
 marker:=' proof:=capture_conversation_evidence(w,roots);';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'committed_room_evidence_placement_changed';END IF;
 body:=replace(body,marker,' proof:=capture_conversation_evidence(w,roots);
 IF proof IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_class c ON c.oid=''public.sessions''::regclass
   WHERE p.oid=''public.capture_committed_room_record_evidence(uuid,uuid,jsonb)''::regprocedure
   AND p.proowner=c.relowner AND p.prosecdef AND p.provolatile=''v''
   AND p.proconfig=ARRAY[''search_path=pg_catalog, public, pg_temp'']
   AND p.proacl=ARRAY[makeaclitem(c.relowner,c.relowner,''EXECUTE'',false)]
   AND encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex'')=''261784fe92b646ff44f83dfa7e38754c53f6381c9948f5099fa8a80f408b2a56'')
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  proof:=public.capture_committed_room_record_evidence(w,s,roots);
 END IF;');
WHEN 'conversation_dag(uuid,jsonb,jsonb)' THEN
 marker:=' ELSIF kind=''session_message'' THEN
    source:=conversation_message_snapshot(';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,' ELSIF kind=''office_observation'' THEN
    -- An Office observation binds the unchanged artifact snapshot and its current access.
    -- Take the artifact first, in the same order as the Office policy writers.
    DECLARE artifact uuid;
    BEGIN
     SELECT o.artifact_id INTO artifact FROM public.office_scope_observations o
      WHERE o.workspace_id=w AND o.id=node_id AND o.content_version=node_version AND NOT o.held;
     IF artifact IS NOT NULL THEN
      PERFORM a.id FROM public.office_artifacts a WHERE a.workspace_id=w AND a.id=artifact FOR SHARE;
      IF FOUND THEN
       PERFORM d.artifact_id FROM public.office_collab_documents d WHERE d.workspace_id=w AND d.artifact_id=artifact FOR SHARE;
       source:=public.read_entity_derivation_source(w,kind,node_id);
      END IF;
     END IF;
    END;
    valid:=source IS NOT NULL AND source->>''held''=''false'' AND source->>''version''=node_version
     AND workflow_evidence_envelope_visible(w,source) IS TRUE;
   ELSIF kind=''session_message'' THEN
    source:=conversation_message_snapshot(');
WHEN 'native_turn_frame_payload_shape(jsonb)' THEN
 marker:='''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''';
 IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1 THEN
  RAISE EXCEPTION 'conversation_office_evidence_placement_changed: % (% occurrences of %)',signature,
   (length(body)-length(replace(body,marker,'')))/length(marker),left(marker,160);
 END IF;
 body:=replace(body,marker,'''application_field'',''external_source'',''crm_event'',''private_transcript'',''conversation_record'',''office_observation'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''');
ELSE NULL; END CASE;
 IF signature='conversation_dag(uuid,jsonb,jsonb)' AND successor THEN
  marker:=';flat jsonb;privacy jsonb;';
  IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1
  THEN RAISE EXCEPTION 'conversation_graph_body_marker_changed: %',left(marker,120);END IF;
  body:=replace(body,marker,';privacy jsonb;');
  marker:='BEGIN
 SELECT coalesce(jsonb_agg(n)';
  IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1
  THEN RAISE EXCEPTION 'conversation_graph_body_marker_changed: %',left(marker,120);END IF;
  body:=replace(body,marker,' verify_nodes bigint;verify_edges bigint;verify_current boolean;
BEGIN
 SELECT coalesce(jsonb_agg(n)');
  marker:='
 WITH RECURSIVE closure(n) AS(
  SELECT value FROM jsonb_array_elements(seeds)
  UNION SELECT e FROM closure c CROSS JOIN LATERAL conversation_dag_edges(w,c.n) e
 ) SELECT coalesce(jsonb_agg(n),''[]'') INTO nodes FROM(SELECT n FROM closure LIMIT 4097) bounded;
 IF jsonb_array_length(nodes)>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501'';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(''parent'',n,''child'',e,''edge_kind'',''derivation'')),''[]'') INTO edges
 FROM (SELECT n,e FROM jsonb_array_elements(nodes) n CROSS JOIN LATERAL conversation_dag_edges(w,n) e LIMIT 65537) bounded_edges;';
  IF (length(body)-length(replace(body,marker,'')))/length(marker)<>1
  THEN RAISE EXCEPTION 'conversation_graph_body_marker_changed: %',left(marker,120);END IF;
  body:=replace(body,marker,'
 -- Stage A retains the VOLATILE canonical per-node edge reads while
 -- retaining each distinct observed parent/child tuple.
 WITH RECURSIVE closure(parent,child) AS(
  SELECT NULL::jsonb,value FROM jsonb_array_elements(seeds)
  UNION
  SELECT step.parent,step.child FROM closure c
  CROSS JOIN LATERAL (
   SELECT active.node, adjacent.child FROM (SELECT c.child node WHERE c.parent IS NULL OFFSET 0) active
   CROSS JOIN LATERAL conversation_dag_edges(w,active.node) adjacent(child)
   UNION ALL SELECT NULL::jsonb,c.child WHERE c.parent IS NOT NULL
  ) step(parent,child)
 ), bounded AS MATERIALIZED (
  SELECT parent,child FROM closure LIMIT 69633
 ), budget AS MATERIALIZED(
  SELECT count(*) FILTER(WHERE parent IS NULL) AS nodes,count(*) FILTER(WHERE parent IS NOT NULL) AS edges FROM bounded
 )
 SELECT coalesce(jsonb_agg(child) FILTER(WHERE parent IS NULL AND budget.nodes<=4096),''[]''),
  coalesce(jsonb_agg(jsonb_build_object(''parent'',parent,''child'',child,''edge_kind'',''derivation''))
   FILTER(WHERE parent IS NOT NULL AND budget.nodes<=4096 AND budget.edges<=65536),''[]''),
  (SELECT b.nodes FROM budget b),(SELECT b.edges FROM budget b)
 INTO nodes,edges,verify_nodes,verify_edges FROM bounded CROSS JOIN budget;
 IF verify_nodes<=4096 AND verify_edges<=65536 AND pg_column_size(nodes)+pg_column_size(edges)<=16777216 THEN
 -- Stage B is an independent, fresh SQL statement, at the original second
 -- edge observation boundary. Decline unfamiliar shapes visibly and keep
 -- the canonical enumeration for them; never infer authorization from
 -- the typed output or discard a fresh mismatch.
 WITH node_input AS MATERIALIZED(
  SELECT n.ordinality::integer pos,n.value node,n.value->>''tag'' tag,n.value->>''kind'' kind,
   CASE WHEN pg_input_is_valid(n.value->>''id'',''uuid'') THEN (n.value->>''id'')::uuid END id,
   n.value->>''version'' version,n.value->''fields'' fields
  FROM jsonb_array_elements(nodes) WITH ORDINALITY n
 ), typed AS MATERIALIZED(
  SELECT n.*,r.id field_id,r.type_key field_type,r.fields field_keys,
   r.resource_id point_id,r.selection,r.selected_version,r.origin field_origin,
   o.resource_id exact_observation,
   q.id domain_id,q.type_key domain_kind,q.origin domain_origin,q.identity domain_identity,
   q.domain domain_document,q.domain->>''kind'' domain_form,q.domain->''fields'' domain_fields,
   CASE WHEN pg_input_is_valid(q.domain->>''sessionId'',''uuid'') THEN (q.domain->>''sessionId'')::uuid END session_id,
   CASE WHEN pg_input_is_valid(q.domain->>''throughSequence'',''integer'') THEN (q.domain->>''throughSequence'')::integer END through
  FROM node_input n
  LEFT JOIN public.application_field_resources r ON n.tag=''source'' AND n.kind=''application_field''
   AND r.workspace_id=w AND r.id=n.id
  LEFT JOIN public.application_field_observations o ON r.id IS NOT NULL
   AND o.workspace_id=w AND o.resource_id=r.id AND o.version=n.version
  LEFT JOIN public.application_query_domains q ON n.tag=''source'' AND n.kind=''application_query_domain''
   AND q.workspace_id=w AND q.id=n.id
 ), support AS MATERIALIZED(
  SELECT t.*,(t.id IS NOT NULL AND jsonb_typeof(t.node)=''object''
   AND jsonb_typeof(t.node->''id'')=''string'' AND t.node->>''id''=t.id::text
   AND CASE WHEN t.tag=''point'' THEN
    t.node ?& ARRAY[''tag'',''kind'',''id'',''fields''] AND t.node-ARRAY[''tag'',''kind'',''id'',''fields'']=''{}''::jsonb
   WHEN t.tag=''source'' THEN
    t.node ?& ARRAY[''tag'',''kind'',''id'',''version''] AND t.node-ARRAY[''tag'',''kind'',''id'',''version'']=''{}''::jsonb
    AND jsonb_typeof(t.node->''version'')=''string''
   ELSE false END AND CASE
   WHEN t.tag=''point'' AND t.kind IN(''session_message'',''session_message_annotation'') THEN
    jsonb_typeof(t.fields)=''array'' AND NOT t.node ? ''version''
    AND t.fields=to_jsonb(ARRAY(SELECT f FROM unnest(application_session_field_keys(t.kind)) f ORDER BY f))
   WHEN t.tag=''source'' AND t.kind IN(''session_message'',''session_context_revision'') THEN
    t.version ~ ''^[0-9]+$'' AND NOT t.node ? ''fields''
   WHEN t.tag=''source'' AND t.kind=''application_field'' THEN
    t.field_id IS NOT NULL AND t.exact_observation IS NOT NULL AND t.selected_version IS NULL
    AND t.field_origin=''{"kind":"native","moduleKey":"native"}''::jsonb
    AND t.field_type IN(''session_message'',''session_message_annotation'')
    AND t.selection IN(''query'',''identity'',''read'',''query_domain'')
    AND to_jsonb(t.field_keys)=to_jsonb(ARRAY(SELECT f FROM unnest(application_session_field_keys(t.field_type)) f ORDER BY f))
   WHEN t.tag=''source'' AND t.kind=''application_query_domain'' THEN
    t.domain_id IS NOT NULL AND t.domain_identity=t.version AND t.domain_form=''session_query_domain_v1''
    AND t.domain_origin=''{"kind":"native","moduleKey":"native"}''::jsonb
    AND t.domain_kind IN(''session_message'',''session_message_annotation'') AND t.session_id IS NOT NULL AND t.through>=0
    AND t.domain_document ?& ARRAY[''kind'',''sessionId'',''throughSequence'',''fields'',''bounds'',''visibility'',''parentFingerprint'',''candidates'',''points'']
    AND t.domain_document-ARRAY[''kind'',''sessionId'',''throughSequence'',''fields'',''bounds'',''visibility'',''parentFingerprint'',''candidates'',''points'']=''{}''::jsonb
    AND jsonb_typeof(t.domain_document->''sessionId'')=''string'' AND t.domain_document->>''sessionId''=t.session_id::text
    AND jsonb_typeof(t.domain_document->''throughSequence'')=''number''
    AND t.domain_fields=to_jsonb(ARRAY(SELECT f FROM unnest(application_session_field_keys(t.domain_kind)) f ORDER BY f))
   ELSE false END) IS TRUE compiled FROM typed t
 ), eligible AS MATERIALIZED(
  SELECT t.* FROM support t WHERE t.compiled
 ), live(parent,tag,kind,id,version,fields) AS (
  SELECT n.pos,''source''::text,s.source_kind,s.source_id,s.source_version,NULL::jsonb
  FROM eligible n JOIN public.scope_derivations d ON d.workspace_id=w AND d.resource_kind=n.kind AND d.resource_id=n.id
   JOIN public.scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id
  WHERE n.tag=''source''
  UNION ALL
  SELECT n.pos,''source'',o.source_kind,o.source_id,o.source_version,NULL::jsonb
  FROM eligible n JOIN public.application_field_observations o ON o.workspace_id=w AND o.resource_id=n.field_id AND o.version=n.version
  WHERE n.tag=''source'' AND n.kind=''application_field''
  UNION ALL
  SELECT n.pos,''source'',o.source_kind,o.source_id,o.source_version,NULL::jsonb
  FROM eligible n JOIN public.application_field_observation_sources o ON o.workspace_id=w AND o.resource_id=n.field_id AND o.version=n.version
  WHERE n.tag=''source'' AND n.kind=''application_field''
  UNION ALL
  SELECT n.pos,''point'',n.field_type,n.point_id,NULL::text,to_jsonb(n.field_keys)
  FROM eligible n
  WHERE n.tag=''source'' AND n.kind=''application_field'' AND n.selection IN(''query'',''identity'',''read'')
  UNION ALL
  SELECT n.pos,''point'',n.domain_kind,m.id,NULL::text,n.domain_fields
  FROM eligible n JOIN public.session_messages m ON m.workspace_id=w AND m.session_id=n.session_id AND m.sequence_num<=n.through
  WHERE n.tag=''source'' AND n.kind=''application_query_domain''
  UNION ALL
  SELECT n.pos,''source'',''session_message'',m.id,m.scope_version::text,NULL::jsonb
  FROM eligible n JOIN public.session_messages m ON m.workspace_id=w AND m.id=n.id
  WHERE n.tag=''point''
  UNION ALL
  SELECT n.pos,''source'',''session_context_revision'',r.id,r.scope_version::text,NULL::jsonb
  FROM eligible n JOIN public.session_message_annotation_heads h ON h.workspace_id=w AND h.message_id=n.id
   JOIN public.session_context_scope_revisions r ON r.workspace_id=w AND r.id=h.scope_revision_id
    AND r.session_id=h.session_id AND r.parent_kind=''message_annotation'' AND r.parent_id=h.message_id
  WHERE n.tag=''point'' AND n.kind=''session_message_annotation''
 ), fresh_candidates AS MATERIALIZED(
  SELECT endpoint.parent,endpoint.child FROM (
   SELECT l.parent,n.pos child
   FROM live l LEFT JOIN node_input n ON n.tag=l.tag AND n.kind=l.kind AND n.id=l.id
    AND n.version IS NOT DISTINCT FROM l.version AND n.fields IS NOT DISTINCT FROM l.fields
   UNION ALL
   SELECT u.pos,n.pos
   FROM (SELECT t.pos,t.node FROM support t WHERE NOT t.compiled OFFSET 0) u
   CROSS JOIN LATERAL conversation_dag_edges(w,u.node) e
   LEFT JOIN node_input n ON n.node=e
  ) endpoint LIMIT 65537
 ), fresh AS MATERIALIZED(
  SELECT DISTINCT candidate.parent,candidate.child FROM fresh_candidates candidate
 ), expected AS MATERIALIZED(
  SELECT p.pos parent,c.pos child FROM jsonb_array_elements(edges) e
  JOIN node_input p ON p.node=e->''parent''
  JOIN node_input c ON c.node=e->''child''
 ), drift AS(
  (SELECT * FROM expected EXCEPT SELECT * FROM fresh)
  UNION ALL
  (SELECT * FROM fresh EXCEPT SELECT * FROM expected)
 )
 SELECT (SELECT count(*) FROM fresh_candidates)<=65536 AND
  (SELECT count(*) FROM expected)=verify_edges AND NOT EXISTS(SELECT 1 FROM drift)
 INTO verify_current;
 END IF;
 IF verify_current IS NOT TRUE THEN
  -- An over-budget observation or disagreement cannot supply topology.
  -- The canonical compiler rediscovers both current closure and adjacency.

 WITH RECURSIVE closure(n) AS(
  SELECT value FROM jsonb_array_elements(seeds)
  UNION SELECT e FROM closure c CROSS JOIN LATERAL conversation_dag_edges(w,c.n) e
 ) SELECT coalesce(jsonb_agg(n),''[]'') INTO nodes FROM(SELECT n FROM closure LIMIT 4097) bounded;
 IF jsonb_array_length(nodes)>4096 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501'';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(''parent'',n,''child'',e,''edge_kind'',''derivation'')),''[]'') INTO edges
 FROM (SELECT n,e FROM jsonb_array_elements(nodes) n CROSS JOIN LATERAL conversation_dag_edges(w,n) e LIMIT 65537) bounded_edges;
 END IF;');
