 END LOOP;
 IF EXISTS(SELECT 1 FROM native_turn_contract_helpers h JOIN pg_proc p ON p.oid=to_regprocedure(h.signature) WHERE ROW(p.oid,p.proname,p.pronamespace,p.proowner,p.prolang,p.procost,p.prorows,p.provariadic,p.prosupport,p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.pronargs,p.pronargdefaults,p.prorettype,p.proargtypes,p.proallargtypes,p.proargmodes,p.proargnames,p.proargdefaults::text,p.protrftypes,p.prosrc,p.probin,p.prosqlbody::text,p.proconfig,p.proacl)::public.native_executable_contract_v1 IS DISTINCT FROM h.contract)
