')<>7 THEN RAISE EXCEPTION 'installation_witness_fast_path_changed';END IF;
 EXECUTE format('CREATE FUNCTION pg_temp.a8314_full_guard() RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog,public,pg_temp AS %L',replace(body,' IF EXISTS(SELECT 1 FROM public.native_turn_contract_witness w CROSS JOIN LATERAL(SELECT array_agg(s.t ORDER BY s.f,s.k1,s.k2,s.t) tids,array_agg(s.x ORDER BY s.f,s.k1,s.k2,s.t) xmins,coalesce(string_agg(s.fl,'''' ORDER BY s.f,s.k1,s.k2,s.t),'''') flags FROM(
  SELECT 1 f,0::oid k1,0 k2,h.ctid t,h.xmin x,NULL::text fl FROM public.native_turn_contract_helpers h
  UNION ALL SELECT 2,p.oid,0,p.ctid,p.xmin,NULL FROM pg_catalog.pg_proc p WHERE p.oid=ANY(w.procs)
