DO $a8314_p_participation$ DECLARE p pg_proc;BEGIN
 SELECT * INTO p FROM pg_proc WHERE oid=to_regprocedure('public.read_entity_derivation_source_before_capture(uuid,text,uuid)');
 IF p.oid IS NULL OR (p.prosrc COLLATE "C") IS DISTINCT FROM ('
DECLARE s jsonb; actor uuid := nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
  teams text[]; projects uuid[]; visible jsonb;
BEGIN
  IF actor IS NULL OR k NOT IN (''entity'',''entity_link'',''episode'',''memory'',''knowledge_entry'',''kb_chunk'',''task'',''workspace_file'')
    OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
    OR (nullif(current_setting(''app.agent_workspace_id'',true),'''') IS NOT NULL
      AND current_setting(''app.agent_workspace_id'',true)::uuid<>w) THEN RETURN NULL; END IF;
  s:=read_scope_source(w,k,i);
  IF s IS NULL OR ((s->>''userId'') IS NOT NULL AND ((s->>''userId''))::uuid<>actor) THEN RETURN NULL; END IF;
  teams:=ARRAY(SELECT jsonb_array_elements_text((s->''compartments'')));
  projects:=ARRAY(SELECT jsonb_array_elements_text((s->''projectIds''))::uuid);
  visible:=nullif(current_setting(''app.agent_visibility_assistants'',true),'''')::jsonb;
  IF visible IS NOT NULL AND visible<>''null''::jsonb AND (s->>''assistantId'') IS NOT NULL
    AND NOT visible ? ((s->>''assistantId'')) THEN RETURN NULL; END IF;
  IF NOT member_operation_scope_allows(w,(s->>''sensitivity''),teams,false)
    OR NOT agent_read_scope_allows((s->>''sensitivity''),teams,projects) THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM unnest(projects) pid WHERE NOT EXISTS(
    SELECT 1 FROM workspace_projects pr WHERE pr.workspace_id=w AND pr.id=pid AND pr.status=''active'')) THEN RETURN NULL; END IF;
  RETURN s;
END ' COLLATE "C") OR NOT p.prosecdef OR p.proowner<>(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  OR p.proconfig IS DISTINCT FROM ARRAY['search_path=public, pg_temp'] OR p.provolatile<>'v' OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
  OR NOT EXISTS(SELECT 1 FROM native_turn_contract_helpers h WHERE h.signature='read_entity_derivation_source_before_capture(uuid,text,uuid)' AND ROW(p.oid,p.proname,p.pronamespace,p.proowner,p.prolang,p.procost,p.prorows,p.provariadic,p.prosupport,p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.pronargs,p.pronargdefaults,p.prorettype,p.proargtypes,p.proallargtypes,p.proargmodes,p.proargnames,p.proargdefaults::text,p.protrftypes,p.prosrc,p.probin,p.prosqlbody::text,p.proconfig,p.proacl)::public.native_executable_contract_v1 IS NOT DISTINCT FROM h.contract)
 THEN RAISE EXCEPTION 'installation_participation_retirement_changed';END IF;
 SELECT * INTO p FROM pg_proc WHERE oid=to_regprocedure('public.native_worklist_source_capture(uuid,text,uuid,jsonb)');
 IF p.oid IS NULL OR (p.prosrc COLLATE "C") IS DISTINCT FROM ('
DECLARE s jsonb; actor uuid := nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
  teams text[]; projects uuid[]; visible jsonb;
BEGIN
  IF actor IS NULL OR k NOT IN (''entity'',''entity_link'',''episode'',''memory'',''knowledge_entry'',''kb_chunk'',''task'',''workspace_file'')
    OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=actor)
    OR (nullif(current_setting(''app.agent_workspace_id'',true),'''') IS NOT NULL
      AND current_setting(''app.agent_workspace_id'',true)::uuid<>w) THEN RETURN NULL; END IF;
  s:=read_scope_source(w,k,i);
  IF s IS NULL OR ((s->>''userId'') IS NOT NULL AND ((s->>''userId''))::uuid<>actor) THEN RETURN NULL; END IF;
  teams:=ARRAY(SELECT jsonb_array_elements_text((s->''compartments'')));
  projects:=ARRAY(SELECT jsonb_array_elements_text((s->''projectIds''))::uuid);
  visible:=nullif(current_setting(''app.agent_visibility_assistants'',true),'''')::jsonb;
  IF visible IS NOT NULL AND visible<>''null''::jsonb AND (s->>''assistantId'') IS NOT NULL
    AND NOT visible ? ((s->>''assistantId'')) THEN RETURN NULL; END IF;
  IF NOT member_operation_scope_allows(w,(s->>''sensitivity''),teams,false)
    OR NOT agent_read_scope_allows((s->>''sensitivity''),teams,projects) THEN RETURN NULL; END IF;
  IF EXISTS(SELECT 1 FROM unnest(projects) pid WHERE NOT EXISTS(
    SELECT 1 FROM workspace_projects pr WHERE pr.workspace_id=w AND pr.id=pid AND pr.status=''active'')) THEN RETURN NULL; END IF;
  RETURN s;
END ' COLLATE "C") OR NOT p.prosecdef OR p.proowner<>(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass)
  OR p.proconfig IS DISTINCT FROM ARRAY['search_path=public, pg_temp'] OR p.provolatile<>'v' OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='plpgsql')
  OR NOT EXISTS(SELECT 1 FROM native_turn_contract_helpers h WHERE h.signature='native_worklist_source_capture(uuid,text,uuid,jsonb)' AND ROW(p.oid,p.proname,p.pronamespace,p.proowner,p.prolang,p.procost,p.prorows,p.provariadic,p.prosupport,p.prokind,p.prosecdef,p.proleakproof,p.proisstrict,p.proretset,p.provolatile,p.proparallel,p.pronargs,p.pronargdefaults,p.prorettype,p.proargtypes,p.proallargtypes,p.proargmodes,p.proargnames,p.proargdefaults::text,p.protrftypes,p.prosrc,p.probin,p.prosqlbody::text,p.proconfig,p.proacl)::public.native_executable_contract_v1 IS NOT DISTINCT FROM h.contract)
 THEN RAISE EXCEPTION 'installation_participation_retirement_changed';END IF;
END $a8314_p_participation$;
DO $a8314_t_fused_tuning$ DECLARE p pg_proc;owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);BEGIN
 SELECT * INTO p FROM pg_proc WHERE oid=to_regprocedure('public.fused_c_admits_point(jsonb,jsonb)');
 IF p.oid IS NULL OR p.proowner<>owner_id OR p.prolang<>(SELECT oid FROM pg_language WHERE lanname='sql') OR p.prosecdef
  OR (p.prosrc COLLATE "C") IS DISTINCT FROM ('
 SELECT CASE WHEN (SELECT v FROM fused_c_scope_valid(bounds)) IS NOT TRUE OR x.rank IS NULL OR x.rank NOT BETWEEN 1 AND 3
   OR jsonb_typeof(source->''compartments'') IS DISTINCT FROM ''array'' OR jsonb_typeof(source->''projectIds'') IS DISTINCT FROM ''array'' THEN false
  WHEN cardinality(t.teams)=0 AND x.rank>(x.scope->>''tier'')::int THEN false
  WHEN cardinality(t.teams)>0 AND x.scope->>''contextDepartment'' IS NOT NULL AND NOT (x.scope->>''contextDepartment''=ANY(t.teams)) THEN false
  WHEN cardinality(t.teams)>0 AND EXISTS(SELECT 1 FROM unnest(t.teams) team WHERE x.rank>(CASE WHEN x.scope->''departments''=''null'' THEN (x.scope->>''tier'')::int ELSE coalesce((x.scope#>>ARRAY[''departments'',team])::int,0) END)) THEN false
  ELSE coalesce(
   (SELECT coalesce(jsonb_agg(to_jsonb(substr(value#>>''{}'',9))),''[]'') FROM jsonb_array_elements(source->''compartments'') WHERE value#>>''{}'' LIKE ''project:%'')<@(x.scope->''projectLabels'')
   AND (x.scope->''otherLabels''=''null'' OR (SELECT coalesce(jsonb_agg(value),''[]'') FROM jsonb_array_elements(source->''compartments'')
    WHERE value#>>''{}'' NOT LIKE ''team:%'' AND value#>>''{}'' NOT LIKE ''project:%'')<@(x.scope->''otherLabels''))
   AND (x.scope->''projectIds''=''null'' OR source->''projectIds''<@(x.scope->''projectIds'')),false) END
 FROM (SELECT (SELECT v FROM fused_c_normalize(bounds)) scope, fused_f_rank(source->>''sensitivity'') rank OFFSET 0) x,
