 -- changed a current visibility/participant row. Its protected mutation must
 -- have committed the exact audience state and audit atomically.
 IF e.classification=''legacy_personal'' AND e.visibility=''workspace''
  AND public.conversation_consent_current(sid) IS NOT TRUE THEN RETURN ''omitted''; END IF;
 -- A personal assistant outside a workspace retains its owner-only contract.
 IF w IS NULL THEN
  RETURN CASE WHEN e.starter_user_id=actor AND s.user_id=actor AND e.visibility<>''workspace'' THEN ''full'' ELSE ''omitted'' END;
 END IF;
 SELECT * INTO m FROM public.workspace_members WHERE workspace_id=w AND user_id=actor;
 IF NOT FOUND THEN RETURN ''omitted''; END IF;
 SELECT department_read_v2 INTO v2 FROM public.workspaces WHERE id=w;
 grants:=public.department_read_grants_for(actor);
 IF v2 THEN
  IF public.department_row_allows(grants,w,e.cap,e.compartments,NULL) IS NOT TRUE THEN RETURN ''omitted''; END IF;
 ELSE
  IF public.sensitivity_rank(m.clearance)<public.sensitivity_rank(e.cap)
   OR public.effective_member_read_compartments(actor,w) IS NOT NULL
    AND NOT e.compartments <@ public.effective_member_read_compartments(actor,w) THEN RETURN ''omitted''; END IF;
 END IF;
 -- Project association is not a reader grant. Actual shared Project labels
 -- retain the canonical roster and owner-read-only oversight semantics.
 IF public.project_labels_allowed(grants,w,e.compartments,false) IS NOT TRUE THEN RETURN ''omitted''; END IF;
 CASE s.anchor_kind
 WHEN ''doc_thread'' THEN
  SELECT ct.page_id INTO page_id FROM public.comment_threads ct WHERE ct.session_id=sid AND ct.workspace_id=w;
  anchor_allowed:=page_id IS NOT NULL AND public.saved_view_root_operation_scope_allows(page_id,false) IS TRUE;
 WHEN ''office_file'' THEN
  SELECT l.artifact_id INTO artifact_id FROM public.office_artifact_sessions l JOIN public.office_artifacts a ON a.id=l.artifact_id
   WHERE l.session_id=sid AND a.workspace_id=w;
  anchor_allowed:=artifact_id IS NOT NULL AND public.conversation_office_anchor_current(artifact_id,actor) IS TRUE;
 WHEN ''feed_draft'' THEN
  anchor_allowed:=public.feed_draft_audience_allowed(sid) IS TRUE;
 WHEN ''feed_thread'' THEN
  SELECT t.session_id INTO parent_id FROM public.feed_comment_threads t JOIN public.sessions parent ON parent.id=t.session_id
   WHERE t.transcript_session_id=sid AND parent.anchor_kind=''feed_draft'' AND parent.workspace_id=w AND parent.assistant_id=s.assistant_id;
  anchor_allowed:=parent_id IS NOT NULL AND parent_id<>sid AND public.conversation_member_tier_current(w,parent_id,actor)=''full'';
 ELSE anchor_allowed:=true;
 END CASE;
 IF anchor_allowed IS NOT TRUE THEN RETURN ''omitted''; END IF;
 IF e.visibility=''workspace'' OR actor=e.starter_user_id OR e.visibility=''configured_private''
  AND EXISTS(SELECT 1 FROM public.conversation_participants p WHERE p.session_id=sid AND p.user_id=actor)
  AND public.conversation_consent_current(sid) IS TRUE THEN RETURN ''full''; END IF;
 RETURN ''presence'';
END $member$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_member_read_current(w uuid,sid uuid,actor uuid) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $current$
 SELECT public.conversation_member_tier_current(w,sid,actor)=''full''
$current$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_envelope_for_reader(sid uuid,actor uuid) RETURNS public.conversation_envelopes
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $envelope$
DECLARE e public.conversation_envelopes;workspace uuid;starter uuid;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid THEN RETURN NULL;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 IF FOUND THEN RETURN e;END IF;
 SELECT coalesce(s.workspace_id,a.workspace_id),s.user_id INTO workspace,starter
 FROM public.sessions s JOIN public.assistants a ON a.id=s.assistant_id WHERE s.id=sid;
 IF NOT FOUND OR workspace IS NULL AND starter<>actor OR workspace IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=workspace AND m.user_id=actor) THEN RETURN NULL;END IF;
 -- Classify a missing legacy envelope only. It never infers a new audience
 -- from the mere fact that a caller is reading it now.
 PERFORM public.classify_conversation_envelope(sid,true);
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 RETURN e;
END $envelope$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_member_tiers(session_ids uuid[],include_presence boolean)
RETURNS TABLE(session_id uuid,tier text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $cohort$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 sid uuid;e public.conversation_envelopes;current_tier text;
BEGIN
 IF session_ids IS NULL OR cardinality(session_ids)>200 OR include_presence IS NULL
  OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
  OR actor IS NULL THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 FOR sid IN SELECT DISTINCT id FROM unnest(session_ids) id WHERE id IS NOT NULL ORDER BY id LOOP
  e:=public.conversation_envelope_for_reader(sid,actor);
  IF e.session_id IS NULL THEN CONTINUE;END IF;
  current_tier:=public.conversation_member_tier_current(e.workspace_id,sid,actor);
  IF current_tier=''full'' AND e.workspace_id IS NOT NULL AND e.visibility=''private_by_kind'' THEN
   PERFORM public.enroll_conversation_legacy_history(sid);
  END IF;
  IF current_tier=''full'' OR current_tier=''presence'' AND include_presence THEN
   session_id:=sid;tier:=current_tier;RETURN NEXT;
  END IF;
 END LOOP;
END $cohort$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_member_read_allowed(w uuid,sid uuid,actor uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $principal$
DECLARE previous_actor text:=current_setting(''app.current_user_id'',true);allowed boolean;
BEGIN
 IF actor IS NULL THEN RETURN false; END IF;
 IF actor::text IS NOT DISTINCT FROM previous_actor THEN RETURN public.conversation_member_read_current(w,sid,actor); END IF;
 PERFORM set_config(''app.current_user_id'',actor::text,true);
 allowed:=public.conversation_member_read_current(w,sid,actor);
 PERFORM set_config(''app.current_user_id'',coalesce(previous_actor,''''),true);
 RETURN allowed;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config(''app.current_user_id'',coalesce(previous_actor,''''),true);
 RAISE;
END $principal$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_visibility_metadata_current(sid uuid,actor uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $metadata$
DECLARE e public.conversation_envelopes;admin boolean;hard_project boolean;
BEGIN
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 IF NOT FOUND OR public.conversation_member_read_allowed(e.workspace_id,sid,actor) IS NOT TRUE THEN RETURN NULL; END IF;
 SELECT coalesce(role IN (''owner'',''admin''),false) INTO admin FROM public.workspace_members WHERE workspace_id=e.workspace_id AND user_id=actor;
 admin:=coalesce(admin,false);
 hard_project:=cardinality(public.conversation_hard_project_ids(e.compartments))>0;
 RETURN jsonb_build_object(''conversationVisibility'',e.visibility,''conversationVisibilityVersion'',e.version,
  ''conversationCap'',e.cap,''conversationCompartments'',ARRAY(SELECT label FROM unnest(e.compartments) label WHERE label NOT LIKE ''project:%'' ORDER BY label),
  ''conversationProjectIds'',public.conversation_hard_project_ids(e.compartments),
  ''participantUserIds'',ARRAY(SELECT p.user_id FROM public.conversation_participants p WHERE p.session_id=sid ORDER BY p.user_id),
  ''capabilities'',jsonb_build_object(
   ''canNarrow'',e.visibility=''workspace'' AND (actor=e.starter_user_id OR admin),
   ''canWiden'',e.visibility<>''private_by_kind'' AND admin,
   ''canManageParticipants'',e.visibility<>''private_by_kind'' AND (actor=e.starter_user_id OR admin),
   ''canRaiseCap'',admin,
   ''canMoveProject'',CASE WHEN e.visibility=''workspace'' THEN admin OR actor=e.starter_user_id AND NOT hard_project ELSE actor=e.starter_user_id END));
END $metadata$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_visibility(sid uuid,device uuid,native_version integer) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $read$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
BEGIN
 IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
  OR NOT EXISTS(SELECT 1 FROM public.auth_sessions a JOIN public.users u ON u.id=a.user_id
  WHERE a.id=device AND a.user_id=actor AND a.auth_version=native_version AND u.auth_version=native_version
   AND a.revoked_at IS NULL AND a.expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM public.conversation_envelope_for_reader(sid,actor);
 RETURN public.conversation_visibility_metadata_current(sid,actor);
END $read$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_enroll_conversation_legacy_history(sid uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $enrollment$
DECLARE s public.sessions;h public.session_legacy_history;e public.conversation_envelopes;digest text;
BEGIN
 SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 IF NOT FOUND OR e.visibility<>''private_by_kind'' OR e.workspace_id IS NULL
  OR s.user_id IS DISTINCT FROM e.starter_user_id THEN RETURN false;END IF;
 SELECT * INTO h FROM public.session_legacy_history WHERE session_id=sid AND workspace_id=e.workspace_id
  AND user_id=e.starter_user_id;
 IF NOT FOUND THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM public.conversation_legacy_history_enrollments WHERE session_id=sid) THEN
  RETURN public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
 END IF;
 IF h.binding IS DISTINCT FROM public.private_legacy_history_binding(s)
  OR NOT EXISTS(SELECT 1 FROM public.assistants a WHERE a.id=s.assistant_id AND a.workspace_id=e.workspace_id)
 THEN RETURN false;END IF;
 digest:=encode(sha256(convert_to(to_jsonb(h)::text,''UTF8'')),''hex'');
 INSERT INTO public.conversation_legacy_history_enrollments(session_id,descriptor_digest) VALUES(sid,digest)
 ON CONFLICT(session_id) DO NOTHING;
 RETURN public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
END $enrollment$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_legacy_enrolled(sid uuid,w uuid,starter uuid,assistant uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $legacy$
 SELECT EXISTS(SELECT 1 FROM public.conversation_legacy_history_enrollments authenticated
  JOIN public.session_legacy_history h USING(session_id)
  JOIN public.sessions s ON s.id=h.session_id AND s.user_id=h.user_id AND s.assistant_id=assistant
  JOIN public.assistants a ON a.id=s.assistant_id AND a.workspace_id=h.workspace_id
  JOIN public.conversation_envelopes e ON e.session_id=s.id AND e.workspace_id=h.workspace_id
   AND e.starter_user_id=h.user_id AND e.visibility=''private_by_kind''
  LEFT JOIN LATERAL(SELECT audit.after_envelope FROM public.conversation_visibility_audit audit
   WHERE audit.session_id=sid ORDER BY audit.next_version DESC LIMIT 1) latest ON true
  WHERE h.session_id=sid AND h.workspace_id=w AND h.user_id=starter AND coalesce(s.workspace_id,a.workspace_id)=w
   AND h.binding->>0=sid::text AND h.binding->>1=starter::text AND h.binding->>2=assistant::text
   AND authenticated.descriptor_digest=encode(sha256(convert_to(to_jsonb(h)::text,''UTF8'')),''hex'')
   AND (h.binding=public.private_legacy_history_binding(s) OR latest.after_envelope->>''legacyBindingDigest''
    =encode(sha256(convert_to(public.private_legacy_history_binding(s)::text,''UTF8'')),''hex'')))
$legacy$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_guard_conversation_record_capture() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $immutable$
BEGIN
 IF (OLD.binding->>''kind''=''conversation_record_v1'' OR NEW.binding->>''kind''=''conversation_record_v1'')
  AND NEW IS DISTINCT FROM OLD THEN RAISE EXCEPTION ''conversation_record_immutable'' USING ERRCODE=''42501''; END IF;
 RETURN NEW;
END $immutable$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_withdraw_conversation_record_targets(targets jsonb) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $withdraw$
DECLARE target record;
BEGIN
 -- Lock even if an earlier snapshot showed no captures. A concurrent first
 -- capture may be advancing its maximum: checking before this lock would let
 -- an edit commit without withdrawing the snapshot that just read old bytes.
 FOR target IN SELECT e.session_id FROM public.conversation_envelopes e
  WHERE e.session_id IN(SELECT (value->>''sessionId'')::uuid FROM jsonb_array_elements(targets))
  ORDER BY e.session_id FOR UPDATE OF e
 LOOP
  WITH change AS MATERIALIZED (
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(targets) item
    WHERE (item->>''sessionId'')::uuid=e.session_id
     AND coalesce((item->>''withdraw'')::boolean,true)
     AND (item->>''sequence'')::integer<=CASE WHEN (item->>''topicOnly'')::boolean
      THEN e.record_topic_captured_through ELSE e.record_captured_through END
     AND CASE WHEN (item->>''topicOnly'')::boolean THEN e.record_topic_captured_through ELSE e.record_captured_through END>0) AS advances
   FROM public.conversation_envelopes e WHERE e.session_id=target.session_id
  )
  UPDATE public.conversation_envelopes e SET record_data_revision=e.record_data_revision+1,
   record_dirty_from=least(e.record_dirty_from,(SELECT min((item->>''sequence'')::integer) FROM jsonb_array_elements(targets) item
    WHERE (item->>''sessionId'')::uuid=e.session_id)),
   version=e.version+change.advances::integer,
   record_captured_through=CASE WHEN change.advances THEN 0 ELSE e.record_captured_through END,
   record_topic_captured_through=CASE WHEN change.advances THEN 0 ELSE e.record_topic_captured_through END
  FROM change WHERE e.session_id=target.session_id;
 END LOOP;
END $withdraw$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_withdraw_conversation_record_rows() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $withdraw_rows$
DECLARE previous jsonb;following jsonb;targets jsonb:=''[]'';item jsonb;sid uuid;position integer;withdraw boolean:=true;
BEGIN
 IF TG_OP<>''INSERT'' THEN previous:=to_jsonb(OLD); END IF;
 IF TG_OP<>''DELETE'' THEN following:=to_jsonb(NEW); END IF;
 IF TG_OP=''UPDATE'' AND previous=following THEN RETURN NULL; END IF;
 IF TG_TABLE_NAME=''session_messages'' THEN
  IF TG_OP=''INSERT'' THEN PERFORM public.quarantine_unadmitted_conversation_append(NEW);END IF;
  IF TG_OP=''UPDATE'' AND (previous-ARRAY[''workspace_id'',''sensitivity'',''compartments'',''project_ids'',''scope_version'',
    ''channel_message_id'',''topic_label'',''topic_confidence'',''reply_to_text''])
   IS NOT DISTINCT FROM (following-ARRAY[''workspace_id'',''sensitivity'',''compartments'',''project_ids'',''scope_version'',
    ''channel_message_id'',''topic_label'',''topic_confidence'',''reply_to_text'']) THEN withdraw:=false; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(jsonb_build_array(previous,following)) WHERE value<>''null''
  LOOP
   targets:=targets||jsonb_build_array(jsonb_build_object(''sessionId'',item->>''session_id'',''sequence'',item->''sequence_num'',''topicOnly'',false,''withdraw'',withdraw));
  END LOOP;
 ELSIF TG_TABLE_NAME=''session_message_annotation_heads'' THEN
  IF TG_OP=''UPDATE'' AND previous=following THEN RETURN NULL; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(''sessionId'',m.session_id,''sequence'',m.sequence_num,''topicOnly'',true,''withdraw'',TG_OP<>''INSERT'')),''[]'') INTO targets
   FROM public.session_messages m WHERE m.id IN(SELECT (value->>''message_id'')::uuid
    FROM jsonb_array_elements(jsonb_build_array(previous,following)) WHERE value<>''null'');
 ELSIF TG_TABLE_NAME=''conversation_message_quarantine'' THEN
  IF TG_OP=''UPDATE'' AND previous=following THEN RETURN NULL; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(''sessionId'',m.session_id,''sequence'',m.sequence_num,''topicOnly'',false)),''[]'') INTO targets
   FROM public.session_messages m WHERE m.id IN(SELECT (value->>''message_id'')::uuid
    FROM jsonb_array_elements(jsonb_build_array(previous,following)) WHERE value<>''null'');
 ELSIF TG_TABLE_NAME=''scope_resource_states'' THEN
  IF TG_OP=''UPDATE'' AND previous->''review_state'' IS NOT DISTINCT FROM following->''review_state''
   AND previous->''resource_kind'' IS NOT DISTINCT FROM following->''resource_kind''
   AND previous->''resource_id'' IS NOT DISTINCT FROM following->''resource_id'' THEN RETURN NULL; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(jsonb_build_array(previous,following))
   WHERE value->>''review_state''=''held''
  LOOP
   IF item->>''resource_kind''=''session'' THEN
    targets:=targets||jsonb_build_array(jsonb_build_object(''sessionId'',item->>''resource_id'',''sequence'',0,''topicOnly'',false));
   ELSIF item->>''resource_kind''=''session_message'' THEN
    SELECT session_id,sequence_num INTO sid,position FROM public.session_messages WHERE id=(item->>''resource_id'')::uuid;
    IF FOUND THEN targets:=targets||jsonb_build_array(jsonb_build_object(''sessionId'',sid,''sequence'',position,''topicOnly'',false)); END IF;
   ELSIF item->>''resource_kind''=''session_context_revision'' THEN
    SELECT m.session_id,m.sequence_num INTO sid,position FROM public.session_message_annotation_heads h
     JOIN public.session_messages m ON m.id=h.message_id WHERE h.scope_revision_id=(item->>''resource_id'')::uuid;
    IF FOUND THEN targets:=targets||jsonb_build_array(jsonb_build_object(''sessionId'',sid,''sequence'',position,''topicOnly'',true)); END IF;
   END IF;
  END LOOP;
 ELSIF TG_TABLE_NAME=''session_context_scope_revisions'' THEN
  withdraw:=TG_OP=''DELETE'' OR previous->''scope_held'' IS DISTINCT FROM following->''scope_held'';
  SELECT coalesce(jsonb_agg(jsonb_build_object(''sessionId'',m.session_id,''sequence'',m.sequence_num,''topicOnly'',true,''withdraw'',withdraw)),''[]'') INTO targets
   FROM public.session_message_annotation_heads h JOIN public.session_messages m ON m.id=h.message_id
   WHERE h.scope_revision_id IN(SELECT (value->>''id'')::uuid FROM jsonb_array_elements(jsonb_build_array(previous,following)) WHERE value<>''null'');
 ELSIF TG_TABLE_NAME=''session_context_revision_contents'' THEN
  IF TG_OP=''UPDATE'' AND previous=following THEN RETURN NULL; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(''sessionId'',m.session_id,''sequence'',m.sequence_num,''topicOnly'',true)),''[]'') INTO targets
   FROM public.session_message_annotation_heads h JOIN public.session_messages m ON m.id=h.message_id
   WHERE h.scope_revision_id IN(SELECT (value->>''revision_id'')::uuid FROM jsonb_array_elements(jsonb_build_array(previous,following)) WHERE value<>''null'');
 END IF;
 PERFORM public.withdraw_conversation_record_targets(targets);
 RETURN NULL;
END $withdraw_rows$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_record_source(w uuid,capture_id uuid) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $source$
DECLARE o public.private_transcript_observations;e public.conversation_envelopes;s public.sessions;
BEGIN
 SELECT * INTO o FROM public.private_transcript_observations WHERE workspace_id=w AND id=capture_id;
 IF NOT FOUND OR o.binding->>''kind'' IS DISTINCT FROM ''conversation_record_v1'' THEN RETURN ''{"held":true}''; END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=o.session_id AND workspace_id=w;
 IF NOT FOUND OR o.binding->>''generation'' IS DISTINCT FROM e.version::text
  OR public.session_recording_read_allowed(o.session_id) IS NOT TRUE
  OR public.scope_review_state_held(''session'',o.session_id) THEN RETURN ''{"held":true}''; END IF;
 IF o.binding->''legacyRowsSelected''=''true''::jsonb THEN
  SELECT * INTO s FROM public.sessions WHERE id=o.session_id;
  IF NOT FOUND OR public.conversation_legacy_enrolled(s.id,w,s.user_id,s.assistant_id) IS NOT TRUE THEN
   RETURN ''{"held":true}'';END IF;
 END IF;
 -- A descriptor is metadata, never a reader/destination authorization. The
 -- admission owner checks current conversation audience; external derivatives
 -- additionally prove their selected lineage/current floor at the real write.
 RETURN jsonb_build_object(''workspaceId'',w,''resourceKind'',''conversation_record'',''resourceId'',o.id,''version'',''1'',
  ''userId'',NULL,''assistantId'',NULL,''sensitivity'',o.sensitivity,''compartments'',o.compartments,''projectIds'',o.project_ids,
  ''held'',false,''validTo'',NULL,''retractedAt'',NULL);
END $source$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_record_member_allowed(w uuid,capture_id uuid,actor uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $record_member$
DECLARE o public.private_transcript_observations;source jsonb;
BEGIN
 source:=public.read_conversation_record_source(w,capture_id);
 IF source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN false; END IF;
 SELECT * INTO o FROM public.private_transcript_observations WHERE workspace_id=w AND id=capture_id;
 RETURN public.conversation_member_read_allowed(w,o.session_id,actor) IS TRUE;
END $record_member$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_record_rows(e public.conversation_envelopes,after_sequence integer,through_sequence integer,
 legacy_allowed boolean,viewer uuid,visual boolean) RETURNS SETOF public.session_messages
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $rows$
 SELECT m.* FROM public.session_messages m
 LEFT JOIN public.session_legacy_history_messages frozen ON legacy_allowed AND frozen.message_id=m.id AND frozen.session_id=m.session_id
 WHERE m.session_id=e.session_id AND m.sequence_num>after_sequence AND (through_sequence IS NULL OR m.sequence_num<=through_sequence)
  AND m.role IN (''user'',''assistant'') AND m.scope_held IS NOT TRUE
  AND NOT EXISTS(SELECT 1 FROM public.scope_resource_states state WHERE state.resource_kind=''session_message''
   AND state.resource_id=m.id AND state.review_state=''held'')
  AND (m.user_id IS NULL OR m.user_id=e.starter_user_id)
  AND (m.user_id IS NULL OR e.visibility=''private_by_kind'' OR e.visibility=''configured_private'' AND (visual OR m.user_id=viewer)
   OR e.classification=''legacy_personal'' AND public.conversation_consent_current(e.session_id) AND (visual OR m.user_id=viewer))
  AND (
   (e.workspace_id IS NULL AND e.starter_user_id=viewer AND m.workspace_id IS NULL)
   OR (m.workspace_id=e.workspace_id AND m.scope_version IS NOT NULL AND m.sensitivity IN (''public'',''internal'',''confidential'')
    AND m.compartments IS NOT NULL AND m.project_ids IS NOT NULL
    AND NOT EXISTS(SELECT 1 FROM public.conversation_message_quarantine q WHERE q.message_id=m.id))
   OR (legacy_allowed AND e.visibility=''private_by_kind''
    AND m.workspace_id IS NULL AND m.user_id IS NULL AND m.assistant_id IS NULL AND m.sensitivity IS NULL
    AND m.compartments IS NULL AND m.project_ids IS NULL AND m.scope_version IS NULL
    AND (m.sender_user_id IS NULL OR m.sender_user_id=e.starter_user_id)
    AND frozen.sequence_num=m.sequence_num AND frozen.fingerprint=encode(sha256(convert_to(to_jsonb(m)::text,''UTF8'')),''hex'')
    AND NOT EXISTS(SELECT 1 FROM public.scope_derivations d WHERE d.resource_kind=''session_message'' AND d.resource_id=m.id)
    AND NOT EXISTS(SELECT 1 FROM public.scope_resource_states state WHERE state.resource_kind=''session_message'' AND state.resource_id=m.id)
    AND NOT EXISTS(SELECT 1 FROM public.conversation_message_quarantine q WHERE q.message_id=m.id AND q.reason<>''missing_stamp'')
    AND octet_length(m.content::text)<=131072)
   OR (visual AND e.workspace_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.conversation_legacy_page_guest_rows(e,after_sequence,through_sequence) g WHERE g.id=m.id))
  )
$rows$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_project_conversation_record(e public.conversation_envelopes,after_sequence integer,through_sequence integer,
 topic_through integer,legacy_allowed boolean,viewer uuid,exact_visual_rows jsonb DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $project_record$
DECLARE rows jsonb;annotations jsonb;row_identity text;annotation_identity text;manifest jsonb;legacy_rows_selected boolean;
BEGIN
 WITH selected AS MATERIALIZED(
  SELECT source.* FROM public.conversation_record_rows(e,after_sequence,through_sequence,legacy_allowed,viewer,false) source
   WHERE exact_visual_rows IS NULL
  UNION ALL
  SELECT source.* FROM jsonb_populate_recordset(NULL::public.session_messages,coalesce(exact_visual_rows,''[]''::jsonb)) source
   WHERE exact_visual_rows IS NOT NULL AND (source.user_id IS NULL OR e.visibility=''private_by_kind'' OR source.user_id=viewer)
 ), payload AS MATERIALIZED(
  SELECT m.sequence_num,jsonb_build_object(''id'',m.id,''sessionId'',m.session_id,''role'',m.role,''content'',m.content,
   ''sequenceNum'',m.sequence_num,''createdAt'',m.created_at,''senderUserId'',m.sender_user_id,
   ''senderAssistantId'',m.sender_assistant_id,''channelMessageId'',m.channel_message_id,''attachments'',m.attachments) value
  FROM selected m
 ), selected_annotations AS MATERIALIZED(
  SELECT m.sequence_num,jsonb_build_object(''id'',m.id,''sequenceNum'',m.sequence_num,''revisionId'',r.id,
   ''version'',r.scope_version::text,''content'',revision_content.content) value,
   jsonb_build_array(to_jsonb(head),to_jsonb(r),to_jsonb(revision_content)) original
  FROM selected m
  JOIN public.session_message_annotation_heads head ON head.message_id=m.id AND head.session_id=m.session_id AND head.workspace_id=e.workspace_id
  JOIN public.session_context_scope_revisions r ON r.id=head.scope_revision_id AND r.workspace_id=head.workspace_id
  JOIN public.session_context_revision_contents revision_content ON revision_content.revision_id=r.id AND revision_content.workspace_id=r.workspace_id
  WHERE m.sequence_num<=topic_through AND r.scope_held IS FALSE
   AND NOT EXISTS(SELECT 1 FROM public.scope_resource_states state
    WHERE state.resource_kind=''session_context_revision'' AND state.resource_id=r.id AND state.review_state=''held'')
 ) SELECT
  (SELECT coalesce(jsonb_agg(value ORDER BY sequence_num),''[]'') FROM payload),
  (SELECT coalesce(jsonb_agg(value ORDER BY sequence_num),''[]'') FROM selected_annotations),
  (SELECT encode(sha256(convert_to(coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.sequence_num),''[]'')::text,''UTF8'')),''hex'') FROM selected m),
  (SELECT encode(sha256(convert_to(coalesce(jsonb_agg(original ORDER BY sequence_num),''[]'')::text,''UTF8'')),''hex'') FROM selected_annotations),
  EXISTS(SELECT 1 FROM selected m WHERE m.workspace_id IS NULL)
 INTO rows,annotations,row_identity,annotation_identity,legacy_rows_selected;
 manifest:=jsonb_build_object(''afterSequence'',after_sequence,''throughSequence'',through_sequence,''topicThroughSequence'',topic_through,
  ''modelRecipe'',''dialogue_text_v1'',
  ''rowCount'',jsonb_array_length(rows),''annotationCount'',jsonb_array_length(annotations),
  ''rowIdentityDigest'',row_identity,''annotationIdentityDigest'',annotation_identity,
  ''payloadDigest'',encode(sha256(convert_to(jsonb_build_array(rows,annotations)::text,''UTF8'')),''hex''));
 RETURN jsonb_build_object(''rows'',rows,''annotations'',annotations,''manifest'',manifest,''legacyRowsSelected'',legacy_rows_selected);
END $project_record$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_capture_conversation_record_current(w uuid,sid uuid,after_sequence integer,through_sequence integer,topic_through integer,
 title_binding jsonb DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $capture$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 s public.sessions;e public.conversation_envelopes;legacy public.session_legacy_history;
 high integer;rows jsonb;annotations jsonb;projection jsonb;hard_projects uuid[];
 binding jsonb;manifest jsonb;capture_identity text;observed uuid;descriptor jsonb;legacy_rows_selected boolean;
BEGIN
 IF actor IS NULL OR after_sequence IS NULL OR through_sequence IS NULL OR topic_through IS NULL
  OR after_sequence<0 OR through_sequence<after_sequence OR topic_through<0 THEN
  RAISE EXCEPTION ''conversation_record_selection_invalid'' USING ERRCODE=''22023''; END IF;
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR UPDATE;
 IF NOT FOUND OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT coalesce(max(sequence_num),0) INTO high FROM public.session_messages WHERE session_id=sid;
 IF through_sequence>high OR topic_through>high THEN RAISE EXCEPTION ''conversation_record_selection_invalid'' USING ERRCODE=''22023''; END IF;
 hard_projects:=public.conversation_hard_project_ids(e.compartments);
 IF through_sequence>e.record_captured_through OR topic_through>e.record_topic_captured_through THEN
  UPDATE public.conversation_envelopes SET record_captured_through=greatest(record_captured_through,through_sequence),
   record_topic_captured_through=greatest(record_topic_captured_through,topic_through) WHERE session_id=sid;
 END IF;
 -- Preserve the reviewed frozen legacy cohort. Its original descriptor and
 -- complete row fingerprint are authority/provenance, not a newly invented
 -- missing-envelope exemption. Any later mutation/hold still withdraws it.
 IF e.visibility=''private_by_kind'' AND public.enroll_conversation_legacy_history(sid) THEN
  SELECT * INTO legacy FROM public.session_legacy_history h WHERE h.session_id=sid
   AND h.user_id=s.user_id AND h.workspace_id=w AND public.conversation_legacy_enrolled(sid,w,s.user_id,s.assistant_id);
 END IF;
 IF to_regprocedure(''public.read_compiled_conversation_payload(conversation_envelopes,integer,integer,integer,boolean,uuid,text)'') IS NOT NULL THEN
  projection:=public.read_compiled_conversation_payload(e,after_sequence,through_sequence,topic_through,legacy.session_id IS NOT NULL,actor,''dialogue_text_v1'');
  IF projection IS NULL THEN
   PERFORM public.enqueue_exact_conversation_record(e,after_sequence,through_sequence,topic_through,legacy.session_id IS NOT NULL);
  END IF;
 END IF;
 IF projection IS NULL THEN
  projection:=public.project_conversation_record(e,after_sequence,through_sequence,topic_through,legacy.session_id IS NOT NULL,actor);
 END IF;
 rows:=projection->''rows'';annotations:=projection->''annotations'';manifest:=projection->''manifest'';
 legacy_rows_selected:=(projection->>''legacyRowsSelected'')::boolean;
 binding:=jsonb_build_object(''kind'',''conversation_record_v1'',''sessionId'',sid,''generation'',e.version::text,
  ''readerUserId'',actor,''purpose'',CASE WHEN title_binding IS NULL THEN ''native_member_dialogue'' ELSE ''native_session_title'' END,
  ''recipe'',''dialogue_text_v1'',''legacyRowsSelected'',legacy_rows_selected)
  ||CASE WHEN title_binding IS NULL THEN ''{}''::jsonb ELSE jsonb_build_object(''titleBinding'',title_binding) END;
 -- Constant-size provenance per capture, independent of history depth. The
 -- selected row bytes/versions are hashed once during the already-required
 -- data acquisition; replay/read admission never walks that history again.
 capture_identity:=encode(sha256(convert_to(jsonb_build_array(w,sid,actor,binding,manifest,e.cap,e.compartments,hard_projects)::text,''UTF8'')),''hex'');
 INSERT INTO public.private_transcript_observations(workspace_id,session_id,user_id,binding,manifest,sensitivity,compartments,project_ids,identity)
 -- Retention belongs to the immutable conversation starter, not an incidental
 -- reader whose account deletion must not erase shared record provenance. The
 -- actual capturing reader remains bound above and in the capture identity.
 VALUES(w,sid,e.starter_user_id,binding,manifest,e.cap,e.compartments,hard_projects,capture_identity)
 ON CONFLICT(session_id,identity) DO NOTHING RETURNING id INTO observed;
 IF observed IS NULL THEN SELECT id INTO observed FROM public.private_transcript_observations o WHERE o.session_id=sid AND o.identity=capture_identity; END IF;
 descriptor:=public.read_conversation_record_source(w,observed);
 IF descriptor->>''held'' IS DISTINCT FROM ''false'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(''source'',descriptor-ARRAY[''held'',''validTo'',''retractedAt''],''rows'',rows,''annotations'',annotations,
  ''generation'',e.version::text,''dataRevision'',e.record_data_revision::text,''manifest'',manifest);
END $capture$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_capture_native_conversation_record(w uuid,sid uuid,device uuid,native_version integer,
 after_sequence integer,through_sequence integer,topic_through integer) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
BEGIN
 IF actor IS NULL OR EXISTS(SELECT 1 FROM pg_roles role JOIN pg_class rel ON rel.oid=''public.sessions''::regclass
  WHERE role.rolname=session_user AND (role.rolsuper OR role.rolbypassrls OR pg_has_role(role.oid,rel.relowner,''USAGE''))) THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM a.id FROM public.auth_sessions a JOIN public.users u ON u.id=a.user_id
  WHERE a.id=device AND a.user_id=actor AND a.auth_version=native_version AND u.auth_version=native_version
   AND a.revoked_at IS NULL AND a.expires_at>clock_timestamp() FOR SHARE OF a,u;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 RETURN public.capture_conversation_record_current(w,sid,after_sequence,through_sequence,topic_through);
END $native$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_record_turn_facts(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, boundary text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $facts$
DECLARE s public.sessions;e public.conversation_envelopes;a public.assistants;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
  OR actor IS DISTINCT FROM credential_actor OR token IS NULL
  OR include_departments IS NULL OR include_policy IS NULL
  OR boundary IS NULL OR boundary NOT IN(''history'',''dispatch'',''frame'',''publication'',''stopped_publication'')
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
    WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;

 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM device_row.id FROM public.auth_sessions device_row JOIN public.users u ON u.id=device_row.user_id
  WHERE device_row.id=device AND device_row.user_id=actor AND device_row.auth_version=native_version
   AND u.auth_version=native_version AND device_row.revoked_at IS NULL AND device_row.expires_at>clock_timestamp()
  FOR SHARE OF device_row,u;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT * INTO a FROM public.assistants WHERE id=answering AND workspace_id=w FOR SHARE;
 IF NOT FOUND OR public.assistant_placement_visible(actor,answering) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;

 SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
 IF NOT FOUND OR s.last_turn_lease_token IS DISTINCT FROM token
  OR coalesce(s.turn_assistant_id,s.assistant_id) IS DISTINCT FROM answering
  OR (
   s.turn_lease_token IS NOT DISTINCT FROM token AND s.status=''running''
    AND s.turn_heartbeat_at>clock_timestamp()-interval ''90 seconds''
    AND (s.cancel_requested_at IS NULL OR boundary=''stopped_publication'')
   OR boundary=''stopped_publication'' AND s.turn_lease_token IS NULL AND s.turn_end_reason=''stopped_by_user''
  ) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF s.workspace_id IS DISTINCT FROM w AND (s.workspace_id IS NOT NULL OR s.user_id IS DISTINCT FROM actor
  OR s.assistant_id IS DISTINCT FROM answering OR boundary IN(''publication'',''stopped_publication'')
  OR (boundary=''history'' AND public.enroll_conversation_legacy_history(sid) IS NOT TRUE)
  OR public.conversation_legacy_enrolled(sid,w,actor,answering) IS NOT TRUE)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 -- Acquisition already takes UPDATE to maintain the capture watermark.
 -- Taking it here avoids upgrading a SHARE lock under two readers.
 IF boundary=''history'' THEN
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR UPDATE;
 ELSE
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR SHARE;
 END IF;
 IF NOT FOUND OR public.sensitivity_rank(a.clearance)<public.sensitivity_rank(e.cap)
  OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(
  ''authority'',public.read_session_authority_facts(w,actor,answering,sid,device,native_version,credential_actor,include_departments,include_policy),
  ''destination'',jsonb_build_object(''sensitivity'',e.cap,''compartments'',e.compartments,
   ''projectIds'',public.conversation_hard_project_ids(e.compartments),''generation'',e.version::text));
END $facts$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_capture_native_turn_conversation_record(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, after_sequence integer, through_sequence integer, topic_through integer) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $history$
DECLARE facts jsonb;high integer;
BEGIN
 facts:=public.conversation_record_turn_facts(w,actor,answering,sid,device,native_version,credential_actor,
  include_departments,include_policy,token,''history'');
 SELECT coalesce(max(sequence_num),0) INTO high FROM public.session_messages WHERE session_id=sid;
 through_sequence:=coalesce(through_sequence,high);
 topic_through:=coalesce(topic_through,through_sequence);
 after_sequence:=least(after_sequence,through_sequence);
 RETURN facts || jsonb_build_object(''record'',public.capture_conversation_record_current(w,sid,after_sequence,through_sequence,topic_through));
END $history$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_admit_native_turn_conversation_records(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, boundary text, capture_ids uuid[], capture_versions text[]) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $admission$
DECLARE facts jsonb;admitted jsonb;
BEGIN
 IF boundary NOT IN(''dispatch'',''frame'',''publication'',''stopped_publication'') OR capture_ids IS NULL
  OR capture_versions IS NULL OR cardinality(capture_ids) NOT BETWEEN 1 AND 4096
  OR cardinality(capture_ids)<>cardinality(capture_versions) OR array_position(capture_ids,NULL) IS NOT NULL
  OR EXISTS(SELECT 1 FROM unnest(capture_versions) v WHERE v IS DISTINCT FROM ''1'')
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 facts:=public.conversation_record_turn_facts(w,actor,answering,sid,device,native_version,credential_actor,
  include_departments,include_policy,token,boundary);
 WITH proven AS MATERIALIZED(
  SELECT ids.ord,public.read_conversation_record_source(w,o.id) AS snapshot
  FROM unnest(capture_ids) WITH ORDINALITY ids(id,ord)
  JOIN public.private_transcript_observations o ON o.workspace_id=w AND o.session_id=sid AND o.id=ids.id
  WHERE o.binding->>''kind''=''conversation_record_v1'' AND o.binding->>''purpose''=''native_member_dialogue''
   AND o.binding->>''readerUserId''=actor::text AND o.binding->>''generation''=facts#>>''{destination,generation}''
 )
 SELECT jsonb_agg(snapshot-ARRAY[''held'',''validTo'',''retractedAt''] ORDER BY ord) INTO admitted
 FROM proven WHERE snapshot->>''held''=''false'';
 IF coalesce(jsonb_array_length(admitted),0)<>cardinality(capture_ids)
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN facts || jsonb_build_object(''records'',admitted);
END $admission$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_record_publication_source(w uuid,capture_id uuid,sid uuid,actor uuid,title_purpose boolean DEFAULT false)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $source$
DECLARE source jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.private_transcript_observations o WHERE o.workspace_id=w AND o.id=capture_id
   AND o.session_id=sid AND o.binding->>''kind''=''conversation_record_v1''
   AND (o.binding->>''purpose''=''native_member_dialogue'' AND NOT title_purpose
    OR o.binding->>''purpose''=''native_session_title'' AND title_purpose AND o.binding->>''readerUserId''=actor::text))
 THEN RETURN ''{"held":true}'';END IF;
 PERFORM session_id FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR SHARE;
 IF NOT FOUND OR public.conversation_member_read_allowed(w,sid,actor) IS NOT TRUE THEN RETURN ''{"held":true}'';END IF;
 source:=public.read_conversation_record_source(w,capture_id);
 RETURN source;
END $source$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_record_for_write(w uuid,capture_id uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $snapshot$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;sid uuid;source jsonb;
BEGIN
 IF nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL THEN RETURN ''{"held":true}'';END IF;
 SELECT o.session_id INTO sid FROM public.private_transcript_observations o WHERE o.workspace_id=w AND o.id=capture_id
  AND o.binding->>''purpose''=''native_member_dialogue'';
 IF NOT FOUND OR actor IS NULL THEN RETURN ''{"held":true}'';END IF;
 PERFORM e.session_id FROM public.conversation_envelopes e WHERE e.session_id=sid AND e.workspace_id=w FOR SHARE;
 IF NOT FOUND OR public.conversation_member_read_allowed(w,sid,actor) IS NOT TRUE THEN RETURN ''{"held":true}'';END IF;
 source:=public.read_conversation_record_source(w,capture_id);
 RETURN source;
END $snapshot$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_record_lineage_roots(w uuid,capture_id uuid,actor uuid)
RETURNS TABLE(kind text,id uuid,version text)
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $roots$
DECLARE o public.private_transcript_observations;e public.conversation_envelopes;projection jsonb;
BEGIN
 SELECT * INTO o FROM public.private_transcript_observations WHERE workspace_id=w AND private_transcript_observations.id=capture_id;
 IF NOT FOUND OR o.binding->>''purpose'' IS DISTINCT FROM ''native_member_dialogue''
  OR o.binding->''legacyRowsSelected'' IS DISTINCT FROM ''false''::jsonb
  OR public.conversation_record_member_allowed(w,capture_id,actor) IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=o.session_id AND workspace_id=w FOR SHARE;
 IF NOT FOUND OR o.binding->>''generation'' IS DISTINCT FROM e.version::text
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 projection:=public.project_conversation_record(e,(o.manifest->>''afterSequence'')::integer,(o.manifest->>''throughSequence'')::integer,
  (o.manifest->>''topicThroughSequence'')::integer,false,(o.binding->>''readerUserId'')::uuid);
 IF projection->''manifest'' IS DISTINCT FROM o.manifest THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 RETURN QUERY
  SELECT ''session_message''::text,m.id,m.scope_version::text FROM jsonb_array_elements(projection->''rows'') item
   JOIN public.session_messages m ON m.id=(item->>''id'')::uuid AND m.session_id=o.session_id AND m.workspace_id=w
  UNION ALL SELECT ''session_context_revision''::text,(item->>''revisionId'')::uuid,item->>''version''
   FROM jsonb_array_elements(projection->''annotations'') item;
END $roots$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_require_conversation_record_current_lineage(w uuid,capture_id uuid,actor uuid,d public.scope_derivations)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $lineage$
DECLARE node record;snapshot jsonb;seen integer:=0;
BEGIN
 FOR node IN WITH RECURSIVE lineage(kind,id,version) AS (
  SELECT ''conversation_record''::text,capture_id,''1''::text
  UNION SELECT next.kind,next.id,next.version FROM lineage l CROSS JOIN LATERAL (
   SELECT r.* FROM public.conversation_record_lineage_roots(w,l.id,actor) r WHERE l.kind=''conversation_record''
   UNION ALL SELECT e.* FROM public.conversation_source_edges(w,l.kind,l.id,l.version) e WHERE l.kind<>''conversation_record''
  ) next
 ) SELECT l.* FROM lineage l LIMIT 4097 LOOP
  seen:=seen+1;
  IF seen>4096 OR node.version IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  IF node.kind=''conversation_record'' THEN
   IF node.version IS DISTINCT FROM ''1'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
   CONTINUE;
  END IF;
  -- These leaves have additional independent, source-family authority. A
  -- metadata snapshot cannot stand in for their native read/retain proof.
  IF node.kind NOT IN(''session_message'',''session_context_revision'',''memory'',''task'',''workspace_file'',''entity'',''entity_link'',''episode'')
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  snapshot:=public.read_scope_source(w,node.kind,node.id);
  IF snapshot->>''held'' IS DISTINCT FROM ''false'' OR snapshot->>''version'' IS DISTINCT FROM node.version
   OR snapshot->>''validTo'' IS NOT NULL OR snapshot->>''retractedAt'' IS NOT NULL
   OR snapshot->>''workspaceId'' IS DISTINCT FROM w::text
   OR snapshot->>''userId'' IS NOT NULL AND snapshot->>''userId'' IS DISTINCT FROM d.user_id::text
   OR snapshot->>''assistantId'' IS NOT NULL AND snapshot->>''assistantId'' IS DISTINCT FROM d.assistant_id::text
   OR (public.sensitivity_rank(snapshot->>''sensitivity'')<=public.sensitivity_rank(d.sensitivity)
    AND to_jsonb(d.compartments) @> (snapshot->''compartments'') AND to_jsonb(d.project_ids) @> (snapshot->''projectIds'')) IS NOT TRUE
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 END LOOP;
END $lineage$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_anchor_key(sid uuid) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $key$
 SELECT CASE s.anchor_kind
  WHEN ''none'' THEN ''[]''::jsonb
  WHEN ''doc_thread'' THEN (SELECT jsonb_build_array(''page'',ct.page_id) FROM public.comment_threads ct WHERE ct.session_id=sid)
  WHEN ''office_file'' THEN (SELECT jsonb_build_array(''office'',l.artifact_id) FROM public.office_artifact_sessions l WHERE l.session_id=sid)
  WHEN ''feed_draft'' THEN jsonb_build_array(''feed'',sid)
  WHEN ''feed_thread'' THEN (SELECT jsonb_build_array(''feed'',t.session_id) FROM public.feed_comment_threads t WHERE t.transcript_session_id=sid)
  WHEN ''channel'' THEN jsonb_build_array(''channel'',s.assistant_id,s.channel_type,s.channel_id)
 END FROM public.sessions s WHERE s.id=sid
$key$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_require_conversation_record_edge(w uuid,did uuid,capture_id uuid,source_version text)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $edge$
DECLARE d public.scope_derivations;destination_id uuid;source jsonb;e public.conversation_envelopes;origin public.conversation_envelopes;
 o public.private_transcript_observations;original_anchor jsonb;one_reader uuid;
 destination jsonb;
 source_readers uuid[];destination_readers uuid[];
 actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
BEGIN
 SELECT * INTO d FROM public.scope_derivations WHERE workspace_id=w AND id=did;
 IF NOT FOUND OR source_version IS DISTINCT FROM ''1'' THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 IF d.resource_kind=''session_message'' THEN
  SELECT m.session_id INTO destination_id FROM public.session_messages m
  WHERE m.workspace_id=w AND m.id=d.resource_id AND m.scope_held IS FALSE AND m.scope_version::text=d.resource_version;
 ELSIF d.resource_kind=''session_context_revision'' THEN
  SELECT r.session_id INTO destination_id FROM public.session_context_scope_revisions r
  WHERE r.workspace_id=w AND r.id=d.resource_id AND r.scope_held IS FALSE AND r.scope_version::text=d.resource_version
   AND r.parent_kind IN(''turn_frame'',''message_annotation'',''session_title'',''compact_summary'');
 END IF;
 SELECT * INTO o FROM public.private_transcript_observations WHERE workspace_id=w AND id=capture_id;
 IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 IF destination_id=o.session_id THEN
  source:=public.conversation_record_publication_source(w,capture_id,destination_id,actor,o.binding->>''purpose''=''native_session_title'');
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=destination_id AND workspace_id=w;
  IF NOT FOUND OR source->>''held'' IS DISTINCT FROM ''false''
   OR public.sensitivity_rank(d.sensitivity)<>public.sensitivity_rank(e.cap)
   OR NOT (to_jsonb(d.compartments) @> (source->''compartments'') AND e.compartments @> d.compartments)
   OR NOT (to_jsonb(d.project_ids) @> (source->''projectIds'') AND public.conversation_hard_project_ids(e.compartments) @> d.project_ids)
   OR d.user_id IS NOT NULL AND d.user_id<>e.starter_user_id
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  RETURN;
 END IF;
 source:=public.read_conversation_record_for_write(w,capture_id);
 SELECT * INTO origin FROM public.conversation_envelopes WHERE session_id=o.session_id AND workspace_id=w;
 IF NOT FOUND OR source->>''held'' IS DISTINCT FROM ''false''
  OR (public.sensitivity_rank(origin.cap)<=public.sensitivity_rank(d.sensitivity)
   AND origin.compartments<@d.compartments AND public.conversation_hard_project_ids(origin.compartments)<@d.project_ids) IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 original_anchor:=public.conversation_anchor_key(origin.session_id);
 IF original_anchor IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 IF destination_id IS NULL THEN
  -- An unresolved transcript output is never a non-conversation destination.
  -- Reacquire the real current output, including its canonical identity and
  -- audience pair, before trusting any labels in the derivation declaration.
  IF d.resource_kind NOT IN(''memory'',''task'',''workspace_file'') THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  destination:=public.read_scope_source(w,d.resource_kind,d.resource_id);
  IF destination->>''held'' IS DISTINCT FROM ''false'' OR destination->>''workspaceId'' IS DISTINCT FROM w::text
   OR destination->>''version'' IS DISTINCT FROM d.resource_version
   OR destination->>''retractedAt'' IS NOT NULL OR destination->>''validTo'' IS NOT NULL
   OR destination->>''userId'' IS DISTINCT FROM d.user_id::text OR destination->>''assistantId'' IS DISTINCT FROM d.assistant_id::text
   OR destination->>''sensitivity'' IS DISTINCT FROM d.sensitivity
   OR NOT ((destination->''compartments'') @> to_jsonb(d.compartments) AND to_jsonb(d.compartments) @> (destination->''compartments''))
   OR NOT ((destination->''projectIds'') @> to_jsonb(d.project_ids) AND to_jsonb(d.project_ids) @> (destination->''projectIds''))
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  one_reader:=d.user_id;
  IF origin.visibility<>''workspace'' AND one_reader IS NULL OR original_anchor<>''[]''::jsonb AND one_reader IS NULL
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 ELSE
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=destination_id AND workspace_id=w FOR SHARE;
  IF NOT FOUND OR public.conversation_member_read_current(w,destination_id,actor) IS NOT TRUE
   OR public.sensitivity_rank(origin.cap)>public.sensitivity_rank(e.cap) OR NOT origin.compartments<@e.compartments
   OR origin.visibility=''private_by_kind'' AND e.visibility<>''private_by_kind''
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  IF e.visibility=''private_by_kind'' THEN one_reader:=e.starter_user_id;END IF;
  IF origin.visibility<>''workspace'' THEN
   source_readers:=ARRAY[origin.starter_user_id]||ARRAY(SELECT user_id FROM public.conversation_participants WHERE session_id=origin.session_id);
   destination_readers:=ARRAY[e.starter_user_id]||ARRAY(SELECT user_id FROM public.conversation_participants WHERE session_id=e.session_id);
   IF e.visibility=''workspace'' OR NOT destination_readers<@source_readers
   THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  END IF;
  IF original_anchor<>''[]''::jsonb AND original_anchor IS DISTINCT FROM public.conversation_anchor_key(e.session_id) AND one_reader IS NULL
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 END IF;
 IF one_reader IS NOT NULL AND public.conversation_member_read_allowed(w,origin.session_id,one_reader) IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
 PERFORM public.require_conversation_record_current_lineage(w,capture_id,actor,d);
END $edge$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_native_conversation_read_credential(device uuid,native_version integer,lock_credential boolean)
RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $credential$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
BEGIN
 IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 IF lock_credential THEN
  PERFORM a.id FROM public.auth_sessions a JOIN public.users u ON u.id=a.user_id
   WHERE a.id=device AND a.user_id=actor AND a.auth_version=native_version AND u.auth_version=native_version
    AND a.revoked_at IS NULL AND a.expires_at>clock_timestamp() FOR SHARE OF a,u;
 ELSE
  PERFORM a.id FROM public.auth_sessions a JOIN public.users u ON u.id=a.user_id
   WHERE a.id=device AND a.user_id=actor AND a.auth_version=native_version AND u.auth_version=native_version
    AND a.revoked_at IS NULL AND a.expires_at>clock_timestamp();
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 RETURN actor;
END $credential$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_native_conversation_history(sid uuid,device uuid,native_version integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $history$
DECLARE actor uuid:=public.native_conversation_read_credential(device,native_version,false);
 e public.conversation_envelopes;s public.sessions;w uuid;legacy_allowed boolean:=false;
 rows jsonb;compiled_rows jsonb;guest_name text;
BEGIN
 e:=public.conversation_envelope_for_reader(sid,actor);
 IF e.session_id IS NULL THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 w:=e.workspace_id;
 IF w IS NOT NULL THEN
  PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
  PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 END IF;
 PERFORM public.native_conversation_read_credential(device,native_version,true);
 SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id IS NOT DISTINCT FROM w FOR SHARE;
 IF NOT FOUND OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 IF w IS NOT NULL AND e.visibility=''private_by_kind'' THEN
  legacy_allowed:=public.enroll_conversation_legacy_history(sid) AND public.conversation_legacy_enrolled(sid,w,s.user_id,s.assistant_id);
 END IF;
 IF s.anchor_kind=''doc_thread'' THEN
  SELECT ct.external_author_name INTO guest_name FROM public.comment_threads ct WHERE ct.session_id=sid AND ct.workspace_id=w;
 END IF;
 IF to_regprocedure(''public.read_compiled_conversation_payload(conversation_envelopes,integer,integer,integer,boolean,uuid,text)'') IS NOT NULL THEN
  compiled_rows:=public.read_compiled_conversation_payload(e,0,NULL,NULL,legacy_allowed,actor,''visual_rows_v1'')->''rows'';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',m.id,''sequence'',m.sequence_num,''role'',m.role,
  ''timestamp'',m.created_at,''content'',m.content,''senderUserId'',m.sender_user_id,''senderAssistantId'',m.sender_assistant_id,
  ''publishedSenderName'',m.published_sender_name,''replyToText'',content.content->>''replyToText'',''attachments'',coalesce(m.attachments,''[]''),
  ''senderName'',coalesce(u.name,u.email),''senderAvatarUrl'',u.avatar_url,
  ''authoredByViewer'',coalesce(m.sender_user_id=actor,m.role=''user'' AND e.visibility=''private_by_kind'' AND e.starter_user_id=actor))
  ORDER BY m.sequence_num),''[]'') INTO rows
 FROM (
  SELECT source.* FROM public.conversation_record_rows(e,0,NULL,legacy_allowed,actor,true) source WHERE compiled_rows IS NULL
  UNION ALL
  SELECT source.* FROM jsonb_populate_recordset(NULL::public.session_messages,coalesce(compiled_rows,''[]''::jsonb)) source
 ) m
 LEFT JOIN public.users u ON u.id=m.sender_user_id
 LEFT JOIN public.session_message_annotation_heads head ON head.message_id=m.id AND head.session_id=sid AND head.workspace_id=w
 LEFT JOIN public.session_context_scope_revisions r ON r.id=head.scope_revision_id AND r.workspace_id=head.workspace_id
  AND r.scope_held IS FALSE AND NOT public.scope_review_state_held(''session_context_revision'',r.id)
 LEFT JOIN public.session_context_revision_contents content ON content.revision_id=r.id AND content.workspace_id=r.workspace_id;
 RETURN jsonb_build_object(''sessionId'',sid,''version'',e.version,''guestName'',guest_name,''rows'',rows);
END $history$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_rls_session_current(sid uuid) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $session$
 SELECT nullif(current_setting(''app.application_id'',true),'''') IS NULL
  AND EXISTS(SELECT 1 FROM public.conversation_envelopes e WHERE e.session_id=sid
   AND public.conversation_member_read_current(e.workspace_id,sid,nullif(current_setting(''app.current_user_id'',true),'''')::uuid))
$session$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_rls_message_current(sid uuid,mid uuid,sequence integer) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $message$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 e public.conversation_envelopes;s public.sessions;legacy_allowed boolean:=false;
BEGIN
 IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL OR sequence<1 THEN RETURN false;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 IF NOT FOUND OR public.conversation_member_read_current(e.workspace_id,sid,actor) IS NOT TRUE THEN RETURN false;END IF;
 IF e.workspace_id IS NOT NULL AND e.visibility=''private_by_kind'' THEN
  SELECT * INTO s FROM public.sessions WHERE id=sid;
  legacy_allowed:=public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
 END IF;
 RETURN EXISTS(SELECT 1 FROM public.conversation_record_rows(e,sequence-1,sequence,legacy_allowed,actor,true) m
  WHERE m.id=mid AND lower(m.content::text) NOT LIKE ''%<attached_file%''
   AND CASE jsonb_typeof(m.content) WHEN ''string'' THEN true WHEN ''array'' THEN NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(m.content) block WHERE CASE jsonb_typeof(block) WHEN ''object'' THEN
     block->>''type'' IS DISTINCT FROM ''text'' OR jsonb_typeof(block->''text'') IS DISTINCT FROM ''string''
     OR block-ARRAY[''type'',''text'']<>''{}''::jsonb ELSE true END) ELSE false END);
END $message$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_searchable_text(content jsonb) RETURNS text
LANGUAGE sql IMMUTABLE SET search_path=pg_catalog,public,pg_temp AS $text$
 SELECT CASE WHEN jsonb_path_exists(content,''$[*] ? (@.type == "tool_use" || @.type == "tool_result" || @.type == "host_observation")'') THEN NULL
  ELSE btrim(regexp_replace(CASE jsonb_typeof(content) WHEN ''string'' THEN content#>>''{}''
   WHEN ''array'' THEN (SELECT string_agg(block->>''text'','' '' ORDER BY ordinality)
    FROM jsonb_array_elements(content) WITH ORDINALITY blocks(block,ordinality) WHERE block->>''type''=''text'') END,
   ''<attached_file([[:space:]][^>]*|)>.*?(</attached_file>|$)'','''', ''gi'')) END
$text$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_search_text_current(sid uuid) RETURNS text
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $search$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 e public.conversation_envelopes;s public.sessions;legacy_allowed boolean:=false;
BEGIN
 IF public.conversation_rls_session_current(sid) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 IF e.workspace_id IS NOT NULL AND e.visibility=''private_by_kind'' THEN
  SELECT * INTO s FROM public.sessions WHERE id=sid;
  legacy_allowed:=public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
 END IF;
 RETURN (SELECT string_agg(public.conversation_searchable_text(m.content),'' '' ORDER BY m.sequence_num)
  FROM public.conversation_record_rows(e,0,NULL,legacy_allowed,actor,true) m);
END $search$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_conversation_title_current(sid uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $title$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 e public.conversation_envelopes;s public.sessions;head_id uuid;label text;legacy_allowed boolean:=false;
BEGIN
 IF public.conversation_rls_session_current(sid) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid;
 SELECT h.scope_revision_id INTO head_id FROM public.session_title_heads h WHERE h.session_id=sid AND h.workspace_id=e.workspace_id;
 IF head_id IS NOT NULL THEN
  SELECT c.content->>''title'' INTO label FROM public.session_context_scope_revisions r
   JOIN public.session_context_revision_contents c ON c.workspace_id=r.workspace_id AND c.revision_id=r.id
   WHERE r.id=head_id AND r.workspace_id=e.workspace_id AND r.session_id=sid AND r.parent_kind=''session_title''
    AND NOT r.scope_held AND NOT public.scope_review_state_held(''session_context_revision'',r.id)
    AND public.conversation_title_record_current(e,r.id);
  RETURN CASE WHEN label IS NULL THEN NULL ELSE jsonb_build_object(''title'',label,''titleRevisionId'',head_id) END;
 END IF;
 IF e.workspace_id IS NOT NULL AND e.visibility=''private_by_kind'' THEN
  SELECT * INTO s FROM public.sessions WHERE id=sid;
  legacy_allowed:=public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
 END IF;
 SELECT left(nullif(public.conversation_searchable_text(m.content),''''),200) INTO label
  FROM public.conversation_record_rows(e,0,NULL,legacy_allowed,actor,true) m
  WHERE m.role=''user'' AND nullif(public.conversation_searchable_text(m.content),'''') IS NOT NULL
  ORDER BY m.sequence_num LIMIT 1;
 RETURN CASE WHEN label IS NULL THEN NULL ELSE jsonb_build_object(''title'',label,''titleRevisionId'',NULL) END;
END $title$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_title_record_current(e public.conversation_envelopes,title_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $current$
DECLARE capture public.private_transcript_observations;actor uuid;generation bigint;projection jsonb;s public.sessions;legacy_allowed boolean:=false;
BEGIN
 FOR capture IN SELECT o.* FROM public.scope_derivations title
  JOIN public.scope_derivation_sources parent ON parent.workspace_id=title.workspace_id AND parent.derivation_id=title.id
   AND parent.source_kind=''session_context_revision''
  JOIN public.scope_derivations frame ON frame.workspace_id=parent.workspace_id AND frame.resource_kind=parent.source_kind
   AND frame.resource_id=parent.source_id AND frame.resource_version=parent.source_version
  JOIN public.scope_derivation_sources record ON record.workspace_id=frame.workspace_id AND record.derivation_id=frame.id
   AND record.source_kind=''conversation_record'' AND record.source_version=''1''
  LEFT JOIN public.private_transcript_observations o ON o.workspace_id=record.workspace_id AND o.id=record.source_id
  WHERE title.workspace_id=e.workspace_id AND title.resource_kind=''session_context_revision'' AND title.resource_id=title_id
 LOOP
  IF capture.id IS NULL OR capture.session_id IS DISTINCT FROM e.session_id
   OR capture.binding->>''purpose'' IS DISTINCT FROM ''native_session_title'' THEN RETURN false;END IF;
  generation:=(capture.binding->>''generation'')::bigint;
  IF generation IS NULL OR generation>e.version THEN RETURN false;END IF;
  IF capture.binding->''legacyRowsSelected''=''true''::jsonb THEN
   SELECT * INTO s FROM public.sessions WHERE id=e.session_id;
   legacy_allowed:=public.conversation_legacy_enrolled(e.session_id,e.workspace_id,s.user_id,s.assistant_id);
   IF NOT legacy_allowed THEN RETURN false;END IF;
  END IF;
  -- An audit accounts for a settings-only generation. Only a withdrawal
  -- requires comparing this title''s bounded, originally selected dialogue.
  IF generation<e.version AND e.version-generation>(SELECT count(*) FROM public.conversation_visibility_audit a
   WHERE a.session_id=e.session_id AND a.next_version>generation AND a.next_version<=e.version) THEN
   actor:=(capture.binding->>''readerUserId'')::uuid;
   projection:=public.project_conversation_record(e,(capture.manifest->>''afterSequence'')::integer,
    (capture.manifest->>''throughSequence'')::integer,(capture.manifest->>''topicThroughSequence'')::integer,legacy_allowed,actor);
   IF (projection->''manifest''->''payloadDigest'') IS DISTINCT FROM capture.manifest->''payloadDigest'' THEN RETURN false;END IF;
  END IF;
 END LOOP;
 RETURN true;
END $current$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_native_conversation_title_context(sid uuid,device uuid,native_version integer,answering uuid,mutation boolean)
RETURNS public.conversation_envelopes
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $context$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;w uuid;
 s public.sessions;e public.conversation_envelopes;assistant_clearance text;
BEGIN
 IF actor IS NULL OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 SELECT workspace_id INTO w FROM public.conversation_envelopes WHERE session_id=sid;
 IF w IS NULL THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 PERFORM public.native_conversation_read_credential(device,native_version,true);
 SELECT clearance INTO assistant_clearance FROM public.assistants WHERE id=answering AND workspace_id=w FOR SHARE;
 IF NOT FOUND OR public.assistant_placement_visible(actor,answering) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 IF mutation THEN SELECT * INTO s FROM public.sessions WHERE id=sid AND workspace_id=w FOR UPDATE;
 ELSE SELECT * INTO s FROM public.sessions WHERE id=sid AND workspace_id=w FOR SHARE;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w;
 IF NOT FOUND OR s.id IS NULL OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE
  OR public.sensitivity_rank(assistant_clearance)<public.sensitivity_rank(e.cap)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 RETURN e;
END $context$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_prepare_native_conversation_title(sid uuid,device uuid,native_version integer,answering uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $prepare$
DECLARE e public.conversation_envelopes;actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 head_id uuid;previous jsonb;turn_count integer:=0;through_sequence integer;capture jsonb;legacy_allowed boolean:=false;
 s public.sessions;
BEGIN
 e:=public.native_conversation_title_context(sid,device,native_version,answering,false);
 SELECT h.scope_revision_id INTO head_id FROM public.session_title_heads h WHERE h.session_id=sid AND h.workspace_id=e.workspace_id;
 IF head_id IS NOT NULL THEN
  SELECT c.content INTO previous FROM public.session_context_scope_revisions r
   JOIN public.session_context_revision_contents c ON c.workspace_id=r.workspace_id AND c.revision_id=r.id
   WHERE r.id=head_id AND r.workspace_id=e.workspace_id AND r.session_id=sid AND r.parent_kind=''session_title'' AND NOT r.scope_held
    AND NOT public.scope_review_state_held(''session_context_revision'',r.id)
    AND public.session_context_payload_shape(''session_title'',c.content);
 END IF;
 IF previous->''manual'' IS DISTINCT FROM ''true''::jsonb THEN
  IF previous IS NOT NULL THEN
   SELECT * INTO s FROM public.sessions WHERE id=sid;
   IF e.visibility=''private_by_kind'' THEN
    legacy_allowed:=public.enroll_conversation_legacy_history(sid)
     AND public.conversation_legacy_enrolled(sid,e.workspace_id,s.user_id,s.assistant_id);
   END IF;
   SELECT count(*)::int INTO turn_count FROM public.conversation_record_rows(e,0,NULL,legacy_allowed,actor,false) m
    WHERE m.role=''user'' AND public.conversation_searchable_text(m.content) IS NOT NULL;
  END IF;
  SELECT coalesce(max(selected.sequence_num),0) INTO through_sequence FROM (
   SELECT m.sequence_num FROM public.session_messages m WHERE m.session_id=sid ORDER BY m.sequence_num LIMIT 10
  ) selected;
  capture:=public.capture_conversation_record_current(e.workspace_id,sid,0,through_sequence,0,
   jsonb_build_object(''deviceId'',device,''authVersion'',native_version,''assistantId'',answering,''headId'',head_id));
 END IF;
 RETURN jsonb_build_object(''sessionId'',sid,''workspaceId'',e.workspace_id,''headId'',head_id,''previous'',previous,
  ''turnCount'',turn_count,''throughSequence'',through_sequence,''record'',capture);
END $prepare$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_require_native_conversation_title_capture(w uuid,sid uuid,device uuid,native_version integer,
 answering uuid,capture_id uuid,expected_head uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $capture$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;source jsonb;current_head uuid;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.private_transcript_observations o WHERE o.workspace_id=w AND o.id=capture_id AND o.session_id=sid
  AND o.binding->>''purpose''=''native_session_title'' AND o.binding->>''readerUserId''=actor::text
  AND o.binding->''titleBinding''=jsonb_build_object(''deviceId'',device,''authVersion'',native_version,''assistantId'',answering,''headId'',expected_head))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 source:=public.conversation_record_publication_source(w,capture_id,sid,actor,true);
 IF source->>''held'' IS DISTINCT FROM ''false'' THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 SELECT h.scope_revision_id INTO current_head FROM public.session_title_heads h WHERE h.session_id=sid AND h.workspace_id=w;
 IF current_head IS DISTINCT FROM expected_head THEN RETURN NULL;END IF;
 RETURN source-ARRAY[''held'',''validTo'',''retractedAt''];
END $capture$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_check_native_conversation_title(sid uuid,device uuid,native_version integer,answering uuid,capture_id uuid,
 expected_head uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $check$
DECLARE e public.conversation_envelopes;
BEGIN
 e:=public.native_conversation_title_context(sid,device,native_version,answering,false);
 RETURN public.require_native_conversation_title_capture(e.workspace_id,sid,device,native_version,answering,capture_id,expected_head) IS NOT NULL;
END $check$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_publish_native_conversation_title(sid uuid,device uuid,native_version integer,answering uuid,capture_id uuid,
 expected_head uuid,label text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $publish$
DECLARE e public.conversation_envelopes;source jsonb;payload jsonb;revision uuid:=gen_random_uuid();written jsonb;
BEGIN
 e:=public.native_conversation_title_context(sid,device,native_version,answering,true);
 source:=public.require_native_conversation_title_capture(e.workspace_id,sid,device,native_version,answering,capture_id,expected_head);
 IF source IS NULL THEN RETURN NULL;END IF;
 payload:=jsonb_build_object(''title'',label,''manual'',false);
 IF public.session_context_payload_shape(''session_title'',payload) IS NOT TRUE THEN RAISE EXCEPTION ''conversation_title_invalid'' USING ERRCODE=''22023'';END IF;
 written:=public.publish_native_session_context_revision(e.workspace_id,sid,''session_title'',sid,revision,payload,
  ''turn:session-title'',jsonb_build_array(source),expected_head,NULL,NULL);
 RETURN CASE WHEN written IS NULL THEN NULL ELSE jsonb_build_object(''title'',label,''titleRevisionId'',revision) END;
END $publish$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_read_native_conversation_title_result(sid uuid,device uuid,native_version integer,answering uuid,
 expected_head uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $egress$
DECLARE title jsonb;
BEGIN
 PERFORM public.native_conversation_title_context(sid,device,native_version,answering,false);
 title:=public.read_conversation_title_current(sid);
 RETURN CASE WHEN title->>''titleRevisionId''=expected_head::text THEN title ELSE NULL END;
END $egress$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_conversation_settings_transition_matches(sid uuid,previous_project uuid,next_project uuid,
 previous_compartments text[],next_compartments text[]) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $transition$
 SELECT EXISTS(SELECT 1 FROM public.conversation_settings_transitions t WHERE transaction_id=pg_current_xact_id_if_assigned() AND session_id=sid
  AND t.previous_project_id IS NOT DISTINCT FROM previous_project AND t.next_project_id IS NOT DISTINCT FROM next_project
  AND t.previous_compartments=previous_compartments AND t.next_compartments=next_compartments)
$transition$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_mutate_conversation_settings(sid uuid,device uuid,native_version integer,expected_version bigint,
 operation text,choice text,requested_participants jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $mutation$
DECLARE actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 s public.sessions;e public.conversation_envelopes;w uuid;before_state jsonb;audit_id uuid;
 admin boolean;starter boolean;current_participants uuid[];next_participants uuid[];member_id uuid;
 next_visibility text;next_cap text;next_project uuid;next_labels text[];next_projects uuid[];promote_legacy boolean:=false;
 previous_hard_projects uuid[];participant_added uuid[];notice text;metadata jsonb;published_version bigint;
BEGIN
 IF expected_version IS NULL OR expected_version<1 OR operation IS NULL OR operation NOT IN(''visibility'',''cap'',''project'',''legacy_promotion'')
  OR actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 SELECT workspace_id INTO w FROM public.conversation_envelopes WHERE session_id=sid;
 IF w IS NULL THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 SELECT role IN(''owner'',''admin'') INTO admin FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 PERFORM a.id FROM public.auth_sessions a JOIN public.users u ON u.id=a.user_id
  WHERE a.id=device AND a.user_id=actor AND a.auth_version=native_version AND u.auth_version=native_version
   AND a.revoked_at IS NULL AND a.expires_at>clock_timestamp() FOR SHARE OF a,u;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 SELECT * INTO s FROM public.sessions WHERE id=sid FOR UPDATE;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR UPDATE;
 IF NOT FOUND OR public.session_recording_read_allowed(sid) IS NOT TRUE OR public.scope_review_state_held(''session'',sid)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 starter:=actor=e.starter_user_id;
 IF (NOT admin AND NOT starter OR NOT admin AND public.conversation_member_read_current(w,sid,actor) IS NOT TRUE)
  OR operation=''cap'' AND NOT admin
  OR e.visibility=''private_by_kind'' AND operation=''visibility''
  OR operation=''project'' AND e.visibility<>''workspace'' AND NOT starter
  OR operation=''legacy_promotion'' AND (NOT starter OR e.visibility<>''private_by_kind''
   OR s.workspace_id IS NOT NULL AND s.workspace_id IS DISTINCT FROM w
   OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 IF e.version<>expected_version THEN RAISE EXCEPTION ''conversation_visibility_conflict'' USING ERRCODE=''40001'';END IF;
 before_state:=public.conversation_authority_state(sid);
 SELECT coalesce(array_agg(user_id ORDER BY user_id),''{}'') INTO current_participants FROM public.conversation_participants WHERE session_id=sid;
 next_participants:=current_participants;next_visibility:=e.visibility;next_cap:=e.cap;next_project:=s.context_project_id;
 next_labels:=e.compartments;next_projects:=e.project_ids;
 previous_hard_projects:=public.conversation_hard_project_ids(e.compartments);
 IF operation=''visibility'' THEN
  IF choice IS NULL OR choice NOT IN(''configured_private'',''workspace'')
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  next_visibility:=choice;
  IF requested_participants IS NOT NULL THEN
   IF jsonb_typeof(requested_participants) IS DISTINCT FROM ''array'' OR jsonb_array_length(requested_participants)>1000
   THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
   SELECT coalesce(array_agg(value::uuid ORDER BY value::uuid),''{}'') INTO next_participants FROM jsonb_array_elements_text(requested_participants);
   IF array_position(next_participants,NULL) IS NOT NULL OR e.starter_user_id=ANY(next_participants)
     OR cardinality(next_participants)<>(SELECT count(DISTINCT u) FROM unnest(next_participants) u)
   THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  END IF;
  participant_added:=ARRAY(SELECT u FROM unnest(next_participants) u WHERE NOT u=ANY(current_participants));
  IF NOT admin AND (cardinality(participant_added)>0 OR next_visibility=''workspace'' AND e.visibility<>''workspace'')
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  IF requested_participants IS NOT NULL THEN
   FOREACH member_id IN ARRAY next_participants LOOP
    PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=member_id FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
   END LOOP;
  END IF;
  IF next_visibility=''workspace'' AND e.visibility<>''workspace'' THEN notice:=''widened'';END IF;
  IF next_visibility=''configured_private'' AND e.visibility=''workspace'' THEN notice:=''narrowed'';END IF;
 ELSIF operation=''cap'' THEN
  IF choice IS NULL OR choice NOT IN(''public'',''internal'',''confidential'') THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  IF public.sensitivity_rank(choice)<public.sensitivity_rank(e.cap)
  THEN RAISE EXCEPTION ''conversation_cap_cannot_lower'' USING ERRCODE=''22023'';END IF;
  next_cap:=choice;
 ELSIF operation=''project'' THEN
  next_project:=choice::uuid;
  IF next_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.workspace_projects p WHERE p.workspace_id=w AND p.id=next_project AND p.status=''active'')
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  IF e.visibility=''workspace'' AND next_project IS DISTINCT FROM s.context_project_id THEN
   IF cardinality(previous_hard_projects)>0 AND NOT admin
   THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
   IF next_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.project_shared_scopes ps WHERE ps.workspace_id=w AND ps.project_id=next_project AND ps.status=''active'')
   THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
   next_labels:=ARRAY(SELECT label FROM unnest(e.compartments) label WHERE label NOT LIKE ''project:%'');
   IF next_project IS NOT NULL THEN
    next_labels:=ARRAY(SELECT label FROM unnest(next_labels||(''project:''||next_project::text)) label ORDER BY label);
   END IF;
   IF cardinality(previous_hard_projects)>0 AND (next_project IS NULL OR NOT next_project=ANY(previous_hard_projects))
   THEN notice:=''project_boundary_removed'';END IF;
  END IF;
  next_projects:=public.conversation_hard_project_ids(next_labels);
 ELSE
  IF public.enroll_conversation_legacy_history(sid) IS NOT TRUE
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  IF public.conversation_legacy_enrolled(sid,w,actor,s.assistant_id) IS NOT TRUE
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  promote_legacy:=s.workspace_id IS NULL;
 END IF;

 IF promote_legacy OR (next_visibility,next_cap,next_project,next_labels,next_projects,next_participants)
  IS DISTINCT FROM (e.visibility,e.cap,s.context_project_id,e.compartments,e.project_ids,current_participants) THEN
  -- Prove the exact immutable 8203 parent before a reviewed mutation changes
  -- it. A mismatch remains withheld and is never repaired by this transition.
  IF e.visibility=''private_by_kind'' AND EXISTS(SELECT 1 FROM public.session_legacy_history WHERE session_id=sid)
   AND public.enroll_conversation_legacy_history(sid) IS NOT TRUE
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  IF promote_legacy THEN
   UPDATE public.sessions SET workspace_id=w WHERE id=sid AND workspace_id IS NULL;
   IF NOT FOUND THEN RAISE EXCEPTION ''conversation_visibility_conflict'' USING ERRCODE=''40001'';END IF;
  END IF;
  IF next_project IS DISTINCT FROM s.context_project_id OR next_labels IS DISTINCT FROM e.compartments THEN
   INSERT INTO public.conversation_settings_transitions VALUES(pg_current_xact_id(),sid,s.context_project_id,next_project,
    s.context_compartments,next_labels)
   ON CONFLICT(transaction_id,session_id) DO NOTHING;
   IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
   UPDATE public.sessions SET context_project_id=next_project,context_compartments=next_labels WHERE id=sid;
   DELETE FROM public.conversation_settings_transitions WHERE transaction_id=pg_current_xact_id() AND session_id=sid;
  END IF;
  IF next_cap IS DISTINCT FROM e.cap THEN UPDATE public.sessions SET effective_clearance=next_cap WHERE id=sid;END IF;
  UPDATE public.conversation_envelopes SET visibility=next_visibility,cap=next_cap,compartments=next_labels,
   project_ids=next_projects,version=e.version+1,record_data_revision=record_data_revision+1,record_dirty_from=0 WHERE session_id=sid
   RETURNING version INTO published_version;
  DELETE FROM public.conversation_participants WHERE session_id=sid AND NOT user_id=ANY(next_participants);
  INSERT INTO public.conversation_participants(session_id,user_id)
   SELECT sid,u FROM unnest(next_participants) u ORDER BY u ON CONFLICT DO NOTHING;
  INSERT INTO public.conversation_visibility_audit(session_id,actor_user_id,previous_version,next_version,before_envelope,after_envelope)
   VALUES(sid,actor,e.version,published_version,before_state,
    public.conversation_authority_state(sid)) RETURNING id INTO audit_id;
  -- A private participant must be a current member meeting the new labels and
  -- its actual anchor under that participant''s authority.
  FOREACH member_id IN ARRAY CASE WHEN operation=''visibility'' AND requested_participants IS NOT NULL THEN next_participants ELSE ''{}''::uuid[] END LOOP
   IF public.conversation_member_read_allowed(w,sid,member_id) IS NOT TRUE
   THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
  END LOOP;
  IF notice IS NOT NULL THEN
   INSERT INTO public.conversation_visibility_notices(session_id,audit_id,recipient_user_id,kind)
   SELECT sid,audit_id,u,notice FROM (
    SELECT DISTINCT u FROM unnest(current_participants||next_participants||e.starter_user_id) u
   ) audience;
  END IF;
  INSERT INTO public.conversation_visibility_notices(session_id,audit_id,recipient_user_id,kind)
   SELECT sid,audit_id,u,''participant_added'' FROM unnest(participant_added) u;
 ELSE published_version:=e.version;END IF;
 metadata:=public.conversation_visibility_metadata_current(sid,actor);
 RETURN CASE WHEN metadata IS NULL THEN jsonb_build_object(''committed'',true,''readable'',false,''sessionId'',sid,
  ''version'',published_version,''code'',''conversation_access_denied'')
 ELSE jsonb_build_object(''committed'',true,''readable'',true,''sessionId'',sid,''version'',published_version,''metadata'',metadata) END;
END $mutation$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_change_conversation_visibility(sid uuid,device uuid,native_version integer,expected_version bigint,visibility text,participants jsonb)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $visibility$
 SELECT public.mutate_conversation_settings(sid,device,native_version,expected_version,''visibility'',visibility,participants)
$visibility$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_raise_conversation_cap(sid uuid,device uuid,native_version integer,expected_version bigint,cap text)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $cap$
 SELECT public.mutate_conversation_settings(sid,device,native_version,expected_version,''cap'',cap,NULL)
$cap$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_move_conversation_project(sid uuid,device uuid,native_version integer,expected_version bigint,project_id uuid)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $project$
 SELECT public.mutate_conversation_settings(sid,device,native_version,expected_version,''project'',project_id::text,NULL)
$project$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_promote_native_conversation_legacy_history(sid uuid,device uuid,native_version integer,expected_version bigint)
RETURNS jsonb LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $promotion$
 SELECT public.mutate_conversation_settings(sid,device,native_version,expected_version,''legacy_promotion'',NULL,NULL)
$promotion$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_prevent_locked_session_context_change() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''public'', ''pg_temp''
AS $$
BEGIN
  IF OLD.context_locked_at IS NOT NULL AND (
    NEW.context_group_id IS DISTINCT FROM OLD.context_group_id OR
    NEW.context_project_id IS DISTINCT FROM OLD.context_project_id OR
    NEW.context_compartments IS DISTINCT FROM OLD.context_compartments
  ) AND NOT (NEW.context_group_id IS NOT DISTINCT FROM OLD.context_group_id
    AND public.conversation_settings_transition_matches(OLD.id,
    OLD.context_project_id,NEW.context_project_id,OLD.context_compartments,NEW.context_compartments)) THEN
    RAISE EXCEPTION USING ERRCODE = ''P0001'', MESSAGE = ''context_locked'';
  END IF;
  RETURN NEW;
END;
$$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_stamp_session_project_label() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
BEGIN
  IF TG_OP=''UPDATE'' THEN
    IF public.conversation_settings_transition_matches(OLD.id,
    OLD.context_project_id,NEW.context_project_id,OLD.context_compartments,NEW.context_compartments) THEN RETURN NEW;END IF;
  END IF;
  IF NEW.context_locked_at IS NOT NULL THEN RETURN NEW; END IF;
  IF TG_OP = ''UPDATE'' AND NEW.context_project_id IS DISTINCT FROM OLD.context_project_id THEN
    NEW.context_compartments := ARRAY(SELECT k FROM unnest(coalesce(NEW.context_compartments, ''{}''::text[])) k
      WHERE k NOT LIKE ''project:%'' OR k = ''project:'' || NEW.context_project_id::text);
  END IF;
  IF NEW.visibility = ''workspace'' AND NEW.context_project_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.project_shared_scopes s WHERE s.project_id = NEW.context_project_id AND s.workspace_id = NEW.workspace_id)
     AND NOT ((''project:'' || NEW.context_project_id::text) = ANY (coalesce(NEW.context_compartments, ''{}''::text[]))) THEN
    NEW.context_compartments := array_append(coalesce(NEW.context_compartments, ''{}''::text[]), ''project:'' || NEW.context_project_id::text);
  END IF;
  RETURN NEW;
END $$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_record_ref_validate_session_context_binding() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''public'', ''pg_temp''
AS $$
DECLARE
  backing_key text;
  project_label text := CASE WHEN NEW.context_project_id IS NULL THEN NULL ELSE ''project:'' || NEW.context_project_id::text END;
  team_labels text[];
  reviewed_transition boolean:=false;
BEGIN
  IF TG_OP=''UPDATE'' THEN reviewed_transition:=public.conversation_settings_transition_matches(OLD.id,
    OLD.context_project_id,NEW.context_project_id,OLD.context_compartments,NEW.context_compartments);END IF;
  IF EXISTS (SELECT 1 FROM unnest(coalesce(NEW.context_compartments, ''{}''::text[])) k
              WHERE k LIKE ''project:%'' AND ((NOT reviewed_transition AND k IS DISTINCT FROM project_label) OR NOT EXISTS (
                SELECT 1 FROM public.project_shared_scopes s WHERE ''project:''||s.project_id::text=k AND s.workspace_id = NEW.workspace_id))) THEN
    RAISE EXCEPTION ''session Project label must name its bound shared Project'';
  END IF;
  team_labels := ARRAY(SELECT k FROM unnest(coalesce(NEW.context_compartments, ''{}''::text[])) k WHERE k NOT LIKE ''project:%'');
  IF NEW.context_group_id IS NOT NULL THEN
    SELECT g.compartment_key INTO backing_key
      FROM public.workspace_groups g
     WHERE g.id = NEW.context_group_id
       AND g.workspace_id = NEW.workspace_id
       AND g.kind = ''team'';
    IF backing_key IS NULL THEN
      RAISE EXCEPTION ''session Team must belong to its workspace'';
    END IF;
    IF team_labels IS DISTINCT FROM ARRAY[backing_key]::text[] THEN
      RAISE EXCEPTION ''session context_compartments must equal the selected Team backing key'';
    END IF;
  ELSIF cardinality(team_labels) <> 0 THEN
    RAISE EXCEPTION ''a session without a Team must have an empty context_compartments projection'';
  END IF;

  IF NEW.context_project_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.workspace_projects p
     WHERE p.id = NEW.context_project_id AND p.workspace_id = NEW.workspace_id
  ) THEN
    RAISE EXCEPTION ''session Project must belong to its workspace'';
  END IF;
  RETURN NEW;
END;
$$;';
END $record_reference_compile$;
CREATE TEMP TABLE a8314_record_reference_oids(oid oid PRIMARY KEY) ON COMMIT DROP;
DO $record_references$
DECLARE item record;actual pg_proc;reviewed pg_proc;access_rows jsonb;
 owner_id constant oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 runtime_id constant oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
BEGIN
 FOR item IN SELECT * FROM (VALUES ('a8314_record_ref_conversation_office_anchor_current','conversation_office_anchor_current',false,false),('a8314_record_ref_conversation_hard_project_ids','conversation_hard_project_ids',false,false),('a8314_record_ref_conversation_authority_state','conversation_authority_state',false,false),('a8314_record_ref_conversation_consent_current','conversation_consent_current',false,false),('a8314_record_ref_conversation_member_tier_current','conversation_member_tier_current',false,false),('a8314_record_ref_conversation_member_read_current','conversation_member_read_current',false,false),('a8314_record_ref_conversation_envelope_for_reader','conversation_envelope_for_reader',false,false),('a8314_record_ref_read_conversation_member_tiers','read_conversation_member_tiers',false,true),('a8314_record_ref_conversation_member_read_allowed','conversation_member_read_allowed',false,false),('a8314_record_ref_conversation_visibility_metadata_current','conversation_visibility_metadata_current',false,false),('a8314_record_ref_read_conversation_visibility','read_conversation_visibility',false,true),('a8314_record_ref_enroll_conversation_legacy_history','enroll_conversation_legacy_history',false,false),('a8314_record_ref_conversation_legacy_enrolled','conversation_legacy_enrolled',false,false),('a8314_record_ref_guard_conversation_record_capture','guard_conversation_record_capture',false,false),('a8314_record_ref_withdraw_conversation_record_targets','withdraw_conversation_record_targets',false,false),('a8314_record_ref_withdraw_conversation_record_rows','withdraw_conversation_record_rows',false,false),('a8314_record_ref_read_conversation_record_source','read_conversation_record_source',false,false),('a8314_record_ref_conversation_record_member_allowed','conversation_record_member_allowed',false,false),('a8314_record_ref_conversation_record_rows','conversation_record_rows',false,false),('a8314_record_ref_project_conversation_record','project_conversation_record',false,false),('a8314_record_ref_capture_conversation_record_current','capture_conversation_record_current',false,false),('a8314_record_ref_capture_native_conversation_record','capture_native_conversation_record',false,true),('a8314_record_ref_conversation_record_turn_facts','conversation_record_turn_facts',false,false),('a8314_record_ref_capture_native_turn_conversation_record','capture_native_turn_conversation_record',false,true),('a8314_record_ref_admit_native_turn_conversation_records','admit_native_turn_conversation_records',false,true),('a8314_record_ref_conversation_record_publication_source','conversation_record_publication_source',false,false),('a8314_record_ref_read_conversation_record_for_write','read_conversation_record_for_write',false,true),('a8314_record_ref_conversation_record_lineage_roots','conversation_record_lineage_roots',false,false),('a8314_record_ref_require_conversation_record_current_lineage','require_conversation_record_current_lineage',false,false),('a8314_record_ref_conversation_anchor_key','conversation_anchor_key',false,false),('a8314_record_ref_require_conversation_record_edge','require_conversation_record_edge',false,false),('a8314_record_ref_native_conversation_read_credential','native_conversation_read_credential',false,false),('a8314_record_ref_read_native_conversation_history','read_native_conversation_history',false,false),('a8314_record_ref_conversation_rls_session_current','conversation_rls_session_current',false,true),('a8314_record_ref_conversation_rls_message_current','conversation_rls_message_current',false,true),('a8314_record_ref_conversation_searchable_text','conversation_searchable_text',false,true),('a8314_record_ref_read_conversation_search_text_current','read_conversation_search_text_current',false,true),('a8314_record_ref_read_conversation_title_current','read_conversation_title_current',false,true),('a8314_record_ref_conversation_title_record_current','conversation_title_record_current',false,false),('a8314_record_ref_native_conversation_title_context','native_conversation_title_context',false,false),('a8314_record_ref_prepare_native_conversation_title','prepare_native_conversation_title',false,true),('a8314_record_ref_require_native_conversation_title_capture','require_native_conversation_title_capture',false,false),('a8314_record_ref_check_native_conversation_title','check_native_conversation_title',false,true),('a8314_record_ref_publish_native_conversation_title','publish_native_conversation_title',false,true),('a8314_record_ref_read_native_conversation_title_result','read_native_conversation_title_result',false,true),('a8314_record_ref_conversation_settings_transition_matches','conversation_settings_transition_matches',false,false),('a8314_record_ref_mutate_conversation_settings','mutate_conversation_settings',false,false),('a8314_record_ref_change_conversation_visibility','change_conversation_visibility',false,true),('a8314_record_ref_raise_conversation_cap','raise_conversation_cap',false,true),('a8314_record_ref_move_conversation_project','move_conversation_project',false,true),('a8314_record_ref_promote_native_conversation_legacy_history','promote_native_conversation_legacy_history',false,true),('a8314_record_ref_prevent_locked_session_context_change','prevent_locked_session_context_change',true,false),('a8314_record_ref_stamp_session_project_label','stamp_session_project_label',true,false),('a8314_record_ref_validate_session_context_binding','validate_session_context_binding',true,false)) spec(reference,routine,replacement,app) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=item.reference;
  SELECT * INTO actual FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=item.routine AND proargtypes=reviewed.proargtypes;
  IF actual.oid IS NULL OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
   (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl']) THEN
   RAISE EXCEPTION 'conversation_record_helper_source_changed: %',item.routine;
  END IF;
  SELECT jsonb_object_agg(grantee,grantor) INTO access_rows FROM aclexplode(coalesce(actual.proacl,acldefault('f',owner_id)))
   WHERE privilege_type='EXECUTE' AND NOT is_grantable;
  IF actual.proowner<>owner_id OR access_rows IS DISTINCT FROM (jsonb_build_object(owner_id::text,owner_id)||
    CASE WHEN item.app THEN jsonb_build_object(runtime_id::text,owner_id)
         WHEN item.replacement THEN jsonb_build_object('0',owner_id) ELSE '{}'::jsonb END)
   OR (SELECT count(*) FROM aclexplode(coalesce(actual.proacl,acldefault('f',owner_id))))<>
    (CASE WHEN item.app OR item.replacement THEN 2 ELSE 1 END) THEN
   RAISE EXCEPTION 'conversation_record_helper_acl_changed: %',item.routine;
  END IF;
  INSERT INTO a8314_record_reference_oids VALUES(actual.oid);
 END LOOP;
END $record_references$;
CREATE TEMP TABLE a8314_record_policy_sessions(id uuid) ON COMMIT DROP;
CREATE TEMP TABLE a8314_record_policy_messages(session_id uuid,id uuid,sequence_num integer) ON COMMIT DROP;
CREATE POLICY sessions_conversation_envelope_select ON pg_temp.a8314_record_policy_sessions FOR SELECT TO app_user USING (nullif(current_setting('app.current_user_id',true),'') IS NOT NULL);
CREATE POLICY sessions_conversation_envelope_floor ON pg_temp.a8314_record_policy_sessions AS RESTRICTIVE FOR SELECT TO app_user USING (public.conversation_rls_session_current(id));
CREATE POLICY session_messages_conversation_record_select ON pg_temp.a8314_record_policy_messages FOR SELECT TO app_user USING (nullif(current_setting('app.current_user_id',true),'') IS NOT NULL);
CREATE POLICY session_messages_conversation_record_floor ON pg_temp.a8314_record_policy_messages AS RESTRICTIVE FOR SELECT TO app_user USING (public.conversation_rls_message_current(session_id,id,sequence_num));
DO $record_catalog$ DECLARE item record;actual pg_policy;reviewed pg_policy;relation regclass;
BEGIN
 FOR item IN SELECT * FROM (VALUES ('sessions','sessions_conversation_envelope_select','a8314_record_policy_sessions'),('sessions','sessions_conversation_envelope_floor','a8314_record_policy_sessions'),('session_messages','session_messages_conversation_record_select','a8314_record_policy_messages'),('session_messages','session_messages_conversation_record_floor','a8314_record_policy_messages')) q(relation,policy,peer) LOOP
  relation:=to_regclass('public.'||item.relation);
  SELECT * INTO actual FROM pg_policy WHERE polrelid=relation AND polname=item.policy;
  SELECT * INTO STRICT reviewed FROM pg_policy WHERE polrelid=to_regclass('pg_temp.'||item.peer) AND polname=item.policy;
  IF actual.oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=relation AND relrowsecurity)
   OR ROW(actual.polpermissive,actual.polcmd,actual.polroles,pg_get_expr(actual.polqual,actual.polrelid),pg_get_expr(actual.polwithcheck,actual.polrelid))
   IS DISTINCT FROM ROW(reviewed.polpermissive,reviewed.polcmd,reviewed.polroles,pg_get_expr(reviewed.polqual,reviewed.polrelid),pg_get_expr(reviewed.polwithcheck,reviewed.polrelid)) THEN
   RAISE EXCEPTION 'conversation_record_policy_changed: %.%',item.relation,item.policy;
  END IF;
 END LOOP;
 FOR item IN SELECT * FROM (VALUES ('private_transcript_observations','conversation_record_capture_immutable',19,'public.guard_conversation_record_capture()'),('session_messages','conversation_record_message_withdrawal',29,'public.withdraw_conversation_record_rows()'),('session_message_annotation_heads','conversation_record_annotation_withdrawal',29,'public.withdraw_conversation_record_rows()'),('conversation_message_quarantine','conversation_record_quarantine_withdrawal',29,'public.withdraw_conversation_record_rows()'),('scope_resource_states','conversation_record_review_withdrawal',29,'public.withdraw_conversation_record_rows()'),('session_context_scope_revisions','conversation_record_revision_withdrawal',25,'public.withdraw_conversation_record_rows()'),('session_context_revision_contents','conversation_record_revision_content_withdrawal',25,'public.withdraw_conversation_record_rows()')) q(relation,trigger_name,mask,routine) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid=to_regclass('public.'||item.relation) AND tgname=item.trigger_name
   AND tgfoid=to_regprocedure(item.routine) AND tgtype=item.mask AND tgenabled='O' AND NOT tgisinternal AND tgconstraint=0
   AND tgnargs=0 AND tgattr=''::int2vector AND tgqual IS NULL AND tgoldtable IS NULL AND tgnewtable IS NULL) THEN
   RAISE EXCEPTION 'conversation_record_trigger_changed: %.%',item.relation,item.trigger_name;
  END IF;
 END LOOP;
 FOR relation IN SELECT to_regclass('public.'||name) FROM unnest(ARRAY['conversation_legacy_history_enrollments','conversation_settings_transitions','conversation_visibility_notices']::text[]) name LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=relation AND c.relkind='r' AND c.relrowsecurity AND NOT c.relforcerowsecurity
    AND c.relowner=(SELECT owner.relowner FROM pg_class owner WHERE owner.oid='public.sessions'::regclass)
    AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=c.oid)
    AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE a.grantee<>c.relowner)) THEN
    RAISE EXCEPTION 'conversation_record_private_catalog_changed: %',relation;
   END IF;
 END LOOP;
END $record_catalog$;
CREATE FUNCTION pg_temp.legacy_bypass_successor_0(p jsonb,e jsonb,sources jsonb,target_id uuid,expected_version text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 w uuid:=(p->>'workspaceId')::uuid;s workspace_knowledge_sources;old knowledge_entries;
 context jsonb;catalog jsonb;mask jsonb;fields text[];source jsonb;current jsonb;field text;
BEGIN
 IF actor IS NULL OR actor::text IS DISTINCT FROM p->>'actorId'
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR nullif(current_setting('app.agent_actor_id',true),'') IS DISTINCT FROM actor::text
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
    WHERE r.rolname=session_user AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) x WHERE x->>'resourceKind'='application_field')
  OR entity_derivation_envelope_valid(p||jsonb_build_object('userId',NULL,'assistantId',NULL)) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='42501';END IF;
 SELECT * INTO s FROM workspace_knowledge_sources WHERE workspace_id=w AND id=(p->>'sourceId')::uuid FOR SHARE;
 IF s.id IS NULL OR s.binding_held OR s.configured_by_user_id IS NULL
  OR s.id::text IS DISTINCT FROM e->>'id' OR s.workspace_id::text IS DISTINCT FROM e->>'workspaceId'
  OR s.binding_version::text IS DISTINCT FROM e->>'bindingVersion'
  OR s.repo IS DISTINCT FROM e->>'repo' OR s.branch IS DISTINCT FROM e->>'branch'
  OR s.root_path IS DISTINCT FROM e->>'rootPath' OR s.source_type IS DISTINCT FROM e->>'sourceType'
  OR s.connector_instance_id::text IS DISTINCT FROM e->>'connectorInstanceId'
  OR(s.source_type='github' AND s.write_access IS DISTINCT FROM true)
  OR(s.sync_run_id IS NOT NULL AND s.sync_lease_until>clock_timestamp())
  THEN RAISE EXCEPTION 'knowledge_source_changed' USING ERRCODE='42501';END IF;
 IF member_operation_scope_allows(w,s.binding_sensitivity,s.binding_compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(s.binding_compartments) IS NOT TRUE
  OR agent_read_scope_allows(s.binding_sensitivity,s.binding_compartments,s.binding_project_ids) IS NOT TRUE
  OR read_entity_derivation_source(w,'knowledge_source',s.id) IS NULL
  OR sensitivity_rank(p->>'sensitivity')<sensitivity_rank(s.binding_sensitivity)
  OR NOT(p->'compartments')@>to_jsonb(s.binding_compartments) OR NOT(p->'projectIds')@>to_jsonb(s.binding_project_ids)
  THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM knowledge_entries WHERE workspace_id=w AND path=p->>'path' FOR UPDATE;
 IF target_id IS NULL THEN
  IF old.id IS NOT NULL OR expected_version IS NOT NULL THEN RAISE EXCEPTION 'knowledge_source_target_conflict';END IF;
  fields:=ARRAY['path','title','content','summary','tags','metadata'];
  IF native_knowledge_creation_fields_allowed(w,fields,NULL,NULL) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 ELSE
  IF old.id IS DISTINCT FROM target_id OR old.source_id IS DISTINCT FROM s.id OR old.scope_held
   OR old.scope_version::text IS DISTINCT FROM expected_version
   OR native_knowledge_version_fields_allowed(w,old.id,application_knowledge_field_keys()) IS NOT TRUE
   OR application_canonical_ancestry_allowed(w,'knowledge_entry',old.id,expected_version,true) IS NOT TRUE
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) x WHERE x->>'resourceKind'='knowledge_entry'
     AND x->>'resourceId'=old.id::text AND x->>'version'=expected_version)
   THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  fields:=ARRAY['content'];
  IF old.title IS DISTINCT FROM p->>'title' THEN fields:=array_append(fields,'title');END IF;
  IF old.summary IS DISTINCT FROM p->>'summary' THEN fields:=array_append(fields,'summary');END IF;
  IF to_jsonb(old.tags) IS DISTINCT FROM p->'tags' THEN fields:=array_append(fields,'tags');END IF;
  IF old.metadata IS DISTINCT FROM p->'metadata' THEN fields:=array_append(fields,'metadata');END IF;
  context:=application_knowledge_query_context(w);
  IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
   catalog:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
   mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',old.id::text,expected_version);
   FOREACH field IN ARRAY fields LOOP
    IF catalog IS NULL OR mask IS NULL OR NOT coalesce(catalog->'writeFields' ? field,false)
     OR NOT coalesce(mask->'writeFields' ? field,false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
   END LOOP;
  END IF;
 END IF;
 IF member_operation_scope_allows(w,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),true) IS NOT TRUE
  OR agent_mutation_scope_allows(ARRAY(SELECT jsonb_array_elements_text(p->'compartments'))) IS NOT TRUE
  OR agent_read_scope_allows(p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)) IS NOT TRUE
  THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(sources) LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN RAISE EXCEPTION 'scope_evidence_missing';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR(current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity') IS DISTINCT FROM(source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT(current->'compartments')@>(source->'compartments') OR NOT(source->'compartments')@>(current->'compartments')
   OR NOT(current->'projectIds')@>(source->'projectIds') OR NOT(source->'projectIds')@>(current->'projectIds') THEN RAISE EXCEPTION 'scope_source_changed';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text
   OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(p->>'sensitivity')
   OR NOT(p->'compartments')@>(source->'compartments') OR NOT(p->'projectIds')@>(source->'projectIds') THEN RAISE EXCEPTION 'scope_visibility_incompatible';END IF;
 END LOOP;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_0(jsonb,jsonb,jsonb,uuid,text)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','admit_knowledge_repo_write(jsonb,jsonb,jsonb,uuid,text)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_0(jsonb,jsonb,jsonb,uuid,text);
CREATE FUNCTION pg_temp.legacy_bypass_successor_1(w uuid,administrator uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE revision text;context jsonb;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.tasks'::regclass
   WHERE r.rolname=session_user AND r.oid=c.relowner)
  OR nullif(current_setting('app.scope_review_actor',true),'') IS DISTINCT FROM administrator::text
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.current_user_id',true),'') IS NOT NULL AND current_setting('app.current_user_id',true)<>administrator::text THEN
  RAISE EXCEPTION 'access_unavailable: native review identity unavailable' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=administrator AND m.role IN('owner','admin') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'access_unavailable: current administrator required' USING ERRCODE='42501';END IF;
 PERFORM 1 FROM application_native_role_assignments r WHERE r.workspace_id=w AND r.module_key='native' AND r.status='active' ORDER BY r.id FOR SHARE;
 IF NOT EXISTS(SELECT 1 FROM application_policy_workspace_epochs e WHERE e.workspace_id=w)
  OR NOT EXISTS(SELECT 1 FROM application_policy_contract_epoch) THEN
  RAISE EXCEPTION 'access_unavailable: native review epoch missing' USING ERRCODE='42501';END IF;
 revision:=application_native_task_write_policy_revision(w);
 IF revision IS NULL THEN RAISE EXCEPTION 'access_unavailable: native review policy unavailable' USING ERRCODE='42501';END IF;
 SELECT jsonb_object_agg(name,to_jsonb(nullif(current_setting(name,true),''))) INTO context FROM unnest(ARRAY[
  'app.current_user_id','app.application_id','app.application_assistant_id','app.v2_assistant_id','app.application_command_key',
  'app.agent_workspace_id','app.agent_actor_id','app.agent_assistant_id','app.scope_review_actor',
  'app.agent_clearance','app.agent_compartments','app.agent_project_ids','app.agent_shared_audience','app.agent_mutation_compartments',
  'app.agent_visibility_assistants','app.v2_active','app.v2_context_department','app.v2_binding','app.v2_cap','app.native_task_write_intent']) name;
 RETURN jsonb_build_object('session',session_user,'contextDigest',application_field_digest(context),'policy',revision);
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.application_native_task_review_current(uuid,uuid)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_1(uuid,uuid)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','application_native_task_review_current(uuid,uuid)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_1(uuid,uuid);
CREATE FUNCTION pg_temp.legacy_bypass_successor_2(p jsonb,e jsonb) RETURNS SETOF knowledge_entries
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE w uuid:=(p->>'workspaceId')::uuid;s workspace_knowledge_sources;old knowledge_entries;output knowledge_entries;
 actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 prior_revision uuid;next_revision uuid;derivation uuid;context jsonb;catalog jsonb;mask jsonb;field text;fields text[];
 setting record;saved jsonb:='{}';node record;current jsonb;
BEGIN
 PERFORM assert_bound_knowledge_sync_actor(w,(p->>'sourceId')::uuid);
 SELECT * INTO s FROM workspace_knowledge_sources WHERE workspace_id=w AND id=(p->>'sourceId')::uuid FOR SHARE;
 IF s.id IS NULL OR s.binding_held OR s.sync_run_id IS NULL OR s.sync_lease_until IS NULL OR s.sync_run_id::text IS DISTINCT FROM e->>'syncRunId'
  OR s.sync_lease_until<=clock_timestamp() OR s.binding_version::text IS DISTINCT FROM e->>'bindingVersion'
  OR s.id::text IS DISTINCT FROM e->>'id' OR w::text IS DISTINCT FROM e->>'workspaceId'
  OR s.repo IS DISTINCT FROM e->>'repo' OR s.branch IS DISTINCT FROM e->>'branch' OR s.root_path IS DISTINCT FROM e->>'rootPath'
  OR s.source_type IS DISTINCT FROM e->>'sourceType' OR s.connector_instance_id::text IS DISTINCT FROM e->>'connectorInstanceId'
  OR s.last_synced_sha IS DISTINCT FROM e->>'lastSyncedSha' OR s.configured_by_user_id::text IS DISTINCT FROM e->>'configuredByUserId'
  OR s.binding_sensitivity IS DISTINCT FROM e->>'bindingSensitivity'
  OR to_jsonb(s.binding_compartments) IS DISTINCT FROM e->'bindingCompartments'
  OR to_jsonb(s.binding_project_ids) IS DISTINCT FROM e->'bindingProjectIds'
  THEN RAISE EXCEPTION 'knowledge_source_changed' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM knowledge_entries WHERE workspace_id=w AND path=p->>'path' FOR UPDATE;
 IF old.id IS NULL OR NOT EXISTS(SELECT 1 FROM knowledge_repo_publication_heads h WHERE h.workspace_id=w AND h.entry_id=old.id)
  OR coalesce(p->>'operation','') NOT IN('','related') THEN
  RETURN QUERY SELECT * FROM apply_knowledge_source_sync(p,e);RETURN;
 END IF;
 IF old.source_id IS DISTINCT FROM s.id OR old.scope_held OR coalesce(p->>'sourceSha','')=''
  OR entity_derivation_envelope_valid(p||jsonb_build_object('userId',NULL,'assistantId',NULL)) IS NOT TRUE
  OR p->>'userId' IS NOT NULL OR p->>'assistantId' IS NOT NULL
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.v2_assistant_id',true),'') IS NOT NULL
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass WHERE r.rolname=session_user
   AND(r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 -- No caller-selected ceilings and no assistant/attended identity. Current
 -- membership remains independently enforced by every canonical native reader.
 FOR setting IN SELECT * FROM jsonb_each_text(jsonb_build_object(
  'app.agent_workspace_id',w::text,'app.agent_actor_id',actor::text,'app.agent_clearance',s.binding_sensitivity,
  'app.agent_compartments',to_jsonb(s.binding_compartments)::text,'app.agent_project_ids',to_jsonb(s.binding_project_ids)::text,
  'app.agent_mutation_compartments',to_jsonb(s.binding_compartments)::text,
  'app.agent_shared_audience','true','app.agent_visibility_assistants','[]')) LOOP
  saved:=saved||jsonb_build_object(setting.key,current_setting(setting.key,true));
  PERFORM set_config(setting.key,setting.value,true);
 END LOOP;
 IF sensitivity_rank(p->>'sensitivity')<sensitivity_rank(old.sensitivity)
  OR NOT(p->'compartments')@>to_jsonb(old.compartments) OR NOT(p->'projectIds')@>to_jsonb(old.project_ids)
  OR member_operation_scope_allows(w,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),true) IS NOT TRUE
  OR agent_mutation_scope_allows(ARRAY(SELECT jsonb_array_elements_text(p->'compartments'))) IS NOT TRUE
  OR agent_read_scope_allows(p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)) IS NOT TRUE
  OR native_knowledge_version_fields_allowed(w,old.id,application_knowledge_field_keys()) IS NOT TRUE
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 -- Walk exact immutable observations. Unsupported kinds and all external
 -- dependencies hold before capture/archive or changing the mutable head.
 FOR node IN SELECT * FROM application_scope_lineage(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) LOOP
  IF node.kind NOT IN('knowledge_entry','knowledge_entry_revision','knowledge_source','application_field','application_query_domain')
   THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
  IF node.kind='application_field' THEN
   current:=read_admitted_application_field_snapshot(w,node.id,node.version);
  ELSIF node.kind='application_query_domain' THEN
   -- A query domain is admitted through its complete recorded field observation.
   IF NOT EXISTS(SELECT 1 FROM application_field_resources f JOIN application_field_observations o
    ON o.workspace_id=f.workspace_id AND o.resource_id=f.id
    WHERE f.workspace_id=w AND f.resource_id=node.id AND f.selection='query_domain'
     AND EXISTS(SELECT 1 FROM application_scope_lineage(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) l
      WHERE l.kind='application_field' AND l.id=f.id AND l.version=o.version)) THEN
    RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
   CONTINUE;
  ELSIF node.kind='knowledge_entry' THEN
   current:=read_entity_derivation_source(w,node.kind,node.id);
   IF current->>'version' IS DISTINCT FROM node.version THEN
    current:=knowledge_version_field_state(w,node.id,node.version,'{}');
    IF current IS NULL OR current->>'recordVersion' IS DISTINCT FROM node.version THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
    CONTINUE;
   END IF;
  ELSE current:=read_entity_derivation_source(w,node.kind,node.id);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM node.version
   THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM read_external_source_dependencies(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]))
  OR application_canonical_ancestry_allowed(w,'knowledge_entry',old.id,old.scope_version::text,true) IS NOT TRUE
  THEN RAISE EXCEPTION 'knowledge_repo_reconciliation_required' USING ERRCODE='42501';END IF;
 context:=application_knowledge_query_context(w);
 IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 fields:=CASE WHEN p->>'operation'='related' THEN ARRAY['relatedIds'] ELSE ARRAY['content','title','summary','tags','metadata'] END;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  catalog:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',old.id::text,old.scope_version::text);
  FOREACH field IN ARRAY fields LOOP
   IF catalog IS NULL OR mask IS NULL OR NOT coalesce(catalog->'writeFields' ? field,false)
    OR NOT coalesce(mask->'writeFields' ? field,false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  END LOOP;
 END IF;
 IF p->>'operation'='related' AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(p->'relatedIds') r(id) WHERE NOT EXISTS(
  SELECT 1 FROM knowledge_entries k WHERE k.id=r.id::uuid AND k.workspace_id=w AND NOT k.scope_held
   AND sensitivity_rank(k.sensitivity)<=sensitivity_rank(old.sensitivity) AND k.compartments<@old.compartments AND k.project_ids<@old.project_ids))
  THEN RAISE EXCEPTION 'knowledge_source_target_conflict';END IF;
 IF p->>'operation'='related' AND to_jsonb(old.related_ids)=p->'relatedIds'
  OR coalesce(p->>'operation','')='' AND (old.title,old.summary,old.content,to_jsonb(old.tags),old.sensitivity,old.sensitivity_explicit,old.metadata,old.source_sha,to_jsonb(old.compartments),to_jsonb(old.project_ids))
    IS NOT DISTINCT FROM (p->>'title',p->>'summary',p->>'content',coalesce(p->'tags','[]'),p->>'sensitivity',(p->>'sensitivityExplicit')::boolean,coalesce(p->'metadata','{}'),p->>'sourceSha',p->'compartments',p->'projectIds') THEN
  FOR setting IN SELECT * FROM jsonb_each_text(saved) LOOP PERFORM set_config(setting.key,coalesce(setting.value,''),true);END LOOP;
  RETURN NEXT old;RETURN;
 END IF;
 prior_revision:=capture_native_knowledge_version(w,old.id,old.scope_version::text,application_knowledge_field_keys());
 IF prior_revision IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 PERFORM archive_native_knowledge_version(w,old.id,old.scope_version::text,prior_revision);
 -- A newly captured prior root must pair while its version is still current.
 -- New body publication is created only after these queued checks are complete.
 SET CONSTRAINTS knowledge_scope_revision_pair,knowledge_revision_publication_pair IMMEDIATE;
 SET CONSTRAINTS knowledge_scope_revision_pair,knowledge_revision_publication_pair DEFERRED;
 INSERT INTO knowledge_entry_scope_revisions(workspace_id,entry_id,sensitivity,compartments,project_ids,revision_kind)
  VALUES(w,old.id,p->>'sensitivity',ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid),'body') RETURNING id INTO next_revision;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry_revision',next_revision,'1','knowledge-source-reconciliation',NULL,NULL,p->>'sensitivity',
   ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid),revision
  FROM workspace_access_policies WHERE workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version) VALUES
  (w,derivation,'knowledge_entry_revision',prior_revision,'1'),(w,derivation,'knowledge_source',s.id,s.binding_version::text);
 -- Canonical field validation requires exact direct witnesses as well as the
 -- complete immutable root. Reuse original identities/versions; never observe anew.
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT DISTINCT w,derivation,'application_field',(dependency.source->>'resourceId')::uuid,dependency.node_version
  FROM read_application_field_dependencies(w,ARRAY['knowledge_entry'],ARRAY[old.id],ARRAY[old.scope_version::text]) dependency;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 IF p->>'operation'='related' THEN
  UPDATE knowledge_entries SET related_ids=ARRAY(SELECT jsonb_array_elements_text(p->'relatedIds')::uuid) WHERE id=old.id RETURNING * INTO output;
 ELSE
  UPDATE knowledge_entries SET title=p->>'title',summary=p->>'summary',content=p->>'content',tags=ARRAY(SELECT jsonb_array_elements_text(p->'tags')),
   sensitivity=p->>'sensitivity',sensitivity_explicit=(p->>'sensitivityExplicit')::boolean,metadata=coalesce(p->'metadata','{}'),
   source_sha=p->>'sourceSha',compartments=ARRAY(SELECT jsonb_array_elements_text(p->'compartments')),project_ids=ARRAY(SELECT jsonb_array_elements_text(p->'projectIds')::uuid)
   WHERE id=old.id AND scope_version=old.scope_version RETURNING * INTO output;
 END IF;
 PERFORM publish_native_knowledge_body_revision(w,old.id,output.scope_version::text,next_revision);
 INSERT INTO knowledge_repo_publication_heads VALUES(w,old.id,output.scope_version::text);
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 FOR setting IN SELECT * FROM jsonb_each_text(saved) LOOP PERFORM set_config(setting.key,coalesce(setting.value,''),true);END LOOP;
 RETURN NEXT output;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.apply_knowledge_source_refresh(jsonb,jsonb)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_2(jsonb,jsonb)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','apply_knowledge_source_refresh(jsonb,jsonb)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_2(jsonb,jsonb);
CREATE FUNCTION pg_temp.legacy_bypass_successor_3(p_workspace_id uuid,p_team_id uuid) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE viewer uuid; reach text[];
BEGIN
  viewer=nullif(current_setting('app.current_user_id',true),'')::uuid;
  IF NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer) THEN RETURN false; END IF;
  -- INSERT ... RETURNING evaluates SELECT policies before the inserted group
  -- is query-visible to a STABLE helper. Administrative authority is independent
  -- of group visibility and must not query the not-yet-visible group row.
  IF EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=p_workspace_id AND user_id=viewer AND role IN ('owner','admin')) THEN RETURN true; END IF;
  reach=effective_member_read_compartments(viewer,p_workspace_id);
  RETURN EXISTS(SELECT 1 FROM workspace_groups g WHERE g.id=p_team_id AND g.workspace_id=p_workspace_id AND (
    g.kind<>'team' OR g.directory_visibility='workspace' OR reach IS NULL OR g.compartment_key=ANY(reach)
    OR EXISTS(SELECT 1 FROM workspace_team_managers m WHERE m.workspace_id=p_workspace_id AND m.team_id=p_team_id AND m.user_id=viewer AND m.revoked_at IS NULL)
  ));
END;
$$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.can_view_department_directory(uuid,uuid)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_3(uuid,uuid)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM NULL
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','can_view_department_directory(uuid,uuid)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_3(uuid,uuid);
CREATE FUNCTION pg_temp.legacy_bypass_successor_4(a crm_activities,mutation boolean) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
  SELECT NOT a.scope_held
    AND (a.scope_origin='captured' OR NOT EXISTS(SELECT 1 FROM workspace_access_policies p
      WHERE p.workspace_id=a.workspace_id AND p.classification_mode='strict'))
    AND EXISTS(
      SELECT 1 FROM entities e JOIN workspaces w ON w.id=e.workspace_id JOIN workspace_members m ON m.workspace_id=e.workspace_id
        AND m.user_id=nullif(current_setting('app.current_user_id',true),'')::uuid
      WHERE e.id=a.entity_id AND e.workspace_id=a.workspace_id
        AND e.kind IN('person','company','deal') AND e.valid_to IS NULL AND e.retracted_at IS NULL AND NOT e.scope_held
        AND (a.user_id IS NULL OR a.user_id=m.user_id) AND (e.user_id IS NULL OR e.user_id=m.user_id)
        AND CASE WHEN w.department_read_v2 THEN
          department_read_grants() ? a.workspace_id::text
          AND department_row_allows(department_read_grants(),a.workspace_id,a.sensitivity,a.compartments,a.user_id)
          AND department_row_allows(department_read_grants(),e.workspace_id,e.sensitivity,e.compartments,e.user_id)
        ELSE (sensitivity_rank(a.sensitivity)<=sensitivity_rank(m.clearance)
        AND sensitivity_rank(e.sensitivity)<=sensitivity_rank(m.clearance)
        AND (effective_member_team_compartments(m.user_id,m.workspace_id) IS NULL OR
          (a.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)
            AND e.compartments <@ effective_member_team_compartments(m.user_id,m.workspace_id)))
        AND context_scope_allows_current_principal(a.workspace_id,a.sensitivity,a.compartments,a.project_ids)
        AND context_scope_allows_current_principal(e.workspace_id,e.sensitivity,e.compartments,e.project_ids)) END
        AND agent_visibility_allows(a.workspace_id,a.user_id,a.assistant_id)
        AND agent_visibility_allows(e.workspace_id,e.user_id,e.assistant_id)
        AND (NOT mutation OR (agent_mutation_scope_allows(a.compartments) AND agent_mutation_scope_allows(e.compartments)))
    )
$$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.crm_activity_scope_allows(crm_activities,boolean)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_4(crm_activities,boolean)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM NULL
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','crm_activity_scope_allows(crm_activities,boolean)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_4(crm_activities,boolean);
CREATE FUNCTION pg_temp.legacy_bypass_successor_5(w uuid,fields text[],i uuid DEFAULT NULL,v text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE context jsonb;mask jsonb;output knowledge_entries;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 IF fields IS NULL OR NOT ARRAY['path','title','content']::text[]<@fields
  OR NOT fields<@ARRAY['path','title','content','summary','tags','metadata']::text[]
  OR array_position(fields,NULL) IS NOT NULL OR cardinality(fields)<>(SELECT count(DISTINCT f) FROM unnest(fields) f)
  OR (i IS NULL) IS DISTINCT FROM (v IS NULL)
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR nullif(current_setting('app.agent_actor_id',true),'') IS DISTINCT FROM actor::text THEN RETURN false;END IF;
 -- Delegates current member/actor, catalog, bounds and the closed physical schema.
 context:=application_knowledge_query_context(w);
 IF context IS NULL THEN RETURN false;END IF;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  mask:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
  IF mask IS NULL OR NOT coalesce(to_jsonb(fields)<@(mask->'writeFields'),false) THEN RETURN false;END IF;
 END IF;
 IF i IS NOT NULL THEN
  SELECT k.* INTO output FROM knowledge_entries k WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=v
   AND k.xmin::text::bigint=(pg_current_xact_id()::text::numeric % 4294967296)::bigint FOR UPDATE;
  IF NOT FOUND OR output.created_by IS DISTINCT FROM actor OR output.scope_held OR output.source_id IS NOT NULL OR output.source_sha IS NOT NULL
   OR member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
   OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
   OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE THEN RETURN false;END IF;
  IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
   mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',i::text,v);
   IF mask IS NULL OR NOT coalesce(to_jsonb(fields)<@(mask->'writeFields'),false) THEN RETURN false;END IF;
  END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR numeric_value_out_of_range
 OR insufficient_privilege THEN RETURN false;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.native_knowledge_creation_fields_allowed(uuid,text[],uuid,text)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_5(uuid,text[],uuid,text)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','native_knowledge_creation_fields_allowed(uuid,text[],uuid,text)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_5(uuid,text[],uuid,text);
CREATE FUNCTION pg_temp.legacy_bypass_successor_6(w uuid,i uuid,v text,producer text,sources jsonb)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
 output knowledge_entries;source jsonb;current jsonb;output_source jsonb;derivation uuid;
BEGIN
 IF actor IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS NOT NULL AND current_setting('app.agent_workspace_id',true)::uuid<>w
  OR nullif(current_setting('app.agent_actor_id',true),'') IS NOT NULL AND current_setting('app.agent_actor_id',true)::uuid<>actor
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sources) proposed(value) WHERE proposed.value->>'resourceKind'='application_field') THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT k.* INTO output FROM knowledge_entries k WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=v
  AND k.xmin::text::bigint=(pg_current_xact_id()::text::numeric % 4294967296)::bigint FOR UPDATE;
 IF NOT FOUND OR output.created_by IS DISTINCT FROM actor OR output.scope_held OR output.source_id IS NOT NULL OR output.source_sha IS NOT NULL
  OR member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 output_source:=read_admitted_native_scope_snapshot(w,'knowledge_entry',i);
 IF output_source IS NULL OR output_source->>'held' IS DISTINCT FROM 'false' OR output_source->>'version' IS DISTINCT FROM v
  OR (SELECT count(DISTINCT (s->>'resourceKind',s->>'resourceId')) FROM jsonb_array_elements(sources) s)<>jsonb_array_length(sources) THEN
  RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
 FOR source IN SELECT value FROM jsonb_array_elements(sources) ORDER BY value->>'resourceKind',value->>'resourceId' LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN
   RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN
    RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR (current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity')
    IS DISTINCT FROM (source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT (current->'compartments')@>(source->'compartments') OR NOT (source->'compartments')@>(current->'compartments')
   OR NOT (current->'projectIds')@>(source->'projectIds') OR NOT (source->'projectIds')@>(current->'projectIds') THEN
   RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text
   OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN
   RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
 END LOOP;
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry',i,v,producer,NULL,NULL,output.sensitivity,output.compartments,output.project_ids,p.revision
  FROM workspace_access_policies p WHERE p.workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,derivation,s->>'resourceKind',(s->>'resourceId')::uuid,s->>'version' FROM jsonb_array_elements(sources) s ORDER BY s->>'resourceKind',s->>'resourceId';
 SET CONSTRAINTS page_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS page_derivation_dependencies DEFERRED;
 RETURN derivation;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_6(uuid,uuid,text,text,jsonb)');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','record_admitted_knowledge_entry_derivation(uuid,uuid,text,text,jsonb)';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_6(uuid,uuid,text,text,jsonb);
CREATE FUNCTION pg_temp.legacy_bypass_successor_7(w uuid,i uuid,expected_version text,body text,producer text,sources jsonb,teams text[],projects uuid[])
RETURNS SETOF knowledge_entries LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;output knowledge_entries;
 context jsonb;mask jsonb;source jsonb;current jsonb;derivation uuid;prior_revision uuid;next_revision uuid;
BEGIN
 IF actor IS NULL OR body IS NULL OR expected_version IS NULL OR nullif(current_setting('app.application_id',true),'') IS NOT NULL
  OR nullif(current_setting('app.public_share_root',true),'') IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR nullif(current_setting('app.agent_workspace_id',true),'') IS DISTINCT FROM w::text
  OR nullif(current_setting('app.agent_actor_id',true),'') IS DISTINCT FROM actor::text
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid='public.knowledge_entries'::regclass
   WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,'USAGE')))
  OR jsonb_typeof(sources) IS DISTINCT FROM 'array' OR jsonb_array_length(sources) NOT BETWEEN 1 AND 1000
  OR length(btrim(producer)) NOT BETWEEN 1 AND 256 OR teams IS NULL OR projects IS NULL
  OR array_position(teams,NULL) IS NOT NULL OR array_position(projects,NULL) IS NOT NULL
  OR (SELECT count(DISTINCT (s->>'resourceKind',s->>'resourceId')) FROM jsonb_array_elements(sources) s)<>jsonb_array_length(sources) THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 context:=application_knowledge_query_context(w);IF context IS NULL THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 IF native_knowledge_version_fields_allowed(w,i,application_knowledge_field_keys()) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 SELECT k.* INTO output FROM knowledge_entries k WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=expected_version FOR UPDATE;
 IF NOT FOUND OR output.scope_held OR output.source_id IS NOT NULL OR output.source_sha IS NOT NULL
  OR member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE
  OR application_canonical_ancestry_allowed(w,'knowledge_entry',i,expected_version,true) IS NOT TRUE THEN
  RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  mask:=read_native_application_field_catalog(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry');
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',i::text,expected_version);
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 END IF;
 SELECT ARRAY(SELECT DISTINCT unnest(output.compartments||teams) ORDER BY 1),ARRAY(SELECT DISTINCT unnest(output.project_ids||projects) ORDER BY 1)
  INTO output.compartments,output.project_ids;
 IF member_operation_scope_allows(w,output.sensitivity,output.compartments,true) IS NOT TRUE
  OR agent_mutation_scope_allows(output.compartments) IS NOT TRUE
  OR agent_read_scope_allows(output.sensitivity,output.compartments,output.project_ids) IS NOT TRUE THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 -- Every exact original observation is validated before its own canonical body changes.
 -- No source edge, selected field or same-destination guard is removed.
 FOR source IN SELECT value FROM jsonb_array_elements(sources) ORDER BY value->>'resourceKind',value->>'resourceId' LOOP
  IF entity_derivation_envelope_valid(source) IS NOT TRUE OR source->>'workspaceId' IS DISTINCT FROM w::text THEN RAISE EXCEPTION 'scope_evidence_missing' USING ERRCODE='22023';END IF;
  IF source->>'resourceKind'='external_source' THEN
   IF external_source_retention_allowed(w,(source->>'resourceId')::uuid,source->>'version') IS NOT TRUE THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
   current:=external_source_snapshot(w,(source->>'resourceId')::uuid);
  ELSE current:=read_entity_derivation_source(w,source->>'resourceKind',(source->>'resourceId')::uuid);END IF;
  IF current IS NULL OR current->>'held' IS DISTINCT FROM 'false' OR current->>'version' IS DISTINCT FROM source->>'version'
   OR current->>'validTo' IS NOT NULL OR current->>'retractedAt' IS NOT NULL
   OR (current->'workspaceId',current->'userId',current->'assistantId',current->'sensitivity') IS DISTINCT FROM (source->'workspaceId',source->'userId',source->'assistantId',source->'sensitivity')
   OR NOT (current->'compartments')@>(source->'compartments') OR NOT (source->'compartments')@>(current->'compartments')
   OR NOT (current->'projectIds')@>(source->'projectIds') OR NOT (source->'projectIds')@>(current->'projectIds') THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
  IF source->>'userId' IS NOT NULL AND source->>'userId' IS DISTINCT FROM actor::text OR sensitivity_rank(source->>'sensitivity')>sensitivity_rank(output.sensitivity)
   OR NOT to_jsonb(output.compartments)@>(source->'compartments') OR NOT to_jsonb(output.project_ids)@>(source->'projectIds') THEN RAISE EXCEPTION 'scope_visibility_incompatible' USING ERRCODE='22023';END IF;
 END LOOP;
 prior_revision:=capture_native_knowledge_version(w,i,expected_version,application_knowledge_field_keys());
 PERFORM archive_native_knowledge_version(w,i,expected_version,prior_revision);
 INSERT INTO knowledge_entry_scope_revisions(workspace_id,entry_id,sensitivity,compartments,project_ids,revision_kind)
  VALUES(w,i,output.sensitivity,output.compartments,output.project_ids,'body') RETURNING id INTO next_revision;
 INSERT INTO workspace_access_policies(workspace_id) VALUES(w) ON CONFLICT DO NOTHING;
 INSERT INTO scope_derivations(workspace_id,resource_kind,resource_id,resource_version,producer,user_id,assistant_id,sensitivity,compartments,project_ids,source_policy_revision)
  SELECT w,'knowledge_entry_revision',next_revision,'1',producer,NULL,NULL,output.sensitivity,output.compartments,output.project_ids,p.revision
  FROM workspace_access_policies p WHERE p.workspace_id=w RETURNING id INTO derivation;
 INSERT INTO scope_derivation_sources(workspace_id,derivation_id,source_kind,source_id,source_version)
  SELECT w,derivation,s->>'resourceKind',(s->>'resourceId')::uuid,s->>'version' FROM jsonb_array_elements(sources) s ORDER BY s->>'resourceKind',s->>'resourceId';
 -- Validate the complete original input graph before its carrier is changed.
 -- New publication/value pairing remains deferred until the actual result exists.
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies IMMEDIATE;
 SET CONSTRAINTS application_field_derivation_dependencies,page_derivation_dependencies,workflow_derivation_dependencies DEFERRED;
 UPDATE knowledge_entries k SET content=body,compartments=output.compartments,project_ids=output.project_ids,updated_at=now()
  WHERE k.workspace_id=w AND k.id=i AND k.scope_version::text=expected_version RETURNING k.* INTO output;
 IF NOT FOUND THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF context#>>'{policy,nativeDefault}' IS DISTINCT FROM 'true' THEN
  mask:=read_native_application_field_mask(w,'{"kind":"native","moduleKey":"native"}','knowledge_entry',i::text,output.scope_version::text);
  IF mask IS NULL OR NOT coalesce(mask->'writeFields' ? 'content',false) THEN RAISE EXCEPTION 'scope_operation_denied' USING ERRCODE='42501';END IF;
 END IF;
 PERFORM publish_native_knowledge_body_revision(w,i,output.scope_version::text,next_revision);
 RETURN NEXT output;
END $$;
 DO $legacy_bypass_predecessor$
 DECLARE actual pg_proc;reference pg_proc;owner_role oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
 BEGIN
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])');
  SELECT * INTO STRICT reference FROM pg_proc WHERE oid=to_regprocedure('pg_temp.legacy_bypass_successor_7(uuid,uuid,text,text,text,jsonb,text[],uuid[])');
  IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_role OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_role,owner_role,'EXECUTE',false),makeaclitem('app_user'::regrole,owner_role,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proowner','proacl']) IS DISTINCT FROM
      (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proowner','proacl'])
  THEN RAISE EXCEPTION 'legacy_bypass_function_predecessor_changed: %','update_admitted_knowledge_entry_body(uuid,uuid,text,text,text,jsonb,text[],uuid[])';END IF;
  
 END $legacy_bypass_predecessor$;
 DROP FUNCTION pg_temp.legacy_bypass_successor_7(uuid,uuid,text,text,text,jsonb,text[],uuid[]);
-- [COMP:api/migration-owner-role] Restricted current workspace admission facts.
-- Installed by the authenticated legacy bypass retirement successor.
CREATE FUNCTION pg_temp.a8314_admission_policy_ref(w uuid)
RETURNS TABLE("workspaceId" uuid,mode text,"setupState" text,"departmentReadV2" boolean,
 revision text,"defaultDepartmentId" uuid,"defaultCompartment" text)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT p.workspace_id,p.access_mode,p.setup_state,ws.department_read_v2,
  p.revision::text,p.default_department_id,g.compartment_key
 FROM public.workspace_access_policies p
 JOIN public.workspaces ws ON ws.id=p.workspace_id
 LEFT JOIN public.workspace_groups g ON g.id=p.default_department_id AND g.workspace_id=p.workspace_id
  AND g.kind='team' AND g.status='active'
 WHERE p.workspace_id=w AND (
  EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=w
   AND m.user_id=nullif(current_setting('app.current_user_id',true),'')::uuid)
  OR EXISTS(SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid='public.workspace_access_policies'::regclass
   AND pg_catalog.pg_has_role(session_user,c.relowner,'USAGE')));
$$;

DO $bypass_admission_reference$
DECLARE actual pg_proc;reference pg_proc;owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
BEGIN
 SELECT * INTO STRICT actual FROM pg_proc WHERE oid='public.read_workspace_admission_policy(uuid)'::regprocedure;
 SELECT * INTO STRICT reference FROM pg_proc WHERE oid='pg_temp.a8314_admission_policy_ref(uuid)'::regprocedure;
 IF actual.proowner<>owner_id OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl'])
  IS DISTINCT FROM (to_jsonb(reference)-ARRAY['oid','proname','pronamespace','proacl'])
  OR (SELECT count(*) FROM aclexplode(actual.proacl))<>2
  OR EXISTS(SELECT 1 FROM aclexplode(actual.proacl) a WHERE a.grantor<>owner_id
      OR a.grantee NOT IN(owner_id,'app_user'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)
 THEN RAISE EXCEPTION 'legacy_bypass_admission_member_changed';END IF;
END $bypass_admission_reference$;
