CREATE TEMP TABLE a8314_bypass_setup_ref(actor_user_id uuid,workspace_id uuid) ON COMMIT DROP;
CREATE POLICY connector_setup_owner_read ON pg_temp.a8314_bypass_setup_ref FOR SELECT USING (
 actor_user_id=nullif(current_setting('app.current_user_id',true),'')::uuid
 AND (workspace_id IS NULL OR EXISTS (SELECT 1 FROM public.workspace_members m
   WHERE m.workspace_id=a8314_bypass_setup_ref.workspace_id AND m.user_id=actor_user_id)));
CREATE TEMP TABLE a8314_bypass_approval_ref(kind text,approval_payload jsonb) ON COMMIT DROP;
CREATE POLICY department_approval_privacy ON pg_temp.a8314_bypass_approval_ref AS RESTRICTIVE FOR SELECT USING ((kind <> 'department_access'::text) OR
  public.can_view_department_request(NULLIF(approval_payload->>'requestId','')::uuid,
   NULLIF(current_setting('app.current_user_id',true),'')::uuid));
DO $bypass_policy_successor$
DECLARE t record;rel pg_class;p pg_policy;r pg_policy;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.workspaces'::regclass);
BEGIN
 IF pg_has_role('app_user',owner_id,'MEMBER') THEN RAISE EXCEPTION 'legacy_bypass_connector_owner_unsafe';END IF;
 FOR t IN SELECT * FROM pg_temp.legacy_bypass_policies LOOP
  SELECT * INTO STRICT rel FROM pg_class WHERE oid=to_regclass(format('public.%I',t.relation));
  SELECT * INTO p FROM pg_policy WHERE polrelid=rel.oid AND polname=t.policy;
  IF NOT rel.relrowsecurity OR rel.relforcerowsecurity IS DISTINCT FROM t.forced
    OR (NOT t.forced AND p.oid IS NOT NULL)
    OR (t.forced AND (rel.relowner<>owner_id OR p.oid IS NULL OR p.polcmd<>'*' OR NOT p.polpermissive
      OR p.polroles<>ARRAY[owner_id] OR pg_get_expr(p.polqual,rel.oid) IS DISTINCT FROM 'true'
      OR pg_get_expr(p.polwithcheck,rel.oid) IS DISTINCT FROM 'true'
      OR (SELECT count(*) FROM pg_policy WHERE polrelid=rel.oid)<>CASE WHEN t.relation='connector_pending_setups' THEN 2 ELSE 1 END))
  THEN RAISE EXCEPTION 'legacy_bypass_policy_successor_changed: %.%',t.relation,t.policy;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_temp.legacy_bypass_inert_policies inert JOIN pg_class c ON c.relname=inert.relation
    JOIN pg_policy pol ON pol.polrelid=c.oid AND pol.polname=inert.policy WHERE c.relnamespace='public'::regnamespace)
 THEN RAISE EXCEPTION 'legacy_bypass_inert_successor_changed';END IF;
 FOR t IN SELECT * FROM (VALUES ('connector_pending_setups','a8314_bypass_setup_ref','connector_setup_owner_read'),
   ('pending_approvals','a8314_bypass_approval_ref','department_approval_privacy')) policy(relation,reference,policy) LOOP
  SELECT * INTO STRICT p FROM pg_policy WHERE polrelid=to_regclass('public.'||t.relation) AND polname=t.policy;
  SELECT * INTO STRICT r FROM pg_policy WHERE polrelid=to_regclass('pg_temp.'||t.reference) AND polname=t.policy;
  IF (p.polcmd,p.polpermissive,p.polroles,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))
    IS DISTINCT FROM (r.polcmd,r.polpermissive,r.polroles,
      replace(pg_get_expr(r.polqual,r.polrelid),t.reference||'.',t.relation||'.'),pg_get_expr(r.polwithcheck,r.polrelid))
  THEN RAISE EXCEPTION 'legacy_bypass_policy_floor_changed: %',t.policy;END IF;
 END LOOP;
END $bypass_policy_successor$;
DROP TABLE pg_temp.a8314_bypass_setup_ref,pg_temp.a8314_bypass_approval_ref,
 pg_temp.legacy_bypass_policies,pg_temp.legacy_bypass_inert_policies;
DO $legacy_bypass_postconditions$ DECLARE remaining text;
 BEGIN
  SELECT p.oid::regprocedure::text INTO remaining FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
   WHERE n.nspname NOT IN('pg_catalog','information_schema') AND n.nspname!~'^pg_' AND strpos(p.prosrc,'app.system_bypass')>0 LIMIT 1;
  IF remaining IS NOT NULL THEN RAISE EXCEPTION 'legacy_bypass_function_reader_remains: %',remaining;END IF;
  SELECT p.polrelid::regclass::text||'.'||p.polname INTO remaining FROM pg_policy p
   WHERE p.polrelid<>coalesce(to_regclass('public.pending_classifications')::oid,0::oid)
     AND strpos(concat(pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)),'app.system_bypass')>0 LIMIT 1;
  IF remaining IS NOT NULL THEN RAISE EXCEPTION 'legacy_bypass_policy_reader_remains: %',remaining;END IF;
 END $legacy_bypass_postconditions$;
DO $record_conversion_auth_envelope$
DECLARE e oid:='public.conversation_envelopes'::regclass;a pg_attribute;t pg_trigger;r record;
BEGIN
 FOR r IN SELECT * FROM (VALUES('record_conversion_generation','int8'),('record_conversion_revision','int8'),
   ('record_conversion_through','int4'),('record_conversion_legacy','bool')) fields(name,type) LOOP
  SELECT * INTO STRICT a FROM pg_attribute WHERE attrelid=e AND attname=r.name AND attnum>0 AND NOT attisdropped;
  IF a.atttypid<>to_regtype(r.type) OR a.attnotnull OR a.atthasdef OR a.attgenerated<>'' OR a.attidentity<>''
  THEN RAISE EXCEPTION 'record_conversion_auth_envelope_field_changed: %',r.name;END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=e AND conname='conversation_envelopes_record_conversion_through_check'
    AND convalidated AND pg_get_constraintdef(oid)='CHECK ((record_conversion_through >= 0))')
 THEN RAISE EXCEPTION 'record_conversion_auth_envelope_bound_changed';END IF;
 FOR r IN SELECT * FROM (VALUES('enqueue_conversation_record_conversion',12),('requeue_conversation_record_conversion',16)) deps(name,type) LOOP
  SELECT * INTO STRICT t FROM pg_trigger WHERE tgrelid=e AND tgname=r.name;
  IF t.tgfoid<>'public.enqueue_conversation_record_conversion()'::regprocedure OR t.tgtype<>r.type+1 OR t.tgenabled<>'O'
   OR t.tgnargs<>0 OR t.tgisinternal OR t.tgconstraint<>0
  THEN RAISE EXCEPTION 'record_conversion_auth_envelope_trigger_changed: %',r.name;END IF;
  IF r.type=16 AND (t.tgqual IS NULL OR pg_get_triggerdef(t.oid) NOT LIKE
    '% AFTER UPDATE OF version, record_data_revision ON % FOR EACH ROW WHEN (((old.version IS DISTINCT FROM new.version) OR (old.record_data_revision IS DISTINCT FROM new.record_data_revision))) EXECUTE FUNCTION enqueue_conversation_record_conversion()')
   OR r.type=12 AND (t.tgqual IS NOT NULL OR t.tgattr::text<>'')
  THEN RAISE EXCEPTION 'record_conversion_auth_envelope_trigger_condition_changed: %',r.name;END IF;
 END LOOP;
END $record_conversion_auth_envelope$;
DO $receiving_owner_compile$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_receiving_ref_conversation_page_visitor_current(page_id uuid,sid uuid,guest_token text,mutation boolean)
RETURNS public.conversation_envelopes LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path=pg_catalog,public,pg_temp AS $visitor$
DECLARE e public.conversation_envelopes;s public.sessions;workspace uuid;
 sentinel constant uuid:=''00000000-0000-0000-0000-0000000c0a57'';
BEGIN
 IF mutation IS NULL OR (mutation AND guest_token IS NULL) THEN RETURN NULL;END IF;
 SELECT ct.workspace_id INTO workspace FROM public.comment_threads ct JOIN public.saved_views p
  ON p.id=ct.page_id AND p.workspace_id=ct.workspace_id WHERE ct.page_id=$1 AND ct.session_id=sid;
 IF workspace IS NULL THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.conversation_envelopes WHERE session_id=sid) THEN
  PERFORM public.classify_conversation_envelope(sid,true);
 END IF;
 IF mutation THEN
  SELECT * INTO s FROM public.sessions WHERE id=sid FOR UPDATE;
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid FOR UPDATE;
 ELSE
  SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid FOR SHARE;
 END IF;
 IF s.id IS NULL OR e.session_id IS NULL OR e.workspace_id IS DISTINCT FROM workspace
  OR e.starter_user_id IS DISTINCT FROM s.user_id OR s.anchor_kind IS DISTINCT FROM ''doc_thread''
  OR s.recording_privacy_held OR public.scope_review_state_held(''session'',sid)
  OR e.cap IS DISTINCT FROM ''public'' OR e.compartments<>''{}''::text[]
  OR (guest_token IS NULL AND (e.visibility<>''workspace'' OR e.classification=''legacy_personal'' AND NOT public.conversation_consent_current(sid)))
  OR (guest_token IS NOT NULL AND (s.user_id<>sentinel OR s.guest_session_token IS DISTINCT FROM guest_token))
 THEN RETURN NULL;END IF;
 RETURN e;
END $visitor$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_receiving_ref_conversation_legacy_page_guest_rows(e public.conversation_envelopes,after_sequence integer,through_sequence integer)
RETURNS SETOF public.session_messages LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $guest_rows$
 SELECT m.* FROM public.session_messages m JOIN public.sessions s ON s.id=m.session_id
 JOIN public.comment_threads ct ON ct.session_id=s.id AND ct.workspace_id=e.workspace_id
 WHERE m.session_id=e.session_id AND s.anchor_kind=''doc_thread'' AND s.guest_session_token IS NOT NULL
  AND s.user_id=''00000000-0000-0000-0000-0000000c0a57''::uuid AND m.sender_user_id=s.user_id AND m.role=''user''
  AND m.sequence_num>after_sequence AND (through_sequence IS NULL OR m.sequence_num<=through_sequence)
  AND m.workspace_id IS NULL AND m.user_id IS NULL AND m.assistant_id IS NULL AND m.scope_held IS NOT TRUE
  AND m.sensitivity IS NULL AND m.compartments IS NULL AND m.project_ids IS NULL AND m.scope_version IS NULL
  AND jsonb_typeof(m.content)=''string'' AND m.attachments=''[]''::jsonb
  AND NOT EXISTS(SELECT 1 FROM public.scope_resource_states r WHERE r.resource_kind=''session_message'' AND r.resource_id=m.id)
  AND NOT EXISTS(SELECT 1 FROM public.scope_derivations d WHERE d.resource_kind=''session_message'' AND d.resource_id=m.id)
  AND NOT EXISTS(SELECT 1 FROM public.conversation_message_quarantine q WHERE q.message_id=m.id AND q.reason<>''missing_stamp'')
$guest_rows$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_receiving_ref_read_native_page_conversation_rows(page_id uuid,guest_token text)
RETURNS TABLE("threadId" uuid,"sessionId" uuid,"anchorBlockId" text,quote text,"threadCreatedAt" timestamptz,
 "guestName" text,author text,avatar text,body text,"messageCreatedAt" timestamptz)
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $page_rows$
 SELECT ct.id,ct.session_id,ct.anchor_block_id,ct.quote,ct.created_at,ct.external_author_name,
  CASE WHEN m.sender_user_id=''00000000-0000-0000-0000-0000000c0a57''::uuid THEN ct.external_author_name ELSE u.name END,
  CASE WHEN m.sender_user_id=''00000000-0000-0000-0000-0000000c0a57''::uuid THEN NULL ELSE u.avatar_url END,
  nullif(public.conversation_searchable_text(m.content),''''),m.created_at
 FROM public.comment_threads ct
 CROSS JOIN LATERAL public.conversation_page_visitor_current($1,ct.session_id,$2,false) e
 LEFT JOIN LATERAL (
  SELECT visible.* FROM public.conversation_record_rows(e,0,NULL,false,NULL,true) visible
 ) m ON $2 IS NULL OR m.role=''user'' AND m.sender_user_id=e.starter_user_id
 LEFT JOIN public.users u ON u.id=m.sender_user_id
 WHERE ct.page_id=$1 AND e.session_id=ct.session_id
  AND ($2 IS NOT NULL OR ct.resolved_at IS NULL)
 ORDER BY ct.created_at,ct.id,m.sequence_num
$page_rows$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_receiving_ref_advance_conversation_envelope_backfill(batch_size integer)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $backfill$
DECLARE checkpoint public.conversation_envelope_backfill_checkpoint;ids uuid[];sid uuid;
 scanned integer:=0;classified integer:=0;has_more boolean;
BEGIN
 IF batch_size IS NULL OR batch_size NOT BETWEEN 1 AND 200 THEN
  RAISE EXCEPTION ''conversation_backfill_limit'' USING ERRCODE=''22023'';END IF;
 SELECT * INTO checkpoint FROM public.conversation_envelope_backfill_checkpoint WHERE singleton FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN jsonb_build_object(''busy'',true,''classified'',0,''scanned'',0);END IF;
 IF checkpoint.complete THEN RETURN jsonb_build_object(''done'',true,''classified'',0,''scanned'',0);END IF;
 IF checkpoint.after_session_id IS NULL THEN
  ids:=ARRAY(SELECT id FROM public.sessions ORDER BY id LIMIT batch_size+1);
 ELSE
  ids:=ARRAY(SELECT id FROM public.sessions WHERE id>checkpoint.after_session_id ORDER BY id LIMIT batch_size+1);
 END IF;
 has_more:=cardinality(ids)>batch_size;
 FOREACH sid IN ARRAY ids[1:batch_size] LOOP
  scanned:=scanned+1;
  IF NOT EXISTS(SELECT 1 FROM public.conversation_envelopes e WHERE e.session_id=sid) THEN
   -- Retained historical facts must come from one locked session version.
   PERFORM id FROM public.sessions WHERE id=sid FOR SHARE;
   IF FOUND AND public.classify_conversation_envelope(sid,true) THEN classified:=classified+1;END IF;
  END IF;
 END LOOP;
 UPDATE public.conversation_envelope_backfill_checkpoint SET after_session_id=coalesce(ids[scanned],after_session_id),complete=NOT has_more WHERE singleton;
 RETURN jsonb_build_object(''done'',NOT has_more,''classified'',classified,''scanned'',scanned);
END $backfill$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_receiving_ref_quarantine_unadmitted_conversation_append(message public.session_messages)
RETURNS void LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $append_floor$
DECLARE e public.conversation_envelopes;reason text;
BEGIN
 IF message.role NOT IN(''user'',''assistant'') THEN RETURN;END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=message.session_id FOR UPDATE;
 IF NOT FOUND OR e.workspace_id IS NULL THEN RETURN;END IF;
 reason:=CASE
  WHEN message.workspace_id IS DISTINCT FROM e.workspace_id OR message.sensitivity IS NULL
    OR message.compartments IS NULL OR message.project_ids IS NULL OR message.scope_version IS NULL THEN ''missing_stamp''
  WHEN message.user_id IS NOT NULL AND (e.visibility=''workspace'' OR message.user_id<>e.starter_user_id) THEN ''private_owner''
  WHEN public.sensitivity_rank(message.sensitivity)>public.sensitivity_rank(e.cap) THEN ''above_cap''
  WHEN NOT message.compartments<@e.compartments OR NOT message.project_ids<@public.conversation_hard_project_ids(e.compartments) THEN ''outside_boundary''
  ELSE NULL END;
 IF reason IS NOT NULL THEN
  INSERT INTO public.conversation_message_quarantine(session_id,message_id,reason)
  VALUES(message.session_id,message.id,reason) ON CONFLICT DO NOTHING;
 END IF;
END $append_floor$;';
END $receiving_owner_compile$;
CREATE TEMP TABLE a8314_receiving_oid(oid oid PRIMARY KEY) ON COMMIT DROP;
DO $receiving_owner_source$
DECLARE member record;actual pg_proc;reviewed pg_proc;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
BEGIN
 FOR member IN SELECT * FROM (VALUES ('conversation_page_visitor_current','a8314_receiving_ref_conversation_page_visitor_current'),('conversation_legacy_page_guest_rows','a8314_receiving_ref_conversation_legacy_page_guest_rows'),('read_native_page_conversation_rows','a8314_receiving_ref_read_native_page_conversation_rows'),('advance_conversation_envelope_backfill','a8314_receiving_ref_advance_conversation_envelope_backfill'),('quarantine_unadmitted_conversation_append','a8314_receiving_ref_quarantine_unadmitted_conversation_append')) q(name,reference) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=member.reference;
  SELECT * INTO actual FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=member.name AND proargtypes=reviewed.proargtypes;
  IF actual.oid IS NULL OR actual.proowner<>owner_id OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)]
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
    (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl']) THEN
   RAISE EXCEPTION 'conversation_receiving_helper_changed: %',member.name;END IF;
  INSERT INTO pg_temp.a8314_receiving_oid VALUES(actual.oid);
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE oid='public.conversation_envelope_backfill_checkpoint'::regclass AND c.relkind='r'
   AND c.relowner=owner_id AND c.relrowsecurity AND NOT c.relforcerowsecurity
   AND NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=c.oid)
   AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(c.relacl,acldefault('r',owner_id))) WHERE grantee<>owner_id))
  OR (SELECT array_agg(attname::text ORDER BY attnum) FROM pg_attribute WHERE attrelid='public.conversation_envelope_backfill_checkpoint'::regclass
   AND attnum>0 AND NOT attisdropped) IS DISTINCT FROM ARRAY['singleton','after_session_id','complete']::text[]
 THEN RAISE EXCEPTION 'conversation_receiving_backfill_catalog_changed';END IF;
END $receiving_owner_source$;
DO $prompt_memory_compile$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_prompt_memory_ref(
 w uuid, actor uuid, answering uuid, sid uuid, device uuid, native_version integer,
 credential_actor uuid, include_departments boolean, include_policy boolean, token uuid
) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $prompt$
DECLARE
 facts jsonb;
 memory_ids uuid[];
 memory_versions text[];
 dependency record;
 workspace_fields constant text[]:=ARRAY[
  ''id'',''summary'',''tags'',''app_id'',''scope'',''confidence'',''valid_to'',''scope_held'',''updated_at'',
  ''workspace_id'',''user_id'',''assistant_id'',''created_by_user_id'',''scope_version'',''sensitivity'',''compartments'',''project_ids'',''learning''
 ];
 ranked_fields constant text[]:=workspace_fields||ARRAY[''created_at'',''last_recalled_at'',''recall_count''];
 member record;
 section jsonb;
 section_roots jsonb;
 observations jsonb:=''{}'';
 roots jsonb:=''[]'';
 submitted text[]:=''{}'';
 proof jsonb;
 refused_message text;
 index integer;
 verdict jsonb;
BEGIN
 IF current_setting(''transaction_isolation'') NOT IN(''repeatable read'',''serializable'') THEN
  RAISE EXCEPTION ''prompt_memory_snapshot_required'' USING ERRCODE=''42501'';
 END IF;
 facts:=public.conversation_record_turn_facts(w,actor,answering,sid,device,native_version,credential_actor,
  include_departments,include_policy,token,''dispatch'');
 IF current_setting(''app.agent_shared_audience'',true)=''true''
  OR NOT EXISTS(SELECT 1 FROM public.sessions s WHERE s.id=sid AND s.workspace_id=w
    AND s.user_id=actor AND s.assistant_id=answering AND s.channel_type=''web''
    AND s.app_origin=''chat'' AND s.anchor_kind=''none'' AND s.anchor_ref IS NULL
    AND s.visibility IN(''owner'',''personal'') AND s.mode IS DISTINCT FROM ''draft'') THEN
  RETURN facts||jsonb_build_object(''kind'',''unsupported'',''reason'',''conversation_shape'');
 END IF;

 -- Keep the metadata owner''s admission and the complete workspace domain,
 -- including currently denied rows. Scan only the first 101 tuples through
 -- the workspace prefix of idx_memories_visibility. An overfull domain uses
 -- the original owners before evaluating any ancestry or payload.
 IF public.application_memory_query_context(w) IS NULL THEN
  RAISE EXCEPTION ''query_domain_unavailable'' USING ERRCODE=''42501'';
 END IF;
 WITH candidate AS MATERIALIZED (
  SELECT m.id,m.scope_version FROM public.memories m WHERE m.workspace_id=w
  ORDER BY m.user_id,m.assistant_id LIMIT 101
 )
 SELECT array_agg(id ORDER BY id),array_agg(scope_version::text ORDER BY id)
 INTO memory_ids,memory_versions FROM candidate;
 IF coalesce(cardinality(memory_ids),0)>100 THEN
  RETURN facts||jsonb_build_object(''kind'',''unsupported'',''reason'',''metadata_cohort_bound'');
 END IF;
 IF cardinality(memory_ids)>0 THEN
  FOR dependency IN SELECT node_version,source FROM public.read_external_source_dependencies(
   w,array_fill(''memory''::text,ARRAY[cardinality(memory_ids)]),memory_ids,memory_versions
  ) LOOP
   IF dependency.source IS NULL OR dependency.node_version IS NULL
    OR dependency.source->>''version'' IS DISTINCT FROM dependency.node_version
    OR dependency.source->>''workspaceId'' IS DISTINCT FROM w::text
    OR dependency.source->>''resourceKind'' IS DISTINCT FROM ''external_source''
    OR NOT coalesce(pg_input_is_valid(dependency.source->>''resourceId'',''uuid''),false)
   THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
   verdict:=jsonb_build_object(''kind'',''unsupported'',''reason'',''external_ancestry'');
  END LOOP;
  IF verdict IS NOT NULL THEN RETURN facts||verdict;END IF;
 END IF;

 FOR member IN SELECT * FROM (VALUES (''ranked'',ranked_fields),(''workspace'',workspace_fields)) AS m(name,keys) LOOP
  BEGIN
   SELECT jsonb_agg(value ORDER BY ord) INTO section
   FROM public.read_native_memory_query_projection(w,member.keys,true) WITH ORDINALITY p(value,ord);
  EXCEPTION WHEN insufficient_privilege THEN
   GET STACKED DIAGNOSTICS refused_message=MESSAGE_TEXT;
   IF refused_message NOT IN(''query_domain_unavailable'',''access_unavailable'') THEN RAISE;END IF;
   observations:=observations||jsonb_build_object(member.name,jsonb_build_object(''state'',''denied''));
   CONTINUE;
  END;
  IF jsonb_typeof(section) IS DISTINCT FROM ''array'' OR section->0->''row'' IS DISTINCT FROM ''null''::jsonb
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  SELECT jsonb_agg(DISTINCT jsonb_build_object(''kind'',source->''resourceKind'',''id'',source->''resourceId'',''version'',source->''version''))
  INTO section_roots FROM jsonb_array_elements(section) entry
  CROSS JOIN LATERAL jsonb_array_elements(entry->''sources'') source;
  IF section_roots IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  roots:=roots||jsonb_build_array(section_roots);
  submitted:=array_append(submitted,member.name);
  observations:=observations||jsonb_build_object(member.name,jsonb_build_object(''state'',''pending'',''projection'',section));
 END LOOP;

 IF cardinality(submitted)>0 THEN
  proof:=public.capture_conversation_preparation(w,roots,NULL,NULL)->''cohorts'';
  IF jsonb_typeof(proof) IS DISTINCT FROM ''array'' OR jsonb_array_length(proof)<>cardinality(submitted)
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';END IF;
  FOR index IN 1..cardinality(submitted) LOOP
   verdict:=proof->(index-1);
   IF verdict=''null''::jsonb THEN
    RETURN facts||jsonb_build_object(''kind'',''unsupported'',''reason'',''independent_ancestry'');
   ELSIF verdict->>''admitted''=''false'' THEN
    observations:=jsonb_set(observations,ARRAY[submitted[index]],jsonb_build_object(''state'',''denied''));
   ELSIF verdict->>''admitted''=''true'' THEN
    observations:=jsonb_set(observations,ARRAY[submitted[index]],
     (observations->submitted[index])||jsonb_build_object(''state'',''admitted'',''proof'',verdict));
   ELSE
    RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501'';
   END IF;
  END LOOP;
 END IF;
 RETURN facts||jsonb_build_object(''kind'',''sections'',''indexes'',observations);
END $prompt$;
';
END $prompt_memory_compile$;
DO $prompt_memory_current$
DECLARE actual pg_proc;reviewed pg_proc;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 runtime_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
BEGIN
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname='a8314_prompt_memory_ref';
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.capture_native_prompt_memory_sections(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean,uuid)');
 IF actual.oid IS NULL OR actual.pronamespace<>'public'::regnamespace OR actual.proowner<>owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(runtime_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'prompt_memory_executable_contract_changed';END IF;
END $prompt_memory_current$;
DROP FUNCTION pg_temp.a8314_prompt_memory_ref(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean,uuid);
CREATE FUNCTION pg_temp.a8314_lineage_ref_0(
 w uuid, capture_id uuid, recipient uuid, destination public.scope_derivations
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $origin_current$
DECLARE
 observation public.private_transcript_observations;
 envelope public.conversation_envelopes;
 reader uuid;
 projected jsonb;
 origin_anchor jsonb;
 selected_after integer;selected_through integer;selected_topics integer;
 candidate_count integer;candidate_bytes bigint;
BEGIN
 SELECT * INTO observation FROM public.private_transcript_observations o
 WHERE o.workspace_id=w AND o.id=capture_id;
 IF NOT FOUND OR observation.binding->>'kind' IS DISTINCT FROM 'conversation_record_v1'
  OR observation.binding->>'purpose' IS DISTINCT FROM 'native_member_dialogue'
  OR observation.binding->'legacyRowsSelected' IS DISTINCT FROM 'false'::jsonb
 THEN RETURN NULL;END IF;
 SELECT * INTO envelope FROM public.conversation_envelopes e
 WHERE e.workspace_id=w AND e.session_id=observation.session_id;
 IF NOT FOUND OR destination.workspace_id IS DISTINCT FROM w
  OR public.sensitivity_rank(envelope.cap)>public.sensitivity_rank(destination.sensitivity)
  OR NOT envelope.compartments<@destination.compartments
  OR NOT public.conversation_hard_project_ids(envelope.compartments)<@destination.project_ids
 THEN RETURN NULL;END IF;
 reader:=(observation.binding->>'readerUserId')::uuid;
 origin_anchor:=public.conversation_anchor_key(envelope.session_id);
 IF origin_anchor IS NULL OR reader IS NULL OR public.conversation_member_read_allowed(w,envelope.session_id,reader) IS NOT TRUE
  OR NOT EXISTS(SELECT 1 FROM public.sessions s JOIN public.assistants a ON a.id=s.assistant_id AND a.workspace_id=w
   WHERE s.id=envelope.session_id AND NOT reader=ANY(a.blocked_user_ids) AND public.assistant_placement_visible(reader,a.id))
  OR destination.user_id IS NULL AND destination.resource_kind NOT IN('session_message','session_context_revision')
   AND (envelope.visibility<>'workspace' OR origin_anchor<>'[]'::jsonb)
  OR recipient IS NOT NULL AND public.conversation_member_read_allowed(w,envelope.session_id,recipient) IS NOT TRUE
 THEN RETURN NULL;END IF;
 -- A later append or benign settings transition can preserve the exact
 -- selected window. Current role/anchor expiry and a changed selection do
 -- not require a dependency index or a notification to withhold this copy.
 selected_after:=(observation.manifest->>'afterSequence')::integer;
 selected_through:=(observation.manifest->>'throughSequence')::integer;
 selected_topics:=(observation.manifest->>'topicThroughSequence')::integer;
 SELECT count(*),coalesce(sum(bytes),0) INTO candidate_count,candidate_bytes
 FROM (SELECT octet_length(m.content::text)+octet_length(m.attachments::text) AS bytes FROM public.session_messages m
  WHERE m.session_id=envelope.session_id AND m.sequence_num>selected_after AND m.sequence_num<=selected_through
  ORDER BY m.sequence_num LIMIT 4097) bounded;
 IF candidate_count>4096 OR candidate_bytes>8388608 THEN RETURN NULL;END IF;
 projected:=public.project_conversation_record(envelope,selected_after,selected_through,selected_topics,false,reader);
 IF (projected->'manifest') IS DISTINCT FROM observation.manifest THEN RETURN NULL;END IF;
 RETURN projected;
END $origin_current$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_1(w uuid,capture_id uuid,k text,i uuid,recipient uuid,
 destination public.scope_derivations)
RETURNS TABLE(kind text,id uuid,version text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $derivative_edges$
DECLARE sid uuid;projection jsonb;
BEGIN
 SELECT o.session_id INTO sid FROM public.private_transcript_observations o WHERE o.workspace_id=w AND o.id=capture_id;
 -- A durable reply may retain the conversation's own delivered record.
 IF (k,i)=(destination.resource_kind,destination.resource_id) AND sid=(CASE k
  WHEN 'session_message' THEN (SELECT m.session_id FROM public.session_messages m WHERE m.workspace_id=w AND m.id=i)
  WHEN 'session_context_revision' THEN (SELECT r.session_id FROM public.session_context_scope_revisions r WHERE r.workspace_id=w AND r.id=i)
  END) THEN RETURN;END IF;
 projection:=public.conversation_record_derivative_origin(w,capture_id,recipient,destination);
 IF projection IS NULL THEN
  RETURN QUERY SELECT 'conversation_record_refused'::text,capture_id,NULL::text;
  RETURN;
 END IF;
 RETURN QUERY SELECT 'conversation_record_current_root'::text,capture_id,'1'::text
 UNION ALL SELECT 'session_message'::text,m.id,m.scope_version::text
 FROM jsonb_array_elements(projection->'rows') item
 JOIN public.session_messages m ON m.id=(item->>'id')::uuid AND m.workspace_id=w AND m.session_id=sid
 UNION ALL SELECT 'session_context_revision'::text,(item->>'revisionId')::uuid,item->>'version'
 FROM jsonb_array_elements(projection->'annotations') item;
END $derivative_edges$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_2(w uuid,k text,i uuid,recipient uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $native_source$
DECLARE original_actor text:=current_setting('app.current_user_id',true);source jsonb;
BEGIN
 IF recipient IS NULL THEN RETURN public.read_scope_source(w,k,i);END IF;
 IF recipient::text IS NOT DISTINCT FROM original_actor THEN RETURN public.read_admitted_native_scope_snapshot(w,k,i);END IF;
 PERFORM set_config('app.current_user_id',recipient::text,true);
 source:=public.read_admitted_native_scope_snapshot(w,k,i);
 PERFORM set_config('app.current_user_id',coalesce(original_actor,''),true);
 RETURN source;
EXCEPTION WHEN OTHERS THEN
 PERFORM set_config('app.current_user_id',coalesce(original_actor,''),true);
 RAISE;
END $native_source$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_3(w uuid,k text,i uuid,v text,recipient uuid)
RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $derived_current$
DECLARE
 destination public.scope_derivations;
 node record;
 total integer;intact boolean;record_found boolean;obligations jsonb;
 prior_possible boolean:=false;
 snapshot jsonb;
 destination_current boolean;
BEGIN
 IF w IS NULL THEN RETURN true;END IF;
 IF k IS NULL OR i IS NULL OR v IS NULL THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT 1 FROM public.scope_derivations d WHERE d.workspace_id=w AND d.resource_kind=k AND d.resource_id=i) THEN
  -- A content/metadata revision cannot discard its predecessor's lineage.
  CASE k
  WHEN 'memory' THEN SELECT EXISTS(SELECT 1 FROM public.memories m WHERE m.workspace_id=w AND m.superseded_by=i) INTO prior_possible;
  WHEN 'task' THEN SELECT EXISTS(SELECT 1 FROM public.tasks t WHERE t.workspace_id=w AND t.superseded_by=i) INTO prior_possible;
  WHEN 'workspace_file' THEN SELECT EXISTS(SELECT 1 FROM public.workspace_files f WHERE f.workspace_id=w AND f.superseded_by=i) INTO prior_possible;
  ELSE NULL;
  END CASE;
  IF NOT prior_possible THEN RETURN true;END IF;
 END IF;
 snapshot:=public.read_scope_source(w,k,i);
 destination_current:=snapshot->>'workspaceId' IS NOT DISTINCT FROM w::text
  AND snapshot->>'version' IS NOT DISTINCT FROM v AND snapshot->>'held' IS NOT DISTINCT FROM 'false'
  AND snapshot->>'validTo' IS NULL AND snapshot->>'retractedAt' IS NULL;
 destination.workspace_id:=w;destination.resource_kind:=k;destination.resource_id:=i;
 destination.user_id:=(snapshot->>'userId')::uuid;
 destination.assistant_id:=(snapshot->>'assistantId')::uuid;
 destination.sensitivity:=snapshot->>'sensitivity';
 destination.compartments:=ARRAY(SELECT jsonb_array_elements_text(snapshot->'compartments'));
 destination.project_ids:=ARRAY(SELECT jsonb_array_elements_text(snapshot->'projectIds')::uuid);
 WITH RECURSIVE origins(kind,id,version,parent_kind,parent_id) AS (
  SELECT edge.kind,edge.id,edge.version,k,i FROM public.conversation_source_edges(w,k,i,v) edge
  UNION SELECT forward.kind,forward.id,forward.version,origins.kind,origins.id
   FROM origins CROSS JOIN LATERAL (
    SELECT edge.* FROM public.conversation_source_edges(w,origins.kind,origins.id,origins.version) edge
    WHERE origins.kind NOT IN('conversation_record','conversation_record_current_root','conversation_record_refused')
    UNION ALL
    SELECT edge.* FROM public.conversation_record_derivative_edges(w,origins.id,origins.parent_kind,origins.parent_id,recipient,destination) edge
    WHERE origins.kind='conversation_record'
   ) forward
 ), bounded AS MATERIALIZED(SELECT origins.* FROM origins LIMIT 4097)
 SELECT count(*),coalesce(bool_and(version IS NOT NULL AND (kind<>'conversation_record' OR version='1')),true),
  coalesce(bool_or(kind='conversation_record_current_root'),false),
  coalesce(jsonb_agg(jsonb_build_array(kind,id,version))
   FILTER(WHERE kind NOT IN('conversation_record','conversation_record_current_root')),'[]'::jsonb)
 INTO total,intact,record_found,obligations FROM bounded;
 IF total>4096 OR NOT intact THEN RETURN false;END IF;
 -- A native predecessor link can exist without conversation evidence. Native
 -- policies govern those rows, including their historical and in-flight versions.
 IF NOT record_found THEN RETURN true;END IF;
 IF NOT destination_current THEN RETURN false;END IF;
 IF destination.user_id IS NOT NULL AND destination.user_id IS DISTINCT FROM recipient THEN RETURN false;END IF;
 FOR node IN SELECT DISTINCT value->>0 kind,(value->>1)::uuid id,value->>2 version FROM jsonb_array_elements(obligations) LOOP
  IF node.kind NOT IN('memory','task','workspace_file','entity','entity_link','episode','session_message','session_context_revision')
  THEN RETURN false;END IF;
  IF node.kind='session_message' AND recipient IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.session_messages m
   WHERE m.workspace_id=w AND m.id=node.id AND public.conversation_member_read_allowed(w,m.session_id,recipient))
   OR node.kind='session_context_revision' AND recipient IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.session_context_scope_revisions r
   WHERE r.workspace_id=w AND r.id=node.id AND public.conversation_member_read_allowed(w,r.session_id,recipient))
  THEN RETURN false;END IF;
  snapshot:=CASE WHEN node.kind IN('session_message','session_context_revision') THEN public.read_scope_source(w,node.kind,node.id)
    ELSE public.conversation_record_retained_native_source(w,node.kind,node.id,recipient) END;
  IF snapshot->>'version' IS DISTINCT FROM node.version OR snapshot->>'held' IS DISTINCT FROM 'false'
   OR snapshot->>'validTo' IS NOT NULL OR snapshot->>'retractedAt' IS NOT NULL
   OR (snapshot->>'userId' IS NOT NULL AND snapshot->>'userId' IS DISTINCT FROM destination.user_id::text)
   OR (snapshot->>'assistantId' IS NOT NULL AND snapshot->>'assistantId' IS DISTINCT FROM destination.assistant_id::text)
   OR (public.sensitivity_rank(snapshot->>'sensitivity')<=public.sensitivity_rank(destination.sensitivity)
    AND to_jsonb(destination.compartments) @> (snapshot->'compartments')
    AND to_jsonb(destination.project_ids) @> (snapshot->'projectIds')) IS NOT TRUE
  THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN insufficient_privilege OR invalid_parameter_value OR invalid_text_representation THEN RETURN false;
END $derived_current$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_4(w uuid,k text,i uuid,v text) RETURNS boolean
LANGUAGE sql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $resource_current$
 SELECT CASE WHEN k IN('memory','task','workspace_file') AND EXISTS(
  SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=w
   AND m.user_id=nullif(current_setting('app.current_user_id',true),'')::uuid) THEN
  public.conversation_record_derivation_current(w,k,i,v,nullif(current_setting('app.current_user_id',true),'')::uuid)
  ELSE false END
$resource_current$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_5() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $retention$
DECLARE kind text;actor uuid:=nullif(current_setting('app.current_user_id',true),'')::uuid;
BEGIN
 kind:=CASE TG_TABLE_NAME WHEN 'memories' THEN 'memory' WHEN 'tasks' THEN 'task' WHEN 'workspace_files' THEN 'workspace_file' END;
 IF kind IS NULL THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 IF actor IS NULL AND EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=TG_RELID
  WHERE r.rolname=session_user AND NOT (r.rolsuper OR r.rolbypassrls) AND pg_has_role(r.oid,c.relowner,'USAGE'))
 THEN actor:=NEW.created_by_user_id;END IF;
 -- At transaction end the native writer has attached the complete retained
 -- evidence to this physical output. Verify against both its author and its
 -- actual recipient, with the original write admission still in force.
 IF public.conversation_record_derivation_current(NEW.workspace_id,kind,NEW.id,NEW.scope_version::text,NEW.user_id) IS NOT TRUE
  OR actor IS DISTINCT FROM NEW.user_id AND public.conversation_record_derivation_current(
   NEW.workspace_id,kind,NEW.id,NEW.scope_version::text,actor) IS NOT TRUE
 THEN RAISE EXCEPTION 'scope_source_changed' USING ERRCODE='42501';END IF;
 RETURN NULL;
END $retention$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_6() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $anchor_change$
DECLARE old_id uuid;new_id uuid;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'page_grants' THEN
  IF TG_OP<>'INSERT' THEN old_id:=OLD.page_id;END IF;
  IF TG_OP<>'DELETE' THEN new_id:=NEW.page_id;END IF;
  PERFORM id FROM public.saved_views WHERE id IN(old_id,new_id) ORDER BY id FOR NO KEY UPDATE;
 WHEN 'office_artifact_grants','office_artifact_sources' THEN
  IF TG_OP<>'INSERT' THEN old_id:=OLD.artifact_id;END IF;
  IF TG_OP<>'DELETE' THEN new_id:=NEW.artifact_id;END IF;
  PERFORM id FROM public.office_artifacts WHERE id IN(old_id,new_id) ORDER BY id FOR NO KEY UPDATE;
 WHEN 'feed_post_working_copies' THEN
  IF TG_OP<>'INSERT' THEN old_id:=OLD.session_id;END IF;
  IF TG_OP<>'DELETE' THEN new_id:=NEW.session_id;END IF;
  PERFORM id FROM public.sessions WHERE id IN(old_id,new_id) ORDER BY id FOR NO KEY UPDATE;
 ELSE RAISE EXCEPTION 'conversation_anchor_policy_changed' USING ERRCODE='55000';
 END CASE;
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;
 RETURN NEW;
END $anchor_change$;
CREATE FUNCTION pg_temp.a8314_lineage_ref_7(w uuid,sid uuid,actor uuid) RETURNS boolean
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $read_pin$
DECLARE bound_session public.sessions;root uuid;project uuid;teamspace uuid;labels text[];
BEGIN
 IF w IS NULL OR sid IS NULL OR actor IS NULL THEN RETURN false;END IF;
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT * INTO bound_session FROM public.sessions s WHERE s.id=sid AND s.workspace_id=w FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 SELECT e.compartments INTO labels FROM public.conversation_envelopes e WHERE e.session_id=sid AND e.workspace_id=w FOR SHARE;
 IF NOT FOUND THEN RETURN false;END IF;
 CASE bound_session.anchor_kind
 WHEN 'doc_thread' THEN
  SELECT t.page_id INTO root FROM public.comment_threads t WHERE t.session_id=sid AND t.workspace_id=w FOR SHARE;
  SELECT v.shared_project_id,v.teamspace_id INTO project,teamspace FROM public.saved_views v WHERE v.id=root AND v.workspace_id=w FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
  IF teamspace IS NOT NULL THEN
   PERFORM id FROM public.teamspaces WHERE id=teamspace AND workspace_id=w FOR SHARE;
   PERFORM user_id FROM public.teamspace_members WHERE teamspace_id=teamspace AND user_id=actor FOR SHARE;
  END IF;
  IF project IS NOT NULL AND NOT ('project:'||project::text)=ANY(labels) THEN labels:=array_append(labels,'project:'||project::text);END IF;
 WHEN 'office_file' THEN
  SELECT l.artifact_id INTO root FROM public.office_artifact_sessions l WHERE l.session_id=sid AND l.workspace_id=w FOR SHARE;
  PERFORM id FROM public.office_artifacts WHERE id=root AND workspace_id=w FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
 WHEN 'feed_thread' THEN
  SELECT t.session_id INTO root FROM public.feed_comment_threads t WHERE t.transcript_session_id=sid AND t.workspace_id=w FOR SHARE;
  PERFORM id FROM public.sessions WHERE id=root AND workspace_id=w AND anchor_kind='feed_draft' FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
  PERFORM session_id FROM public.conversation_envelopes WHERE session_id=root AND workspace_id=w FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
 WHEN 'feed_draft','none' THEN NULL;
 ELSE RETURN false;
 END CASE;
 FOR project IN SELECT unnest(public.conversation_hard_project_ids(labels)) LOOP
  PERFORM project_id FROM public.project_shared_scopes WHERE workspace_id=w AND project_id=project FOR SHARE;
  IF NOT FOUND THEN RETURN false;END IF;
  PERFORM project_id FROM public.project_shared_members WHERE project_id=project AND user_id=actor FOR SHARE;
 END LOOP;
 RETURN public.conversation_member_read_allowed(w,sid,actor);
END $read_pin$;
CREATE TEMP TABLE a8314_lineage_oids(oid oid PRIMARY KEY) ON COMMIT DROP;
DO $lineage_source$
DECLARE item record;actual pg_proc;reviewed pg_proc;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 app_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
BEGIN
 FOR item IN SELECT * FROM (VALUES ('conversation_record_derivative_origin','a8314_lineage_ref_0',false),('conversation_record_derivative_edges','a8314_lineage_ref_1',false),('conversation_record_retained_native_source','a8314_lineage_ref_2',false),('conversation_record_derivation_current','a8314_lineage_ref_3',false),('conversation_record_resource_current','a8314_lineage_ref_4',true),('require_conversation_record_retention_current','a8314_lineage_ref_5',false),('lock_conversation_anchor_policy_change','a8314_lineage_ref_6',false),('lock_conversation_member_read','a8314_lineage_ref_7',false)) q(name,reference,exposed) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=item.reference;
  SELECT * INTO actual FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=item.name AND proargtypes=reviewed.proargtypes;
  IF actual.oid IS NULL OR actual.proowner<>owner_id OR actual.proacl IS DISTINCT FROM
    (CASE WHEN item.exposed THEN ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
     ELSE ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)] END)
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
    (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
  THEN RAISE EXCEPTION 'conversation_lineage_function_changed: %',item.name;END IF;
  INSERT INTO pg_temp.a8314_lineage_oids VALUES(actual.oid);
 END LOOP;
END $lineage_source$;
CREATE TEMP TABLE a8314_lineage_policy(workspace_id uuid,id uuid,scope_version bigint) ON COMMIT DROP;
CREATE POLICY memories_conversation_record_ancestry ON pg_temp.a8314_lineage_policy AS RESTRICTIVE FOR SELECT TO app_user USING (public.conversation_record_resource_current(workspace_id,'memory',id,scope_version::text));
CREATE POLICY tasks_conversation_record_ancestry ON pg_temp.a8314_lineage_policy AS RESTRICTIVE FOR SELECT TO app_user USING (public.conversation_record_resource_current(workspace_id,'task',id,scope_version::text));
CREATE POLICY workspace_files_conversation_record_ancestry ON pg_temp.a8314_lineage_policy AS RESTRICTIVE FOR SELECT TO app_user USING (public.conversation_record_resource_current(workspace_id,'workspace_file',id,scope_version::text));
DO $lineage_catalog$
DECLARE item record;actual pg_policy;reviewed pg_policy;relation regclass;
BEGIN
 FOR item IN SELECT * FROM (VALUES ('memories','memories_conversation_record_ancestry'),('tasks','tasks_conversation_record_ancestry'),('workspace_files','workspace_files_conversation_record_ancestry')) q(relation,policy) LOOP
  relation:=to_regclass('public.'||item.relation);
  SELECT * INTO actual FROM pg_policy WHERE polrelid=relation AND polname=item.policy;
  SELECT * INTO STRICT reviewed FROM pg_policy WHERE polrelid='pg_temp.a8314_lineage_policy'::regclass AND polname=item.policy;
  IF actual.oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=relation AND relrowsecurity)
   OR ROW(actual.polpermissive,actual.polcmd,actual.polroles,pg_get_expr(actual.polqual,actual.polrelid),actual.polwithcheck)
   IS DISTINCT FROM ROW(reviewed.polpermissive,reviewed.polcmd,reviewed.polroles,pg_get_expr(reviewed.polqual,reviewed.polrelid),reviewed.polwithcheck)
  THEN RAISE EXCEPTION 'conversation_lineage_policy_changed: %.%',item.relation,item.policy;END IF;
 END LOOP;
 FOR item IN SELECT * FROM (VALUES
  ('page_grants','conversation_lock_page_grants',31,'public.lock_conversation_anchor_policy_change()',false),
  ('office_artifact_grants','conversation_lock_office_grants',31,'public.lock_conversation_anchor_policy_change()',false),
  ('office_artifact_sources','conversation_lock_office_sources',31,'public.lock_conversation_anchor_policy_change()',false),
  ('feed_post_working_copies','conversation_lock_feed_working_copy',31,'public.lock_conversation_anchor_policy_change()',false),
  ('memories','conversation_record_retention_current',5,'public.require_conversation_record_retention_current()',true),
  ('tasks','conversation_record_retention_current',5,'public.require_conversation_record_retention_current()',true),
  ('workspace_files','conversation_record_retention_current',5,'public.require_conversation_record_retention_current()',true)
 ) q(relation,trigger_name,mask,routine,deferred) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass('public.'||item.relation) AND t.tgname=item.trigger_name
   AND t.tgfoid=to_regprocedure(item.routine) AND t.tgtype=item.mask AND t.tgenabled='O' AND NOT t.tgisinternal
   AND t.tgdeferrable=item.deferred AND t.tginitdeferred=item.deferred
   AND CASE WHEN item.deferred THEN EXISTS(SELECT 1 FROM pg_constraint c WHERE c.oid=t.tgconstraint
     AND c.conrelid=t.tgrelid AND c.contype='t' AND c.condeferrable AND c.condeferred) ELSE t.tgconstraint=0 END
   AND t.tgnargs=0 AND t.tgattr=''::int2vector AND t.tgqual IS NULL AND t.tgoldtable IS NULL AND t.tgnewtable IS NULL)
  THEN RAISE EXCEPTION 'conversation_lineage_trigger_changed: %.%',item.relation,item.trigger_name;END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_am a ON a.oid=c.relam
  WHERE i.indexrelid=to_regclass('public.workspace_files_conversation_record_predecessor')
   AND i.indrelid='public.workspace_files'::regclass AND a.amname='btree'
   AND i.indisvalid AND i.indisready AND i.indislive AND NOT i.indisunique AND i.indnatts=2 AND i.indnkeyatts=2
   AND i.indexprs IS NULL AND pg_get_expr(i.indpred,i.indrelid)='(superseded_by IS NOT NULL)'
   AND (SELECT array_agg(attname::text ORDER BY keys.position) FROM unnest(i.indkey) WITH ORDINALITY keys(number,position)
        JOIN pg_attribute x ON x.attrelid=i.indrelid AND x.attnum=keys.number)=ARRAY['workspace_id','superseded_by'])
 THEN RAISE EXCEPTION 'conversation_lineage_predecessor_index_changed';END IF;
END $lineage_catalog$;
DO $public_receiving_references$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.public_receiving_reviewed_0(target uuid, historical boolean) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$
DECLARE s public.sessions; w uuid; assistant_cap text; chosen text; chosen_cap text; legacy_group boolean; member_now boolean;
BEGIN
 SELECT * INTO s FROM public.sessions WHERE id=target;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT workspace_id,clearance INTO w,assistant_cap FROM public.assistants WHERE id=s.assistant_id;
 w:=coalesce(s.workspace_id,w);
 -- A shared anchored thread is already workspace; a personal dock remains
 -- personal. Unknown personal shapes are never inferred to be shared.
 -- Only positive convergence evidence identifies a historical per-user group.
 -- Archived 1:1s and former members keep private-by-kind protection forever.
 legacy_group:=s.archived_at IS NOT NULL AND s.channel_type IN (''telegram'',''slack'',''discord'',''feishu'',''msteams'',''whatsapp'',''wechat'',''email'',''custom'',''imessage'') AND EXISTS(SELECT 1 FROM public.sessions room JOIN public.assistants a ON a.id=room.assistant_id
  WHERE coalesce(room.workspace_id,a.workspace_id)=w AND room.visibility=''workspace'' AND room.anchor_kind=''channel''
   AND room.channel_type=s.channel_type AND room.channel_id=s.channel_id AND room.id<>s.id);
 member_now:=EXISTS(SELECT 1 FROM public.workspace_members m WHERE m.workspace_id=w AND m.user_id=s.user_id);
 chosen:=CASE WHEN w IS NOT NULL AND (s.visibility=''workspace'' OR s.anchor_kind=''feed_draft'') THEN ''workspace''
  WHEN w IS NOT NULL AND NOT historical AND s.channel_type=''api'' AND member_now THEN ''private_by_kind''
 WHEN w IS NOT NULL AND NOT historical AND ((s.guest_session_token IS NOT NULL OR s.channel_type=''api'') OR (NOT member_now AND s.channel_type IN (''telegram'',''slack'',''discord'',''feishu'',''msteams'',''whatsapp'',''wechat'',''email'',''custom'',''imessage'') AND s.transient IS NOT TRUE)) THEN ''workspace''
  WHEN (s.guest_session_token IS NOT NULL OR s.channel_type=''api'') OR legacy_group OR s.channel_type IN (''assistant-call'',''a2a-external'',''workflow'',''api'',''brain_inspection'',''brain_edit'',''cron'',''programmatic'',''assistant_mcp'',''system'',''synthesis'',''worker'',''skill-draft'',''replay'',''home-refresh'',''session_resume'',''adhoc'') OR s.transient IS TRUE THEN ''configured_private''
  ELSE ''private_by_kind'' END;
 -- An established cap is never lowered. A legacy private NULL cap is not
 -- the answering assistant''s current clearance: derive its actual retained
 -- admitted floor from complete in-boundary stamps, then the original owner''s
 -- current membership for an empty conversation. Unknown rows are quarantined.
 chosen_cap:=s.effective_clearance;
 IF chosen_cap IS NULL THEN
  SELECT m.sensitivity INTO chosen_cap FROM public.session_messages m
   WHERE m.session_id=s.id AND m.workspace_id=w AND m.scope_held IS FALSE
    AND m.scope_version IS NOT NULL AND m.sensitivity IN (''public'',''internal'',''confidential'')
    AND (m.user_id IS NULL OR chosen<>''workspace'' AND m.user_id=s.user_id)
    AND m.compartments IS NOT NULL AND m.project_ids IS NOT NULL
    AND m.compartments <@ coalesce(s.context_compartments,ARRAY[]::text[])
    AND m.project_ids <@ CASE WHEN s.context_project_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[s.context_project_id] END
    AND NOT public.scope_review_state_held(''session_message'',m.id)
   ORDER BY public.sensitivity_rank(m.sensitivity) DESC LIMIT 1;
 END IF;
 IF chosen_cap IS NULL THEN
  SELECT clearance INTO chosen_cap FROM public.workspace_members WHERE workspace_id=w AND user_id=s.user_id;
 END IF;
 chosen_cap:=coalesce(chosen_cap,CASE WHEN w IS NULL THEN assistant_cap ELSE ''public'' END,''public'');
 IF chosen=''workspace'' AND NOT historical AND s.visibility<>''workspace'' THEN chosen_cap:=''public''; END IF;
 INSERT INTO public.conversation_envelopes(session_id,workspace_id,starter_user_id,visibility,cap,compartments,project_ids,classification)
 VALUES(s.id,w,s.user_id,chosen,
  chosen_cap,
  coalesce(s.context_compartments,ARRAY[]::text[]),
  CASE WHEN s.context_project_id IS NULL THEN ARRAY[]::uuid[] ELSE ARRAY[s.context_project_id] END,
  CASE WHEN chosen=''private_by_kind'' THEN ''member_direct'' WHEN chosen=''workspace'' AND s.visibility=''workspace'' THEN ''existing_workspace''
   WHEN chosen=''workspace'' THEN ''new_public'' ELSE ''legacy_personal'' END)
 ON CONFLICT(session_id) DO NOTHING;
 IF NOT FOUND THEN RETURN false; END IF;
 -- The starter is implicit; do not invent participants from message senders.
 -- Existing held rows are untouched. Quarantine inventories invalid stamps
 -- without relabelling or triggering historical hold-release side effects.
 INSERT INTO public.conversation_message_quarantine(session_id,message_id,reason)
 SELECT s.id,m.id,r.reason FROM public.session_messages m
 JOIN public.conversation_envelopes e ON e.session_id=m.session_id
 CROSS JOIN LATERAL (SELECT CASE
   WHEN m.sensitivity IS NULL OR m.compartments IS NULL OR m.project_ids IS NULL THEN ''missing_stamp''
   WHEN m.user_id IS NOT NULL AND (e.visibility=''workspace'' OR m.user_id<>e.starter_user_id) THEN ''private_owner''
   WHEN public.sensitivity_rank(m.sensitivity)>public.sensitivity_rank(e.cap) THEN ''above_cap''
   WHEN NOT m.compartments <@ e.compartments OR NOT m.project_ids <@ e.project_ids THEN ''outside_boundary''
   ELSE NULL END AS reason) r
 WHERE m.session_id=s.id AND r.reason IS NOT NULL
 ON CONFLICT DO NOTHING;
 RETURN true;
END $$;';
 EXECUTE 'CREATE FUNCTION pg_temp.public_receiving_reviewed_1(
 target_assistant uuid, credential jsonb, attributed_actor uuid,
 visitor text, channel text, expected_session uuid DEFAULT NULL,
 expected_actor uuid DEFAULT NULL, claimed_email text DEFAULT NULL,
 expected_version bigint DEFAULT NULL, write_lock boolean DEFAULT false,
 expected_lease uuid DEFAULT NULL, pin_facts boolean DEFAULT true
) RETURNS public.conversation_envelopes
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $public_session$
DECLARE
 key_id uuid:=(credential->>''id'')::uuid;
 kind text:=credential->>''kind'';
 fingerprint text:=credential->>''fingerprint'';
 a public.assistants;
 s public.sessions;
 e public.conversation_envelopes;
 actor uuid;
 w uuid;
 namespace text;
 original_cap text;
 scoped_member boolean:=attributed_actor IS NOT NULL;
BEGIN
 IF key_id IS NULL OR fingerprint IS NULL OR fingerprint!~''^[a-f0-9]{64}$''
  OR visitor IS NULL OR length(visitor) NOT BETWEEN 1 AND 256
  OR channel IS NULL OR length(channel) NOT BETWEEN 1 AND 256
  OR write_lock IS NULL OR pin_facts IS NULL OR (write_lock AND (expected_session IS NULL OR expected_actor IS NULL
   OR expected_version IS NULL OR expected_lease IS NULL OR NOT pin_facts))
  OR (NOT pin_facts AND (expected_session IS NULL OR expected_version IS NULL))
  OR (expected_session IS NULL AND (expected_actor IS NOT NULL OR claimed_email IS NOT NULL OR expected_version IS NOT NULL))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT assistant.workspace_id INTO w FROM public.assistants assistant WHERE id=target_assistant;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF w IS NOT NULL THEN
  IF pin_facts THEN PERFORM id FROM public.workspaces WHERE id=w FOR SHARE; END IF;
  PERFORM id FROM public.workspaces WHERE id=w
   AND (kind IS DISTINCT FROM ''chat_link'' OR external_sharing_enabled);
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 END IF;
 IF pin_facts THEN PERFORM id FROM public.assistants WHERE id=target_assistant FOR SHARE; END IF;
 SELECT * INTO a FROM public.assistants WHERE id=target_assistant AND workspace_id IS NOT DISTINCT FROM w;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 CASE kind
 WHEN ''chat_link'' THEN
  IF attributed_actor IS NOT NULL OR claimed_email IS NOT NULL OR a.placement_department_id IS NOT NULL THEN
   RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
  IF pin_facts THEN PERFORM id FROM public.assistant_chat_links WHERE id=key_id AND assistant_id=target_assistant FOR SHARE; END IF;
  PERFORM id FROM public.assistant_chat_links
   WHERE id=key_id AND assistant_id=target_assistant AND status=''active''
   AND encode(sha256(convert_to(token,''UTF8'')),''hex'')=fingerprint;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
  namespace:=''chatlink:''||key_id;
 WHEN ''api_key'' THEN
  IF pin_facts THEN PERFORM id FROM public.api_keys WHERE id=key_id AND assistant_id=target_assistant FOR SHARE; END IF;
  PERFORM id FROM public.api_keys
   WHERE id=key_id AND assistant_id=target_assistant AND status=''active''
   AND workspace_mcp_consent IS NULL
   AND audience=CASE WHEN attributed_actor IS NULL THEN ''external'' ELSE ''internal'' END
   AND jsonb_build_object(''scope'',scope,''audience'',audience,''anonymousContext'',anonymous_context,
    ''toolPolicy'',tool_policy,''createdBy'',created_by)=credential->''configuration''
   AND encode(sha256(convert_to(key_hash,''UTF8'')),''hex'')=fingerprint;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
  namespace:=''api:''||key_id;
 ELSE RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';
 END CASE;

 IF attributed_actor IS NOT NULL THEN
  IF pin_facts THEN PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=attributed_actor FOR SHARE; END IF;
  SELECT user_id INTO actor FROM public.workspace_members WHERE workspace_id=w AND user_id=attributed_actor;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 ELSE
  IF pin_facts THEN PERFORM id FROM public.users WHERE auth_provider=''channel'' AND auth_provider_id=namespace||'':''||visitor FOR SHARE; END IF;
  SELECT id INTO actor FROM public.users WHERE auth_provider=''channel'' AND auth_provider_id=namespace||'':''||visitor
   AND (expected_actor IS NULL OR id=expected_actor);
  IF actor IS NULL AND claimed_email IS NOT NULL AND expected_actor IS NOT NULL THEN
   IF pin_facts THEN
    PERFORM id FROM public.users WHERE id=expected_actor FOR SHARE;
    PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=expected_actor FOR SHARE;
   END IF;
   SELECT id INTO actor FROM public.users
    WHERE id=expected_actor AND lower(email)=lower(claimed_email);
   scoped_member:=EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=w AND user_id=actor);
  END IF;
  IF actor IS NULL AND expected_session IS NULL THEN RETURN NULL; END IF;
 END IF;
 IF expected_actor IS NOT NULL AND actor IS DISTINCT FROM expected_actor THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF write_lock THEN
  PERFORM id FROM public.sessions WHERE id=expected_session AND assistant_id=target_assistant AND user_id=actor FOR NO KEY UPDATE;
 END IF;
 SELECT * INTO s FROM public.sessions WHERE assistant_id=target_assistant AND user_id=actor
  AND channel_type=''api'' AND channel_id=channel AND app_id=''Use Brian'' AND visibility=''personal''
  AND anchor_kind=''none'' AND (workspace_id=w OR workspace_id IS NULL)
  AND (expected_session IS NULL OR id=expected_session);
 IF NOT FOUND THEN
  IF expected_session IS NULL THEN RETURN NULL; END IF;
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';
 END IF;
 IF pin_facts AND NOT write_lock THEN
  PERFORM id FROM public.sessions current_session WHERE current_session.id=s.id
   AND ROW(current_session.assistant_id,current_session.user_id,current_session.channel_type,current_session.channel_id,
   current_session.app_id,current_session.visibility,current_session.anchor_kind,current_session.workspace_id)
   IS NOT DISTINCT FROM ROW(s.assistant_id,s.user_id,s.channel_type,s.channel_id,s.app_id,s.visibility,s.anchor_kind,s.workspace_id)
   FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 END IF;
 IF expected_lease IS NOT NULL AND (s.last_turn_lease_token IS DISTINCT FROM expected_lease
  OR s.turn_lease_token IS DISTINCT FROM expected_lease OR s.status<>''running'' OR s.cancel_requested_at IS NOT NULL
  OR s.turn_heartbeat_at IS NULL OR s.turn_heartbeat_at<=clock_timestamp()-interval ''90 seconds'')
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 -- Classify at most the exactly addressed legacy session. No user, session, or
 -- message is created by this GET. The actor and protected binding are pinned.
 IF pin_facts AND NOT EXISTS(SELECT 1 FROM public.conversation_envelopes WHERE session_id=s.id) THEN
  PERFORM public.classify_conversation_envelope(s.id,true);
 END IF;
 IF write_lock THEN
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=s.id AND workspace_id IS NOT DISTINCT FROM w FOR UPDATE;
 ELSIF pin_facts THEN
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=s.id AND workspace_id IS NOT DISTINCT FROM w FOR SHARE;
 ELSE
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=s.id AND workspace_id IS NOT DISTINCT FROM w;
 END IF;
 IF e.session_id IS NULL OR e.starter_user_id IS DISTINCT FROM actor
  OR expected_version IS NOT NULL AND e.version IS DISTINCT FROM expected_version
  OR expected_session IS NOT NULL AND public.sensitivity_rank(a.clearance)<public.sensitivity_rank(e.cap)
  OR NOT public.session_recording_read_allowed(s.id)
  OR public.scope_review_state_held(''session'',s.id) THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF scoped_member THEN
  IF public.conversation_member_read_allowed(w,s.id,actor) IS NOT TRUE THEN
   RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 ELSIF w IS NOT NULL THEN
  -- A visitor is not a workspace member. Its exact original configured-private
  -- record remains accessible, while a newer room is limited to the public cap.
  SELECT before_envelope->>''cap'' INTO original_cap
  FROM public.conversation_visibility_audit WHERE session_id=s.id ORDER BY next_version LIMIT 1;
  IF public.sensitivity_rank(a.clearance)<public.sensitivity_rank(e.cap) OR e.compartments<>''{}''::text[]
   OR NOT (e.visibility IN(''configured_private'',''workspace'') AND e.cap=''public''
    AND (e.visibility<>''workspace'' OR e.classification<>''legacy_personal'' OR public.conversation_consent_current(s.id))
    OR e.visibility=''configured_private'' AND e.classification=''legacy_personal''
    AND e.cap IS NOT DISTINCT FROM coalesce(original_cap,e.cap))
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 ELSIF e.visibility=''workspace'' THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';
 END IF;
 RETURN e;
END $public_session$;';
 EXECUTE 'CREATE FUNCTION pg_temp.public_receiving_reviewed_2(
 target_assistant uuid, credential jsonb, actor uuid, visitor text, channel text, expected_session uuid,
 expected_version bigint, lease uuid
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $publication$
DECLARE e public.conversation_envelopes;
BEGIN
 IF credential->>''kind'' IS DISTINCT FROM ''api_key'' OR actor IS NULL
  OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
  OR target_assistant IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid
  OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 e:=public.public_conversation_session_current(target_assistant,credential,actor,visitor,channel,
  expected_session,actor,NULL,expected_version,true,lease);
 RETURN jsonb_build_object(''sessionId'',e.session_id,''workspaceId'',e.workspace_id,''starterUserId'',e.starter_user_id,
  ''version'',e.version::text,''visibility'',e.visibility,''cap'',e.cap,''compartments'',e.compartments,''projectIds'',e.project_ids);
END $publication$;';
 EXECUTE 'CREATE FUNCTION pg_temp.public_receiving_reviewed_3(
 target_assistant uuid, credential jsonb, attributed_actor uuid,
 visitor text, channel text, row_limit integer
) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp SET timezone=''UTC'' AS $public_history$
DECLARE e public.conversation_envelopes;output jsonb;
BEGIN
 IF row_limit IS NULL OR row_limit NOT BETWEEN 1 AND 500 THEN
  RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501'';END IF;
 e:=public.public_conversation_session_current(target_assistant,credential,attributed_actor,visitor,channel);
 IF e.session_id IS NULL THEN RETURN ''[]''::jsonb; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(''id'',selected.id,''role'',selected.role,
  ''content'',projection.content,''sequenceNum'',selected.sequence_num,''createdAt'',selected.created_at)
  ORDER BY selected.sequence_num),''[]'') INTO output
 FROM (SELECT * FROM public.conversation_record_rows(e,0,NULL,false,e.starter_user_id,true)
       ORDER BY sequence_num LIMIT row_limit) selected
 CROSS JOIN LATERAL (
  SELECT btrim(regexp_replace(CASE jsonb_typeof(selected.content)
   WHEN ''string'' THEN selected.content#>>''{}''
   WHEN ''array'' THEN (SELECT string_agg(block->>''text'',E''\n\n'' ORDER BY ord)
    FROM jsonb_array_elements(selected.content) WITH ORDINALITY items(block,ord)
    WHERE block->>''type''=''text'' AND jsonb_typeof(block->''text'')=''string'' AND block->>''text''<>'''') END,
   ''<attached_file([[:space:]][^>]*|)>.*?(</attached_file>|$)'','''', ''gi'')) AS content
 ) projection
 WHERE projection.content<>'''' AND NOT jsonb_path_exists(selected.content,
  ''$[*] ? (@.type == "tool_use" || @.type == "tool_result" || @.type == "host_observation")'');
 RETURN output;
END $public_history$;';
END $public_receiving_references$;
CREATE TEMP TABLE public_receiving_reviewed_oids(oid oid PRIMARY KEY) ON COMMIT DROP;
DO $public_receiving_catalog$
DECLARE item record;actual pg_proc;reviewed pg_proc;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 app_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
BEGIN
 FOR item IN SELECT * FROM (VALUES
  ('classify_conversation_envelope','public_receiving_reviewed_0',false),('public_conversation_session_current','public_receiving_reviewed_1',false),('pin_public_member_conversation_publication','public_receiving_reviewed_2',true),('read_public_conversation_history','public_receiving_reviewed_3',false)
 ) declarations(name,reference,exposed) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=item.reference;
  SELECT * INTO actual FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=item.name AND proargtypes=reviewed.proargtypes;
  IF actual.oid IS NULL OR actual.proowner<>owner_id
   OR actual.proacl IS DISTINCT FROM (CASE WHEN item.exposed THEN
    ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
   ELSE ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)] END)
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
    (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
  THEN RAISE EXCEPTION 'public_receiving_function_changed: %',item.name;END IF;
  INSERT INTO pg_temp.public_receiving_reviewed_oids VALUES(actual.oid);
 END LOOP;
END $public_receiving_catalog$;
DO $page_delivery_references$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.page_delivery_reviewed_0(w uuid,sid uuid,k text,i uuid,v text,owner uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $private_page_frame$
 SELECT EXISTS(
  SELECT 1 FROM public.sessions s
  JOIN public.comment_threads t ON t.workspace_id=w AND t.session_id=s.id
  LEFT JOIN public.workflow_page_event_observations o ON o.workspace_id=w AND o.id=i
   AND k IN(''page_live_changed'',''page_live_destination'')
  JOIN public.workflow_page_event_receipts r ON r.workspace_id=w AND r.page_id=t.page_id
   AND r.revision=CASE WHEN k IN(''page_live_changed'',''page_live_destination'') THEN o.receipt_id ELSE i END
  CROSS JOIN LATERAL (SELECT CASE WHEN k IN(''page_event_destination'',''page_live_destination'') THEN ''destination'' ELSE ''changed'' END) slot(role)
  CROSS JOIN LATERAL (SELECT CASE WHEN o.id IS NULL THEN r.boundaries->slot.role ELSE o.boundary END) selected(scope)
  WHERE s.workspace_id=w AND s.id=sid AND s.visibility=''workspace'' AND s.anchor_kind=''doc_thread''
   AND owner IS NOT NULL AND k IN(''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'')
   AND (CASE WHEN o.id IS NOT NULL THEN o.role=slot.role ELSE slot.role=''changed'' OR r.metadata->>''action'' IN(''created'',''moved'') END)
   AND selected.scope->>''creatorId''=owner::text
   AND public.page_event_scope_descriptor(i,slot.role,selected.scope,o.id IS NOT NULL)->>''version''=v
   AND NOT EXISTS(SELECT 1 FROM (SELECT value FROM jsonb_each(r.boundaries)
     UNION ALL SELECT o.boundary WHERE o.id IS NOT NULL) a
    WHERE a.value->>''unavailable'' IS DISTINCT FROM ''false''
     OR a.value->>''pageId'' IS DISTINCT FROM t.page_id::text OR a.value->>''workspaceId'' IS DISTINCT FROM w::text
     OR a.value->>''principalBoundary'' IS DISTINCT FROM ''private'' OR a.value->>''creatorId'' IS DISTINCT FROM owner::text)
 )
$private_page_frame$;';
 EXECUTE 'CREATE FUNCTION pg_temp.page_delivery_reviewed_1(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, boundary text) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $facts$
DECLARE s public.sessions;e public.conversation_envelopes;a public.assistants;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
  OR actor IS DISTINCT FROM credential_actor OR token IS NULL
  OR include_departments IS NULL OR include_policy IS NULL
  OR boundary IS NULL OR boundary NOT IN(''history'',''dispatch'',''frame'',''publication'',''stopped_publication'')
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
    WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;

 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM device_row.id FROM public.auth_sessions device_row JOIN public.users u ON u.id=device_row.user_id
  WHERE device_row.id=device AND device_row.user_id=actor AND device_row.auth_version=native_version
   AND u.auth_version=native_version AND device_row.revoked_at IS NULL AND device_row.expires_at>clock_timestamp()
  FOR SHARE OF device_row,u;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT * INTO a FROM public.assistants WHERE id=answering AND workspace_id=w FOR SHARE;
 IF NOT FOUND OR public.assistant_placement_visible(actor,answering) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;

 SELECT * INTO s FROM public.sessions WHERE id=sid FOR SHARE;
 IF NOT FOUND OR s.last_turn_lease_token IS DISTINCT FROM token
  OR coalesce(s.turn_assistant_id,s.assistant_id) IS DISTINCT FROM answering
  OR (
   s.turn_lease_token IS NOT DISTINCT FROM token AND s.status=''running''
    AND s.turn_heartbeat_at>clock_timestamp()-interval ''90 seconds''
    AND (s.cancel_requested_at IS NULL OR boundary=''stopped_publication'')
   OR boundary=''stopped_publication'' AND s.turn_lease_token IS NULL AND s.turn_end_reason=''stopped_by_user''
  ) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF s.workspace_id IS DISTINCT FROM w AND (s.workspace_id IS NOT NULL OR s.user_id IS DISTINCT FROM actor
  OR s.assistant_id IS DISTINCT FROM answering OR boundary IN(''publication'',''stopped_publication'')
  OR (boundary=''history'' AND public.enroll_conversation_legacy_history(sid) IS NOT TRUE)
  OR public.conversation_legacy_enrolled(sid,w,actor,answering) IS NOT TRUE)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 -- Acquisition already takes UPDATE to maintain the capture watermark.
 -- Taking it here avoids upgrading a SHARE lock under two readers.
 IF boundary=''history'' THEN
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR UPDATE;
 ELSE
  SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR SHARE;
 END IF;
 IF NOT FOUND OR public.sensitivity_rank(a.clearance)<public.sensitivity_rank(e.cap)
  OR s.anchor_kind IS DISTINCT FROM ''doc_thread''
  OR public.lock_conversation_member_read(w,sid,actor) IS NOT TRUE
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(
  ''authority'',public.read_session_authority_facts(w,actor,answering,sid,device,native_version,credential_actor,include_departments,include_policy),
  ''destination'',jsonb_build_object(''sensitivity'',e.cap,''compartments'',e.compartments,
   ''projectIds'',public.conversation_hard_project_ids(e.compartments),''generation'',e.version::text));
END $facts$;';
 EXECUTE 'CREATE FUNCTION pg_temp.page_delivery_reviewed_2(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, boundary text, ordinary jsonb, pages jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $page_delivery$
DECLARE facts jsonb;proof jsonb;target jsonb;candidate record;source jsonb;current_pages jsonb:=''[]'';
 required jsonb;receipt_proofs jsonb:=''{}'';current_digest text;
BEGIN
 IF boundary IS NULL OR boundary NOT IN (''dispatch'',''frame'')
  OR jsonb_typeof(ordinary) IS DISTINCT FROM ''array'' OR jsonb_array_length(ordinary)>4096
  OR jsonb_typeof(pages) IS DISTINCT FROM ''array'' OR jsonb_array_length(pages)>32
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(pages) AS p(kind text,id uuid,version text)
   WHERE p.id IS NULL OR p.version IS NULL OR p.kind IS NULL OR p.kind NOT IN
    (''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''))
 THEN RAISE EXCEPTION ''invalid_scope_source'' USING ERRCODE=''22023''; END IF;
 -- The shared lock order is workspace/member/session/envelope followed by the
 -- concrete Page. The normal writer (including grants) waits on those rows.
 facts:=public.conversation_page_turn_facts(w,actor,answering,sid,device,native_version,credential_actor,
  include_departments,include_policy,token,boundary);
 SELECT public.workflow_page_event_boundary(p) INTO target
 FROM public.sessions s JOIN public.comment_threads ct ON ct.session_id=s.id AND ct.workspace_id=w
 JOIN public.saved_views p ON p.id=ct.page_id AND p.workspace_id=w
 WHERE s.id=sid AND s.workspace_id=w AND s.visibility=''workspace'' AND s.anchor_kind=''doc_thread'';
 IF target->>''unavailable'' IS DISTINCT FROM ''false''
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;

 IF jsonb_array_length(pages)>0 AND public.page_event_principal_allows(w,actor,target) IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;

 -- The ordinary planner must positively own every non-Page root, including
 -- its current ancestry. An independent family must use its existing owner.
 IF jsonb_array_length(ordinary)>0 THEN
  proof:=public.capture_conversation_evidence(w,ordinary);
  IF proof IS NULL THEN RETURN NULL; END IF;
 END IF;

 current_digest:=encode(sha256(convert_to(target::text,''UTF8'')),''hex'');
 FOR candidate IN SELECT input.kind,input.id,input.version,r.revision,r.boundaries,r.metadata,
  o.id AS observation_id,o.role AS observation_role,o.boundary AS observation,
  CASE WHEN input.kind IN(''page_event_destination'',''page_live_destination'') THEN ''destination'' ELSE ''changed'' END AS role
  FROM ROWS FROM(jsonb_to_recordset(pages) AS (kind text,id uuid,version text)) WITH ORDINALITY input(kind,id,version,ordinality)
  LEFT JOIN public.workflow_page_event_observations o ON o.workspace_id=w AND o.id=input.id
   AND input.kind IN(''page_live_changed'',''page_live_destination'')
  LEFT JOIN public.workflow_page_event_receipts r ON r.workspace_id=w AND r.page_id=(target->>''pageId'')::uuid
   AND r.revision=CASE WHEN input.kind IN(''page_live_changed'',''page_live_destination'') THEN o.receipt_id ELSE input.id END
  ORDER BY input.ordinality
 LOOP
  -- Every saved or observed receipt axis must describe this exact live Page.
  -- A Page receipt elsewhere with identical labels never satisfies the room.
  IF candidate.boundaries IS NULL OR EXISTS(
   SELECT 1 FROM (SELECT value FROM jsonb_each(candidate.boundaries)
    UNION ALL SELECT candidate.observation WHERE candidate.observation IS NOT NULL) b
   WHERE b.value->>''unavailable'' IS DISTINCT FROM ''false''
    OR b.value->>''pageId'' IS DISTINCT FROM target->>''pageId'' OR b.value->>''workspaceId'' IS DISTINCT FROM w::text
    OR b.value->>''principalBoundary'' IS DISTINCT FROM target->>''principalBoundary''
    OR CASE target->>''principalBoundary''
     WHEN ''private'' THEN b.value->>''creatorId'' IS DISTINCT FROM target->>''creatorId''
     WHEN ''department'' THEN b.value->>''departmentId'' IS DISTINCT FROM target->>''departmentId''
     WHEN ''teamspace'' THEN b.value->>''teamspaceId'' IS DISTINCT FROM target->>''teamspaceId''
     ELSE true END)
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  IF (candidate.kind IN(''page_live_changed'',''page_live_destination'')
    AND (candidate.observation_id IS NULL OR candidate.observation_role IS DISTINCT FROM candidate.role))
   OR (candidate.role=''destination'' AND candidate.metadata->>''action'' NOT IN(''created'',''moved''))
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  source:=public.page_event_scope_descriptor(candidate.id,candidate.role,
   CASE WHEN candidate.observation_id IS NOT NULL THEN candidate.observation ELSE candidate.boundaries->candidate.role END,
   candidate.observation_id IS NOT NULL);
  IF candidate.observation_id IS NOT NULL THEN
   PERFORM 1 FROM public.workflow_page_event_observations WHERE workspace_id=w AND id=candidate.observation_id FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  END IF;
  IF source->>''version'' IS DISTINCT FROM candidate.version
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;

  -- Each receipt has one saved/current projection. Its multiple roots keep
  -- their own identities and exact original versions in the returned order.
  required:=receipt_proofs->candidate.revision::text;
  IF required IS NULL THEN
   PERFORM 1 FROM public.workflow_page_event_receipts WHERE workspace_id=w AND revision=candidate.revision FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
   SELECT jsonb_agg(origin.value ORDER BY b.key,origin.ordinality) INTO required
   FROM jsonb_each(candidate.boundaries) b
   LEFT JOIN LATERAL (SELECT o.id FROM public.workflow_page_event_observations o WHERE o.workspace_id=w
    AND o.receipt_id=candidate.revision AND o.role=b.key AND o.boundary_digest=current_digest AND o.boundary=target FOR SHARE
   ) current_observation ON true
   CROSS JOIN LATERAL jsonb_array_elements(jsonb_build_array(
    public.page_event_scope_descriptor(candidate.revision,b.key,b.value,false),
    CASE WHEN current_observation.id IS NOT NULL THEN public.page_event_scope_descriptor(current_observation.id,b.key,target,true)
     ELSE public.capture_page_event_observation(w,candidate.revision,b.key,target) END
   )) WITH ORDINALITY origin(value,ordinality)
   WHERE (b.key=''changed'' OR candidate.metadata->>''action'' IN(''created'',''moved'')) AND origin.value IS DISTINCT FROM ''null''::jsonb;
   IF required IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
   receipt_proofs:=jsonb_set(receipt_proofs,ARRAY[candidate.revision::text],required,true);
  END IF;
  current_pages:=current_pages||jsonb_build_array(jsonb_build_object(''source'',source,''requiredSources'',required,''principalAllowed'',true));
 END LOOP;
 RETURN facts||jsonb_build_object(''ordinary'',proof,''pages'',current_pages);
END $page_delivery$;';
 EXECUTE 'CREATE FUNCTION pg_temp.page_delivery_reviewed_3(w uuid, actor uuid, answering uuid, sid uuid,
 device uuid, native_version integer, credential_actor uuid, include_departments boolean,
 include_policy boolean, token uuid, requested_page uuid) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog,public,pg_temp AS $page_anchor$
DECLARE revision uuid;admitted jsonb;payload jsonb;
BEGIN
 SELECT p.page_event_revision INTO revision FROM public.comment_threads t
 JOIN public.saved_views p ON p.workspace_id=t.workspace_id AND p.id=t.page_id
 WHERE t.workspace_id=w AND t.session_id=sid AND p.id=requested_page;
 IF revision IS NULL THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 admitted:=public.capture_native_page_turn_delivery(w,actor,answering,sid,device,native_version,credential_actor,
  include_departments,include_policy,token,''dispatch'',''[]'',
  jsonb_build_array(jsonb_build_object(''kind'',''page_event_changed'',''id'',revision,''version'',revision)));
 SELECT jsonb_build_object(''page'',coalesce(d.snapshot_json,p.page),''version'',coalesce(d.seq::integer,p.version),
  ''title'',coalesce(d.snapshot_title,p.name),''nameOrigin'',p.name_origin,''icon'',p.icon)
 INTO payload FROM public.saved_views p LEFT JOIN public.documents d ON d.page_id=p.id
 WHERE p.id=requested_page AND p.workspace_id=w AND p.page_event_revision=revision;
 IF payload IS NULL OR admitted IS NULL THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(''authority'',admitted->''authority'',''page'',payload,''source'',admitted->''pages''->0);
END $page_anchor$;';
END $page_delivery_references$;
CREATE TEMP TABLE page_delivery_reviewed_oids(oid oid PRIMARY KEY) ON COMMIT DROP;
DO $page_delivery_catalog$
DECLARE item record;actual pg_proc;reviewed pg_proc;
 owner_id oid:=(SELECT relowner FROM pg_class WHERE oid='public.sessions'::regclass);
 app_id oid:=(SELECT oid FROM pg_roles WHERE rolname='app_user');
BEGIN
 FOR item IN SELECT * FROM (VALUES
  ('private_conversation_page_frame_source','page_delivery_reviewed_0',false),('conversation_page_turn_facts','page_delivery_reviewed_1',false),('capture_native_page_turn_delivery','page_delivery_reviewed_2',true),('capture_native_page_turn_anchor','page_delivery_reviewed_3',true)
 ) declarations(name,reference,exposed) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE pronamespace=pg_my_temp_schema() AND proname=item.reference;
  SELECT * INTO actual FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname=item.name AND proargtypes=reviewed.proargtypes;
  IF actual.oid IS NULL OR actual.proowner<>owner_id
   OR actual.proacl IS DISTINCT FROM (CASE WHEN item.exposed THEN
    ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
   ELSE ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)] END)
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
      (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
  THEN RAISE EXCEPTION 'conversation_page_function_changed: %',item.name; END IF;
  INSERT INTO pg_temp.page_delivery_reviewed_oids VALUES(actual.oid);
 END LOOP;
END $page_delivery_catalog$;
DO $verified_channel_publication_reference$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.verified_channel_publication_reviewed(w uuid,sid uuid,actor uuid,responder uuid,
 transport text,address text,member_actor boolean,room boolean,expected_version bigint,lease uuid,integration uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $channel_append$
DECLARE s public.sessions;e public.conversation_envelopes;owns_tables boolean;bound_channel uuid;parent_address text;
BEGIN
 SELECT NOT r.rolsuper AND NOT r.rolbypassrls AND r.oid=c.relowner INTO owns_tables
  FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass WHERE r.rolname=session_user;
 IF num_nulls(w,sid,actor,responder,transport,address,member_actor,room,expected_version,lease)<>0
  OR transport NOT IN(''telegram'',''slack'',''discord'',''feishu'',''msteams'',''whatsapp'',''wechat'',''email'',''custom'',''imessage'')
  OR length(address) NOT BETWEEN 1 AND 1000 OR expected_version<1
  OR owns_tables IS NOT TRUE AND (session_user<>''app_user'' OR member_actor IS NOT TRUE
   OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
   OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL)
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 PERFORM id FROM public.assistants WHERE id=responder AND workspace_id=w FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM id FROM public.users WHERE id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF FOUND IS DISTINCT FROM member_actor THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 IF integration IS NOT NULL THEN
  SELECT c.id INTO bound_channel FROM public.channel_integrations ci JOIN public.channels c ON c.id=ci.channel_id
   WHERE ci.id=integration AND ci.channel_type=transport AND c.workspace_id=w AND ci.status=''active'' AND c.status=''active''
   FOR UPDATE OF c FOR SHARE OF ci;
  IF NOT FOUND THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
  parent_address:=CASE WHEN transport=''telegram'' THEN regexp_replace(address,''^(\-?[0-9]+):(topic|discussion):[0-9]+$'',''\1'')
   WHEN transport IN(''slack'',''feishu'') THEN split_part(address,'':thread:'',1) ELSE address END;
  IF (SELECT ca.assistant_id FROM public.channel_assistants ca WHERE ca.channel_id=bound_channel
   AND (ca.external_surface_id IS NULL OR ca.external_surface_id IN(address,parent_address))
   ORDER BY CASE WHEN ca.external_surface_id=address THEN 0 WHEN ca.external_surface_id=parent_address THEN 1 ELSE 2 END
   LIMIT 1 FOR SHARE) IS DISTINCT FROM responder
  THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 END IF;
 SELECT * INTO s FROM public.sessions WHERE id=sid AND (workspace_id IS NULL OR workspace_id=w) FOR UPDATE;
 IF NOT FOUND OR s.channel_type<>transport OR s.channel_id<>address OR s.archived_at IS NOT NULL
  OR s.recording_privacy_held IS TRUE OR public.scope_review_state_held(''session'',sid)
  OR s.turn_lease_token IS DISTINCT FROM lease OR s.last_turn_lease_token IS DISTINCT FROM lease OR s.status<>''running''
  OR s.cancel_requested_at IS NOT NULL OR s.turn_heartbeat_at IS NULL
  OR s.turn_heartbeat_at<=clock_timestamp()-interval ''90 seconds''
  OR coalesce(s.turn_assistant_id,s.assistant_id)<>responder
  OR NOT (room AND s.anchor_kind=''channel'' OR NOT room AND s.anchor_kind=''none'' AND s.user_id=actor AND s.assistant_id=responder)
  OR s.provider_context_identity IS NOT NULL AND s.provider_context_identity->>''integrationId'' IS DISTINCT FROM integration::text
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 SELECT * INTO e FROM public.conversation_envelopes WHERE session_id=sid AND workspace_id=w FOR UPDATE;
 IF NOT FOUND OR e.starter_user_id<>s.user_id OR e.version<>expected_version OR room AND e.visibility<>''workspace''
  OR member_actor AND public.conversation_member_read_allowed(w,sid,actor) IS NOT TRUE
  OR NOT member_actor AND (e.visibility<>''workspace'' OR NOT room AND (e.cap<>''public''
   OR cardinality(e.compartments)<>0 OR e.classification<>''new_public''))
 THEN RAISE EXCEPTION ''conversation_access_denied'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(''version'',e.version::text,''visibility'',e.visibility,''cap'',e.cap,''compartments'',e.compartments,
  ''projects'',public.conversation_hard_project_ids(e.compartments));
END $channel_append$;';
END $verified_channel_publication_reference$;
DO $verified_channel_publication_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.verified_channel_publication_reviewed(uuid,uuid,uuid,uuid,text,text,boolean,boolean,bigint,uuid,uuid)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.pin_verified_channel_conversation_append(uuid,uuid,uuid,uuid,text,text,boolean,boolean,bigint,uuid,uuid)');
 IF actual.oid IS NULL OR actual.proowner<>owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'verified_channel_publication_function_changed';END IF;
END $verified_channel_publication_catalog$;
DO $settings_readiness_reference$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.settings_readiness_reviewed(protocol integer) RETURNS boolean
LANGUAGE sql STABLE SET search_path=pg_catalog,public,pg_temp AS $settings_ready$
 SELECT protocol=1
  AND coalesce(has_function_privilege(current_user,to_regprocedure(''public.read_conversation_member_tiers(uuid[],boolean)''),''EXECUTE''),false)
  AND coalesce(has_function_privilege(current_user,to_regprocedure(''public.read_conversation_visibility(uuid,uuid,integer)''),''EXECUTE''),false)
  AND coalesce(has_function_privilege(current_user,to_regprocedure(''public.change_conversation_visibility(uuid,uuid,integer,bigint,text,jsonb)''),''EXECUTE''),false)
  AND coalesce(has_function_privilege(current_user,to_regprocedure(''public.capture_native_page_turn_anchor(uuid,uuid,uuid,uuid,uuid,integer,uuid,boolean,boolean,uuid,uuid)''),''EXECUTE''),false)
  AND coalesce(has_function_privilege(current_user,to_regprocedure(''public.pin_verified_channel_conversation_append(uuid,uuid,uuid,uuid,text,text,boolean,boolean,bigint,uuid,uuid)''),''EXECUTE''),false)
  AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY[
   ''public.read_native_conversation_history(uuid,uuid,integer)'',
   ''public.read_native_page_conversation_rows(uuid,text)'',
   ''public.lock_conversation_member_read(uuid,uuid,uuid)'',
   ''public.read_public_conversation_history(uuid,jsonb,uuid,text,text,integer)'',
   ''public.conversation_record_derivation_current(uuid,text,uuid,text,uuid)'',
   ''public.read_compiled_conversation_payload(public.conversation_envelopes,integer,integer,integer,boolean,uuid,text)''
  ]) owner_function(signature)
   WHERE to_regprocedure(signature) IS NULL OR has_function_privilege(current_user,to_regprocedure(signature),''EXECUTE''))
$settings_ready$;';
END $settings_readiness_reference$;
DO $settings_readiness_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.settings_readiness_reviewed(integer)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.conversation_visibility_settings_ready(integer)');
 IF actual.oid IS NULL OR actual.proowner<>owner_id OR to_regprocedure('public.conversation_visibility_settings_ready()') IS NOT NULL
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'conversation_settings_readiness_function_changed';END IF;
END $settings_readiness_catalog$;
DO $mixed_evidence_reference$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.conversation_mixed_evidence_route_reviewed(w uuid, roots jsonb) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $route$
DECLARE
 actor uuid:=nullif(current_setting(''app.current_user_id'',true),'''')::uuid;
 native_roots constant text[]:=ARRAY[''application_field'',''session_message'',''session_context_revision'',''memory'',''workspace_file'',''private_transcript''];
 page_kinds constant text[]:=ARRAY[''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''];
 route jsonb;
BEGIN
 IF actor IS NULL OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL
  OR NOT EXISTS(SELECT 1 FROM workspace_members m WHERE m.workspace_id=w AND m.user_id=actor)
  OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.session_messages''::regclass
    WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RETURN NULL; END IF;
 IF native_turn_helpers_current() IS NOT TRUE THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 IF jsonb_typeof(roots) IS DISTINCT FROM ''array'' OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096
 THEN RAISE EXCEPTION ''invalid_scope_source'' USING ERRCODE=''22023''; END IF;

 WITH RECURSIVE original AS MATERIALIZED(
  SELECT r.ord,r.kind,r.id,r.version
  FROM ROWS FROM(jsonb_to_recordset(roots) AS (kind text,id uuid,version text))
   WITH ORDINALITY AS r(kind,id,version,ord)
 ), reached(kind,id,version) AS(
  SELECT o.kind,o.id,o.version FROM original o WHERE o.kind=ANY(native_roots||page_kinds)
  UNION SELECT e.kind,e.id,e.version FROM reached p
   CROSS JOIN LATERAL conversation_source_edges(w,p.kind,p.id,p.version) e
  WHERE p.kind NOT IN (''conversation_record'',''conversation_record_refused'',''conversation_record_current_root'')
 ), nodes AS MATERIALIZED(
  SELECT * FROM reached LIMIT 4097
 ), edges AS MATERIALIZED(
  SELECT n.kind AS pk,n.id AS pi,n.version AS pv,e.kind,e.id,e.version
  FROM nodes n CROSS JOIN LATERAL conversation_source_edges(w,n.kind,n.id,n.version) e
  WHERE n.kind NOT IN (''conversation_record'',''conversation_record_refused'',''conversation_record_current_root'')
  LIMIT 65537
 ), types AS MATERIALIZED(
  SELECT n.*,CASE
   WHEN n.kind=ANY(page_kinds) THEN ''page''
   WHEN n.kind=''conversation_record'' THEN ''record''
   WHEN n.kind=''application_field'' AND f.origin=''{"kind":"native","moduleKey":"native"}''::jsonb
    AND f.type_key=''memory'' AND f.selection=''history'' THEN ''history''
   WHEN n.kind=''application_field'' AND (f.id IS NULL
     OR f.origin IS DISTINCT FROM ''{"kind":"native","moduleKey":"native"}''::jsonb
     OR f.type_key NOT IN(''session_message'',''session_message_annotation'',''memory'')) THEN ''independent''
   WHEN n.kind=''application_field'' AND f.type_key=''memory'' AND f.selection=''query_domain''
    AND EXISTS(SELECT 1 FROM application_query_domains d WHERE d.workspace_id=w AND d.id=f.resource_id
      AND d.domain->>''includeRetained''=''true'') THEN ''retained''
   WHEN n.kind=ANY(native_roots||ARRAY[''application_query_domain'',''recording'',''episode'']) THEN ''native''
   ELSE ''independent'' END AS family
  FROM nodes n LEFT JOIN application_field_resources f ON n.kind=''application_field'' AND f.workspace_id=w AND f.id=n.id
 ), inherited(kind,id,version,family) AS(
  SELECT t.kind,t.id,t.version,t.family FROM types t WHERE t.family<>''native''
  UNION SELECT e.pk,e.pi,e.pv,a.family FROM inherited a
   JOIN edges e ON (e.kind,e.id,e.version)=(a.kind,a.id,a.version)
 ), families AS(
  SELECT o.ord,CASE
   WHEN NOT o.kind=ANY(native_roots||page_kinds) OR max(t.family)=''independent'' THEN ''independent''
   WHEN bool_or(a.family=''record'') THEN ''record''
   WHEN bool_or(a.family=''history'') AND max(t.family)=''history'' THEN ''history''
   WHEN bool_or(a.family IN (''history'',''independent'')) THEN ''hybrid''
   WHEN bool_or(a.family=''retained'') THEN ''retained''
   WHEN bool_or(a.family=''page'') THEN ''page''
   ELSE ''native'' END AS family
  FROM original o LEFT JOIN inherited a ON (o.kind,o.id,o.version)=(a.kind,a.id,a.version)
  LEFT JOIN types t ON (o.kind,o.id,o.version)=(t.kind,t.id,t.version)
  GROUP BY o.ord,o.kind
 )
 SELECT CASE WHEN (SELECT count(*) FROM nodes)>4096 OR (SELECT count(*) FROM edges)>65536 THEN NULL ELSE
  jsonb_build_object(''actor'',actor,''families'',(SELECT jsonb_agg(family ORDER BY ord) FROM families),
   ''footprint'',encode(sha256(convert_to(jsonb_build_array(
    (SELECT jsonb_agg(to_jsonb(t) ORDER BY t.kind,t.id,t.version) FROM types t),
    (SELECT jsonb_agg(to_jsonb(e) ORDER BY e.pk,e.pi,e.pv,e.kind,e.id,e.version) FROM edges e),
    (SELECT jsonb_build_array(c.revision,p.revision) FROM application_policy_contract_epoch c
     CROSS JOIN application_policy_workspace_epochs p WHERE c.singleton AND p.workspace_id=w),
    native_turn_context())::text,''UTF8'')),''hex''))
  END INTO route;
 IF route IS NULL THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501''; END IF;
 RETURN route;
END $route$;';
END $mixed_evidence_reference$;
DO $mixed_evidence_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.conversation_mixed_evidence_route_reviewed(uuid,jsonb)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.conversation_mixed_evidence_route(uuid,jsonb)');
 IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'installation_mixed_evidence_route_changed';END IF;
END $mixed_evidence_catalog$;
DO $mixed_evidence_reference$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.capture_hybrid_conversation_evidence_reviewed(w uuid, roots jsonb) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $hybrid$
DECLARE
 route jsonb; memo jsonb; n record; stored jsonb; source jsonb; key text; selected_history boolean;
 native_roots constant text[]:=ARRAY[''application_field'',''session_message'',''session_context_revision'',''memory'',''workspace_file'',''private_transcript''];
 page_kinds constant text[]:=ARRAY[''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination''];
 immutable jsonb:=''[]''; currents jsonb:=''[]''; independent jsonb:=''[]'';
BEGIN
 route:=public.conversation_mixed_evidence_route(w,roots);
 IF route IS NULL OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(route->''families'') f
  WHERE f NOT IN (''native'',''hybrid'',''retained'',''page'',''record'',''history''))
 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501''; END IF;
 selected_history:=NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(route->''families'') f WHERE f<>''history'');
 IF NOT selected_history THEN
  IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(route->''families'') f WHERE f=''history'')
  THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501''; END IF;
  -- A retained conversation record keeps its own current origin/recipient proof.
  -- It does not go through the ordinary native source snapshot register.
  IF EXISTS (SELECT 1 FROM jsonb_array_elements_text(route->''families'') f WHERE f=''record'')
   AND EXISTS(SELECT 1 FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
    WHERE public.conversation_record_derivation_current(w,r.kind,r.id,r.version,(route->>''actor'')::uuid) IS NOT TRUE)
  THEN RETURN ''{"admitted":false}''; END IF;
  memo:=public.conversation_dag(w,roots,''[]'');
  IF memo->>''recordingEligible'' IS DISTINCT FROM ''true'' THEN RETURN ''{"admitted":false}''; END IF;
 END IF;
 FOR n IN
  WITH RECURSIVE closure(kind,id,version) AS (
   SELECT * FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
   UNION SELECT e.kind,e.id,e.version FROM closure c
    CROSS JOIN LATERAL public.conversation_source_edges(w,c.kind,c.id,c.version) e
  )
  SELECT * FROM closure
  WHERE NOT selected_history OR kind IN (''external_source'',''office_observation'',''page_event_changed'',''page_event_destination'',''page_live_changed'',''page_live_destination'')
  ORDER BY kind,id,version
 LOOP
  key:=n.kind||'':''||n.id||'':''||n.version;
  IF n.kind=''application_query_domain'' THEN CONTINUE; END IF;
  IF n.kind=''conversation_record'' THEN
   IF n.version<>''1'' OR NOT EXISTS(SELECT 1 FROM public.private_transcript_observations o
    WHERE o.workspace_id=w AND o.id=n.id AND o.binding->>''kind''=''conversation_record_v1''
     AND o.binding->>''purpose''=''native_member_dialogue'')
   THEN RETURN ''{"admitted":false}''; END IF;
   CONTINUE;
  END IF;
  IF n.kind=''application_field'' THEN
   source:=memo#>ARRAY[''field:''||n.id||'':''||n.version,''value''];
   IF source->>''held'' IS DISTINCT FROM ''false'' THEN RETURN ''{"admitted":false}''; END IF;
   SELECT o.source_scope INTO STRICT stored FROM public.application_field_observations o
    WHERE o.workspace_id=w AND o.resource_id=n.id AND o.version=n.version;
   immutable:=immutable||jsonb_build_array(stored||jsonb_build_object(''resourceKind'',n.kind,''resourceId'',n.id,''version'',n.version));
  ELSIF n.kind=''external_source'' THEN
   -- The graph has already checked the live SQL pin. The caller separately
   -- requires the original context/delivery action on this exact observation.
   IF NOT selected_history AND memo#>>ARRAY[''native:''||key,''value''] IS DISTINCT FROM ''true'' THEN RETURN ''{"admitted":false}''; END IF;
   SELECT jsonb_build_object(''workspaceId'',w,''userId'',NULL,''assistantId'',NULL,''resourceKind'',n.kind,
    ''resourceId'',n.id,''version'',o.version,''sensitivity'',o.sensitivity,''compartments'',o.compartments,''projectIds'',o.project_ids)
   INTO stored FROM public.external_source_observations o WHERE o.workspace_id=w AND o.id=n.id AND o.version=n.version;
   IF stored IS NULL THEN RETURN ''{"admitted":false}''; END IF;
   independent:=independent||jsonb_build_array(stored);
   CONTINUE;
  ELSIF n.kind=''office_observation'' OR n.kind=ANY(page_kinds) THEN
   -- Both need the receiver''s principal, which can differ from the SQL actor.
   -- Their host adapters check the saved identity and the exact current grants.
   stored:=public.read_scope_source(w,n.kind,n.id);
   IF stored->>''held'' IS DISTINCT FROM ''false'' OR stored->>''version'' IS DISTINCT FROM n.version
   THEN RETURN ''{"admitted":false}''; END IF;
   independent:=independent||jsonb_build_array(stored-ARRAY[''held'',''validTo'',''retractedAt'',''requiredSources'']);
   CONTINUE;
  ELSE
   IF n.kind NOT IN (''recording'',''episode'') AND NOT n.kind=ANY(native_roots)
    AND public.scope_source_table(n.kind) IS NULL
   THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501''; END IF;
   IF memo#>>ARRAY[''native:''||key,''value''] IS DISTINCT FROM ''true'' THEN RETURN ''{"admitted":false}''; END IF;
   source:=memo#>ARRAY[''current'',key];
   IF source IS NULL OR source=''null''::jsonb THEN CONTINUE; END IF;
   IF n.kind=''session_context_revision'' AND source->>''version'' IS DISTINCT FROM n.version
   THEN RETURN ''{"admitted":false}''; END IF;
  END IF;
  source:=jsonb_build_object(''workspaceId'',w,''userId'',source->''userId'',''assistantId'',source->''assistantId'',
   ''sensitivity'',source->''sensitivity'',''compartments'',source->''compartments'',''projectIds'',source->''projectIds'',
   ''resourceKind'',n.kind,''resourceId'',n.id,''version'',source->''version'');
  IF n.kind=''session_context_revision'' THEN immutable:=immutable||jsonb_build_array(source); END IF;
  currents:=currents||jsonb_build_array(source);
 END LOOP;
 IF native_turn_helpers_current() IS NOT TRUE OR NOT selected_history AND clock_timestamp()>=(memo->>''validUntil'')::timestamptz
  OR public.conversation_mixed_evidence_route(w,roots) IS DISTINCT FROM route
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(''admitted'',true,''immutable'',immutable,''current'',currents,''independent'',independent);
END $hybrid$;';
END $mixed_evidence_reference$;
DO $mixed_evidence_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.capture_hybrid_conversation_evidence_reviewed(uuid,jsonb)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.capture_hybrid_conversation_evidence(uuid,jsonb)');
 IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'installation_mixed_evidence_route_changed';END IF;
END $mixed_evidence_catalog$;
DO $shared_room_resume_reference$ BEGIN
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_reviewed_lock_shared_room_resume_evidence(
 w uuid, actor uuid, answering uuid, sid uuid, channel text, approval uuid, lease uuid, roots jsonb, writing boolean
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
 SET search_path=pg_catalog,public,pg_temp AS $resume_evidence$
DECLARE
 room public.sessions; assistant_clearance text; graph jsonb; edges jsonb; node record; source jsonb;
 current_sources jsonb:=''[]''; revisions jsonb:=''[]''; edge_count integer;
BEGIN
 IF actor IS NULL OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
  OR actor IS DISTINCT FROM nullif(current_setting(''app.agent_actor_id'',true),'''')::uuid
  OR w IS DISTINCT FROM nullif(current_setting(''app.agent_workspace_id'',true),'''')::uuid
  OR answering IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid
  OR current_setting(''app.agent_shared_audience'',true) IS DISTINCT FROM ''true''
  OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
  OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL
  OR writing IS NULL
  OR public.native_turn_helpers_current() IS NOT TRUE
  OR jsonb_typeof(roots) IS DISTINCT FROM ''array'' OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096
  OR EXISTS(SELECT 1 FROM jsonb_to_recordset(roots) AS n(kind text,id uuid,version text)
    WHERE n.kind IS NULL OR n.kind NOT IN(''session_message'',''session_context_revision'')
    OR n.id IS NULL OR n.version IS NULL)
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;

 -- Keep the native principal lock order. The stored writer owns the
 -- stronger destination locks from proof through append and completion.
 PERFORM id FROM public.workspaces WHERE id=w FOR SHARE;
 PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 SELECT coalesce(a.clearance,''internal'') INTO assistant_clearance FROM public.assistants a
 WHERE a.workspace_id=w AND a.id=answering AND NOT actor=ANY(a.blocked_user_ids)
  AND public.assistant_placement_visible(actor,a.id) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 IF writing THEN
  PERFORM id FROM public.sessions WHERE workspace_id=w AND id=sid FOR UPDATE;
  PERFORM session_id FROM public.conversation_envelopes WHERE workspace_id=w AND session_id=sid FOR UPDATE;
 END IF;
 IF public.lock_conversation_member_read(w,sid,actor) IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 SELECT * INTO room FROM public.sessions s WHERE s.workspace_id=w AND s.id=sid;
 IF NOT FOUND OR room.user_id IS DISTINCT FROM actor OR room.assistant_id IS DISTINCT FROM answering
  OR room.channel_type<>''web'' OR room.anchor_kind<>''none'' OR room.visibility<>''workspace''
  OR room.app_origin IS DISTINCT FROM ''chat'' OR room.transient IS TRUE
  OR room.channel_id IS DISTINCT FROM channel
  OR assistant_clearance<>coalesce(room.effective_clearance,''internal'')
  OR lease IS NULL OR room.status<>''running'' OR room.turn_lease_token IS DISTINCT FROM lease
  OR room.last_turn_lease_token IS DISTINCT FROM lease
  OR coalesce(room.turn_assistant_id,room.assistant_id) IS DISTINCT FROM answering
  OR room.cancel_requested_at IS NOT NULL
  OR room.turn_heartbeat_at IS NULL OR room.turn_heartbeat_at<=clock_timestamp()-interval ''90 seconds''
  OR public.scope_review_state_held(''session'',sid)
  OR NOT EXISTS(SELECT 1 FROM public.conversation_envelopes e
    WHERE e.workspace_id=w AND e.session_id=sid AND e.visibility=''workspace'')
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 PERFORM 1 FROM public.session_resume_points p JOIN public.pending_approvals a ON a.id=p.approval_id
  WHERE p.session_id=sid AND a.id=approval AND a.workspace_id=w AND a.approver_user_id=actor
   AND a.blocking_session_id=sid AND a.originating_assistant_id=answering
   AND a.kind IN(''question'',''tool_invocation'')
   AND a.status IN(''approved'',''rejected'',''expired'') FOR SHARE OF p,a;
 IF NOT FOUND THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;

 -- Keep every original edge, including where each record entered the graph.
 -- For this closed family, a row, revision or record from another room
 -- cannot qualify even when this actor can independently read both rooms.
 WITH RECURSIVE closure(kind,id,version) AS (
  SELECT r.kind,r.id,r.version FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
  UNION
  SELECT e.kind,e.id,e.version FROM closure c
  CROSS JOIN LATERAL public.conversation_source_edges(w,c.kind,c.id,c.version) e
  WHERE c.kind IN(''session_message'',''session_context_revision'')
 ), bounded AS MATERIALIZED (SELECT * FROM closure LIMIT 4097)
 SELECT jsonb_agg(to_jsonb(n)) INTO edges FROM bounded n;
 IF jsonb_array_length(edges)>4096 OR EXISTS(
  SELECT 1 FROM jsonb_to_recordset(edges) AS n(kind text,id uuid,version text)
  WHERE n.version IS NULL OR NOT CASE n.kind
   WHEN ''session_message'' THEN EXISTS(SELECT 1 FROM public.session_messages m
    WHERE m.workspace_id=w AND m.session_id=sid AND m.id=n.id AND m.scope_version::text=n.version)
   WHEN ''session_context_revision'' THEN EXISTS(SELECT 1 FROM public.session_context_scope_revisions r
    WHERE r.workspace_id=w AND r.session_id=sid AND r.id=n.id AND r.scope_version::text=n.version)
   WHEN ''conversation_record'' THEN n.version=''1'' AND EXISTS(SELECT 1 FROM public.private_transcript_observations o
    WHERE o.workspace_id=w AND o.session_id=sid AND o.id=n.id AND o.binding->>''kind''=''conversation_record_v1''
     AND o.binding->>''purpose''=''native_member_dialogue'')
   ELSE false END
 ) THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;

 edge_count:=0;
 FOR node IN SELECT d.id,s.source_id,s.source_version FROM jsonb_to_recordset(edges) AS n(kind text,id uuid)
  JOIN public.scope_derivations d ON d.workspace_id=w AND d.resource_kind=n.kind AND d.resource_id=n.id
  JOIN public.scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id
  WHERE n.kind IN(''session_message'',''session_context_revision'') AND s.source_kind=''conversation_record''
  ORDER BY d.id,s.source_id LIMIT 65537
 LOOP
  edge_count:=edge_count+1;
  IF edge_count>65536 THEN RAISE EXCEPTION ''scope_ancestry_unavailable'' USING ERRCODE=''42501''; END IF;
  PERFORM public.require_conversation_record_edge(w,node.id,node.source_id,node.source_version);
 END LOOP;

 -- The native graph owns acyclicity, current row/parent snapshots, all-version
 -- recording privacy, archive rules and dependency validation. M7 record
 -- edges were positively checked above; they never become new input roots.
 graph:=public.conversation_dag(w,roots,''[]'');
 IF graph->>''recordingEligible'' IS DISTINCT FROM ''true'' OR graph->>''hasExternal'' IS DISTINCT FROM ''false''
  OR clock_timestamp()>=(graph->>''validUntil'')::timestamptz
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 FOR node IN SELECT * FROM jsonb_to_recordset(edges) AS n(kind text,id uuid,version text)
  WHERE n.kind<>''conversation_record'' LOOP
  source:=graph#>ARRAY[''current'',node.kind||'':''||node.id||'':''||node.version];
  IF (graph#>>ARRAY[''native:''||node.kind||'':''||node.id||'':''||node.version,''value'']) IS DISTINCT FROM ''true''
   OR source->>''held'' IS DISTINCT FROM ''false'' OR source->>''version'' IS DISTINCT FROM node.version
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  source:=source-ARRAY[''held'',''validTo'',''retractedAt'',''requiredSources''];
  current_sources:=current_sources||jsonb_build_array(source);
  IF node.kind=''session_context_revision'' THEN revisions:=revisions||jsonb_build_array(source); END IF;
 END LOOP;
 IF public.native_turn_helpers_current() IS NOT TRUE
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN jsonb_build_object(''immutable'',revisions,''current'',current_sources);
END $resume_evidence$;';
 EXECUTE 'CREATE FUNCTION pg_temp.a8314_reviewed_capture_shared_room_resume_evidence(
 w uuid, actor uuid, answering uuid, sid uuid, channel text, approval uuid, lease uuid, roots jsonb
) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER
 SET search_path=pg_catalog,public,pg_temp AS $capture$
BEGIN
 IF EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
    WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
 THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 RETURN public.lock_shared_room_resume_evidence(w,actor,answering,sid,channel,approval,lease,roots,false);
END $capture$;';
END $shared_room_resume_reference$;
DO $shared_room_resume_catalog$
DECLARE port record;actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 FOR port IN SELECT * FROM (VALUES ('public.lock_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb,boolean)','pg_temp.a8314_reviewed_lock_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb,boolean)',false),('public.capture_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb)','pg_temp.a8314_reviewed_capture_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb)',true))
  reviewed_ports(signature,reference,exposed) LOOP
  SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid=to_regprocedure(port.reference);
  SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure(port.signature);
  IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id
   OR actual.proacl IS DISTINCT FROM (CASE WHEN port.exposed THEN
    ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
    ELSE ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)] END)
   OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
    (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
  THEN RAISE EXCEPTION 'installation_shared_room_resume_evidence_changed: %',port.signature; END IF;
 END LOOP;
END $shared_room_resume_catalog$;
DO $committed_room_reference$ BEGIN
 EXECUTE '-- [COMP:api/native-turn-frame] Original record edges of a committed room result.
CREATE FUNCTION pg_temp.committed_room_evidence_reviewed(w uuid,s uuid,roots jsonb)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $committed_room$
DECLARE route jsonb; membership jsonb; graph jsonb; edge record; node record; source jsonb; observed jsonb; key text; edge_count integer:=0;
BEGIN
 IF NOT EXISTS(
  SELECT 1 FROM pg_catalog.pg_proc p
  JOIN pg_catalog.pg_class c ON c.oid=''public.sessions''::regclass
  JOIN pg_catalog.pg_roles runtime ON runtime.rolname=''app_user''
  WHERE p.oid=''public.conversation_mixed_evidence_route(uuid,jsonb)''::regprocedure
   AND p.proowner=c.relowner AND p.prosecdef AND p.provolatile=''s''
   AND p.proconfig=ARRAY[''search_path=pg_catalog, public, pg_temp'']
   AND p.proacl=ARRAY[makeaclitem(c.relowner,c.relowner,''EXECUTE'',false),makeaclitem(runtime.oid,c.relowner,''EXECUTE'',false)]
   AND encode(sha256(convert_to(p.prosrc,''UTF8'')),''hex'')=''162c4eaf0a3d727d40f6e9ba729bcb1e8190809e89e1b4896e2bef66ed5be768''
 ) THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
 route:=public.conversation_mixed_evidence_route(w,roots);
 IF route IS NULL OR NOT (route->''families'') ? ''record'' THEN RETURN NULL; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(route->''families'') f WHERE f NOT IN (''native'',''record'',''retained''))
 THEN RETURN NULL; END IF;

 -- This owner only receives roots derived from the immutable publication
 -- receipt. The canonical destination lock is already held by its caller.
 WITH RECURSIVE closure(kind,id,version) AS (
  SELECT * FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
  UNION SELECT e.kind,e.id,e.version FROM closure c
  CROSS JOIN LATERAL public.conversation_source_edges(w,c.kind,c.id,c.version) e
  WHERE c.kind<>''conversation_record''
 )
 SELECT jsonb_agg(to_jsonb(reached)) INTO membership FROM (SELECT * FROM closure LIMIT 4097) reached;
 IF jsonb_array_length(membership)>4096 OR EXISTS (
  SELECT 1 FROM jsonb_to_recordset(membership) AS candidate(kind text,id uuid,version text)
  WHERE candidate.version IS NULL OR CASE candidate.kind
   WHEN ''session_message'' THEN NOT EXISTS(SELECT 1 FROM public.session_messages m
    WHERE m.workspace_id=w AND m.session_id=s AND m.id=candidate.id AND m.scope_version::text=candidate.version)
   WHEN ''session_context_revision'' THEN NOT EXISTS(SELECT 1 FROM public.session_context_scope_revisions r
    WHERE r.workspace_id=w AND r.session_id=s AND r.id=candidate.id AND r.scope_version::text=candidate.version)
   WHEN ''conversation_record'' THEN candidate.version<>''1'' OR NOT EXISTS(SELECT 1 FROM public.private_transcript_observations o
    WHERE o.workspace_id=w AND o.session_id=s AND o.id=candidate.id AND o.binding->>''kind''=''conversation_record_v1''
     AND o.binding->>''purpose''=''native_member_dialogue'')
   ELSE false END
 ) THEN RETURN ''{"admitted":false}''; END IF;
 FOR edge IN
  SELECT d.id,s.source_id,s.source_version FROM jsonb_to_recordset(membership) AS n(kind text,id uuid,version text)
  JOIN public.scope_derivations d ON d.workspace_id=w AND d.resource_kind=n.kind AND d.resource_id=n.id
  JOIN public.scope_derivation_sources s ON s.workspace_id=w AND s.derivation_id=d.id
  WHERE s.source_kind=''conversation_record'' AND s.source_id IS NOT NULL
  ORDER BY d.id,s.source_id LIMIT 65537
 LOOP
  edge_count:=edge_count+1;
  IF edge_count>65536 THEN RETURN ''{"admitted":false}''; END IF;
  PERFORM public.require_conversation_record_edge(w,edge.id,edge.source_id,edge.source_version);
 END LOOP;
 IF edge_count=0 THEN RETURN ''{"admitted":false}''; END IF;

 -- This is continuity of the exact same room, not an external derivative
 -- from each output row. The preceding owner already proved the recorded
 -- edges and their original destination. Evaluate the native row graph once.
 graph:=public.conversation_dag(w,roots,''[]'');
 IF graph->>''recordingEligible'' IS DISTINCT FROM ''true'' OR graph->>''hasExternal'' IS DISTINCT FROM ''false''
  OR clock_timestamp()>=(graph->>''validUntil'')::timestamptz THEN RETURN ''{"admitted":false}''; END IF;
 FOR node IN SELECT * FROM jsonb_to_recordset(membership) AS n(kind text,id uuid,version text)
  WHERE n.kind NOT IN (''application_query_domain'',''conversation_record'')
 LOOP
  key:=node.kind||'':''||node.id||'':''||node.version;
  IF node.kind=''application_field'' THEN
   source:=graph#>ARRAY[''field:''||node.id||'':''||node.version,''value''];
   SELECT o.source_scope INTO observed FROM public.application_field_observations o
    WHERE o.workspace_id=w AND o.resource_id=node.id AND o.version=node.version;
   IF public.workflow_evidence_envelope_visible(w,observed) IS NOT TRUE THEN RETURN ''{"admitted":false}''; END IF;
  ELSE
   IF node.kind NOT IN (''session_message'',''session_context_revision'',''workspace_file'',''memory'',''private_transcript'',''recording'',''episode'')
    OR graph#>>ARRAY[''native:''||key,''value''] IS DISTINCT FROM ''true''
   THEN RETURN ''{"admitted":false}''; END IF;
   source:=graph#>ARRAY[''current'',key];
  END IF;
  IF source->>''held'' IS DISTINCT FROM ''false'' OR public.workflow_evidence_envelope_visible(w,source) IS NOT TRUE
  THEN RETURN ''{"admitted":false}''; END IF;
 END LOOP;
 IF public.conversation_mixed_evidence_route(w,roots) IS DISTINCT FROM route
  OR clock_timestamp()>=(graph->>''validUntil'')::timestamptz
 THEN RETURN ''{"admitted":false}''; END IF;
 RETURN ''{"admitted":true}'';
EXCEPTION WHEN insufficient_privilege THEN RETURN ''{"admitted":false}'';
END $committed_room$;';
END $committed_room_reference$;
DO $committed_room_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.committed_room_evidence_reviewed(uuid,uuid,jsonb)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.capture_committed_room_record_evidence(uuid,uuid,jsonb)');
 IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'installation_committed_room_evidence_changed';END IF;
END $committed_room_catalog$;
DO $verified_telegram_reference$ BEGIN
 EXECUTE '-- [COMP:api/telegram-conversation-context] Exact normal provider-room evidence.
CREATE FUNCTION pg_temp.verified_telegram_conversation_evidence_reviewed(
  w uuid, sid uuid, actor uuid, responder uuid, address text, integration uuid,
  bot text, epoch bigint, envelope_version bigint, lease uuid, speaker text,
  incoming_id text, roots jsonb
) RETURNS jsonb
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp
AS $telegram_evidence$
DECLARE
  s public.sessions;
  e public.conversation_envelopes;
  channel uuid;
  parent_address text;
  n record;
  memo jsonb;
  current_source jsonb;
  current_labels jsonb := ''[]'';
  immutable jsonb := ''[]'';
  original_context jsonb;
  node_count integer := 0;
BEGIN
  IF num_nulls(w,sid,actor,responder,address,integration,bot,epoch,envelope_version,lease,speaker,incoming_id)<>0
    OR actor IS DISTINCT FROM nullif(current_setting(''app.current_user_id'',true),'''')::uuid
    OR responder IS DISTINCT FROM nullif(current_setting(''app.v2_assistant_id'',true),'''')::uuid
    OR current_setting(''app.agent_shared_audience'',true) IS DISTINCT FROM ''true''
    OR nullif(current_setting(''app.application_id'',true),'''') IS NOT NULL
    OR nullif(current_setting(''app.public_share_root'',true),'''') IS NOT NULL
    OR address !~ ''^-[0-9]+(:(topic|discussion):[0-9]+)?$''
    OR speaker !~ ''^[0-9]+$'' OR incoming_id !~ ''^[0-9]+$''
    OR jsonb_typeof(roots) IS DISTINCT FROM ''array''
    OR jsonb_array_length(roots) NOT BETWEEN 1 AND 4096
    OR EXISTS(SELECT 1 FROM pg_roles r JOIN pg_class c ON c.oid=''public.sessions''::regclass
      WHERE r.rolname=session_user AND (r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid,c.relowner,''USAGE'')))
  THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;

  IF EXISTS(SELECT 1 FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
    WHERE r.kind NOT IN (''application_field'',''session_message'',''session_context_revision'')
      OR r.id IS NULL OR r.version IS NULL)
  THEN RETURN NULL; END IF;

  PERFORM id FROM public.workspaces WHERE id=w FOR SHARE NOWAIT;
  PERFORM user_id FROM public.workspace_members WHERE workspace_id=w AND user_id=actor FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;
  PERFORM id FROM public.linked_identities WHERE provider=''telegram'' AND provider_id=speaker AND user_id=actor FOR SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;

  SELECT c.id INTO channel FROM public.channel_integrations ci JOIN public.channels c ON c.id=ci.channel_id
    WHERE ci.id=integration AND ci.channel_type=''telegram'' AND c.channel_type=''telegram''
      AND ci.status=''active'' AND c.status=''active'' AND c.workspace_id=w
      AND ci.bot_user_id=bot AND ci.identity_generation=epoch
    FOR SHARE OF c,ci NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;
  parent_address:=split_part(address,'':'',1);
  IF (SELECT ca.assistant_id FROM public.channel_assistants ca WHERE ca.channel_id=channel
    AND (ca.external_surface_id IS NULL OR ca.external_surface_id IN(address,parent_address))
    ORDER BY CASE WHEN ca.external_surface_id=address THEN 0 WHEN ca.external_surface_id=parent_address THEN 1 ELSE 2 END
    LIMIT 1 FOR SHARE NOWAIT) IS DISTINCT FROM responder
  THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;

  SELECT * INTO s FROM public.sessions WHERE workspace_id=w AND id=sid FOR SHARE NOWAIT;
  IF NOT FOUND OR s.channel_type<>''telegram'' OR s.channel_id<>address OR s.archived_at IS NOT NULL
    OR s.anchor_kind<>''channel'' OR s.anchor_ref<>address OR s.assistant_id<>responder
    OR s.provider_conversation_context IS NOT TRUE
    OR s.provider_context_generation IS DISTINCT FROM epoch
    OR s.provider_context_identity->>''integrationId'' IS DISTINCT FROM integration::text
    OR s.provider_context_identity->>''botId'' IS DISTINCT FROM bot
    OR (s.provider_context_identity->>''generation'')::bigint>epoch
    OR s.turn_lease_token IS DISTINCT FROM lease OR s.last_turn_lease_token IS DISTINCT FROM lease OR s.status<>''running''
    OR s.cancel_requested_at IS NOT NULL OR s.turn_heartbeat_at IS NULL
    OR s.turn_heartbeat_at<=clock_timestamp()-interval ''90 seconds''
    OR coalesce(s.turn_assistant_id,s.assistant_id)<>responder
    OR s.recording_revision IS NOT NULL OR s.recording_privacy_held IS TRUE
    OR public.scope_review_state_held(''session'',sid)
    OR EXISTS(SELECT 1 FROM public.channel_recording_policies p WHERE p.workspace_id=w
      AND p.bot_id=bot AND p.conversation_id=address AND NOT p.enabled)
    OR NOT EXISTS(SELECT 1 FROM public.session_messages m WHERE m.workspace_id=w AND m.session_id=sid
      AND m.role=''user'' AND m.sender_user_id=actor AND m.channel_message_id=incoming_id)
  THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;

  SELECT * INTO e FROM public.conversation_envelopes WHERE workspace_id=w AND session_id=sid FOR SHARE NOWAIT;
  IF NOT FOUND OR e.visibility<>''workspace'' OR e.version<>envelope_version OR e.starter_user_id<>s.user_id
    OR public.conversation_member_read_current(w,sid,actor) IS NOT TRUE
    OR public.native_turn_helpers_current() IS NOT TRUE
  THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;

  original_context:=public.native_turn_context();
  memo:=public.conversation_dag(w,roots,''[]'');
  FOR n IN
    WITH RECURSIVE closure(kind,id,version) AS (
      SELECT r.kind,r.id,r.version FROM jsonb_to_recordset(roots) AS r(kind text,id uuid,version text)
      UNION SELECT next.kind,next.id,next.version FROM closure c
        CROSS JOIN LATERAL public.conversation_source_edges(w,c.kind,c.id,c.version) next
    )
    SELECT * FROM closure LIMIT 4097
  LOOP
    node_count:=node_count+1;
    IF node_count>4096 THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501''; END IF;
    CASE n.kind
      WHEN ''application_query_domain'' THEN
        IF NOT EXISTS(SELECT 1 FROM public.application_query_domains d WHERE d.workspace_id=w AND d.id=n.id
          AND d.origin=''{"kind":"native","moduleKey":"native"}''::jsonb
          AND d.type_key IN (''session_message'',''session_message_annotation'') AND d.identity=n.version
          AND d.domain->>''sessionId''=sid::text) THEN RETURN NULL; END IF;
        CONTINUE;
      WHEN ''application_field'' THEN
        IF NOT EXISTS(SELECT 1 FROM public.application_field_resources f WHERE f.workspace_id=w AND f.id=n.id
          AND f.origin=''{"kind":"native","moduleKey":"native"}''::jsonb
          AND f.type_key IN (''session_message'',''session_message_annotation'')
          AND (f.selection=''query_domain'' AND EXISTS(SELECT 1 FROM public.application_query_domains d
              WHERE d.workspace_id=w AND d.id=f.resource_id AND d.domain->>''sessionId''=sid::text)
            OR f.selection=''query'' AND EXISTS(SELECT 1 FROM public.session_messages m
              WHERE m.workspace_id=w AND m.id=f.resource_id AND m.session_id=sid))) THEN RETURN NULL; END IF;
        current_source:=memo#>ARRAY[''field:''||n.id||'':''||n.version,''value''];
      WHEN ''session_message'' THEN
        IF NOT EXISTS(SELECT 1 FROM public.session_messages m WHERE m.workspace_id=w AND m.id=n.id AND m.session_id=sid)
        THEN RETURN NULL; END IF;
        IF memo#>>ARRAY[''native:session_message:''||n.id||'':''||n.version,''value''] IS DISTINCT FROM ''true''
        THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
        current_source:=memo#>ARRAY[''current'',''session_message:''||n.id||'':''||n.version];
      WHEN ''session_context_revision'' THEN
        IF NOT EXISTS(SELECT 1 FROM public.session_context_scope_revisions r
          WHERE r.workspace_id=w AND r.id=n.id AND r.session_id=sid)
        THEN RETURN NULL; END IF;
        IF memo#>>ARRAY[''native:session_context_revision:''||n.id||'':''||n.version,''value''] IS DISTINCT FROM ''true''
        THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
        current_source:=memo#>ARRAY[''current'',''session_context_revision:''||n.id||'':''||n.version];
      ELSE RETURN NULL;
    END CASE;
    IF current_source->>''held'' IS DISTINCT FROM ''false''
      OR current_source->>''version'' IS DISTINCT FROM n.version
      OR current_source->>''validTo'' IS NOT NULL OR current_source->>''retractedAt'' IS NOT NULL
    THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
    current_source:=jsonb_build_object(
      ''workspaceId'',w,''resourceKind'',n.kind,''resourceId'',n.id,''version'',n.version,
      ''userId'',current_source->''userId'',''assistantId'',current_source->''assistantId'',
      ''sensitivity'',current_source->''sensitivity'',''compartments'',current_source->''compartments'',''projectIds'',current_source->''projectIds'');
    IF n.kind IN (''application_field'',''session_context_revision'') THEN
      immutable:=immutable||jsonb_build_array(current_source);
    END IF;
    current_labels:=current_labels||jsonb_build_array(current_source);
  END LOOP;
  IF public.native_turn_helpers_current() IS NOT TRUE OR public.native_turn_context() IS DISTINCT FROM original_context
    OR clock_timestamp()>=(memo->>''validUntil'')::timestamptz
  THEN RAISE EXCEPTION ''scope_source_changed'' USING ERRCODE=''42501''; END IF;
  RETURN jsonb_build_object(''current'',current_labels,''immutable'',immutable);
EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION ''provider_context_unavailable'' USING ERRCODE=''42501'';
END $telegram_evidence$;';
END $verified_telegram_reference$;
DO $verified_telegram_catalog$
DECLARE actual pg_proc;reviewed pg_proc;owner_id oid;app_id oid;
BEGIN
 SELECT relowner INTO STRICT owner_id FROM pg_class WHERE oid='public.sessions'::regclass;
 SELECT oid INTO STRICT app_id FROM pg_roles WHERE rolname='app_user';
 SELECT * INTO STRICT reviewed FROM pg_proc WHERE oid='pg_temp.verified_telegram_conversation_evidence_reviewed(uuid,uuid,uuid,uuid,text,uuid,text,bigint,bigint,uuid,text,text,jsonb)'::regprocedure;
 SELECT * INTO actual FROM pg_proc WHERE oid=to_regprocedure('public.capture_verified_telegram_conversation_evidence(uuid,uuid,uuid,uuid,text,uuid,text,bigint,bigint,uuid,text,text,jsonb)');
 IF actual.oid IS NULL OR actual.proowner IS DISTINCT FROM owner_id
  OR actual.proacl IS DISTINCT FROM ARRAY[makeaclitem(owner_id,owner_id,'EXECUTE',false),makeaclitem(app_id,owner_id,'EXECUTE',false)]
  OR (to_jsonb(actual)-ARRAY['oid','proname','pronamespace','proacl']) IS DISTINCT FROM
     (to_jsonb(reviewed)-ARRAY['oid','proname','pronamespace','proacl'])
 THEN RAISE EXCEPTION 'installation_verified_telegram_owner_changed'; END IF;
END $verified_telegram_catalog$;
SELECT encode(sha256(convert_to((SELECT jsonb_agg(metadata ORDER BY signature COLLATE "C") FROM pg_temp.a8314_publication_expected_current)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.capture_verified_telegram_conversation_evidence(uuid,uuid,uuid,uuid,text,uuid,text,bigint,bigint,uuid,text,text,jsonb)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.capture_committed_room_record_evidence(uuid,uuid,jsonb)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.lock_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb,boolean)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.capture_shared_room_resume_evidence(uuid,uuid,uuid,uuid,text,uuid,uuid,jsonb)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.conversation_mixed_evidence_route(uuid,jsonb)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.capture_hybrid_conversation_evidence(uuid,jsonb)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.conversation_visibility_settings_ready(integer)'::regprocedure)::text||(SELECT to_jsonb(p) FROM pg_proc p WHERE p.oid='public.pin_verified_channel_conversation_append(uuid,uuid,uuid,uuid,text,text,boolean,boolean,bigint,uuid,uuid)'::regprocedure)::text
